PRINT(N'Update rows in [dbo].[MATURITY_REFERENCE_TEXT]')
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<b>CERT-RMM Reference</b><p class="p1"><b>[MON:SG1.SP2]</b> Identify stakeholders of the monitoring process. The list should include&#160;<span>internal and external stakeholders and should be seeded by examining operational&#160;</span><span>resilience management processes and their organizational owners. Stakeholders of the&#160;</span><span>organization''s monitoring processes are those internal and external people, entities, or&#160;</span><span>agencies that require information about the operational resilience management processes&#160;</span><span>for which they have responsibility and for which they must achieve resilience goals,&#160;</span><span>objectives, and obligations.</span></p><b>Additional References:</b><div><ul><li><span>Special Publication 800-137 &#34;Information Security Continuous Monitoring (ISCM) for&#160;</span><span>Federal Information Systems and Organizations&#34; Page 7-10</span></li><li><span>NIST CSF References: ID.RA-2, PR.AT-5</span></li></ul><p></p></div>' WHERE [Mat_Question_Id] = 1831 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<b>CERT-RMM Reference</b><p class="p1"><b>[MON:SG2.SP2] </b>Review, refine, and develop monitoring operating procedures. Detailed&#160;<span>processes, standard operating procedures, or work instructions may be created during&#160;</span><span>monitoring infrastructure implementation, but they will need to be regularly reviewed,&#160;</span><span>tailored, and possibly supplemented to meet ongoing monitoring needs.</span></p><b>Additional References:&#160;</b><p class="p1"></p><ul><li>Special Publication 800-137 &#34;Information Security Continuous Monitoring (ISCM) for&#160;<span>Federal Information Systems and Organizations&#34; Page 19-26</span></li><li>NIST CSF References: ID.RA-2, ID.RA-3</li></ul><p></p>' WHERE [Mat_Question_Id] = 1832 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<b>CERT-RMM Reference</b><div><b>[MON:SG2.SP3]</b> Assign resources to monitoring processes. Ensure that monitoring support staff have received appropriate training to perform the necessary monitoring activities. These are examples of training:</div><div><ul><li>operating, monitoring, and configuring monitoring systems components</li><li>supporting stakeholders in understanding and interpreting monitoring data</li><li>securing data collected from monitoring systems components</li></ul></div><div><b>Additional References:</b></div><div><ul><li>Special Publication 800-137 &#34;Information Security Continuous Monitoring (ISCM) forFederal Information Systems and Organizations&#34; Page 16-17</li><li>NIST CSF References: PR.AT-1, PR.AT-5</li></ul></div>' WHERE [Mat_Question_Id] = 1833 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<b>CERT-RMM Reference</b><div><b>[COMM:SG1.SP1]</b> Identify relevant stakeholders that may have a vested interest or vital&#160;<span>role in communications about resilience. When determining which stakeholders to include&#160;</span><span>in the list, consider:</span><ul><li>rationale for stakeholder involvement</li><li>roles and responsibilities of the relevant stakeholders</li><li>relationships between stakeholders</li><li>relative importance of the stakeholder to success of the program</li><li>resources (e.g., training, materials, time, and funding) needed to ensure stakeholder interaction.</li></ul><p></p><p class="p1">Stakeholders and their communications needs may be defined as a part of other&#160;<span>operational resilience management processes. For example, the communication needs of&#160;</span><span>staff involved in the incident management process may be defined by that process. These&#160;</span><span>communications requirements should be considered independently of the processes and&#160;</span><span>practices in the Communications process area because they have a specialized purpose&#160;</span><span>and involve specific stakeholders.</span></p><b>Additional References:</b></div><div><ul><li><span>Special Publication 800-137 &#34;Information Security Continuous Monitoring for Federal&#160;</span><span>Information Systems and Organizations&#34; Page 22-23</span></li><li>NIST CSF References: PR.IP-8</li></ul></div>' WHERE [Mat_Question_Id] = 1834 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<b>CERT-RMM Reference</b><p class="p1"><b>[COMM:SG1.SP1]</b> Establish a plan that describes the involvement of all communications&#160;<span>stakeholders. The plan identifies all internal and external stakeholders, including their&#160;</span><span>roles and classes, as well as the types, frequencies, and levels of communication they are&#160;</span><span>to receive in specified circumstances.</span></p><b>Additional References:</b><div><ul><li><span>Special Publication 800-137 &#34;Information Security Continuous Monitoring for Federal&#160;</span><span>Information Systems and Organizations&#34; Page 22-24</span></li><li>NIST CSF References: PR.IP-8, RS.CO-5</li></ul></div>' WHERE [Mat_Question_Id] = 1835 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<b>CERT-RMM Reference</b><p class="p1"><b>[COMM:SG3.SP2]</b> Communicate threat information to stakeholders. Implement and&#160;<span>manage communications infrastructure. From a generic standpoint, the organization''s&#160;</span><span>communications infrastructure must support communications requirements from&#160;</span><span>stakeholders.</span></p><b>Additional References:</b><div><ul><li><span>Special Publication 800-30 &#34;Guide for Conducting Risk Assessments&#34;&#160;</span></li><li>NIST CSF References: PR.IP-8, RS.CO-5</li></ul></div>' WHERE [Mat_Question_Id] = 1861 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<b>CERT-RMM Reference</b><p class="p1"><b>[COMM:SG2.SP3]</b> Assign resources to communications processes roles and&#160;<span>responsibilities. Staff are assigned authority and accountability for carrying out the&#160;</span><span>communications plan and program.</span></p><b>Additional References</b><div><ul><li><span>Special Publication 800-53 Rev.4 </span><span>CP-3</span></li><li>NIST CSF References: PR.AT-5</li></ul></div>' WHERE [Mat_Question_Id] = 1862 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<b>CERT-RMM Reference</b><p class="p1"><b>[COMM:SG2.SP3]</b> Ensure that organizational training is provided to communications staff&#160;<span>respective to the specific resilience communications role they perform. This is especially&#160;</span><span>important for communications roles in other operational resilience management&#160;</span><span>processes such as incident management and in the execution of service continuity plans.</span></p><b>Additional References</b><div><ul><li><span>Special Publication 800-53 Rev.4&#160;</span><span>CP-3</span></li><li>NIST CSF References: PR.AT-1, PR.AT-5</li></ul><p></p></div>' WHERE [Mat_Question_Id] = 1863 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<b>CERT-RMM Reference</b><p class="p1">Consider developing a plan for situational awareness. Special consideration in the plan&#160;<span>may have to be given to information acquisition, sustaining skill competencies, and&#160;</span><span>planning for changes in the operating environment. These activities aid in protecting and&#160;</span><span>sustaining critical services. Special consideration in the plan may also have to be given to&#160;</span><span>how the organization validates and communicates about cyber security information, and&#160;</span><span>how the organization will maintain a common operating picture.</span></p><b><div><b>Additional References</b><br></div></b><div><ul><li>NIST CSF References: ID.RA</li></ul></div>' WHERE [Mat_Question_Id] = 1864 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<b>CERT-RMM Reference</b><br>Consider developing policies and procedures for situational awareness. Include the following:<br><ul><li>methods and tools for rapidly learning cyber security information,&#160;</li><li>processes that will enable effective analysis of cyber security information</li><li>criteria that might be used to evaluate sources of cyber security information.</li><li>identification of methods of communicating cyber security information across the organization to enable a common operating picture</li><li>repositories of cyber security information</li><li>possible actions that the organization might take in an effort to temporarily reduce its attack surface in the event of inclement cyber security information.</li></ul><p></p><b>Additional References:</b><br><ul><li>NIST CSF References: ID.GV-1, PR.IP</li></ul>' WHERE [Mat_Question_Id] = 1865 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<b>CERT-RMM Reference</b><div>Consider identifying stakeholders of the situational awareness process. Examples include:<ul><li>owners of high-value services and supporting assets (for which plans must be developed)</li><li>custodians of high-value services and supporting assets (who may need to execute or participate in plans)</li><li>organizational unit and line of business managers responsible for high-value services and supporting assets</li><li>staff involved in developing plans</li><li>external entities such as public emergency management staff and other public agencies, partners, and suppliers</li><li>external entities responsible for managing high-value services</li><li>external entities to which the organization is a supplier</li><li>regulatory and legal entities</li><li>internal and external auditors</li></ul><p></p><b>Additional References:</b></div><div><ul><li>NIST CSF References: ID.AM-6, ID.GV-2, PR.AT</li></ul></div>' WHERE [Mat_Question_Id] = 1866 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<b>CERT-RMM Reference</b><div>Consider sponsoring standards, and guidelines, including procedures, standards, and&#160;<span>guidelines for:</span><ul><li>monitoring cyber security information</li><li>recording relevant cyber security information</li><li>evaluating sources of cyber security information</li><li>communicating cyber security information</li><li>reducing the organization''s attack surface</li><li>methods for measuring adherence to policy, exceptions granted, and policy violations.</li></ul><p></p><b>Additional References:</b></div><div><ul><li><span>NIST CSF References: ID.RA</span></li></ul></div>' WHERE [Mat_Question_Id] = 1867 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<b>CERT-RMM Reference</b><br><div>Consider conducting periodic reviews of the situational awareness process as needed to ensure that:</div><ul><li>the process is a planned and coordinated activity</li><li>process planning is driven by managing and mitigating organizational risk</li><li>internal and external dependencies that affect the process are identified and considered</li><li>the effectiveness of situational awareness plans is measured</li><li>the process is improved based on experience in executing the process</li><li>status reports are provided to appropriate stakeholders in a timely manner</li><li>process issues are referred to the risk management process when necessary</li><li>actions requiring management involvement are elevated in a timely manner</li><li>the performance of process activities is being monitored and regularly reported</li><li>key measures are within acceptable ranges as demonstrated in governance dashboards or scorecards and financial reports</li><li>actions resulting from internal and external audits are being closed in a timely manner</li></ul><p></p><b>Additional References:</b><div><ul><li><span>NIST CSF References: PR.IP-8</span></li></ul></div>' WHERE [Mat_Question_Id] = 1883 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<b>CERT-RMM Reference</b><div>Consider ensuring that responsible staff are trained in the skills necessary to perform situational awareness. Such skills include:<ul><li>knowledge necessary to elicit and prioritize stakeholder requirements and needs and interpret them to develop situational awareness plans and programs, including the process plan</li><li>knowledge required to identify relevant sources of cyber security information</li><li>communication skills for conveying the contents of situational awareness plans to&#160;<span>stakeholders</span></li><li>knowledge required to identify methods to establish a common operating picture</li><li>knowledge required to identify methods of reducing the organization''s attack surface&#160;<span>in response to a hostile environment.</span></li></ul><b>Additional References:</b></div><div><ul><li><span>NIST CSF References: PR.AT</span></li></ul><p></p><p></p></div>' WHERE [Mat_Question_Id] = 1884 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<div><b>CERT-RMM Reference</b></div><div>Consider ensuring that situational awareness activities are adequately funded. Funding the process should extend beyond the initial development of situational awareness activities, tools, and processes to ensure that the organization maintains a capability to ensure the resilience of essential services.</div><div><span><br></span></div><div><b>Additional References:</b></div><div><ul><li>NIST CSF References: ID.GV-4</li></ul></div>' WHERE [Mat_Question_Id] = 1885 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<div><b>CERT-RMM Reference</b></div><div>Consider managing risk from the failure of the situational awareness process. Failures can&#160;<span>occur in:</span></div><div><ul><li>planning for the process</li><li>making decisions about the process</li><li>making commitments to plans and activities as well as the process plan</li><li>effective communication about cyber security</li><li>development of a common operating picture</li><li>development of effective plans to reduce the organization''s attack surface.</li></ul></div><div><b>Additional References:</b></div><div><ul><li>NIST CSF References: ID.GV-4, ID.RA-6</li></ul></div>' WHERE [Mat_Question_Id] = 1886 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<b>CERT-RMM Reference</b><div>Consider measuring the situational awareness process against its process description,&#160;<span>standards, and procedures, and address non-compliance. Examples of measurement&#160;</span><span>include:</span><p class="p1"></p><ul><li>number of sources of cyber security evaluated for trustworthiness&#160;</li><li>percentage of stakeholders who receive cyber security information within the defined thresholds</li><li>percentage of services that have attack surface reduction plans</li><li>number of stakeholders who seek situational awareness information out on a daily basis.</li></ul><p></p><b>Additional References:</b></div><div><ul><li><span>NIST CSF References: PR.IP-7</span></li></ul></div>' WHERE [Mat_Question_Id] = 1887 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<b>CERT-RMM Reference</b><p class="p1">Consider objectively evaluating adherence of the situational awareness process against its&#160;<span>process description, standards, and procedures, and address non-compliance.</span></p><b>Additional References:</b><div><ul><li><span>NIST CSF References: PR.IP-7</span></li></ul></div>' WHERE [Mat_Question_Id] = 1888 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<b>CERT-RMM Reference</b><p class="p1">Consider ensuring that the organization Reviews the activities, status, and results of the&#160;<span>situational awareness process with higher-level managers and resolves issues.</span></p><b>Additional References:</b><div><ul><li><span>NIST CSF References: PR.IP-8</span></li></ul><p></p></div>' WHERE [Mat_Question_Id] = 1889 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<b>CERT-RMM Reference</b><div>Consider establishing an organization-wide approach to situational awareness, that includes:<ul><li>selecting from the organization''s set of standard processes those processes that cover&#160;<span>the situational awareness process and best meet the needs of the organizational unit&#160;</span><span>or line of business.</span></li><li>establishing the defined process by tailoring the selected processes according to the&#160;<span>organization''s tailoring guidelines.</span></li><li>ensuring that the organization''s process objectives are appropriately addressed in the&#160;<span>defined process, and ensure that process governance extends to the tailored&#160;</span><span>processes.</span></li><li>documenting the defined process and the records of the tailoring.</li><li>revising the description of the defined process as necessary.</li></ul><p></p><b>Additional References:</b></div><div><ul><li><span>NIST CSF References: PR.IP</span></li></ul><p></p></div>' WHERE [Mat_Question_Id] = 1890 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<b>CERT-RMM Reference</b><p class="p1">Consider collecting situational awareness work products, measures, measurement results,&#160;<span>and improvement information derived from planning and performing the process to&#160;</span><span>support future use and improvement of the organization''s processes and process assets.</span></p><b>Additional References:</b><div><ul><li><span>NIST CSF References: PR.IP</span></li></ul><p></p></div>' WHERE [Mat_Question_Id] = 1891 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<div><b>CERT-RMM Reference</b></div>&#10;&#10;    <p><b>[CTRL:SG3.SP1]</b> Analyze existing controls against control objectives. Identify gaps where&#10;enterprise control objectives for the resilience of services and assets and service control objectives are not&#10;adequately satisfied by existing controls.</p>&#10;&#10;<div><b>Additional References:</b></div>&#10;<ul>&#10;    <li>&#10;        Special Publication 800-30 &#34;Guide for Conducting Risk Assessments&#34;&#10;    </li>&#10;    <li>&#10;        NIST CSF References: PR.IP-7&#10;    </li>&#10;</ul>' WHERE [Mat_Question_Id] = 3199 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<div><b>CERT-RMM Reference<br></b></div>&#10;<p><b>[CTRL:SG3.SP1]</b> Analyze existing controls against control objectives. Identify gaps&#10;where enterprise control objectives for the resilience of services and assets and service&#10;control objectives are not adequately satisfied by existing controls.&#10;</p>&#10;&#10;<div><b>Additional References:</b></div>&#10;<ul>&#10;    <li>&#10;        Special Publication 800-30 &#34;Guide for Conducting Risk Assessments&#34;&#10;    </li>&#10;    <li>&#10;        NIST CSF References: PR.IP-7&#10;    </li>&#10;</ul>' WHERE [Mat_Question_Id] = 3200 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<font size="3"><span><b>CERT-RMM Reference<br>[CTRL:SG3.SP1]</b></span> Analyze existing controls against control objectives. Identify gaps where enterprise control objectives for the resilience of services and assets and service control objectives are not </font><font size="3">adequately satisfied by existing controls.</font><div><font size="3"><br></font><font size="3"><span><b>Additional References:</b></span><br><ul><li><font size="3">Special Publication 800-30 &#34;Guide for Conducting Risk Assessments&#34;</font></li><li><font size="3">NIST CSF References: PR.IP-7</font></li></ul></font></div>' WHERE [Mat_Question_Id] = 3201 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<span><b>CERT-RMM Reference<br>[CTRL:SG3.SP1]</b></span> Analyze existing controls against control objectives. Identify gaps where enterprise control objectives for the resilience of services and assets and service control objectives are not adequately satisfied by existing controls.<br><span><b>Additional References:</b></span><br><ul><li>Special Publication 800-30 &#34;Guide for Conducting Risk Assessments&#34;</li><li>NIST CSF References: PR.IP-7</li></ul>' WHERE [Mat_Question_Id] = 3203 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<span><b>CERT-RMM Reference&#160;</b></span><div><b>[CTRL:SG4.SP1]&#160;</b>&#160;Perform control assessments. Performing periodic assessment of the internal control system is necessary to ensure that controls continue to meet control objectives, that control objectives continue to implement strategies for protecting and sustaining services (and their supporting assets), and that resilience requirements are satisfied. Various assessment techniques can be used ranging from informal, self assessments to more structured formal assessments against established standards.Affinity analysis, interviews, and surveys may provide useful insight. In addition, results from business impact analyses, risk assessments, and internal audits and external audits(refer to the Compliance process area) can contribute.&#160;</div><div><br></div><div><span><b>Additional References:</b></span></div><div><ul><li>Special Publication 800-39 &#34;Managing Information Security Risk Organization, Mission, and Information System View&#34; Page 46-48&#160;</li><li>NIST CSF References: PR.IP-7</li></ul></div>' WHERE [Mat_Question_Id] = 3207 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<span><span><b>CERT-RMM Reference&#160;</b></span></span><div><span><b>[CTRL:SG4.SP1]&#160;</b></span>&#160;Perform control assessments. Performing periodic assessment of the internal control system is necessary to ensure that controls continue to meet control objectives, that control objectives continue to implement strategies for protecting and sustaining services (and their supporting assets), and that resilience requirements are satisfied. Various assessment techniques can be used ranging from informal, self assessments to more structured formal assessments against established standards.Affinity analysis, interviews, and surveys may provide useful insight. In addition, results from business impact analyses, risk assessments, and internal audits and external audits(refer to the Compliance process area) can contribute.&#160;</div><div><br></div><div><span><b>Additional References:</b></span></div><div><ul><li>Special Publication 800-39 &#34;Managing Information Security Risk Organization, Mission, and Information System View&#34; Page 46-48&#160;</li><li>NIST CSF References: PR.IP-7</li></ul></div>' WHERE [Mat_Question_Id] = 3208 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<span><span><b>CERT-RMM Reference&#160;</b></span></span><div><b>[CTRL:SG4.SP1]</b>&#160;&#160;Perform control assessments. Performing periodic assessment of the internal control system is necessary to ensure that controls continue to meet control objectives, that control objectives continue to implement strategies for protecting and sustaining services (and their supporting assets), and that resilience requirements are satisfied. Various assessment techniques can be used ranging from informal, self assessments to more structured formal assessments against established standards.Affinity analysis, interviews, and surveys may provide useful insight. In addition, results from business impact analyses, risk assessments, and internal audits and external audits(refer to the Compliance process area) can contribute.&#160;</div><div><br></div><div><span><b>Additional References:</b></span></div><div><ul><li>Special Publication 800-39 &#34;Managing Information Security Risk Organization, Mission, and Information System View&#34; Page 46-48&#160;</li><li>NIST CSF References: PR.IP-7</li></ul></div>' WHERE [Mat_Question_Id] = 3209 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<b>CERT-RMM Reference</b><br><b>[ADM:SG3.SP2]</b> Maintain a requirement change history with rationale for performing the changes. Change management for resilience requirements is a continuous process and therefore requires that the organization effectively assign responsibility and accountability for it. The organization must independently monitor that the change management process is operational and that asset-level resilience requirements have been updated on a regular basis so that they remain in direct alignment with organizational drivers.<div><br><b>Additional References:</b><br><ul><li>NIST SP 800-53 Rev. 4 CM-3</li><li>NIST CSF References: PR.IP-3</li></ul></div>' WHERE [Mat_Question_Id] = 3224 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<b>CERT-RMM Reference<br>[RRM:SG1.SP3] </b>Evaluate the impact of requirement changes on existing activities and commitments for protecting and sustaining assets and services. The organization must independently monitor that the change management process is operational and that asset-level resilience requirements have been updated on a regular basis so that they remain in direct alignment with organizational drivers.<div><br><div><b>Additional References</b><br><ul><li>NIST SP 800-53 Rev. 4 CM-3</li><li>NIST CSF References: PR.IP-3</li></ul></div></div>' WHERE [Mat_Question_Id] = 3228 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<div><b>CERT-RMM Reference</b></div><div><b>[TM:SG4.SP3] </b>Track the status of change requests to closure. Ensure that all change&#160;<span>requests have a disposition and that changes that have not been closed are provided an&#160;</span><span>updated status.</span></div><div><br></div><div><b>Additional References:</b></div><div><ul><li>NIST SP 800-53 Rev. 4 CM-3</li><li>NIST CSF References: PR.IP-3</li></ul></div>' WHERE [Mat_Question_Id] = 3233 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<div><b>CERT-RMM Reference</b></div><div><b>[ADM:SG3.SP2] </b>Establish communication channels to ensure custodians are aware of changes in assets.&#160;&#160;</div><div><br></div><div><b>Additional References:</b></div><div><ul><li>NIST SP 800-53 Rev. 4 CM-3</li><li>NIST CSF References: PR.IP-3</li></ul></div>' WHERE [Mat_Question_Id] = 3234 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<b>CERT-RMM Reference<br>[TM:SG4.SP2] </b>Create baseline configuration items. Establishing a technology asset baseline (commonly called a configuration item) provides a foundation for managing the integrity of the asset as it changes over its life cycle.<div><br><b>Additional References:</b><br><ul><li>Special Publication 800-70 &#34;National Checklist Program for IT Products: Guidelines for Checklist Users and Developers&#34;</li><li>NIST CSF References: PR.IP-1</li></ul><div><br></div></div>' WHERE [Mat_Question_Id] = 3236 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<div><b>CERT-RMM Reference</b></div><div><b>[TM:SG4.SP3]</b> Develop and implement change control policies, procedures, and</div><div>techniques. Change requests address not only new or changed requirements but also</div><div>maintenance and/or failures in the technology assets. Changes are evaluated to ensure</div><div>that they are consistent with all technical and resilience requirements.</div><div><b><br></b></div><div><b>Additional References:</b></div><div><ul><li>NIST SP 800-53 Rev. 4 CM-2</li><li>NIST CSF References: PR.DS-6, PR.DS-8</li></ul></div>' WHERE [Mat_Question_Id] = 3237 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<div><b>CERT-RMM Reference</b></div><div><b>[TM:SG4.SP2], [TM:SG4.SP3]</b> Review configuration control logs and identify anomalies.&#160;<span>Periodically verify (through monitoring and auditing) that changes to configurations are&#160;</span><span>valid and authorized.</span></div><div><br></div><div>Analyze the impact of changes proposed in the change requests. Change requests are&#160;<span>analyzed to determine the impact that the change will have on the resilience&#160;</span><span>requirements, budget, and schedule. Changes are also evaluated for their impact beyond&#160;</span><span>immediate project or contract requirements. Changes to a technology used in multiple&#160;</span><span>services can resolve an immediate issue while causing a problem in other applications.&#160;</span><span>Obtain agreement and approval for changes to baselines from relevant stakeholders.</span></div><div><br></div><div><b>Additional References:</b></div><div><ul><li>NIST SP 800-53 Rev. 4 CM-3</li><li>NIST CSF References: PR.IP-1, PR.IP-3</li></ul></div>' WHERE [Mat_Question_Id] = 3238 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<div><b>CERT-RMM Reference</b></div><div><b>[TM:SG4.SP2 ], [ TM:SG4.SP3] </b>Perform configuration audits. Regularly audit the integrity&#160;<span>of the configuration item baselines to ensure that they are complete and correct and that&#160;</span><span>they continue to meet configuration management standards and procedures. Identify&#160;</span><span>action items that are required to repair any anomalies.</span></div><div><br></div><div><b>Additional References:</b></div><div><ul><li>NIST SP 800-53 Rev. 4 CM-3 and CM-9</li><li>NIST CSF References: PR.IP-3</li></ul></div>' WHERE [Mat_Question_Id] = 3241 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<font color="#000000"><b>CERT-RMM Reference&#160;</b></font><div><font color="#000000"><b>[TM:SG4.SP4]&#160;</b></font><div><font color="#000000">Test release builds. To minimize operational impact, the organization must&#160;</font><font color="#000000">test the release build in a segregated test environment to identify issues, concerns, and&#160;</font><font color="#000000">problems that may cascade into other operational areas when the build is released. Once&#160;</font><font color="#000000">all operational issues have been defined and addressed (in some cases by &#8220;rebuilding&#8221; the&#160;</font><font color="#000000">build), the organization can proceed to move the release build into the production&#160;</font><font color="#000000">environment.&#160;</font><br><font color="#000000"><span><br></span></font><font color="#000000"><span><b>Additional References:</b></span></font><ul><li><span>NIST SP 800-53 Rev. 4 CM-3</span></li><li><font color="#000000"><span>NIST CSF References: PR.DS-7</span></font></li></ul><p></p></div></div>' WHERE [Mat_Question_Id] = 3242 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<div><b>CERT-RMM Reference</b></div><div><b>[TM:SG4.SP2]</b> Create baseline configuration items. Establishing a technology asset&#160;<span>baseline (commonly called a configuration item) provides a foundation for managing the&#160;</span><span>integrity of the asset as it changes over its life cycle.</span></div><div><b><br></b></div><div><b>Additional References:</b></div><div><ul><li>Special Publication 800-70 &#34;National Checklist Program for IT Products: Guidelines for Checklist Users and Developers&#34;</li><li>NIST CSF References: PR.IP-1</li></ul></div>' WHERE [Mat_Question_Id] = 3247 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<div><b>CERT-RMM Reference</b></div><div>Consider ensuring that responsible staff are trained in skills required in the configuration</div><div>and change management process. Examples of these skills include:</div><div><ul><li>knowledge of the tools, techniques, and methods necessary to manage base line configurations</li><li>knowledge necessary to work effectively with asset owners and custodians</li><li>knowledge necessary to elicit and prioritize stakeholder requirements and needs and interpret them to develop effective requirements, plans, and programs for the process</li></ul></div><div><b>Additional References:</b></div><div><ul><li>NIST CSF References: PR.AT</li></ul></div>' WHERE [Mat_Question_Id] = 3258 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<div><b>CERT-RMM Reference</b></div><div><b>[VAR:SG1.SP2] </b>Identify the tools, techniques, and methods that the organization will use&#160;<span>to identify vulnerabilities to assets. The organization should compile a list of approved and&#160;</span><span>recommended tools, techniques, and methods that can be used for vulnerability activities.&#160;</span><span>Pre-approving tools, techniques, and methods ensures consistency and cost-effectiveness,&#160;</span><span>as well as validity of results. This list should cover the entire range of assets and include&#160;</span><span>both procedural and automated methods.</span></div><div><b><br></b></div><div><b>Additional References:</b></div><div><ul><li>Special Publication 800-40 Version &#34;Guide to Enterprise Patch Management Technologies&#34;</li><li>NIST CSF References: DE.CM</li></ul></div>' WHERE [Mat_Question_Id] = 3271 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<div><b>CERT-RMM References</b></div><div><b>[VAR:SG1.SP2]</b> Identify the tools, techniques, and methods that the organization will use&#160;<span>to identify malicious code in assets. The organization should compile a list of approved and&#160;</span><span>recommended tools, techniques, and methods to be used for this activity. Pre-approving&#160;</span><span>tools, techniques, and methods ensures consistency and cost-effectiveness, as well as&#160;</span><span>validity of results. This list should cover the entire range of applicable assets and include&#160;</span><span>both procedural and automated methods.</span></div><div><br></div><div><b>Additional References:</b></div><div><ul><li>NIST SP 800-53 Rev. 4 SI-3: Consider employing malicious code protection mechanisms at information system entry and exit points to detect and eradicate malicious code. Once implemented perform periodic scans to detect malicious code.</li><li>NIST CSF References: DE.CM-4</li></ul></div>' WHERE [Mat_Question_Id] = 3276 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<div><b>CERT-RMM Reference</b></div><div><b>[VAR:SG2.SP1]</b> Review sources on a regular basis and update as necessary. New sources&#160;<span>of vulnerability information are continually emerging. The organization must review the&#160;</span><span>sources and add them to its source list to be sure to have access to the most current,&#160;</span><span>accurate, and extensive information about vulnerabilities.</span></div><div><b><br></b></div><div><b>Additional References:</b></div><div><ul><li>Special Publication 800-40 &#34;Guide to Enterprise Patch Management Technologies&#34;</li><li>NIST CSF References: DE.DP-5, PR.IP-7, RS.AN-5</li></ul></div>' WHERE [Mat_Question_Id] = 3282 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<div><b>CERT-RMM Reference</b></div><div><b>[VAR:SG2.SP1] </b>Review sources on a regular basis and update as necessary. New sources&#160;<span>of vulnerability information are continually emerging. The organization must review the&#160;</span><span>sources and add them to its source list to be sure to have access to the most current,&#160;</span><span>accurate, and extensive information about vulnerabilities.</span></div><div><br></div><div><b>Additional References:</b></div><div><ul><li>Special Publication 800-40 &#34;Guide to Enterprise Patch Management Technologies&#34;</li><li>NIST CSF References: DE.DP-5, PR.IP-7, RS.AN-5</li></ul></div>' WHERE [Mat_Question_Id] = 3283 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<div><b>CERT-RMM Reference</b></div><div><b>[VAR:SG2.SP2] </b>Discover vulnerabilities. Data collection should be coordinated to discover&#160;<span>vulnerabilities and populate the vulnerability repository as efficiently as possible.</span></div><div><br></div><div><b>Additional References:&#160;</b></div><div><ul><li>Special Publication 800-137 &#34;Information Security Continuous Monitoring (ISCM) for Federal Information Systems and Organizations&#34; Page 33</li><li>NIST CSF References: DE.CM-8, ID.RA-1, RS.AN-5</li></ul></div>' WHERE [Mat_Question_Id] = 3287 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<div><b>CERT-RMM Reference</b></div><div><b>[VAR:SG2.SP3] </b>Analyze the structure and action of the vulnerability. This may require the&#160;<span>vulnerability to be decomposed into other artifacts such as threat, threat actor, motive,&#160;</span><span>and potential outcome. In addition, relationships between vulnerabilities may be&#160;</span><span>identified that could indicate similar root causes or origins that must be considered in&#160;</span><span>resolution actions.</span></div><div><b><br></b></div><div><b>Additional References:</b></div><div><ul><li>NIST CSF References: RS.AN-5</li></ul></div>' WHERE [Mat_Question_Id] = 3295 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<div><b>CERT-RMM Reference</b></div><div><b>[VAR:SG2.SP2] </b>Establishes a vulnerability repository as the central source of vulnerability&#160;<span>life-cycle information and populates the vulnerability repository. Basic information that&#160;</span><span>should be collected about vulnerabilities include:</span></div><div><ul><li>a unique organizational identifier for internal reference</li><li>description of the vulnerability</li><li>date entered to the repository</li><li>references to the source of the vulnerability</li><li>the importance of the vulnerability to the organization (critical, moderate, etc.)</li><li>individuals or teams assigned to analyze and remediate the vulnerability</li><li>a log of remediation actions taken to reduce or eliminate the vulnerability</li></ul></div><div><b>Additional References:&#160;</b></div><div><ul><li>Special Publication 800-40 &#34;Guide to Enterprise Patch Management Technologies&#34;</li><li>NIST CSF References: ID.RA-1, RS.AN-5</li></ul></div>' WHERE [Mat_Question_Id] = 3299 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<b>CERT-RMM Reference<br></b><b>[VAR:SG3.SP1]</b> Analyze the effectiveness of vulnerability management strategies to ensure&#160;<span>that objectives are achieved.<br></span><b><br></b><div><b>Additional References:</b><ul><li>Special Publication 800-40 &#34;Guide to Enterprise Patch Management Technologies&#34;</li><li>NIST CSF References: DE.DP-5, PR. IP-7, RS.IM</li></ul><p class="p1"></p><p></p></div>' WHERE [Mat_Question_Id] = 3304 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<div><b>CERT-RMM Reference</b></div><div><b>[VAR:SG3.SP1]</b> Monitor the status of open vulnerabilities.</div><div><b><br></b></div><div><b>Additional References:</b></div><div><ul><li>Special Publication 800-137 &#34;Information Security Continuous Monitoring (ISCM) for Federal Information Systems and Organizations&#34; Page 33&#160;</li><li>NIST CSF References: RS.AN-5</li></ul></div>' WHERE [Mat_Question_Id] = 3305 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<b>CERT-RMM Reference</b><br><b>[IMC:SG1.SP1]</b> Establish the incident management plan. The incident management plan should address at a minimum:<br>&#8226; the organization&#8217;s philosophy for incident management<br>&#8226; the structure of the incident management process<br>&#8226; the requirements and objectives of the incident management process relative to managing operational resilience<br>&#8226; a description of how the organization will identify incidents, analyze them, and respond to them<br>&#8226; the roles and responsibilities necessary to carry out the plan<br>&#8226; applicable training needs and requirements<br>&#8226; resources that will be required to meet the objectives of the plan<br>&#8226; relevant costs and budgets associated with incident management activities<br><b><br></b><div><b>Additional References:</b><br><ul><li>Special Publication 800-61 &#34;Computer Security Incident Handling guide&#34;&#160;</li><li>Handbook for Computer Security Incident Response Teams (CSIRTs)</li><li>NIST CSF References: DE.DP-1, PR.IP-9, ID.SC-5</li></ul></div>' WHERE [Mat_Question_Id] = 3320 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<b>CERT-RMM Reference<br>[IMC:SG1.SP1]</b> Revise the plan and commitments as necessary.<br><b><br></b><div><b>Additional References:</b><br><ul><li>NIST SP 800-53 Rev. 4 IR-8</li><li>NIST CSF References: DE.DP-5, PR.IP-10, ID.SC-5</li></ul></div>' WHERE [Mat_Question_Id] = 3321 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='CERT-RMM Reference<div>[IMC:SG1.SP2] Develop detailed job descriptions for each role and responsibility detailed in the incident management plan.</div><div><b><br></b></div><div><b>Additional References:</b></div><div><ul><li>Special Publication 800-61 &#34;Computer Security Incident Handling guide&#34; Section 2.4</li><li>Handbook for Computer Security Incident Response Teams (CSIRTs) Page 41</li><li>NIST CSF References: DE.DP-1, PR.IP-11</li></ul></div>' WHERE [Mat_Question_Id] = 3322 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<b>CERT-RMM Reference<br>[IMC:SG1.SP2]</b> Assign staff to incident management roles and responsibilities.<br><b><br></b><div><b>Additional References:</b><br><ul><li>Special Publication 800-61 &#34;Computer Security Incident Handling guide&#34; Section 2.4</li><li>Handbook for Computer Security Incident Response Teams (CSIRTs) Page 41</li><li>NIST CSF References: DE.DP-1, RS.CO-1</li></ul></div>' WHERE [Mat_Question_Id] = 3323 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<b>CERT-RMM Reference</b><div><b>[IMC:SG2.SP1] </b>Define the methods of event detection and reporting.</div><div><br></div><div><b>Additional References:</b></div><div><ul><li>Special Publication 800-61 &#34;Computer Security Incident Handling guide&#34; Section 2.3</li><li>Handbook for Computer Security Incident Response Teams (CSIRTs)</li><li>NIST CSF References: DE.CM-1, DE.CM-2, DE.CM-3, DE.DP-4, RS.CO-2</li></ul></div>' WHERE [Mat_Question_Id] = 3324 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<b>CERT-RMM Reference</b><div><b>[IMC:SG2.SP4]</b> Perform correlation analysis on event reports to determine if there is affinity between two or more events.</div><div><br></div><div><b>Additional References:</b></div><div><ul><li>Special Publication 800-61 &#34; Computer Security Incident Handling guide&#34; Section 3.4</li><li>Handbook for Computer Security Incident Response Teams (CSIRTs) Page 69-70</li><li>NIST CSF References: DE.AE-2, DE.AE-3</li></ul></div>' WHERE [Mat_Question_Id] = 3327 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<b>CERT-RMM Reference</b><div><b>[IMC:SG2.SP4]</b> Assign events that have not been assigned a &#8220;closed&#8221; status for further analysis and resolution. Possible dispositions for event reports include:</div><div>&#8226; closed</div><div>&#8226; referred for further analysis</div><div>&#8226; referred to organizational unit or line of business for disposition</div><div>&#8226; declared as incident and referred to incident handling and response process</div><div><br></div><div><b>Additional References:</b></div><div><ul><li>Special Publication 800-61 &#34;Computer Security Incident Handling guide&#34; Section 3</li><li>Handbook for Computer Security Incident Response Teams (CSIRTs) Page 153</li><li>NIST CSF References: DE.AE-3</li></ul></div>' WHERE [Mat_Question_Id] = 3329 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<b>CERT-RMM Reference</b><div><b>[IMC:SG2.SP4]</b> Periodically review the incident knowledge base for events that have not been closed or for which there is no disposition. Events that have not been closed or that do not have a disposition should be reprioritized and analyzed for resolution.</div><div><br></div><div><b>Additional References:</b></div><div><ul><li>Special Publication 800-61 &#34;Computer Security Incident Handling guide&#34; Section 3.4</li><li>Handbook for Computer Security Incident Response Teams (CSIRTs) Page 155-156</li><li>NIST CSF References: DE.AE-3, RS.AN-1</li></ul></div>' WHERE [Mat_Question_Id] = 3330 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<b>CERT-RMM Reference</b><div><b>[IMC:SG2.SP3]</b> Document events and related evidence information in the incident management knowledge base where practical. Rules, laws, regulations, and policies may require specific documentation for forensic purposes. These specific requirements must be included in the organization&#8217;s logging and tracking process. Some information about events may be confidential or sensitive, so the organization must be careful to appropriately limit access to event information to only those who need to know about it.</div><div><br></div><div><b>Additional References:</b></div><div><ul><li>Special Publication 800-61 &#34;Computer Security Incident Handling guide&#34; Section 3</li><li>Handbook for Computer Security Incident Response Teams (CSIRTs) Page 26</li><li>NIST CSF References: ID.GV-3, RS.AN-3</li></ul></div>' WHERE [Mat_Question_Id] = 3332 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<p><font size="3"><b>CERT-RMM Reference<br></b></font><span><b>[IMC:SG3.SP1]</b> Establish a process to declare incidents. Incident declaration defines the&#160;</span><span>point at which the organization has established that an incident has occurred, is occurring,&#160;</span><span>or is imminent, and will need to be handled and responded to. The time from event&#160;</span>detection to incident declaration may be immediate, requiring little additional review and analysis. In other cases, incident declaration requires more thoughtful analysis.<b><br></b></p><b>Additional References:</b><div><ul><li><span>Special Publication 800-61 &#34;Computer Security Incident Handling guide&#34; Section 3.2</span></li><li>Handbook for Computer Security Incident Response Teams (CSIRTs) Page 77-79</li><li>NIST CSF References: RS.CO-2</li></ul><p></p></div>' WHERE [Mat_Question_Id] = 3333 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<b>CERT-RMM Reference</b><div><b>[IMC.SG3.SP1]</b> Establish incident declaration criteria for use in guiding when to declare an incident. To guide the organization in determining when to declare an incident (particularly if incident declaration is not immediately apparent), the organization must define incident declaration criteria.<div><br></div><div><b>Additional References:</b></div><div><ul><li>Special Publication 800-61 &#34;Computer Security Incident Handling guide&#34; Section 3.2.6</li><li>Handbook for Computer Security Incident Response Teams (CSIRTs) Page 77-79</li><li>NIST CSF References: DE.AE-5</li></ul></div></div>' WHERE [Mat_Question_Id] = 3334 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<div><b><span>CERT-RMM Reference<br>[IMC:SG3.SP2]</span>&#160;</b>Identify relevant analysis tools, techniques, and activities that the organization will use to analyze incidents and develop appropriate responses.<br><span><b><br></b></span><div><span><b>Additional References:</b></span><br><ul><li>Special Publication 800-61 &#34;Computer Security Incident Handling guide&#34; Section 3.1.1</li><li>Handbook for Computer Security Incident Response Teams (CSIRTs) Page 79-91</li><li>NIST CSF References: RS.AN-2, RS.AN-4</li></ul></div></div><span><b><div><span><b><br></b></span></div></b></span><br>' WHERE [Mat_Question_Id] = 3335 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<div><span><b>CERT-RMM Reference</b></span><div><span><b>[IMC:SG4.SP1]</b></span>&#160;Develop incident escalation procedures. Incident escalation procedures should consider the type and extent of incident and the appropriate stakeholders. Incidents that the organization has declared and which require an organizational response must be escalated to those stakeholders who can implement, manage, and bring to closure an appropriate and timely solution.</div><div><br></div><div><span><b>Additional References:</b></span></div><div><ul><li>Special Publication 800-61 &#34;Computer Security Incident Handling guide&#34; Section 3.2.6</li><li>Handbook for Computer Security Incident Response Teams (CSIRTs) Page 128-132</li><li>NIST CSF References: RS.CO-4</li></ul></div></div><b><div><b><br></b></div><br></b>' WHERE [Mat_Question_Id] = 3336 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<p><b>CERT-RMM Reference<br>[IMC:SG4.SP2] </b>Develop an incident response strategy and plan to limit incident effect&#10;    and&#10;    to repair incident damage. The incident response strategy and plan should address at a minimum:&#10;&#10;</p><ul>&#10;    <li>the essential&#10;        activities (administrative, technical, and physical) that are required to contain or limit damage and provide&#10;        service&#10;        continuity</li>&#10;    <li>existing continuity of operations and restoration plans in the organization&#8217;s plan inventory</li>&#10;    <li>the&#10;        resources and skills required to perform the incident response strategy and plan</li>&#10;    <li>coordination activities with other&#10;        internal staff and external agencies that must be performed to implement the strategy</li>&#10;    <li>the levels of authority and&#10;        access needed by responders to carry out the strategy and plan</li>&#10;    <li>objectives for measuring when the strategy and plan&#10;        are successful</li>&#10;    <li>the estimated cost of implementing the strategy and plan</li>&#10;    <li>the essential activities necessary to&#10;        restore services to normal operation (recovery), the resources involved in these activities, and their estimated&#10;        cost</li>&#10;    <li>legal and regulatory obligations that must be met by the strategy</li>&#10;    <li>standardized responses for certain&#10;        types of incidents</li>&#10;</ul>&#10;<p></p>&#10;&#10;<b>Additional References:</b><br>&#10;<ul>&#10;    <li>Special Publication 800-61 &#34;Computer Security Incident Handling guide&#34; Section 3.1</li>&#10;    <li>NIST CSF References: RS.MI-1, RS.RP-1</li>&#10;</ul>' WHERE [Mat_Question_Id] = 3337 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<b>CERT-RMM Reference<br>[IMC:SG4.SP3] </b>Develop and implement an organizational incident management communications plan. The incident communications plan should address the stakeholders with whom communications about incidents are required.<br><b><br></b><div><b>Additional References:</b><br><ul><li>Special Publication 800-61 &#34;Computer Security Incident Handling guide&#34; Section 2.3.1</li><li>Handbook for Computer Security Incident Response Teams (CSIRTs) Page 92-99</li><li>NIST CSF References: RC.CO-1, RC.CO-3, RS.CO-3</li></ul></div>' WHERE [Mat_Question_Id] = 3338 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<div><b>CERT-RMM Reference</b></div><div><b>[IMC:SG4.SP4]</b> Track incidents that have been open for an extended period of time without&#160;<span>closure and resolve. Incidents that appear to be open for an extended period of time may&#160;</span><span>not have followed the organization&#8217;s incident management process or may not have been&#160;</span><span>formally closed. The status of incidents in the incident database should be reviewed&#160;</span><span>regularly to determine if open incidents should be closed or need additional action.</span></div><div><br></div><div><b>Additional References:</b></div><div><ul><li>Special Publication 800-61 &#34;Computer Security Incident Handling guide&#34;&#160;</li><li>Handbook for Computer Security Incident Response Teams (CSIRTs)</li><li>NIST CSF References: RS.MI-1, RS.MI-2</li></ul></div>' WHERE [Mat_Question_Id] = 3339 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<font color="#000000" size="3"><b>CERT-RMM Reference<br></b></font><font color="#000000" size="3"><b>[IMC:SG5.SP3] </b>Review incident knowledge base information and update the following&#160;</font><font color="#000000" size="3">areas accordingly:<br></font><font color="#000000" size="3">&#8226; protection strategies and controls for assets involved in the incident<br></font><font color="#000000" size="3">&#8226; continuity plans and strategies for sustaining assets involved in the incident<br></font><font color="#000000" size="3">&#8226; information security and other organizational policies that need to reflect new&#160;</font><font color="#000000" size="3">standards, procedures, and guidelines based on what is learned in the incident&#160;</font><font color="#000000" size="3">handling<br></font><font color="#000000" size="3">&#8226; training for staff on information security, business continuity, and IT operations<br></font><font color="#000000" size="3"><b><br></b></font><div><font color="#000000" size="3"><b>Additional References:</b><br><ul><li><font color="#000000" size="3">NIST SP 800-53 Rev. 4 IR-4</font></li><li><font color="#000000" size="3">NIST CSF References: DE.DP-5, PR.IP-7, RS.IM-1, RS.IM-2</font></li></ul></font></div>' WHERE [Mat_Question_Id] = 3342 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<div><b>CERT-RMM Reference</b></div><div>Consider measuring the performance of incident management activities. Incident&#160;<span>management activities may include:</span></div><div>&#8226; percentage of operational time that high-value services and assets were unavailable&#160;<span>(as seen by users and customers) due to incidents</span></div><div>&#8226; percentage of incidents that exploited existing vulnerabilities with known solutions,&#160;<span>patches, or workarounds</span></div><div>&#8226; number and percentage of events or incidents handled in a specific period</div><div>&#8226; number and percentage of events or incidents that are contained in a specific period</div><div>&#8226; percentage of incidents that require escalation</div><div>&#8226; percentage of incidents that require involvement of law enforcement</div><div>&#8226; number of events or incidents that have been logged but not closed</div><div>&#8226; average time between event detection and related incident declaration, response, or&#160;<span>closure</span></div><div>&#8226; percentage increase in the volume of events and incidents in a specific period</div><div>&#8226; extent of consequences to the organization due to incidents by incident type (also&#160;<span>referred to as &#8220;magnitude&#8221;)</span></div><div>&#8226; percentage increase in the elapsed time of the incident life cycle by incident type</div><div>&#8226; number and percentage of recurrence of specified events or incidents</div><div>&#8226; percentage increase in resource needs (training, skill building, additional human&#160;<span>resources) to support incident management</span></div><div>&#8226; number of post-incident review activities that result in control changes or&#160;<span>improvements to the process</span></div><div>&#8226; number of incidents referred to the risk management process; number of risks where&#160;<span>corrective action is still pending (by risk rank)</span></div><div>&#8226; level of adherence to process policies; number of policy violations; number of policy&#160;<span>exceptions requested and number approved</span></div><div>&#8226; number of process activities that are on track per plan</div><div>&#8226; rate of change of resource needs to support the process</div><div>&#8226; rate of change of costs to support the process</div><div><b><br></b></div><div><b>Additional References:</b></div><div><ul><li>NIST CSF References: DE.DP-3, PR.IP-7</li></ul></div>' WHERE [Mat_Question_Id] = 3351 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<div><b>CERT-RMM Reference</b></div><div>Consider ensuring that the organization reviews the activities, status, and results of the&#160;<span>incident management process with higher-level managers and resolves issues.</span></div><div><b><br></b></div><div><b>Additional References:</b></div><div>NIST CSF References: PR.IP-8</div>' WHERE [Mat_Question_Id] = 3353 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<b>CERT-RMM Reference<br></b>Consider establishing an organization-wide approach to incident management, that&#160;<span>includes:<br></span>&#8226; selecting from the organization&#8217;s set of standard processes those processes that cover&#160;<span>the incident management process and best meet the needs of the organizational unit&#160;</span><span>or line of business.<br></span>&#8226; establishing the defined process by tailoring the selected processes according to the&#160;<span>organization&#8217;s tailoring guidelines.<br></span>&#8226; ensuring that the organization&#8217;s process objectives are appropriately addressed in the&#160;<span>defined process, and ensure that process governance extends to the tailored&#160;</span><span>processes.<br></span>&#8226; documenting the defined process and the records of the tailoring.<br>&#8226; revising the description of the defined process as necessary.<br><b><br></b><b>Additional References:</b><ul><li>NIST CSF References: PR.IP</li></ul><p></p><p class="p1"></p><p></p>' WHERE [Mat_Question_Id] = 3354 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<div><b>CERT-RMM Reference</b></div><div>Consider collecting incident management work products, measures, measurement results,&#160;<span>and improvement information derived from planning and performing the process to&#160;</span><span>support future use and improvement of the organization&#8217;s processes and process assets.</span></div><div><b><br></b></div><div><b>Additional References:</b></div><div><ul><li>NIST CSF References: PR.IP</li></ul></div>' WHERE [Mat_Question_Id] = 3355 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<div><b>CERT-RMM Reference</b></div><div><b>[RISK:SG1.SP1]</b> Determine operational risk sources. Risk sources are the fundamental&#160;<span>areas of risk that can affect organizational services and associated assets while they are in&#160;</span><span>operation to meet the organization''s mission. Risk sources represent common areas&#160;</span><span>where risks may originate. Typical internal and external sources include:</span></div><div><ul><li>poorly designed and executed business processes and services</li><li>inadvertent actions of people, such as accidental disclosures or modifications of information</li><li>intentional actions of people, such as insider threat and fraud</li><li>failure of systems to perform as intended, or risks posed by the complexity and unpredictability of interconnected systems</li><li>failures of technology, such as the unanticipated results of the execution of software and the failure of hardware components such as servers and telecommunications</li><li>external events and forces, such as natural disasters, failures of public infrastructure, and failures in the organization''s supply chain</li></ul></div><div>Advance definition of specific risk sources for the organization provides a means for early&#160;<span>identification of risk and can seed mitigation plans that can cover a broad array of&#160;</span><span>operational risks before the organization realizes the consequences of these risks.</span></div><div><span><br></span></div><div><b>Additional References:</b></div><div><ul><li>Special Publication 800-37 Revision 1 &#34;Guide for Applying the Risk Management Framework to Federal Information Systems&#34; Page 6-8</li><li>NIST CSF References: ID.RM, ID.SC-1</li></ul></div>' WHERE [Mat_Question_Id] = 3389 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='CERT-RMM Reference<br>[RISK:SG1.SP2] Develop and document an operational risk management strategy that<br>aligns with the organization''s overall enterprise risk management strategy. Because of<br>the pervasive nature of operational risk, a comprehensive operational risk management<br>strategy is needed to ensure proper consideration of risk and the effects on operational<br>resilience. The strategy provides a common foundation for the performance of<br>operational risk management activities and for the collection, coordination, and elevation<br>of operational risk to the organization''s risk management process.<br>Additional References<br>Special Publication 800-39 &#34;Managing Information Security Risk Organization, Mission, and<br>Information System View&#34; Page 7-9<br>NIST CSF References: ID.GV-4, ID.RM-1, ID.SC-1' WHERE [Mat_Question_Id] = 3391 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='CERT-RMM Reference<br>[RISK:SG1.SP2] Communicate the operational risk management strategy to relevant<br>stakeholders and obtain their commitment to the activities. The strategy should be<br>documented and communicated to all relevant stakeholders, internal and external, who<br>are responsible for any operational risk management activity.<br>Additional References<br>Special Publication 800-39 &#34;Managing Information Security Risk Organization, Mission, and<br>Information System View&#34; Page 9-11<br>NIST CSF References: ID.RM-1, ID.SC-1' WHERE [Mat_Question_Id] = 3392 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='CERT-RMM Reference<br>[RISK:SG2.SP2] Define organizational impact areas. Organizational impact areas identify<br>the categories where realized risk may have meaningful and disruptive consequences.<br>These areas typify what is important to the organization and to the accomplishment of its<br>mission.<br>Additional References<br>Special Publication 800-39 &#34;Managing Information Security Risk Organization, Mission, and<br>Information System View&#34; Page 9-11<br>&#34;Introducing OCTAVE Allegro: Improving the Information Security Risk Assessment<br>Process&#34;<br>NIST CSF References: ID.RA-4, RC.CO-2' WHERE [Mat_Question_Id] = 3393 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='CERT-RMM Reference<br>[RISK:SG2.SP2] Prioritize areas of impact for the organization. The prioritization of impact<br>areas allows the organization to determine the relative importance of these areas to allow<br>them to be used for risk prioritization and mitigation.<br>Additional References<br>Special Publication 800-39 &#34;Managing Information Security Risk Organization, Mission, and<br>Information System View&#34; Page 37-40<br>NIST CSF References: ID.RA-4, ID.RM' WHERE [Mat_Question_Id] = 3394 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='CERT-RMM Reference<br>[RISK:SG2.SP2] Define and document risk measurement and evaluation criteria. Risk<br>measurement and evaluation criteria provide the bounds on the severity of consequences<br>to the organization across the organizationally defined areas of impact. The consistent<br>application of these criteria across all operational risks ensures that risks are prioritized<br>according to organizational importance (even if they are specific to an organizational unit<br>or line of business) and are mitigated accordingly. The range of criteria can be either<br>qualitative (high, medium, low) or quantitative (based on levels of loss, fines, number of<br>customers lost, etc.).<br>Additional References<br>FIPS Publication 199 Standards for Security Categorization of Federal Information and<br>Information Systems Page 2<br>&#34;Introducing OCTAVE Allegro: Improving the Information Security Risk Assessment<br>Process&#34; Page 32-33<br>NIST CSF References: ID.RM-2, ID.RM-3' WHERE [Mat_Question_Id] = 3395 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='CERT-RMM Reference<br>[RISK:SG3.SP2] Identify the services that are associated with each asset-specific risk<br>statement. Update the risk statement to reflect associated services. Examining risk in the<br>context of services provides the organization additional information that must be<br>considered when prioritizing risks for disposition and mitigation.<br>Additional References<br>Special Publication 800-30 &#34;Guide for Conducting Risk Assessments&#34;<br>&#34;Introducing OCTAVE Allegro: Improving the Information Security Risk Assessment<br>Process&#34;<br>NIST CSF References: ID.RA-5' WHERE [Mat_Question_Id] = 3397 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='CERT-RMM Reference<br>[RISK:SG4.SP3] Assign a risk disposition to each risk statement based on risk valuation and<br>prioritization and obtain approval for the proposed disposition of each risk, particularly<br>risks that are not going to be mitigated. A risk disposition is assigned to each risk<br>statement or group of statements. The organization must establish a range of acceptable<br>and consistent risk dispositions and their definitions. Possible risk dispositions include:<br>&#8226; avoid<br>&#8226; accept<br>&#8226; monitor<br>&#8226; research or defer<br>&#8226; transfer<br>&#8226; mitigate or control.<br>Risks that are to be accepted must be approved by a sufficient level of organizational<br>management that accepts responsibility and authority for the potential impact on<br>operational resilience that could result. Risks that are to be transferred must demonstrate<br>a clear and willing party (organization or person) able to accept the risk. Risks that are to<br>be researched or deferred must be carefully examined to ensure that delaying mitigation<br>will not result in the realization of the risk or effects on operational resilience.<br>Additional References<br>Special Publication 800-30 &#34;Guide for Conducting Risk Assessments&#34;<br>&#34;Introducing OCTAVE Allegro: Improving the Information Security Risk Assessment<br>Process&#34; Appendix I Page 58-64<br>NIST CSF References: ID.RA-6' WHERE [Mat_Question_Id] = 3399 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='CERT-RMM Reference<br>[RISK:SG5.SP1] Develop risk mitigation plans for all risks that have a &#8220;mitigation&#8221; or<br>&#8220;control&#8221; disposition. Developing risk mitigation plans is an extensive activity that will vary<br>by organization. There are some common elements of risk mitigation plans that should be<br>considered for all plans:<br>&#8226; how the threat or vulnerability will be reduced<br>&#8226; the actions that will prevent or limit an actor from exploiting a threat or vulnerability<br>&#8226; the controls that will have to be implemented or updated to reduce exposure,<br>including an articulation of administrative, physical, and technical controls<br>&#8226; the service continuity plans that would be used to reduce the impact of consequences<br>should risk be realized<br>&#8226; the staff who are responsible for implementing and monitoring the mitigation plan<br>&#8226; the cost of the plan, and a cost-benefit analysis that demonstrates the value of the<br>plan commensurate with the value of the related assets and services or avoidance of<br>consequences<br>&#8226; the implementation specifics of the plan (when, where, how)<br>&#8226; the residual risk that would not be addressed by the plan<br>Additional References<br>Special Publication 800-30 &#34;Guide for Conducting Risk Assessments&#34;<br>NIST CSF References: ID.RA-6, ID.RM' WHERE [Mat_Question_Id] = 3400 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='CERT-RMM Reference<br>[RISK:SG5.SP2] Provide a method for tracking open risks to closure.<br>Additional References<br>Special Publication 800-137 &#34;Information Security Continuous Monitoring (ISCM) for<br>Federal Information Systems and Organizations&#34; Page 19-36<br>NIST CSF References: ID.RA-6, ID.RM' WHERE [Mat_Question_Id] = 3401 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='CERT-RMM Reference<br>Consider identifying stakeholders of the risk management process. These are examples of<br>stakeholders:<br>&#8226; organizational unit managers, line of business managers, project managers, and<br>business process owners<br>&#8226; owners of identified assets and services (for which plans to manage risks must be<br>developed)<br>&#8226; custodians of identified assets and services (who may need to execute or participate in<br>plans)<br>&#8226; staff involved in identifying, analyzing, mitigating, and controlling risks to assets and<br>services (such as information technology, human resources, legal, and compliance<br>staff)<br>&#8226; staff involved in reviewing and adjusting strategies to protect and sustain assets and<br>services<br>&#8226; the owner of any resilience management process who has referred risks to the process<br>&#8226; risk owners<br>&#8226; risk mitigation plan owners<br>Additional References<br>NIST CSF References: ID.AM-6, ID.GV-2, PR.AT' WHERE [Mat_Question_Id] = 3404 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='CERT-RMM Reference<br>[EXD:SG3.SP3] Evaluate external entities based on their abilities to meet the resilience<br>specifications and in accordance with the established selection criteria.<br>Additional References<br>Special Publication 800-39 &#34;Managing Information Security Risk Organization, Mission, and<br>Information System View&#34; Page 24-26<br>NIST CSF References: ID.BE-1, ID.BE-4, ID.SC-3' WHERE [Mat_Question_Id] = 3421 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='CERT-RMM Reference<br>[EXD:SG3.SP4] Properly document the agreement terms, conditions, specifications and<br>other provisions. All agreement provisions should be documented in the agreement in<br>language that is unambiguous. The agreement should not contain any general exceptions<br>for achieving the resilience specifications unless they are carefully considered and<br>negotiated. It may, however, contain scenarios of types of unforeseen events for which<br>the external entity is not expected to prepare. Any exceptions granted to resilience<br>specifications or scenarios for which the external entity is not required to prepare should<br>be treated as risks. All agreements should establish and enable procedures for monitoring<br>the performance of external entities and inspecting the services or products they deliver<br>to the organization.<br>Additional References<br>NIST SP 800-53 Rev. 4 SA-4<br>NIST CSF References: ID.BE-1, ID.SC-3, PR.AT-3' WHERE [Mat_Question_Id] = 3422 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='CERT-RMM Reference<br>[EXD:SG4.SP1] Establish procedures and responsibility for monitoring external entity<br>performance and inspecting any external entity deliverables. Procedures should be<br>consistent with the agreement between the organization and the external entity and<br>should be based on verifying that the external entity is achieving the specifications as<br>defined in the agreement. All agreement specifications should be considered for<br>monitoring; it may be appropriate to prioritize monitoring and inspection activities based<br>on a risk analysis of the specifications (which includes all external dependencies).<br>Monitoring and inspection procedures should address the external entity''s required<br>characteristics, required behaviors, and required performance parameters.<br>Additional References<br>NIST CSF References: DE.CM-6, ID.SC-4' WHERE [Mat_Question_Id] = 3423 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='CERT-RMM Reference<br>[EXD:SG4.SP1] Establish the responsibility for monitoring external entity performance and<br>inspecting any external entity deliverables. (Responsibility is typically assigned to the<br>organizational owner of the relationship.)<br>Additional References<br>NIST SP 800-53 Rev. 4 SA-9<br>NIST CSF References: ID.SC-4' WHERE [Mat_Question_Id] = 3424 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='CERT-RMM Reference<br>[EXD:SG4.SP2] The agreement should be reviewed to identify appropriate and allowable<br>corrective actions for consideration. The various alternatives should be evaluated based<br>on their likelihood to succeed in correcting the situation and mitigating any associated<br>risks. It may be valuable and appropriate to include the external entity in the discussion<br>and consideration of alternatives, especially if both the organization and the external<br>entity desire to continue the relationship.<br>Additional References<br>NIST SP 800-53 Rev. 4 SA-12<br>NIST CSF References: ID.SC-4' WHERE [Mat_Question_Id] = 3425 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='CERT-RMM Reference<br>[EXD:SG4.SP2] Monitor as appropriate to ensure that issues are remedied in a timely<br>manner.<br>Additional References<br>NIST SP 800-53 Rev. 4 SA-13<br>NIST CSF References: ID.SC-4' WHERE [Mat_Question_Id] = 3426 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='CERT-RMM Reference<br>[EC:SG4.SP3] Identify and document public services on which facilities rely. Typically, this<br>activity results from business impact analysis. However, it can be included as part of<br>service continuity planning or facility asset definition, depending on the organization. A<br>resulting list of public services for each facility should be documented and made available<br>for inclusion in service continuity plans as appropriate.<br>Additional References<br>Special Publication 800-34 &#34;Contingency Planning for Federal Information Systems&#34;<br>Page 53-55<br>NIST CSF References: ID.BE-4' WHERE [Mat_Question_Id] = 3427 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='CERT-RMM Reference<br>[EC:SG4.SP4] Identify and document infrastructure dependencies that the organization<br>relies upon to provide services. Remember that these dependencies may be internal as<br>well as external, particularly where the organization has control over certain aspects of<br>facility infrastructure such as power or telecommunications that they provide for their<br>own operations.<br>Typically, this activity results from business impact analysis. However, it can be included as<br>part of service continuity planning or facility asset definition, depending on the<br>organization. A resulting list of public infrastructure providers for each facility should be<br>documented and made available for inclusion in service continuity plans as appropriate.<br>Additional References<br>NIST SP 800-53 Rev. 4 CP-2<br>NIST CSF References: ID.BE-4' WHERE [Mat_Question_Id] = 3428 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='CERT-RMM Reference<br>Consider developing a plan for external dependency management. A plan for performing<br>the external dependencies management process is developed to ensure that the<br>organization can satisfy its operational resilience requirements when an external entity<br>has access to, control of, ownership in, possession of, responsibility for (including<br>development, operations, maintenance, or support), or other defined obligations related<br>to one or more assets or services of the organization. The plan must address the<br>enterprise and resilience specifications for the service being performed or the product<br>being provided (i.e., the external dependency) by the external entity. In addition, because<br>external entities can be located in many geographical locations, the plan must address<br>those external entities and stakeholders that can enable or adversely affect operational<br>resilience. The plan for the external dependencies management process should not be<br>confused with service continuity (recovery, restoration) plans for assets and services that<br>are under the control of external entities. The plan for the external dependencies<br>management process details how the organization will manage external dependencies and<br>relationships with external entities, including the development of service continuity plans<br>where such entities are involved.<br>Subpractices:<br>&#8226; define and document the plan for performing the process.<br>&#8226; define and document the process description.<br>&#8226; review the plan with relevant stakeholders and get their agreement.<br>&#8226; revise the plan as necessary.<br>Additional References<br>NIST CSF References: ID.SC' WHERE [Mat_Question_Id] = 3429 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='CERT-RMM Reference<br>Consider developing policies and procedures for external dependency management. The<br>external dependencies management policy should address:<br>&#8226; responsibility, authority, and ownership for performing process activities<br>&#8226; procedures, standards, and guidelines for:<br>- identifying and prioritizing external dependencies<br>- associating external dependencies with services and assets<br>- managing operational risks resulting from external dependencies<br>- evaluating and selecting external entities<br>- formalizing and enforcing agreements with external entities, including changing any<br>provisions by mutual agreement<br>- developing and documenting enterprise and resilience specifications for external<br>entities, including organizational policies to which external entities are expected to<br>adhere<br>- standards of performance and service levels<br>- establishing service continuity plans and procedures for external entities<br>- monitoring the performance of external entities, including inspecting the services or<br>products they deliver (Such procedures specify frequency, protocol, and<br>responsibility for monitoring and inspection.)<br>- terminating relationships with external entities as specified in formal agreements<br>- issue escalation and dispute resolution<br>&#8226; requesting, approving, providing, and terminating access for external entities<br>&#8226; methods for measuring adherence to policy, exceptions granted, and policy violations<br>Additional References<br>NIST CSF References: ID.GV-1, PR.IP' WHERE [Mat_Question_Id] = 3430 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='CERT-RMM Reference<br>Consider identifying stakeholders of the external dependency management process.<br>Examples include:<br>&#8226; internal and external owners and custodians of organizational assets<br>&#8226; internal and external service owners<br>&#8226; organizational unit and line of business managers responsible for high-value assets<br>and the services they support<br>&#8226; staff responsible for managing operational risks arising from external dependencies<br>and relationships with external entities<br>&#8226; staff responsible for establishing, implementing, and maintaining an internal control<br>system for organizational assets where an external dependency and an external entity<br>are involved<br>&#8226; staff required to develop, test, implement, and execute service continuity plans that<br>involve external dependencies and external entities<br>&#8226; acquisition and procurement staff<br>&#8226; internal and external auditors<br>Additional References<br>NIST CSF References: ID.AM-6, ID.GV-2, PR.AT' WHERE [Mat_Question_Id] = 3431 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='CERT-RMM Reference<br>Consider ensuring that the organization reviews the activities, status, and results of the<br>external dependency management process with higher-level managers and resolves<br>issues.<br>Additional References<br>NIST CSF References: PR.IP-8' WHERE [Mat_Question_Id] = 3439 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='CERT-RMM Reference<br>[OTA:SG1.SP1] Analyze the organization''s operational resilience program to identify the<br>types and extent of awareness efforts that are necessary to satisfy resilience program<br>objectives. Because managing operational resilience requires acculturation of both<br>internal and external parties (staff), the types and extent of awareness efforts may need to<br>be extensive and rigorous. The objectives of awareness efforts must be clearly stated and<br>must help the organization achieve inculcation of staff to the organization''s philosophy of<br>managing operational resilience.<br>Additional References<br>Special Publication 800-16 Revision 1 (DRAFT) &#34;A Role-Based Model for Federal<br>Information Technology/Cybersecurity Training (3rd Draft)&#34;<br>NIST CSF References: PR.AT-1' WHERE [Mat_Question_Id] = 3442 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='CERT-RMM Reference<br>[HRM:SG1.SP2] Establish and document baseline competencies necessary to meet the<br>needs of the organization''s operational resilience management process. Baseline<br>competencies may be as detailed as the organization needs to describe its required skill<br>sets. This may involve many layers of information, including role (security administrator,<br>network administrator, CIO, etc.) and position (CIO, senior security analyst, network<br>engineer, etc.).<br>Additional References<br>Special Publication 800-16 Revision 1 (DRAFT) &#34;A Role-Based Model for Federal<br>Information Technology/Cybersecurity Training (3rd Draft)&#34;<br>NIST CSF References: PR.AT-1' WHERE [Mat_Question_Id] = 3443 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='CERT-RMM Reference<br>[OTA:SG3.SP1] Collect information about skill gaps, cross-training, and succession<br>planning by reviewing the job responsibilities of staff involved in resilience processes, as<br>well as current performance levels.<br>Additional References<br>Special Publication 800-16 Revision 1 (DRAFT) &#34;A Role-Based Model for Federal<br>Information Technology/Cybersecurity Training (3rd Draft)&#34;<br>NIST CSF References: PR.AT-1' WHERE [Mat_Question_Id] = 3444 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='CERT-RMM Reference<br>[OTA:SG3.SP1] Document the resilience training needs of the organization.<br>The training needs should focus not only on the skills and knowledge needed to perform<br>particular roles in the supporting disciplines of security, business continuity, and IT<br>operations and service delivery, but also on the convergence aspects of these disciplines<br>toward operational resilience management. The training needs should also adequately<br>cover the capabilities represented by the operational resilience management process.<br>Additional References<br>Special Publication 800-16 Revision 1 (DRAFT) &#34;A Role-Based Model for Federal<br>Information Technology/Cybersecurity Training (3rd Draft)&#34;<br>NIST CSF References: PR.AT-1' WHERE [Mat_Question_Id] = 3445 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='CERT-RMM Reference<br>[OTA:SG2.SP1] Perform awareness activities according to the schedule and the plan.<br>Awareness materials are distributed to the target populations according to the schedule<br>and the approaches established in the plan.<br>Additional References<br>Special Publication 800-16 Revision 1 (DRAFT) &#34;A Role-Based Model for Federal<br>Information Technology/Cybersecurity Training (3rd Draft)&#34;<br>NIST CSF References: PR.AT-1' WHERE [Mat_Question_Id] = 3446 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='<font face="Arial">CERT-RMM Reference<br></font><font face="Arial">[OTA:SG2.SP3], [OTA:SG4.SP3] Provide a mechanism for evaluating the effectiveness of<br></font><font face="Arial">each awareness activity with respect to the objectives for that activity. For awareness<br></font><font face="Arial">presentations, this mechanism should include evaluations of the material and the<br></font><font face="Arial">presenters.<br></font><font face="Arial">Provide a mechanism for assessing the effectiveness of each training course with respect<br></font><font face="Arial">to established organizational, project, or individual learning (or performance) objectives.<br></font><font face="Arial">Additional References<br></font><font face="Arial">Special Publication 800-16 Revision 1 (DRAFT) &#34;A Role-Based Model for Federal<br></font><font face="Arial">Information Technology/Cybersecurity Training (3rd Draft)&#34;<br></font><font face="Arial">NIST CSF References: PR.AT, PR.IP-7</font>' WHERE [Mat_Question_Id] = 3448 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='CERT-RMM Reference<br>[OTA:SG4.SP1] Conduct privileged user training. The organization must perform training to<br>ensure staff are appropriately skilled in their roles. Experienced instructors should perform<br>training. When possible, training is conducted in settings that closely resemble actual<br>performance conditions and includes activities to simulate actual work situations. This<br>approach includes integration of tools, methods, and procedures for competency<br>development. Training is tied to work responsibilities so that on-the-job activities or other<br>outside experiences will reinforce the training within a reasonable time after the training<br>is completed.<div><br><div>Additional References<br>Special Publication 800-16 Revision 1 (DRAFT) &#34;A Role-Based Model for Federal<br>Information Technology/Cybersecurity Training (3rd Draft)&#34;<br>NIST SP 800-53 Rev. 4 AT-3, PM-13<br>Consider providing role-based security training to privileged users with assigned security<br>roles and responsibilities. Comprehensive role-based training addresses management,<br>operational, and technical roles and responsibilities. Role-based security training also<br>applies to contractors providing services. Training should be provided before access is<br>authorized and periodically thereafter.<br>NIST CSF References: PR.AT-2</div></div>' WHERE [Mat_Question_Id] = 3450 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='CERT-RMM Reference<br>Consider developing a plan for training and awareness.<br>&#8226; special consideration in the plan may have to be given to training and awareness for<br>skill development, sustaining skill competencies, and reassignment planning for<br>various roles. These activities aid in protecting and sustaining people to support<br>operational resilience.<br>&#8226; special consideration in the plan may also have to be given to how the organization<br>incorporates training and awareness activities for resources that are not under its<br>direct control, including external entities such as contractors, outsourcing partners,<br>training suppliers, and other business partners.<br>&#8226; define and document the process description.<br>&#8226; review the plan with relevant stakeholders and get their agreement.<br>&#8226; revise the plan as necessary.<br>Additional References<br>NIST CSF References: PR.AT' WHERE [Mat_Question_Id] = 3453 AND [Sequence] = 1
UPDATE [dbo].[MATURITY_REFERENCE_TEXT] SET [Reference_Text]='CERT-RMM Reference<br>Consider identifying stakeholders of the training and awareness process. Examples<br>include:<br>&#8226; staff who are required to determine the degree to which their constituencies<br>understand the organization''s resilience goals, objectives, standards, policies, and<br>processes, including:<br>- asset owners and custodians<br>- service owners<br>- business process owners<br>- organizational unit and line of business managers responsible for high-value services<br>and assets<br>&#8226; external entities responsible for managing high-value assets and services<br>&#8226; human resources (for ensuring the resilience of people assets)<br>&#8226; information technology staff (for ensuring the resilience of technology assets)<br>&#8226; staff responsible for physical security (for ensuring the resilience of facility assets)<br>&#8226; internal and external auditors<br>Additional References<br>NIST CSF References: ID.AM-6, ID.GV-2, PR.AT' WHERE [Mat_Question_Id] = 3455 AND [Sequence] = 1
PRINT(N'Operation applied to 101 rows out of 101')

PRINT(N'Update rows in [dbo].[MATURITY_QUESTIONS]')
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><b>Question Intent:&#160;</b></div><div><br></div><div>To determine if control objectives for the critical service have been established.</div><div><br></div><div>Control objectives are important because controls are designed to meet those objectives.</div><div><ul><li>Control objectives provide a set of high-level requirements for the protection and sustainment of a critical service and associated assets.</li><li>Sources for identifying control objectives may be found in governance documents, policy documents, etc.</li></ul></div><br><table class="MsoNormalTable" border="1" cellspacing="0" cellpadding="0"><tbody><tr><td width="83" valign="top"><p class="TableParagraph" align="right"><b><span>Asset<span> </span><span>Type</span></span></b><b><span></span></b></p></td><td width="270" valign="top"><p class="TableParagraph"><b><span>Control<span> </span>Objective<span> </span>Example</span></b><b><span></span></b></p></td></tr><tr><td width="83" valign="top"><p class="TableParagraph" align="right"><b>People</b><br></p></td><td width="270" valign="top"><p class="TableParagraph"></p><ul><li><span>Ensure all employees are trustworthy<span> </span>and<span> </span>reliable<span> </span>prior<span> </span>to<span> </span>hiring them.</span></li><li><span>All<span> </span>outside<span> </span>support<span> </span>personnel<span> </span>are<span> </span>identified.</span></li></ul><p></p></td></tr><tr><td width="83" valign="top"><p class="TableParagraph" align="right"><b><span>Information</span></b><b><span></span></b></p></td><td width="270" valign="top"><p class="TableParagraph"></p><ul><li><span>Ensure the confidentiality and integrity<span> </span>of<span> </span>customer&#8217;s<span> </span>payment<span> </span>information.</span></li><li><span>Information assets are disposed of<span> </span>according to<span> </span>policy.</span></li></ul><span></span><p></p><p class="TableParagraph"><span></span></p></td></tr><tr><td width="83" valign="top"><p class="TableParagraph" align="right"><b><span>Technology</span></b><b><span></span></b></p></td><td width="270" valign="top"><p class="TableParagraph"></p><ul><li><span>Ensure<span> </span>the<span> </span>databases<span> </span>that<span> </span>support<span> </span>one<span> </span>or more critical services remain<span> </span>available.</span></li><li><span>Network integrity<span> </span>is<span> </span>protected.</span></li></ul><p></p></td></tr><tr><td width="83" valign="top"><p class="TableParagraph" align="right"><b><span>Facilities</span></b><b><span></span></b></p></td><td width="270" valign="top"><p class="TableParagraph"></p><ul><li><span>Ensure environmental systems are<span> </span>maintained<span> </span>at<span> </span>an<span> </span>appropriate<span> </span>level<span> </span>to<span> </span>support<span> </span>datacenter<span> </span>equipment.</span></li><li><span>Physical<span> </span>access<span> </span>to<span> </span>assets<span> </span>is<span> </span>managed<span> </span>and protected.</span></li></ul><span></span><p></p><p class="TableParagraph"><span></span></p></td></tr></tbody></table><b><br></b><div><div><b>Criteria for &#8220;Yes&#8221; Response:</b></div><div><ul><li>Control objectives are established for all assets (people, information, technology, and facilities).</li><li>And; all control objectives are documented.</li></ul></div><div><b>Criteria for &#8220;Incomplete&#8221; Response:</b></div><div><ul><li>Control objectives are established for some assets.</li></ul></div></div>' WHERE [Mat_Question_Id] = 1830
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><b>Question Intent:&#160;<br><br></b></div><div>To determine if the assets that support the critical service are inventoried.</div><div><ul><li>The organization should inventory the assets (people, information, technology, and facilities)&#160;<span>required for the delivery of the critical service.</span></li><li>Inventories of assets may exist in multiple forms or physical locations.</li></ul></div><div><br></div><div><b>Criteria for &#8220;Yes&#8221; Response:<br><br></b></div><div><ul><li><span>The organization inventories all assets that support the critical service.</span></li></ul></div><div><span><br></span></div><div><b>Criteria for &#8220;Incomplete&#8221; Response:<br><br></b></div><div><ul><li>The organization inventories some assets.</li></ul></div>' WHERE [Mat_Question_Id] = 3134
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><b>Question Intent:&#160;<br><br></b></div><div>To determine if the assets that support the critical service are inventoried.</div><div><ul><li>The organization should inventory the assets (people, information, technology, and facilities)&#160;<span>required for the delivery of the critical service.</span></li><li>Inventories of assets may exist in multiple forms or physical locations.</li></ul></div><div><br></div><div><b>Criteria for &#8220;Yes&#8221; Response:<br><br></b></div><div><ul><li><span>The organization inventories all assets that support the critical service.</span></li></ul></div><div><span><br></span></div><div><b>Criteria for &#8220;Incomplete&#8221; Response:<br><br></b></div><div><ul><li>The organization inventories some assets.</li></ul></div>' WHERE [Mat_Question_Id] = 3135
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><b>Question Intent:&#160;<br><br></b></div><div>To determine if the assets that support the critical service are inventoried.</div><div><ul><li>The organization should inventory the assets (people, information, technology, and facilities)&#160;<span>required for the delivery of the critical service.</span></li><li>Inventories of assets may exist in multiple forms or physical locations.</li></ul></div><div><br></div><div><b>Criteria for &#8220;Yes&#8221; Response:<br><br></b></div><div><ul><li><span>The organization inventories all assets that support the critical service.</span></li></ul></div><div><span><br></span></div><div><b>Criteria for &#8220;Incomplete&#8221; Response:<br><br></b></div><div><ul><li>The organization inventories some assets.</li></ul></div>' WHERE [Mat_Question_Id] = 3136
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><b>Question Intent:&#160;<br><br></b></div><div>To determine if the assets that support the critical service are inventoried.</div><div><ul><li>The organization should inventory the assets (people, information, technology, and facilities)&#160;<span>required for the delivery of the critical service.</span></li><li>Inventories of assets may exist in multiple forms or physical locations.</li></ul></div><div><br></div><div><b>Criteria for &#8220;Yes&#8221; Response:<br><br></b></div><div><ul><li><span>The organization inventories all assets that support the critical service.</span></li></ul></div><div><span><br></span></div><div><b>Criteria for &#8220;Incomplete&#8221; Response:<br><br></b></div><div><ul><li>The organization inventories some assets.</li></ul></div>' WHERE [Mat_Question_Id] = 3137
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><b>Question Intent:&#160;</b></p><p class="p1">To determine if asset descriptions include protection and sustainment requirements.</p><p class="p1"></p><ul><li><span>Including protection and sustainment requirements in asset descriptions provides a common source for&#160;</span>communicating and updating those requirements.</li><li>The confidentiality, integrity, and availability requirements of the service are used to derive the collective protection and sustainment requirements of associated assets.</li><li>Activities that implement protection and sustainment requirements often appear as processes, procedures, policies, controls, and plans.</li><li>Protection requirements describe how an asset''s exposure to sources of disruption and to the exploitation of vulnerabilities must be minimized. Examples include:</li><ul><li>People - Ensure all employees are skilled in their role to protect against accidental disruption.</li><li>Information - All information assets will be disposed of according to policy to prevent unintentional disclosure.&#160;</li><li>Technology - All network boundaries should be protected using approved methods and tools to deny unauthorized access.</li><li>Facilities - Physical access to all service related information and technology assets must be limited to approved personnel to protect against accidental and malicious disruption.</li></ul><li>Sustainment requirements describe how assets must be kept operating when faced with disruptive&#160;<span>events. Examples include:</span></li><ul><li>People - All critical personnel shall have a designated backup who can fulfill their service continuity&#160;<span>role.&#160;</span></li><li>Information - No more than 4 hours of the critical service data can be lost to ensure the continuity of&#160;<span>the service.</span></li><li>Technology - The technology assets required for the delivery of the critical service must be&#160;<span>operational within 48 hours to ensure the continuity of the service.</span></li><li>Facilities - The backup facility must meet the service continuity requirements of the critical service.</li></ul></ul><p class="p1"><br></p><p class="p1"><b>Criteria for &#8220;Yes&#8221; Response:</b></p><p class="p1">The organization documents protection and sustainment requirements in asset descriptions for all&#160;<span>assets supporting the critical service.</span></p><p class="p1"><span><br></span></p><p class="p1"><b>Criteria for &#8220;Incomplete&#8221; Response:</b></p><p class="p1">The organization documents protection and sustainment requirements in asset descriptions for some&#160;<span>assets.</span></p>' WHERE [Mat_Question_Id] = 3138
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><b>Question Intent:&#160;</b></p><p class="p1">To determine if asset descriptions include protection and sustainment requirements.</p><p class="p1"></p><ul><li><span>Including protection and sustainment requirements in asset descriptions provides a common source for&#160;</span>communicating and updating those requirements.</li><li>The confidentiality, integrity, and availability requirements of the service are used to derive the collective protection and sustainment requirements of associated assets.</li><li>Activities that implement protection and sustainment requirements often appear as processes, procedures, policies, controls, and plans.</li><li>Protection requirements describe how an asset''s exposure to sources of disruption and to the exploitation of vulnerabilities must be minimized. Examples include:</li><ul><li>People - Ensure all employees are skilled in their role to protect against accidental disruption.</li><li>Information - All information assets will be disposed of according to policy to prevent unintentional disclosure.&#160;</li><li>Technology - All network boundaries should be protected using approved methods and tools to deny unauthorized access.</li><li>Facilities - Physical access to all service related information and technology assets must be limited to approved personnel to protect against accidental and malicious disruption.</li></ul><li>Sustainment requirements describe how assets must be kept operating when faced with disruptive&#160;<span>events. Examples include:</span></li><ul><li>People - All critical personnel shall have a designated backup who can fulfill their service continuity&#160;<span>role.&#160;</span></li><li>Information - No more than 4 hours of the critical service data can be lost to ensure the continuity of&#160;<span>the service.</span></li><li>Technology - The technology assets required for the delivery of the critical service must be&#160;<span>operational within 48 hours to ensure the continuity of the service.</span></li><li>Facilities - The backup facility must meet the service continuity requirements of the critical service.</li></ul></ul><p class="p1"><br></p><p class="p1"><b>Criteria for &#8220;Yes&#8221; Response:</b></p><p class="p1">The organization documents protection and sustainment requirements in asset descriptions for all&#160;<span>assets supporting the critical service.</span></p><p class="p1"><span><br></span></p><p class="p1"><b>Criteria for &#8220;Incomplete&#8221; Response:</b></p><p class="p1">The organization documents protection and sustainment requirements in asset descriptions for some&#160;<span>assets.</span></p>' WHERE [Mat_Question_Id] = 3139
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><b>Question Intent:&#160;</b></p><p class="p1">To determine if asset descriptions include protection and sustainment requirements.</p><p class="p1"></p><ul><li><span>Including protection and sustainment requirements in asset descriptions provides a common source for&#160;</span>communicating and updating those requirements.</li><li>The confidentiality, integrity, and availability requirements of the service are used to derive the collective protection and sustainment requirements of associated assets.</li><li>Activities that implement protection and sustainment requirements often appear as processes, procedures, policies, controls, and plans.</li><li>Protection requirements describe how an asset''s exposure to sources of disruption and to the exploitation of vulnerabilities must be minimized. Examples include:</li><ul><li>People - Ensure all employees are skilled in their role to protect against accidental disruption.</li><li>Information - All information assets will be disposed of according to policy to prevent unintentional disclosure.&#160;</li><li>Technology - All network boundaries should be protected using approved methods and tools to deny unauthorized access.</li><li>Facilities - Physical access to all service related information and technology assets must be limited to approved personnel to protect against accidental and malicious disruption.</li></ul><li>Sustainment requirements describe how assets must be kept operating when faced with disruptive&#160;<span>events. Examples include:</span></li><ul><li>People - All critical personnel shall have a designated backup who can fulfill their service continuity&#160;<span>role.&#160;</span></li><li>Information - No more than 4 hours of the critical service data can be lost to ensure the continuity of&#160;<span>the service.</span></li><li>Technology - The technology assets required for the delivery of the critical service must be&#160;<span>operational within 48 hours to ensure the continuity of the service.</span></li><li>Facilities - The backup facility must meet the service continuity requirements of the critical service.</li></ul></ul><p class="p1"><br></p><p class="p1"><b>Criteria for &#8220;Yes&#8221; Response:</b></p><p class="p1">The organization documents protection and sustainment requirements in asset descriptions for all&#160;<span>assets supporting the critical service.</span></p><p class="p1"><span><br></span></p><p class="p1"><b>Criteria for &#8220;Incomplete&#8221; Response:</b></p><p class="p1">The organization documents protection and sustainment requirements in asset descriptions for some&#160;<span>assets.</span></p>' WHERE [Mat_Question_Id] = 3140
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><b>Question Intent:&#160;</b></p><p class="p1">To determine if asset descriptions include protection and sustainment requirements.</p><p class="p1"></p><ul><li><span>Including protection and sustainment requirements in asset descriptions provides a common source for&#160;</span>communicating and updating those requirements.</li><li>The confidentiality, integrity, and availability requirements of the service are used to derive the collective protection and sustainment requirements of associated assets.</li><li>Activities that implement protection and sustainment requirements often appear as processes, procedures, policies, controls, and plans.</li><li>Protection requirements describe how an asset''s exposure to sources of disruption and to the exploitation of vulnerabilities must be minimized. Examples include:</li><ul><li>People - Ensure all employees are skilled in their role to protect against accidental disruption.</li><li>Information - All information assets will be disposed of according to policy to prevent unintentional disclosure.&#160;</li><li>Technology - All network boundaries should be protected using approved methods and tools to deny unauthorized access.</li><li>Facilities - Physical access to all service related information and technology assets must be limited to approved personnel to protect against accidental and malicious disruption.</li></ul><li>Sustainment requirements describe how assets must be kept operating when faced with disruptive&#160;<span>events. Examples include:</span></li><ul><li>People - All critical personnel shall have a designated backup who can fulfill their service continuity&#160;<span>role.&#160;</span></li><li>Information - No more than 4 hours of the critical service data can be lost to ensure the continuity of&#160;<span>the service.</span></li><li>Technology - The technology assets required for the delivery of the critical service must be&#160;<span>operational within 48 hours to ensure the continuity of the service.</span></li><li>Facilities - The backup facility must meet the service continuity requirements of the critical service.</li></ul></ul><p class="p1"><br></p><p class="p1"><b>Criteria for &#8220;Yes&#8221; Response:</b></p><p class="p1">The organization documents protection and sustainment requirements in asset descriptions for all&#160;<span>assets supporting the critical service.</span></p><p class="p1"><span><br></span></p><p class="p1"><b>Criteria for &#8220;Incomplete&#8221; Response:</b></p><p class="p1">The organization documents protection and sustainment requirements in asset descriptions for some&#160;<span>assets.</span></p>' WHERE [Mat_Question_Id] = 3141
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><b>Question Intent:<span class="Apple-converted-space">&#160;</span></b></p><p class="p1">To determine if owners and custodians of assets are documented in asset descriptions.<span class="Apple-converted-space">&#160;</span></p><p class="p1"></p><ul><li>Asset owners are the people or organizational entities, internal or external to the organization, that have primary responsibility for the viability, productivity, and resilience of the asset. Example asset owners include:<span class="Apple-converted-space">&#160;</span></li><ul><li>service owners<span class="Apple-converted-space">&#160;</span></li><li>managers and staff supervisors<span class="Apple-converted-space">&#160;</span></li><li>organizational units<span class="Apple-converted-space">&#160;</span></li><li>lines of business<span class="Apple-converted-space">&#160;</span></li></ul><li>Asset custodians are people or organizational entities, internal or external to the organization, who are responsible for satisfying the protection and sustainment requirements for the asset established by the asset owner. Example asset custodians include:<span class="Apple-converted-space">&#160;</span></li><ul><li>system/database administrator<span class="Apple-converted-space">&#160;</span></li><li>facility manager<span class="Apple-converted-space">&#160;</span></li><li>IT support organization<span class="Apple-converted-space">&#160;</span></li><li>contractors hosting and managing data (e.g., cloud service provider)<span class="Apple-converted-space">&#160;</span></li></ul></ul><p class="p5"><b>Criteria for &#8220;Yes&#8221; Response:<span class="Apple-converted-space">&#160;</span></b></p><p class="p5"></p><ul><li>The organization documents owners and custodians in asset descriptions for all assets that support the critical service.<span class="Apple-converted-space">&#160;</span></li></ul><p></p><p class="p5"><b>Criteria for &#8220;Incomplete&#8221; Response:<span class="Apple-converted-space">&#160;</span></b></p><p class="p5"></p><ul><li>The organization documents owners and custodians in asset descriptions for some assets.<span class="Apple-converted-space">&#160;</span></li></ul><p></p>' WHERE [Mat_Question_Id] = 3142
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><b>Question Intent:<span class="Apple-converted-space">&#160;</span></b></p><p class="p1">To determine if owners and custodians of assets are documented in asset descriptions.<span class="Apple-converted-space">&#160;</span></p><p class="p1"></p><ul><li>Asset owners are the people or organizational entities, internal or external to the organization, that have primary responsibility for the viability, productivity, and resilience of the asset. Example asset owners include:<span class="Apple-converted-space">&#160;</span></li><ul><li>service owners<span class="Apple-converted-space">&#160;</span></li><li>managers and staff supervisors<span class="Apple-converted-space">&#160;</span></li><li>organizational units<span class="Apple-converted-space">&#160;</span></li><li>lines of business<span class="Apple-converted-space">&#160;</span></li></ul><li>Asset custodians are people or organizational entities, internal or external to the organization, who are responsible for satisfying the protection and sustainment requirements for the asset established by the asset owner. Example asset custodians include:<span class="Apple-converted-space">&#160;</span></li><ul><li>system/database administrator<span class="Apple-converted-space">&#160;</span></li><li>facility manager<span class="Apple-converted-space">&#160;</span></li><li>IT support organization<span class="Apple-converted-space">&#160;</span></li><li>contractors hosting and managing data (e.g., cloud service provider)<span class="Apple-converted-space">&#160;</span></li></ul></ul><p class="p5"><b>Criteria for &#8220;Yes&#8221; Response:<span class="Apple-converted-space">&#160;</span></b></p><p class="p5"></p><ul><li>The organization documents owners and custodians in asset descriptions for all assets that support the critical service.<span class="Apple-converted-space">&#160;</span></li></ul><p></p><p class="p5"><b>Criteria for &#8220;Incomplete&#8221; Response:<span class="Apple-converted-space">&#160;</span></b></p><p class="p5"></p><ul><li>The organization documents owners and custodians in asset descriptions for some assets.<span class="Apple-converted-space">&#160;</span></li></ul><p></p>' WHERE [Mat_Question_Id] = 3143
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><b>Question Intent:<span class="Apple-converted-space">&#160;</span></b></p><p class="p1">To determine if owners and custodians of assets are documented in asset descriptions.<span class="Apple-converted-space">&#160;</span></p><p class="p1"></p><ul><li>Asset owners are the people or organizational entities, internal or external to the organization, that have primary responsibility for the viability, productivity, and resilience of the asset. Example asset owners include:<span class="Apple-converted-space">&#160;</span></li><ul><li>service owners<span class="Apple-converted-space">&#160;</span></li><li>managers and staff supervisors<span class="Apple-converted-space">&#160;</span></li><li>organizational units<span class="Apple-converted-space">&#160;</span></li><li>lines of business<span class="Apple-converted-space">&#160;</span></li></ul><li>Asset custodians are people or organizational entities, internal or external to the organization, who are responsible for satisfying the protection and sustainment requirements for the asset established by the asset owner. Example asset custodians include:<span class="Apple-converted-space">&#160;</span></li><ul><li>system/database administrator<span class="Apple-converted-space">&#160;</span></li><li>facility manager<span class="Apple-converted-space">&#160;</span></li><li>IT support organization<span class="Apple-converted-space">&#160;</span></li><li>contractors hosting and managing data (e.g., cloud service provider)<span class="Apple-converted-space">&#160;</span></li></ul></ul><p class="p5"><b>Criteria for &#8220;Yes&#8221; Response:<span class="Apple-converted-space">&#160;</span></b></p><p class="p5"></p><ul><li>The organization documents owners and custodians in asset descriptions for all assets that support the critical service.<span class="Apple-converted-space">&#160;</span></li></ul><p></p><p class="p5"><b>Criteria for &#8220;Incomplete&#8221; Response:<span class="Apple-converted-space">&#160;</span></b></p><p class="p5"></p><ul><li>The organization documents owners and custodians in asset descriptions for some assets.<span class="Apple-converted-space">&#160;</span></li></ul><p></p>' WHERE [Mat_Question_Id] = 3144
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><b>Question Intent:<span class="Apple-converted-space">&#160;</span></b></p><p class="p1">To determine if owners and custodians of assets are documented in asset descriptions.<span class="Apple-converted-space">&#160;</span></p><p class="p1"></p><ul><li>Asset owners are the people or organizational entities, internal or external to the organization, that have primary responsibility for the viability, productivity, and resilience of the asset. Example asset owners include:<span class="Apple-converted-space">&#160;</span></li><ul><li>service owners<span class="Apple-converted-space">&#160;</span></li><li>managers and staff supervisors<span class="Apple-converted-space">&#160;</span></li><li>organizational units<span class="Apple-converted-space">&#160;</span></li><li>lines of business<span class="Apple-converted-space">&#160;</span></li></ul><li>Asset custodians are people or organizational entities, internal or external to the organization, who are responsible for satisfying the protection and sustainment requirements for the asset established by the asset owner. Example asset custodians include:<span class="Apple-converted-space">&#160;</span></li><ul><li>system/database administrator<span class="Apple-converted-space">&#160;</span></li><li>facility manager<span class="Apple-converted-space">&#160;</span></li><li>IT support organization<span class="Apple-converted-space">&#160;</span></li><li>contractors hosting and managing data (e.g., cloud service provider)<span class="Apple-converted-space">&#160;</span></li></ul></ul><p class="p5"><b>Criteria for &#8220;Yes&#8221; Response:<span class="Apple-converted-space">&#160;</span></b></p><p class="p5"></p><ul><li>The organization documents owners and custodians in asset descriptions for all assets that support the critical service.<span class="Apple-converted-space">&#160;</span></li></ul><p></p><p class="p5"><b>Criteria for &#8220;Incomplete&#8221; Response:<span class="Apple-converted-space">&#160;</span></b></p><p class="p5"></p><ul><li>The organization documents owners and custodians in asset descriptions for some assets.<span class="Apple-converted-space">&#160;</span></li></ul><p></p>' WHERE [Mat_Question_Id] = 3145
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><b>Question Intent:<span class="Apple-converted-space">&#160;</span></b></p><p class="p1">To determine if the physical locations of assets are documented in the asset inventory.<span class="Apple-converted-space">&#160;</span></p><ul><li><span>Physical locations of assets can be internal or external to the organization.</span><span class="Apple-converted-space">&#160;</span></li><li><span>The </span><span>location details should be sufficient enough to support the resilience requirements </span><span>of the service.</span><span class="Apple-converted-space">&#160;</span></li></ul><p></p><p class="p3"><b>Criteria for &#8220;Yes&#8221; Response:<span class="Apple-converted-space">&#160;</span></b><br></p><p class="p4"></p><ul><li>The organization documents the location of all assets that support the critical service in the asset inventory.<span class="Apple-converted-space">&#160;</span></li></ul><p></p><p class="p4"><b>Criteria for &#8220;Incomplete&#8221; Response:<span class="Apple-converted-space">&#160;</span></b></p><p class="p4"></p><ul><li>The organization documents the location of some assets in the asset inventory.<span class="Apple-converted-space">&#160;</span></li></ul><p></p>' WHERE [Mat_Question_Id] = 3146
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><b>Question Intent:<span class="Apple-converted-space">&#160;</span></b></p><p class="p1">To determine if the physical locations of assets are documented in the asset inventory.<span class="Apple-converted-space">&#160;</span></p><ul><li><span>Physical locations of assets can be internal or external to the organization.</span><span class="Apple-converted-space">&#160;</span></li><li><span>The </span><span>location details should be sufficient enough to support the resilience requirements </span><span>of the service.</span><span class="Apple-converted-space">&#160;</span></li></ul><p></p><p class="p3"><b>Criteria for &#8220;Yes&#8221; Response:<span class="Apple-converted-space">&#160;</span></b><br></p><p class="p4"></p><ul><li>The organization documents the location of all assets that support the critical service in the asset inventory.<span class="Apple-converted-space">&#160;</span></li></ul><p></p><p class="p4"><b>Criteria for &#8220;Incomplete&#8221; Response:<span class="Apple-converted-space">&#160;</span></b></p><p class="p4"></p><ul><li>The organization documents the location of some assets in the asset inventory.<span class="Apple-converted-space">&#160;</span></li></ul><p></p>' WHERE [Mat_Question_Id] = 3147
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><b>Question Intent:<span class="Apple-converted-space">&#160;</span></b></p><p class="p1">To determine if the physical locations of assets are documented in the asset inventory.<span class="Apple-converted-space">&#160;</span></p><ul><li><span>Physical locations of assets can be internal or external to the organization.</span><span class="Apple-converted-space">&#160;</span></li><li><span>The </span><span>location details should be sufficient enough to support the resilience requirements </span><span>of the service.</span><span class="Apple-converted-space">&#160;</span></li></ul><p></p><p class="p3"><b>Criteria for &#8220;Yes&#8221; Response:<span class="Apple-converted-space">&#160;</span></b><br></p><p class="p4"></p><ul><li>The organization documents the location of all assets that support the critical service in the asset inventory.<span class="Apple-converted-space">&#160;</span></li></ul><p></p><p class="p4"><b>Criteria for &#8220;Incomplete&#8221; Response:<span class="Apple-converted-space">&#160;</span></b></p><p class="p4"></p><ul><li>The organization documents the location of some assets in the asset inventory.<span class="Apple-converted-space">&#160;</span></li></ul><p></p>' WHERE [Mat_Question_Id] = 3148
