UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><b>Question Intent:<span class="Apple-converted-space">&#160;</span></b></p><p class="p1">To determine if the associations between assets and the critical service they support are documented.<span class="Apple-converted-space">&#160;</span></p><p class="p1"></p><ul><li>Associating assets in the asset inventory to services helps the organization to determine where critical dependencies exist, validate resilience requirements, and develop and implement resilience strategies in support of the critical service.<span class="Apple-converted-space">&#160;</span></li></ul><p></p><p class="p1"><b>Criteria for &#8220;Yes&#8221; Response:<span class="Apple-converted-space">&#160;</span></b><br></p><p class="p2"></p><ul><li>The organization documents associations between assets and the critical service for all assets that support the critical service.<span class="Apple-converted-space">&#160;</span></li></ul><p></p><p class="p2"><b>Criteria for &#8220;Incomplete&#8221; Response:<span class="Apple-converted-space">&#160;</span></b></p><p class="p2"></p><ul><li>The organization documents associations between assets and the critical service for some assets.<span class="Apple-converted-space">&#160;</span></li></ul><p></p>' WHERE [Mat_Question_Id] = 3150
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><b>Question Intent:<span class="Apple-converted-space">&#160;</span></b></p><p class="p1">To determine if the associations between assets and the critical service they support are documented.<span class="Apple-converted-space">&#160;</span></p><p class="p1"></p><ul><li>Associating assets in the asset inventory to services helps the organization to determine where critical dependencies exist, validate resilience requirements, and develop and implement resilience strategies in support of the critical service.<span class="Apple-converted-space">&#160;</span></li></ul><p></p><p class="p1"><b>Criteria for &#8220;Yes&#8221; Response:<span class="Apple-converted-space">&#160;</span></b><br></p><p class="p2"></p><ul><li>The organization documents associations between assets and the critical service for all assets that support the critical service.<span class="Apple-converted-space">&#160;</span></li></ul><p></p><p class="p2"><b>Criteria for &#8220;Incomplete&#8221; Response:<span class="Apple-converted-space">&#160;</span></b></p><p class="p2"></p><ul><li>The organization documents associations between assets and the critical service for some assets.<span class="Apple-converted-space">&#160;</span></li></ul><p></p>' WHERE [Mat_Question_Id] = 3151
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><b>Question Intent:<span class="Apple-converted-space">&#160;</span></b></p><p class="p1">To determine if the associations between assets and the critical service they support are documented.<span class="Apple-converted-space">&#160;</span></p><p class="p1"></p><ul><li>Associating assets in the asset inventory to services helps the organization to determine where critical dependencies exist, validate resilience requirements, and develop and implement resilience strategies in support of the critical service.<span class="Apple-converted-space">&#160;</span></li></ul><p></p><p class="p1"><b>Criteria for &#8220;Yes&#8221; Response:<span class="Apple-converted-space">&#160;</span></b><br></p><p class="p2"></p><ul><li>The organization documents associations between assets and the critical service for all assets that support the critical service.<span class="Apple-converted-space">&#160;</span></li></ul><p></p><p class="p2"><b>Criteria for &#8220;Incomplete&#8221; Response:<span class="Apple-converted-space">&#160;</span></b></p><p class="p2"></p><ul><li>The organization documents associations between assets and the critical service for some assets.<span class="Apple-converted-space">&#160;</span></li></ul><p></p>' WHERE [Mat_Question_Id] = 3152
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><b>Question Intent:<span class="Apple-converted-space">&#160;</span></b></p><p class="p1">To determine if the associations between assets and the critical service they support are documented.<span class="Apple-converted-space">&#160;</span></p><p class="p1"></p><ul><li>Associating assets in the asset inventory to services helps the organization to determine where critical dependencies exist, validate resilience requirements, and develop and implement resilience strategies in support of the critical service.<span class="Apple-converted-space">&#160;</span></li></ul><p></p><p class="p1"><b>Criteria for &#8220;Yes&#8221; Response:<span class="Apple-converted-space">&#160;</span></b><br></p><p class="p2"></p><ul><li>The organization documents associations between assets and the critical service for all assets that support the critical service.<span class="Apple-converted-space">&#160;</span></li></ul><p></p><p class="p2"><b>Criteria for &#8220;Incomplete&#8221; Response:<span class="Apple-converted-space">&#160;</span></b></p><p class="p2"></p><ul><li>The organization documents associations between assets and the critical service for some assets.<span class="Apple-converted-space">&#160;</span></li></ul><p></p>' WHERE [Mat_Question_Id] = 3153
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><b>Question Intent:&#160;</b></p><p class="p1">To determine if confidentiality, integrity, and availability requirements are&#160;<span>established for each service-related asset.</span></p><p class="p2"></p><ul><li>The confidentiality, integrity, and availability requirements of the service are used to derive&#160;<span>the collective protection and sustainment requirements of associated assets.</span></li><li>Asset-level requirements should be based on the deployment in, contributions to, and the&#160;<span>support of the critical service.</span></li></ul><p></p><p class="p1"><b>Criteria for &#8220;Yes&#8221; Response:</b></p><p class="p2"></p><ul><li>The organization establishes confidentiality, integrity, and availability requirements for all&#160;<span>assets that support the critical service.</span></li></ul><p></p><p class="p1"><b>Criteria for &#8220;Incomplete&#8221; Response:</b></p><p class="p3"></p><ul><li>The organization establishes confidentiality, integrity, and availability requirements for some&#160;<span>assets.</span></li></ul><p></p>' WHERE [Mat_Question_Id] = 3154
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><b>Question Intent:&#160;</b></p><p class="p1">To determine if confidentiality, integrity, and availability requirements are&#160;<span>established for each service-related asset.</span></p><p class="p2"></p><ul><li>The confidentiality, integrity, and availability requirements of the service are used to derive&#160;<span>the collective protection and sustainment requirements of associated assets.</span></li><li>Asset-level requirements should be based on the deployment in, contributions to, and the&#160;<span>support of the critical service.</span></li></ul><p></p><p class="p1"><b>Criteria for &#8220;Yes&#8221; Response:</b></p><p class="p2"></p><ul><li>The organization establishes confidentiality, integrity, and availability requirements for all&#160;<span>assets that support the critical service.</span></li></ul><p></p><p class="p1"><b>Criteria for &#8220;Incomplete&#8221; Response:</b></p><p class="p3"></p><ul><li>The organization establishes confidentiality, integrity, and availability requirements for some&#160;<span>assets.</span></li></ul><p></p>' WHERE [Mat_Question_Id] = 3155
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><b>Question Intent:&#160;</b></p><p class="p1">To determine if confidentiality, integrity, and availability requirements are&#160;<span>established for each service-related asset.</span></p><p class="p2"></p><ul><li>The confidentiality, integrity, and availability requirements of the service are used to derive&#160;<span>the collective protection and sustainment requirements of associated assets.</span></li><li>Asset-level requirements should be based on the deployment in, contributions to, and the&#160;<span>support of the critical service.</span></li></ul><p></p><p class="p1"><b>Criteria for &#8220;Yes&#8221; Response:</b></p><p class="p2"></p><ul><li>The organization establishes confidentiality, integrity, and availability requirements for all&#160;<span>assets that support the critical service.</span></li></ul><p></p><p class="p1"><b>Criteria for &#8220;Incomplete&#8221; Response:</b></p><p class="p3"></p><ul><li>The organization establishes confidentiality, integrity, and availability requirements for some&#160;<span>assets.</span></li></ul><p></p>' WHERE [Mat_Question_Id] = 3156
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><b>Question Intent:&#160;</b></p><p class="p1">To determine if confidentiality, integrity, and availability requirements are&#160;<span>established for each service-related asset.</span></p><p class="p2"></p><ul><li>The confidentiality, integrity, and availability requirements of the service are used to derive&#160;<span>the collective protection and sustainment requirements of associated assets.</span></li><li>Asset-level requirements should be based on the deployment in, contributions to, and the&#160;<span>support of the critical service.</span></li></ul><p></p><p class="p1"><b>Criteria for &#8220;Yes&#8221; Response:</b></p><p class="p2"></p><ul><li>The organization establishes confidentiality, integrity, and availability requirements for all&#160;<span>assets that support the critical service.</span></li></ul><p></p><p class="p1"><b>Criteria for &#8220;Incomplete&#8221; Response:</b></p><p class="p3"></p><ul><li>The organization establishes confidentiality, integrity, and availability requirements for some&#160;<span>assets.</span></li></ul><p></p>' WHERE [Mat_Question_Id] = 3157
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><b>Question Intent:&#160;</b></p><p class="p1">To determine if change criteria have been established for asset descriptions.</p><p class="p2"></p><ul><li>The organization should have a set of criteria to identify when changes to assets affect the&#160;<span>delivery of the critical service and require a change to the asset description.</span></li><li>Change criteria should be applied consistently across all asset types.</li></ul><p></p><p class="p1"><b>Examples of triggers that can affect high-value assets:</b></p><p class="p2"></p><ul><li>changes in services affecting the assets on which they rely (e.g., changes in availability&#160;<span>requirements)</span></li><li>changes in technology infrastructure and configuration</li><li>creation or alteration of information</li><li>contracts that the organization enters into that would identify new assets</li><li>changes in organizational structure and staff - termination or transfer of staff between&#160;<span>organizational units or changes in roles and responsibilities</span></li><li>real-estate transactions that add, alter, or change existing facilities</li><li>acquisition of assets such as technology or facilities</li></ul><p></p><p class="p1"><b>Criteria for &#8220;Yes&#8221; Response:</b></p><p class="p2">The organization has established asset description change criteria for all assets that support&#160;<span>the critical service.</span></p><p class="p1"><b>Criteria for &#8220;Incomplete&#8221; Response:</b></p><p class="p3">The organization has established asset description change criteria for some assets.</p>' WHERE [Mat_Question_Id] = 3158
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><b>Question Intent:&#160;</b></p><p class="p1">To determine if change criteria have been established for asset descriptions.</p><p class="p2"></p><ul><li>The organization should have a set of criteria to identify when changes to assets affect the&#160;<span>delivery of the critical service and require a change to the asset description.</span></li><li>Change criteria should be applied consistently across all asset types.</li></ul><p></p><p class="p1"><b>Examples of triggers that can affect high-value assets:</b></p><p class="p2"></p><ul><li>changes in services affecting the assets on which they rely (e.g., changes in availability&#160;<span>requirements)</span></li><li>changes in technology infrastructure and configuration</li><li>creation or alteration of information</li><li>contracts that the organization enters into that would identify new assets</li><li>changes in organizational structure and staff - termination or transfer of staff between&#160;<span>organizational units or changes in roles and responsibilities</span></li><li>real-estate transactions that add, alter, or change existing facilities</li><li>acquisition of assets such as technology or facilities</li></ul><p></p><p class="p1"><b>Criteria for &#8220;Yes&#8221; Response:</b></p><p class="p2">The organization has established asset description change criteria for all assets that support&#160;<span>the critical service.</span></p><p class="p1"><b>Criteria for &#8220;Incomplete&#8221; Response:</b></p><p class="p3">The organization has established asset description change criteria for some assets.</p>' WHERE [Mat_Question_Id] = 3159
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><b>Question Intent:&#160;</b></p><p class="p1">To determine if change criteria have been established for asset descriptions.</p><p class="p2"></p><ul><li>The organization should have a set of criteria to identify when changes to assets affect the&#160;<span>delivery of the critical service and require a change to the asset description.</span></li><li>Change criteria should be applied consistently across all asset types.</li></ul><p></p><p class="p1"><b>Examples of triggers that can affect high-value assets:</b></p><p class="p2"></p><ul><li>changes in services affecting the assets on which they rely (e.g., changes in availability&#160;<span>requirements)</span></li><li>changes in technology infrastructure and configuration</li><li>creation or alteration of information</li><li>contracts that the organization enters into that would identify new assets</li><li>changes in organizational structure and staff - termination or transfer of staff between&#160;<span>organizational units or changes in roles and responsibilities</span></li><li>real-estate transactions that add, alter, or change existing facilities</li><li>acquisition of assets such as technology or facilities</li></ul><p></p><p class="p1"><b>Criteria for &#8220;Yes&#8221; Response:</b></p><p class="p2">The organization has established asset description change criteria for all assets that support&#160;<span>the critical service.</span></p><p class="p1"><b>Criteria for &#8220;Incomplete&#8221; Response:</b></p><p class="p3">The organization has established asset description change criteria for some assets.</p>' WHERE [Mat_Question_Id] = 3160
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><b>Question Intent:&#160;</b></p><p class="p1">To determine if change criteria have been established for asset descriptions.</p><p class="p2"></p><ul><li>The organization should have a set of criteria to identify when changes to assets affect the&#160;<span>delivery of the critical service and require a change to the asset description.</span></li><li>Change criteria should be applied consistently across all asset types.</li></ul><p></p><p class="p1"><b>Examples of triggers that can affect high-value assets:</b></p><p class="p2"></p><ul><li>changes in services affecting the assets on which they rely (e.g., changes in availability&#160;<span>requirements)</span></li><li>changes in technology infrastructure and configuration</li><li>creation or alteration of information</li><li>contracts that the organization enters into that would identify new assets</li><li>changes in organizational structure and staff - termination or transfer of staff between&#160;<span>organizational units or changes in roles and responsibilities</span></li><li>real-estate transactions that add, alter, or change existing facilities</li><li>acquisition of assets such as technology or facilities</li></ul><p></p><p class="p1"><b>Criteria for &#8220;Yes&#8221; Response:</b></p><p class="p2">The organization has established asset description change criteria for all assets that support&#160;<span>the critical service.</span></p><p class="p1"><b>Criteria for &#8220;Incomplete&#8221; Response:</b></p><p class="p3">The organization has established asset description change criteria for some assets.</p>' WHERE [Mat_Question_Id] = 3161
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><b>Question Intent:&#160;</b></p><p class="p1">To determine if asset descriptions are updated when changes to assets occur.</p><p class="p2"></p><ul><li>When changes to assets occur, asset descriptions should be updated to ensure that current&#160;<span>protection and sustainment strategies continue to be satisfied.</span></li></ul><p></p><p class="p1"><b>Typical work products:</b></p><p class="p2"></p><ul><li>asset change documentation</li><li>asset inventory status</li><li>updated asset and service resilience requirements</li><li>updated asset and service protection strategies and controls</li><li>updated strategies and continuity plans for sustaining assets and services</li></ul><p></p><p class="p1"><b>Criteria for &#8220;Yes&#8221; Response:</b></p><p class="p2"></p><ul><li>When changes to assets occur, asset descriptions are updated for all changed assets that&#160;<span>support the critical service.</span></li></ul><p></p><p class="p1"><b>Criteria for &#8220;Incomplete&#8221; Response:</b></p><p class="p3"></p><ul><li>When changes to assets occur, asset descriptions are updated for some changed assets.</li></ul><p></p>' WHERE [Mat_Question_Id] = 3162
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><b>Question Intent:&#160;</b></p><p class="p1">To determine if asset descriptions are updated when changes to assets occur.</p><p class="p2"></p><ul><li>When changes to assets occur, asset descriptions should be updated to ensure that current&#160;<span>protection and sustainment strategies continue to be satisfied.</span></li></ul><p></p><p class="p1"><b>Typical work products:</b></p><p class="p2"></p><ul><li>asset change documentation</li><li>asset inventory status</li><li>updated asset and service resilience requirements</li><li>updated asset and service protection strategies and controls</li><li>updated strategies and continuity plans for sustaining assets and services</li></ul><p></p><p class="p1"><b>Criteria for &#8220;Yes&#8221; Response:</b></p><p class="p2"></p><ul><li>When changes to assets occur, asset descriptions are updated for all changed assets that&#160;<span>support the critical service.</span></li></ul><p></p><p class="p1"><b>Criteria for &#8220;Incomplete&#8221; Response:</b></p><p class="p3"></p><ul><li>When changes to assets occur, asset descriptions are updated for some changed assets.</li></ul><p></p>' WHERE [Mat_Question_Id] = 3163
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><b>Question Intent:&#160;</b></p><p class="p1">To determine if asset descriptions are updated when changes to assets occur.</p><p class="p2"></p><ul><li>When changes to assets occur, asset descriptions should be updated to ensure that current&#160;<span>protection and sustainment strategies continue to be satisfied.</span></li></ul><p></p><p class="p1"><b>Typical work products:</b></p><p class="p2"></p><ul><li>asset change documentation</li><li>asset inventory status</li><li>updated asset and service resilience requirements</li><li>updated asset and service protection strategies and controls</li><li>updated strategies and continuity plans for sustaining assets and services</li></ul><p></p><p class="p1"><b>Criteria for &#8220;Yes&#8221; Response:</b></p><p class="p2"></p><ul><li>When changes to assets occur, asset descriptions are updated for all changed assets that&#160;<span>support the critical service.</span></li></ul><p></p><p class="p1"><b>Criteria for &#8220;Incomplete&#8221; Response:</b></p><p class="p3"></p><ul><li>When changes to assets occur, asset descriptions are updated for some changed assets.</li></ul><p></p>' WHERE [Mat_Question_Id] = 3164
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><b>Question Intent:&#160;</b></p><p class="p1">To determine if asset descriptions are updated when changes to assets occur.</p><p class="p2"></p><ul><li>When changes to assets occur, asset descriptions should be updated to ensure that current&#160;<span>protection and sustainment strategies continue to be satisfied.</span></li></ul><p></p><p class="p1"><b>Typical work products:</b></p><p class="p2"></p><ul><li>asset change documentation</li><li>asset inventory status</li><li>updated asset and service resilience requirements</li><li>updated asset and service protection strategies and controls</li><li>updated strategies and continuity plans for sustaining assets and services</li></ul><p></p><p class="p1"><b>Criteria for &#8220;Yes&#8221; Response:</b></p><p class="p2"></p><ul><li>When changes to assets occur, asset descriptions are updated for all changed assets that&#160;<span>support the critical service.</span></li></ul><p></p><p class="p1"><b>Criteria for &#8220;Incomplete&#8221; Response:</b></p><p class="p3"></p><ul><li>When changes to assets occur, asset descriptions are updated for some changed assets.</li></ul><p></p>' WHERE [Mat_Question_Id] = 3165
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><b>Question Intent:&#160;</b></p><p class="p1">To determine if access to assets is granted based on their protection requirements.</p><p class="p1"></p><ul><li><span>Protection requirements describe how an asset''s exposure to sources of disruption and to the exploitation of vulnerabilities must be minimized.</span></li><li>Access requests should be granted in accordance with the protection requirements that have&#160;<span>been established for the asset.</span></li><li>Access privileges are assigned and approved by asset owners based on the role of the person,&#160;<span>object, or entity that is requesting access.</span></li></ul><p></p><p></p><p class="p1"><b>Typical work products:</b></p><p class="p2"></p><ul><li>asset protection requirements</li><li>access requests</li><li>access approval</li><li>access control policy</li><li>access rights and responsibilities</li></ul><p></p><p class="p1"><b>Criteria for &#8220;Yes&#8221; Response:</b></p><p class="p2"></p><ul><li>Access to assets is granted based on their protection requirements, for all assets that&#160;<span>support the critical service.</span></li></ul><p></p><p class="p1"><b>Criteria for &#8220;Incomplete&#8221; Response:</b></p><p class="p3"></p><ul><li>Access to assets is granted based on their protection requirements, for some assets.</li></ul><p></p>' WHERE [Mat_Question_Id] = 3166
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><b>Question Intent:&#160;</b></p><p class="p1">To determine if access to assets is granted based on their protection requirements.</p><p class="p1"></p><ul><li><span>Protection requirements describe how an asset''s exposure to sources of disruption and to the exploitation of vulnerabilities must be minimized.</span></li><li>Access requests should be granted in accordance with the protection requirements that have&#160;<span>been established for the asset.</span></li><li>Access privileges are assigned and approved by asset owners based on the role of the person,&#160;<span>object, or entity that is requesting access.</span></li></ul><p></p><p></p><p class="p1"><b>Typical work products:</b></p><p class="p2"></p><ul><li>asset protection requirements</li><li>access requests</li><li>access approval</li><li>access control policy</li><li>access rights and responsibilities</li></ul><p></p><p class="p1"><b>Criteria for &#8220;Yes&#8221; Response:</b></p><p class="p2"></p><ul><li>Access to assets is granted based on their protection requirements, for all assets that&#160;<span>support the critical service.</span></li></ul><p></p><p class="p1"><b>Criteria for &#8220;Incomplete&#8221; Response:</b></p><p class="p3"></p><ul><li>Access to assets is granted based on their protection requirements, for some assets.</li></ul><p></p>' WHERE [Mat_Question_Id] = 3167
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><b>Question Intent:&#160;</b></p><p class="p1">To determine if access to assets is granted based on their protection requirements.</p><p class="p1"></p><ul><li><span>Protection requirements describe how an asset''s exposure to sources of disruption and to the exploitation of vulnerabilities must be minimized.</span></li><li>Access requests should be granted in accordance with the protection requirements that have&#160;<span>been established for the asset.</span></li><li>Access privileges are assigned and approved by asset owners based on the role of the person,&#160;<span>object, or entity that is requesting access.</span></li></ul><p></p><p></p><p class="p1"><b>Typical work products:</b></p><p class="p2"></p><ul><li>asset protection requirements</li><li>access requests</li><li>access approval</li><li>access control policy</li><li>access rights and responsibilities</li></ul><p></p><p class="p1"><b>Criteria for &#8220;Yes&#8221; Response:</b></p><p class="p2"></p><ul><li>Access to assets is granted based on their protection requirements, for all assets that&#160;<span>support the critical service.</span></li></ul><p></p><p class="p1"><b>Criteria for &#8220;Incomplete&#8221; Response:</b></p><p class="p3"></p><ul><li>Access to assets is granted based on their protection requirements, for some assets.</li></ul><p></p>' WHERE [Mat_Question_Id] = 3168
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><b>Question Intent:&#160;</b></p><p class="p1">To determine if access requests are reviewed and approved by the asset owner.</p><p class="p2"></p><ul><li>Asset owners are responsible for reviewing the access request and the asset''s protection&#160;<span>requirements to decide whether to approve or deny access.</span></li><li>The access provided should be commensurate with and not exceed the requestor''s job&#160;<span>responsibilities.</span></li><li>If the custodian of the asset is different from the owner, the owner should communicate in&#160;<span>writing the approval for the request.</span></li></ul><p></p><p class="p1"><b>Criteria for &#8220;Yes&#8221; Response:</b></p><p class="p2"></p><ul><li>All access requests for assets that support the critical service are reviewed and approved by&#160;<span>the asset owner.</span></li></ul><p></p><p class="p1"><b>Criteria for &#8220;Incomplete&#8221; Response:</b></p><p class="p2"></p><ul><li>Some access requests for assets that support the critical service are reviewed and approved by&#160;<span>the asset owner.</span></li></ul><p></p>' WHERE [Mat_Question_Id] = 3169
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><b>Question Intent:&#160;</b></p><p class="p1">To determine if access requests are reviewed and approved by the asset owner.</p><p class="p2"></p><ul><li>Asset owners are responsible for reviewing the access request and the asset''s protection&#160;<span>requirements to decide whether to approve or deny access.</span></li><li>The access provided should be commensurate with and not exceed the requestor''s job&#160;<span>responsibilities.</span></li><li>If the custodian of the asset is different from the owner, the owner should communicate in&#160;<span>writing the approval for the request.</span></li></ul><p></p><p class="p1"><b>Criteria for &#8220;Yes&#8221; Response:</b></p><p class="p2"></p><ul><li>All access requests for assets that support the critical service are reviewed and approved by&#160;<span>the asset owner.</span></li></ul><p></p><p class="p1"><b>Criteria for &#8220;Incomplete&#8221; Response:</b></p><p class="p2"></p><ul><li>Some access requests for assets that support the critical service are reviewed and approved by&#160;<span>the asset owner.</span></li></ul><p></p>' WHERE [Mat_Question_Id] = 3170
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><b>Question Intent:&#160;</b></p><p class="p1">To determine if access requests are reviewed and approved by the asset owner.</p><p class="p2"></p><ul><li>Asset owners are responsible for reviewing the access request and the asset''s protection&#160;<span>requirements to decide whether to approve or deny access.</span></li><li>The access provided should be commensurate with and not exceed the requestor''s job&#160;<span>responsibilities.</span></li><li>If the custodian of the asset is different from the owner, the owner should communicate in&#160;<span>writing the approval for the request.</span></li></ul><p></p><p class="p1"><b>Criteria for &#8220;Yes&#8221; Response:</b></p><p class="p2"></p><ul><li>All access requests for assets that support the critical service are reviewed and approved by&#160;<span>the asset owner.</span></li></ul><p></p><p class="p1"><b>Criteria for &#8220;Incomplete&#8221; Response:</b></p><p class="p2"></p><ul><li>Some access requests for assets that support the critical service are reviewed and approved by&#160;<span>the asset owner.</span></li></ul><p></p>' WHERE [Mat_Question_Id] = 3171
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><span><b>Question Intent:&#160;</b></span></p><p class="p1">To determine if access permissions are managed in accordance with the principle&#160;of separation of duties.</p><p class="p1"></p><ul><li>The identification of authorized users and the specification of access privileges reflect the&#160;requirements of the critical service.</li><li>Access control policies control access between users (or processes acting on behalf of users)&#160;and information systems.</li><li>Separation of duties addresses the potential for abuse of authorized privileges by dividing&#160;roles and privileges between users (e.g., ensuring security personnel administering access&#160;control functions do not also administer audit functions.).</li></ul><p></p><p class="p1"><span><b>Criteria for &#8220;Yes&#8221; Response:</b></span></p><p class="p2"></p><ul><li>Access permissions for all assets that support the critical service are managed in accordance&#160;with the principle of separation of duties.</li></ul><p></p><p class="p1"><span><b>Criteria for &#8220;Incomplete&#8221; Response:</b></span></p><p class="p2"></p><ul><li>Access permissions for some assets that support the critical service are managed in&#160;accordance the principle of separation of duties.</li></ul><p></p>', [Parent_Question_Id]=1844 WHERE [Mat_Question_Id] = 3172
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><span><b>Question Intent:&#160;</b></span></p><p class="p1">To determine if access permissions are managed in accordance with the principle&#160;of separation of duties.</p><p class="p1"></p><ul><li>The identification of authorized users and the specification of access privileges reflect the&#160;requirements of the critical service.</li><li>Access control policies control access between users (or processes acting on behalf of users)&#160;and information systems.</li><li>Separation of duties addresses the potential for abuse of authorized privileges by dividing&#160;roles and privileges between users (e.g., ensuring security personnel administering access&#160;control functions do not also administer audit functions.).</li></ul><p></p><p class="p1"><span><b>Criteria for &#8220;Yes&#8221; Response:</b></span></p><p class="p2"></p><ul><li>Access permissions for all assets that support the critical service are managed in accordance&#160;with the principle of separation of duties.</li></ul><p></p><p class="p1"><span><b>Criteria for &#8220;Incomplete&#8221; Response:</b></span></p><p class="p2"></p><ul><li>Access permissions for some assets that support the critical service are managed in&#160;accordance the principle of separation of duties.</li></ul><p></p>', [Parent_Question_Id]=1844 WHERE [Mat_Question_Id] = 3173
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><span><b>Question Intent:&#160;</b></span></p><p class="p1">To determine if access permissions are managed in accordance with the principle&#160;of separation of duties.</p><p class="p1"></p><ul><li>The identification of authorized users and the specification of access privileges reflect the&#160;requirements of the critical service.</li><li>Access control policies control access between users (or processes acting on behalf of users)&#160;and information systems.</li><li>Separation of duties addresses the potential for abuse of authorized privileges by dividing&#160;roles and privileges between users (e.g., ensuring security personnel administering access&#160;control functions do not also administer audit functions.).</li></ul><p></p><p class="p1"><span><b>Criteria for &#8220;Yes&#8221; Response:</b></span></p><p class="p2"></p><ul><li>Access permissions for all assets that support the critical service are managed in accordance&#160;with the principle of separation of duties.</li></ul><p></p><p class="p1"><span><b>Criteria for &#8220;Incomplete&#8221; Response:</b></span></p><p class="p2"></p><ul><li>Access permissions for some assets that support the critical service are managed in&#160;accordance the principle of separation of duties.</li></ul><p></p>', [Parent_Question_Id]=1844 WHERE [Mat_Question_Id] = 3174
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><span><b>Question Intent:&#160;</b></span></p><p class="p1">To determine if access privileges are modified as a result of the reviews.</p><p class="p2"></p><ul><li>Excessive or inappropriate levels of access privileges must be corrected in a timely manner to&#160;avoid exposing the organization to additional risk.</li><li>As a result of periodic review, asset owners may authorize custodians to make modifications&#160;such as:</li><ul><li>change or disable certain privileges to preserve resilience requirements</li><li>disable an access account that is no longer valid</li></ul></ul><p></p><p class="p1"><span><b>Criteria for &#8220;Yes&#8221; Response:</b></span></p><p class="p2"></p><ul><li>Access privileges are modified as a result of reviews for all assets that support the critical&#160;service.</li></ul><p></p><p class="p1"><span><b>Criteria for &#8220;Incomplete&#8221; Response:</b></span></p><p class="p3"></p><ul><li>Access privileges are modified as a result of reviews for some assets.</li></ul><p></p>' WHERE [Mat_Question_Id] = 3175
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><span><b>Question Intent:&#160;</b></span></p><p class="p1">To determine if access privileges are modified as a result of the reviews.</p><p class="p2"></p><ul><li>Excessive or inappropriate levels of access privileges must be corrected in a timely manner to&#160;avoid exposing the organization to additional risk.</li><li>As a result of periodic review, asset owners may authorize custodians to make modifications&#160;such as:</li><ul><li>change or disable certain privileges to preserve resilience requirements</li><li>disable an access account that is no longer valid</li></ul></ul><p></p><p class="p1"><span><b>Criteria for &#8220;Yes&#8221; Response:</b></span></p><p class="p2"></p><ul><li>Access privileges are modified as a result of reviews for all assets that support the critical&#160;service.</li></ul><p></p><p class="p1"><span><b>Criteria for &#8220;Incomplete&#8221; Response:</b></span></p><p class="p3"></p><ul><li>Access privileges are modified as a result of reviews for some assets.</li></ul><p></p>' WHERE [Mat_Question_Id] = 3176
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><span><b>Question Intent:&#160;</b></span></p><p class="p1">To determine if access privileges are modified as a result of the reviews.</p><p class="p2"></p><ul><li>Excessive or inappropriate levels of access privileges must be corrected in a timely manner to&#160;avoid exposing the organization to additional risk.</li><li>As a result of periodic review, asset owners may authorize custodians to make modifications&#160;such as:</li><ul><li>change or disable certain privileges to preserve resilience requirements</li><li>disable an access account that is no longer valid</li></ul></ul><p></p><p class="p1"><span><b>Criteria for &#8220;Yes&#8221; Response:</b></span></p><p class="p2"></p><ul><li>Access privileges are modified as a result of reviews for all assets that support the critical&#160;service.</li></ul><p></p><p class="p1"><span><b>Criteria for &#8220;Incomplete&#8221; Response:</b></span></p><p class="p3"></p><ul><li>Access privileges are modified as a result of reviews for some assets.</li></ul><p></p>' WHERE [Mat_Question_Id] = 3177
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><b>Question Intent:&#160;</b></p><p class="p1">To determine if access permissions are managed in accordance with the principle&#160;<span>of least privilege.</span></p><p class="p1"></p><ul><li><span>The identification of authorized users and the specification of access privileges reflect the&#160;</span><span>requirements of the critical service.</span></li><li>Access control policies control access between users (or processes acting on behalf of users)&#160;<span>and information systems.</span></li><li>Access permissions can also be employed at the application and service level to provide&#160;<span>increased information security.</span></li><li>The principle of least privilege is employed to ensure users and processes operate at privilege&#160;<span>levels no higher than necessary.</span></li></ul><p></p><p class="p1"><b>Criteria for &#8220;Yes&#8221; Response:</b></p><p class="p2"></p><ul><li>Access permissions for all assets that support the critical service are managed in accordance&#160;<span>with the principle of least privilege.</span></li></ul><p></p><p class="p1"><b>Criteria for &#8220;Incomplete&#8221; Response:</b></p><p class="p2"></p><ul><li>Access permissions for some assets that support the critical service are managed in&#160;<span>accordance with the principle of least privilege.</span></li></ul><p></p>' WHERE [Mat_Question_Id] = 3178
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><b>Question Intent:&#160;</b></p><p class="p1">To determine if access permissions are managed in accordance with the principle&#160;<span>of least privilege.</span></p><p class="p1"></p><ul><li><span>The identification of authorized users and the specification of access privileges reflect the&#160;</span><span>requirements of the critical service.</span></li><li>Access control policies control access between users (or processes acting on behalf of users)&#160;<span>and information systems.</span></li><li>Access permissions can also be employed at the application and service level to provide&#160;<span>increased information security.</span></li><li>The principle of least privilege is employed to ensure users and processes operate at privilege&#160;<span>levels no higher than necessary.</span></li></ul><p></p><p class="p1"><b>Criteria for &#8220;Yes&#8221; Response:</b></p><p class="p2"></p><ul><li>Access permissions for all assets that support the critical service are managed in accordance&#160;<span>with the principle of least privilege.</span></li></ul><p></p><p class="p1"><b>Criteria for &#8220;Incomplete&#8221; Response:</b></p><p class="p2"></p><ul><li>Access permissions for some assets that support the critical service are managed in&#160;<span>accordance with the principle of least privilege.</span></li></ul><p></p>' WHERE [Mat_Question_Id] = 3179
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><b>Question Intent:&#160;</b></p><p class="p1">To determine if access permissions are managed in accordance with the principle&#160;<span>of least privilege.</span></p><p class="p1"></p><ul><li><span>The identification of authorized users and the specification of access privileges reflect the&#160;</span><span>requirements of the critical service.</span></li><li>Access control policies control access between users (or processes acting on behalf of users)&#160;<span>and information systems.</span></li><li>Access permissions can also be employed at the application and service level to provide&#160;<span>increased information security.</span></li><li>The principle of least privilege is employed to ensure users and processes operate at privilege&#160;<span>levels no higher than necessary.</span></li></ul><p></p><p class="p1"><b>Criteria for &#8220;Yes&#8221; Response:</b></p><p class="p2"></p><ul><li>Access permissions for all assets that support the critical service are managed in accordance&#160;<span>with the principle of least privilege.</span></li></ul><p></p><p class="p1"><b>Criteria for &#8220;Incomplete&#8221; Response:</b></p><p class="p2"></p><ul><li>Access permissions for some assets that support the critical service are managed in&#160;<span>accordance with the principle of least privilege.</span></li></ul><p></p>' WHERE [Mat_Question_Id] = 3180
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><span><b>Question Intent:&#160;</b></span></p><p class="p1">To determine if access permissions are managed in accordance with the principle&#160;of separation of duties.</p><p class="p1"></p><ul><li>The identification of authorized users and the specification of access privileges reflect the&#160;requirements of the critical service.</li><li>Access control policies control access between users (or processes acting on behalf of users)&#160;and information systems.</li><li>Separation of duties addresses the potential for abuse of authorized privileges by dividing&#160;roles and privileges between users (e.g., ensuring security personnel administering access&#160;control functions do not also administer audit functions.).</li></ul><p></p><p class="p1"><span><b>Criteria for &#8220;Yes&#8221; Response:</b></span></p><p class="p2"></p><ul><li>Access permissions for all assets that support the critical service are managed in accordance&#160;with the principle of separation of duties.</li></ul><p></p><p class="p1"><span><b>Criteria for &#8220;Incomplete&#8221; Response:</b></span></p><p class="p2"></p><ul><li>Access permissions for some assets that support the critical service are managed in&#160;accordance the principle of separation of duties.</li></ul><p></p>' WHERE [Mat_Question_Id] = 3181
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><span><b>Question Intent:&#160;</b></span></p><p class="p1">To determine if access permissions are managed in accordance with the principle&#160;of separation of duties.</p><p class="p1"></p><ul><li>The identification of authorized users and the specification of access privileges reflect the&#160;requirements of the critical service.</li><li>Access control policies control access between users (or processes acting on behalf of users)&#160;and information systems.</li><li>Separation of duties addresses the potential for abuse of authorized privileges by dividing&#160;roles and privileges between users (e.g., ensuring security personnel administering access&#160;control functions do not also administer audit functions.).</li></ul><p></p><p class="p1"><span><b>Criteria for &#8220;Yes&#8221; Response:</b></span></p><p class="p2"></p><ul><li>Access permissions for all assets that support the critical service are managed in accordance&#160;with the principle of separation of duties.</li></ul><p></p><p class="p1"><span><b>Criteria for &#8220;Incomplete&#8221; Response:</b></span></p><p class="p2"></p><ul><li>Access permissions for some assets that support the critical service are managed in&#160;accordance the principle of separation of duties.</li></ul><p></p>' WHERE [Mat_Question_Id] = 3182
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<p class="p1"><span><b>Question Intent:&#160;</b></span></p><p class="p1">To determine if access permissions are managed in accordance with the principle&#160;of separation of duties.</p><p class="p1"></p><ul><li>The identification of authorized users and the specification of access privileges reflect the&#160;requirements of the critical service.</li><li>Access control policies control access between users (or processes acting on behalf of users)&#160;and information systems.</li><li>Separation of duties addresses the potential for abuse of authorized privileges by dividing&#160;roles and privileges between users (e.g., ensuring security personnel administering access&#160;control functions do not also administer audit functions.).</li></ul><p></p><p class="p1"><span><b>Criteria for &#8220;Yes&#8221; Response:</b></span></p><p class="p2"></p><ul><li>Access permissions for all assets that support the critical service are managed in accordance&#160;with the principle of separation of duties.</li></ul><p></p><p class="p1"><span><b>Criteria for &#8220;Incomplete&#8221; Response:</b></span></p><p class="p2"></p><ul><li>Access permissions for some assets that support the critical service are managed in&#160;accordance the principle of separation of duties.</li></ul><p></p>' WHERE [Mat_Question_Id] = 3183
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><span><b>Question Intent:&#160;</b></span></div><div><br></div><div>To determine if control objectives for the critical service have been established.</div><div><br></div><div>Control objectives are important because controls are designed to meet those objectives.</div><div><ul><li>Control objectives provide a set of high-level requirements for the protection and sustainment of a critical service and associated assets.</li><li>Sources for identifying control objectives may be found in governance documents, policy documents, etc.</li></ul></div><br><table class="MsoNormalTable" border="1" cellspacing="0" cellpadding="0"><tbody><tr><td width="83" valign="top"><p class="TableParagraph" align="right"><b><span>Asset&#160;Type</span><span></span></b></p></td><td width="270" valign="top"><p class="TableParagraph"><span><b>Control&#160;Objective&#160;Example</b></span><span></span></p></td></tr><tr><td width="83" valign="top"><p class="TableParagraph" align="right"><b><span>People</span><br></b></p></td><td width="270" valign="top"><p class="TableParagraph"></p><ul><li>Ensure all employees are trustworthy&#160;and&#160;reliable&#160;prior&#160;to&#160;hiring them.</li><li>All&#160;outside&#160;support&#160;personnel&#160;are&#160;identified.</li></ul><p></p></td></tr><tr><td width="83" valign="top"><p class="TableParagraph" align="right"><b><span>Information</span><span></span></b></p></td><td width="270" valign="top"><p class="TableParagraph"></p><ul><li>Ensure the confidentiality and integrity&#160;of&#160;customer&#8217;s&#160;payment&#160;information.</li><li>Information assets are disposed of&#160;according to&#160;policy.</li></ul><p></p><p class="TableParagraph"></p></td></tr><tr><td width="83" valign="top"><p class="TableParagraph" align="right"><b><span>Technology</span><span></span></b></p></td><td width="270" valign="top"><p class="TableParagraph"></p><ul><li>Ensure&#160;the&#160;databases&#160;that&#160;support&#160;one&#160;or more critical services remain&#160;available.</li><li>Network integrity&#160;is&#160;protected.</li></ul><p></p></td></tr><tr><td width="83" valign="top"><p class="TableParagraph" align="right"><b><span>Facilities</span><span></span></b></p></td><td width="270" valign="top"><p class="TableParagraph"></p><ul><li>Ensure environmental systems are&#160;maintained&#160;at&#160;an&#160;appropriate&#160;level&#160;to&#160;support&#160;datacenter&#160;equipment.</li><li>Physical&#160;access&#160;to&#160;assets&#160;is&#160;managed&#160;and protected.</li></ul><p></p><p class="TableParagraph"></p></td></tr></tbody></table><span><b><br></b></span><div><div><span><b>Criteria for &#8220;Yes&#8221; Response:</b></span></div><div><ul><li>Control objectives are established for all assets (people, information, technology, and facilities).</li><li>And; all control objectives are documented.</li></ul></div><div><span><b>Criteria for &#8220;Incomplete&#8221; Response:</b></span></div><div><ul><li>Control objectives are established for some assets.</li></ul></div></div>' WHERE [Mat_Question_Id] = 3184
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><b>Question Intent:</b>&#160;</div><div><br></div><div>To determine if control objectives for the critical service have been established.</div><div><br></div><div>Control objectives are important because controls are designed to meet those objectives.</div><div><ul><li>Control objectives provide a set of high-level requirements for the protection and sustainment of a critical service and associated assets.</li><li>Sources for identifying control objectives may be found in governance documents, policy documents, etc.</li></ul></div><br><table class="MsoNormalTable" border="1" cellspacing="0" cellpadding="0"><tbody><tr><td width="83" valign="top"><p class="TableParagraph" align="right"><b><span>Asset&#160;Type</span><span></span></b></p></td><td width="270" valign="top"><span><b>Control&#160;Objective&#160;Example</b></span><span></span></td></tr><tr><td width="83" valign="top"><p class="TableParagraph" align="right"><b><span>People</span><br></b></p></td><td width="270" valign="top"><p class="TableParagraph"></p><ul><li>Ensure all employees are trustworthy&#160;and&#160;reliable&#160;prior&#160;to&#160;hiring them.</li><li>All&#160;outside&#160;support&#160;personnel&#160;are&#160;identified.</li></ul><p></p></td></tr><tr><td width="83" valign="top"><p class="TableParagraph" align="right"><span><b>Information</b></span><span></span></p></td><td width="270" valign="top"><p class="TableParagraph"></p><ul><li>Ensure the confidentiality and integrity&#160;of&#160;customer&#8217;s&#160;payment&#160;information.</li><li>Information assets are disposed of&#160;according to&#160;policy.</li></ul><p></p><p class="TableParagraph"></p></td></tr><tr><td width="83" valign="top"><p class="TableParagraph" align="right"><span><b>Technology</b></span><span></span></p></td><td width="270" valign="top"><p class="TableParagraph"></p><ul><li>Ensure&#160;the&#160;databases&#160;that&#160;support&#160;one&#160;or more critical services remain&#160;available.</li><li>Network integrity&#160;is&#160;protected.</li></ul><p></p></td></tr><tr><td width="83" valign="top"><p class="TableParagraph" align="right"><span><b>Facilities</b></span><span></span></p></td><td width="270" valign="top"><p class="TableParagraph"></p><ul><li>Ensure environmental systems are&#160;maintained&#160;at&#160;an&#160;appropriate&#160;level&#160;to&#160;support&#160;datacenter&#160;equipment.</li><li>Physical&#160;access&#160;to&#160;assets&#160;is&#160;managed&#160;and protected.</li></ul><p></p><p class="TableParagraph"></p></td></tr></tbody></table><span><br></span><div><div><span><b>Criteria for &#8220;Yes&#8221; Response:</b></span></div><div><ul><li>Control objectives are established for all assets (people, information, technology, and facilities).</li><li>And; all control objectives are documented.</li></ul></div><div><span><b>Criteria for &#8220;Incomplete&#8221; Response:</b></span></div><div><ul><li>Control objectives are established for some assets.</li></ul></div></div>' WHERE [Mat_Question_Id] = 3185
