UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><p><b>Question Intent:</b></p></div> To determine if a standard set of tools and/or methods are in use to identify vulnerabilities in assets.  <ul> <li> Pre-approving tools, techniques, and methods ensures  consistency, as well as validity of results.</li> <li> The tools and methods should cover all the assets that support the critical service.</li> <li> The tools and methods can be both procedural and automated.</li> </ul>  <div><p><b>Criteria for “Yes” Response:</b></p></div> <ul> <li> The organization has a standard set of tools and/or methods that are used to identify vulnerabilities in all assets that support the critical service.</li> </ul> <div><p><b>Criteria for “Incomplete” Response:</b></p></div> <ul> <li> The organization has a standard set of tools and/or methods that are used to identify vulnerabilities in some assets.</li> </ul>' WHERE [Mat_Question_Id] = 3272
