UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><p><b>Question Intent:</b></p></div>&#160;To determine if sources of vulnerability information have been identified.&#10;&#10;<ul>&#10;<li>&#160;Internal sources typically&#160;provide information about vulnerabilities that are&#160;unique to the organization.</li>&#10;<li>&#160;Internal processes, such as incident management, could be an internal source of vulnerability information.</li>&#10;<li>&#160;External&#160;or public&#160;sources typically provide information that is focused on common technologies.</li>&#10;</ul>&#10;&#10;<div><p><b>Example sources of vulnerability information:</b></p></div>&#10;<ul>&#10;<li>&#160;vendors of software, systems, and hardware technologies</li>&#10;<li>&#160;common free catalogs, such as:</li><ul><li>US-CERT Vulnerability Database</li><li>The Common Vulnerabilities and Exposures (CVE) List</li></ul><li>&#160;industry groups</li>&#10;<li>&#160;results of executing automated tools, techniques, and methods</li>&#10;</ul>&#10;&#10;<div><p><b>Criteria for &#8220;Yes&#8221; Response:</b></p></div>&#10;<ul>&#10;<li>&#160;The organization has&#160;identified and documented&#160;sources of vulnerability information for&#160;all of the assets that support the critical service.</li>&#10;</ul>&#10;<div><p><b>Criteria for &#8220;Incomplete&#8221; Response:</b></p></div>&#10;<ul>&#10;<li>&#160;The organization has identified and documented sources of vulnerability information for&#160;some assets.</li>&#10;</ul>&#10;' WHERE [Mat_Question_Id] = 3280
