UPDATE [dbo].[MATURITY_QUESTIONS] SET [Ranking]=1111 WHERE [Mat_Question_Id] = 3287
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><p><b>Question Intent:</b></p></div> To determine if vulnerabilities are actively being discovered.  <ul> <li> Vulnerabilities are discovered from an active review of the organization''s standard list of vulnerability sources.</li> </ul>  <div><p><b>Techniques used to discover vulnerabilities include:</b></p></div> <ul> <li> performing internal vulnerability audits or assessments</li> <li> performing assessments of external entities</li> <li> reviewing the results of internal and external audits</li> <li> periodically reviewing vulnerability catalogs, such as the US-CERT</li> <li> reviewing notifications from identified vendor services</li> <li> reviewing notifications from identified vulnerability services</li> <li> reviewing reports from industry groups</li> <li> using reports of vulnerabilities from other processes such as the organization''s service desk</li> </ul>  <div><p><b>Criteria for “Yes” Response:</b></p></div> <ul> <li> Vulnerabilities are actively being discovered for all assets that support the critical service.</li> </ul> <div><p><b>Criteria for “Incomplete” Response:</b></p></div> <ul> <li> Vulnerabilities are actively being discovered for some assets that support the critical service.</li> <li> Or; vulnerabilities are inconsistently being discovered for all assets that support the critical service.</li> </ul>' WHERE [Mat_Question_Id] = 3288
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><p><b>Question Intent:</b></p></div> To determine if vulnerabilities are actively being discovered.  <ul> <li> Vulnerabilities are discovered from an active review of the organization''s standard list of vulnerability sources.</li> </ul>  <div><p><b>Techniques used to discover vulnerabilities include:</b></p></div> <ul> <li> performing internal vulnerability audits or assessments</li> <li> performing assessments of external entities</li> <li> reviewing the results of internal and external audits</li> <li> periodically reviewing vulnerability catalogs, such as the US-CERT</li> <li> reviewing notifications from identified vendor services</li> <li> reviewing notifications from identified vulnerability services</li> <li> reviewing reports from industry groups</li> <li> using reports of vulnerabilities from other processes such as the organization''s service desk</li> </ul>  <div><p><b>Criteria for “Yes” Response:</b></p></div> <ul> <li> Vulnerabilities are actively being discovered for all assets that support the critical service.</li> </ul> <div><p><b>Criteria for “Incomplete” Response:</b></p></div> <ul> <li> Vulnerabilities are actively being discovered for some assets that support the critical service.</li> <li> Or; vulnerabilities are inconsistently being discovered for all assets that support the critical service.</li> </ul>' WHERE [Mat_Question_Id] = 3289
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><p><b>Question Intent:</b></p></div> To determine if vulnerabilities are actively being discovered.  <ul> <li> Vulnerabilities are discovered from an active review of the organization''s standard list of vulnerability sources.</li> </ul>  <div><p><b>Techniques used to discover vulnerabilities include:</b></p></div> <ul> <li> performing internal vulnerability audits or assessments</li> <li> performing assessments of external entities</li> <li> reviewing the results of internal and external audits</li> <li> periodically reviewing vulnerability catalogs, such as the US-CERT</li> <li> reviewing notifications from identified vendor services</li> <li> reviewing notifications from identified vulnerability services</li> <li> reviewing reports from industry groups</li> <li> using reports of vulnerabilities from other processes such as the organization''s service desk</li> </ul>  <div><p><b>Criteria for “Yes” Response:</b></p></div> <ul> <li> Vulnerabilities are actively being discovered for all assets that support the critical service.</li> </ul> <div><p><b>Criteria for “Incomplete” Response:</b></p></div> <ul> <li> Vulnerabilities are actively being discovered for some assets that support the critical service.</li> <li> Or; vulnerabilities are inconsistently being discovered for all assets that support the critical service.</li> </ul>' WHERE [Mat_Question_Id] = 3290
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Ranking]=1111 WHERE [Mat_Question_Id] = 3291
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><p><b>Question Intent:</b></p></div>&#160;To determine if vulnerabilities are&#160;categorized and prioritized.&#10;&#10;<ul>&#10;<li>&#160;Prioritization can be:</li><ul><li>qualitative (high, medium, or low)</li><li>quantitative (through a numerical scale)</li></ul><li>&#160;Prioritization provides the organization a structured&#160;means for determining the appropriate categorization.</li>&#10;</ul>&#10;&#10;<div><p><b>Examples of categories based on actions to be taken for vulnerability resolution:</b></p></div>&#10;<ul>&#10;<li>&#160;take no action; ignore</li>&#10;<li>&#160;fix immediately (typically the case for vendor updates or changes)</li>&#10;<li>&#160;develop and implement a vulnerability resolution strategy (typically the case when the resolution is more extensive than simple actions such as vendor updates)</li>&#10;<li>&#160;perform additional research and analysis</li>&#10;<li>&#160;refer the vulnerability to the risk management process for formal risk consideration</li>&#10;</ul><b>&#10;&#10;Typical Work Products:</b><div><b><br></b><ul>&#10;<li>&#160;vulnerability categorization and prioritization guidelines</li>&#10;<li>&#160;list of vulnerabilities categorized and prioritized for disposition</li>&#10;<li>&#160;updated vulnerability repository</li>&#10;</ul>&#10;&#10;<div><p><b>Criteria for &#8220;Yes&#8221; Response:</b></p></div>&#10;<ul>&#10;<li>&#160;The organization&#160;prioritizes and categorizes vulnerabilities for all assets that support the critical service.</li>&#10;</ul>&#10;<div><p><b>Criteria for &#8220;Incomplete&#8221; Response:</b></p></div>&#10;<ul>&#10;<li>&#160;The organization prioritizes and categorizes&#160;vulnerabilities for&#160;some assets.</li>&#10;</ul>&#10;</div>' WHERE [Mat_Question_Id] = 3292
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><p><b>Question Intent:</b></p></div>&#160;To determine if vulnerabilities are&#160;categorized and prioritized.&#10;&#10;<ul>&#10;<li>&#160;Prioritization can be:</li><ul><li>qualitative (high, medium, or low)</li><li>quantitative (through a numerical scale)</li></ul><li>&#160;Prioritization provides the organization a structured&#160;means for determining the appropriate categorization.</li>&#10;</ul>&#10;&#10;<div><p><b>Examples of categories based on actions to be taken for vulnerability resolution:</b></p></div>&#10;<ul>&#10;<li>&#160;take no action; ignore</li>&#10;<li>&#160;fix immediately (typically the case for vendor updates or changes)</li>&#10;<li>&#160;develop and implement a vulnerability resolution strategy (typically the case when the resolution is more extensive than simple actions such as vendor updates)</li>&#10;<li>&#160;perform additional research and analysis</li>&#10;<li>&#160;refer the vulnerability to the risk management process for formal risk consideration</li>&#10;</ul><b>&#10;&#10;Typical Work Products:</b><div><b><br></b><ul>&#10;<li>&#160;vulnerability categorization and prioritization guidelines</li>&#10;<li>&#160;list of vulnerabilities categorized and prioritized for disposition</li>&#10;<li>&#160;updated vulnerability repository</li>&#10;</ul>&#10;&#10;<div><p><b>Criteria for &#8220;Yes&#8221; Response:</b></p></div>&#10;<ul>&#10;<li>&#160;The organization&#160;prioritizes and categorizes vulnerabilities for all assets that support the critical service.</li>&#10;</ul>&#10;<div><p><b>Criteria for &#8220;Incomplete&#8221; Response:</b></p></div>&#10;<ul>&#10;<li>&#160;The organization prioritizes and categorizes&#160;vulnerabilities for&#160;some assets.</li>&#10;</ul>&#10;</div>' WHERE [Mat_Question_Id] = 3293
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><p><b>Question Intent:</b></p></div>&#160;To determine if vulnerabilities are&#160;categorized and prioritized.&#10;&#10;<ul>&#10;<li>&#160;Prioritization can be:</li><ul><li>qualitative (high, medium, or low)</li><li>quantitative (through a numerical scale)</li></ul><li>&#160;Prioritization provides the organization a structured&#160;means for determining the appropriate categorization.</li>&#10;</ul>&#10;&#10;<div><p><b>Examples of categories based on actions to be taken for vulnerability resolution:</b></p></div>&#10;<ul>&#10;<li>&#160;take no action; ignore</li>&#10;<li>&#160;fix immediately (typically the case for vendor updates or changes)</li>&#10;<li>&#160;develop and implement a vulnerability resolution strategy (typically the case when the resolution is more extensive than simple actions such as vendor updates)</li>&#10;<li>&#160;perform additional research and analysis</li>&#10;<li>&#160;refer the vulnerability to the risk management process for formal risk consideration</li>&#10;</ul><b>&#10;&#10;Typical Work Products:</b><div><b><br></b><ul>&#10;<li>&#160;vulnerability categorization and prioritization guidelines</li>&#10;<li>&#160;list of vulnerabilities categorized and prioritized for disposition</li>&#10;<li>&#160;updated vulnerability repository</li>&#10;</ul>&#10;&#10;<div><p><b>Criteria for &#8220;Yes&#8221; Response:</b></p></div>&#10;<ul>&#10;<li>&#160;The organization&#160;prioritizes and categorizes vulnerabilities for all assets that support the critical service.</li>&#10;</ul>&#10;<div><p><b>Criteria for &#8220;Incomplete&#8221; Response:</b></p></div>&#10;<ul>&#10;<li>&#160;The organization prioritizes and categorizes&#160;vulnerabilities for&#160;some assets.</li>&#10;</ul>&#10;</div>' WHERE [Mat_Question_Id] = 3294
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Ranking]=1111 WHERE [Mat_Question_Id] = 3295
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><p><b>Question Intent:</b></p></div> To determine if vulnerabilities are analyzed to determine relevance to the organization.  <ul> <li> Through vulnerability analysis, the organization seeks to understand the potential threat that the vulnerability represents.</li> <li> The organization should assign a course of action to each vulnerability based upon its relevance to the organization.</li> </ul>  Vulnerability analysis includes activities to: <ul> <li> understand the threat and exposure</li> <li> review trend information to determine whether the vulnerability existed before and what actions were taken to reduce or eliminate it</li> <li> identify and understand underlying causes for exposure to the vulnerability</li> </ul>  <div><p><b>Criteria for “Yes” Response:</b></p></div> <ul> <li> The organization analyzes all vulnerabilities to determine their relevance to the critical service.</li> </ul> <div><p><b>Criteria for “Incomplete” Response:</b></p></div> <ul> <li> The organization analyzes some vulnerabilities to determine their relevance to the critical service.</li> </ul>' WHERE [Mat_Question_Id] = 3296
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><p><b>Question Intent:</b></p></div> To determine if vulnerabilities are analyzed to determine relevance to the organization.  <ul> <li> Through vulnerability analysis, the organization seeks to understand the potential threat that the vulnerability represents.</li> <li> The organization should assign a course of action to each vulnerability based upon its relevance to the organization.</li> </ul>  Vulnerability analysis includes activities to: <ul> <li> understand the threat and exposure</li> <li> review trend information to determine whether the vulnerability existed before and what actions were taken to reduce or eliminate it</li> <li> identify and understand underlying causes for exposure to the vulnerability</li> </ul>  <div><p><b>Criteria for “Yes” Response:</b></p></div> <ul> <li> The organization analyzes all vulnerabilities to determine their relevance to the critical service.</li> </ul> <div><p><b>Criteria for “Incomplete” Response:</b></p></div> <ul> <li> The organization analyzes some vulnerabilities to determine their relevance to the critical service.</li> </ul>' WHERE [Mat_Question_Id] = 3297
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><p><b>Question Intent:</b></p></div> To determine if vulnerabilities are analyzed to determine relevance to the organization.  <ul> <li> Through vulnerability analysis, the organization seeks to understand the potential threat that the vulnerability represents.</li> <li> The organization should assign a course of action to each vulnerability based upon its relevance to the organization.</li> </ul>  Vulnerability analysis includes activities to: <ul> <li> understand the threat and exposure</li> <li> review trend information to determine whether the vulnerability existed before and what actions were taken to reduce or eliminate it</li> <li> identify and understand underlying causes for exposure to the vulnerability</li> </ul>  <div><p><b>Criteria for “Yes” Response:</b></p></div> <ul> <li> The organization analyzes all vulnerabilities to determine their relevance to the critical service.</li> </ul> <div><p><b>Criteria for “Incomplete” Response:</b></p></div> <ul> <li> The organization analyzes some vulnerabilities to determine their relevance to the critical service.</li> </ul>' WHERE [Mat_Question_Id] = 3298
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Ranking]=1111 WHERE [Mat_Question_Id] = 3299
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><p><b>Question Intent:</b></p></div> To determine if a repository for recording information about vulnerabilities and their resolution is used.  <ul> <li> A vulnerability repository should be used as the central source of vulnerability life-cycle information.</li> <li> A vulnerability repository supports analysis, disposition, trending, root cause analysis, and vulnerability management.</li> </ul>  <div><p><b>Information that should be recorded includes:</b></p></div> <ul> <li> a unique identifier</li> <li> description of the vulnerability</li> <li> date entered into the repository</li> <li> references to the source of the vulnerability</li> <li> the priority of the vulnerability (high, medium, low)</li> <li> categorization and disposition of the vulnerability</li> <li> individuals or teams assigned to analyze and remediate the vulnerability</li> <li> a log of actions taken to reduce or eliminate the vulnerability</li> </ul>  <div><p><b>Criteria for “Yes” Response:</b></p></div> <ul> <li> The organization uses a repository to record all vulnerability information for all of the assets that support the critical service.</li> </ul> <div><p><b>Criteria for “Incomplete” Response:</b></p></div> <ul> <li> The organization uses a repository to record some vulnerability information.</li> <li> Or; the organization uses a repository to record all vulnerability information for some assets.</li> </ul>' WHERE [Mat_Question_Id] = 3300
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><p><b>Question Intent:</b></p></div> To determine if a repository for recording information about vulnerabilities and their resolution is used.  <ul> <li> A vulnerability repository should be used as the central source of vulnerability life-cycle information.</li> <li> A vulnerability repository supports analysis, disposition, trending, root cause analysis, and vulnerability management.</li> </ul>  <div><p><b>Information that should be recorded includes:</b></p></div> <ul> <li> a unique identifier</li> <li> description of the vulnerability</li> <li> date entered into the repository</li> <li> references to the source of the vulnerability</li> <li> the priority of the vulnerability (high, medium, low)</li> <li> categorization and disposition of the vulnerability</li> <li> individuals or teams assigned to analyze and remediate the vulnerability</li> <li> a log of actions taken to reduce or eliminate the vulnerability</li> </ul>  <div><p><b>Criteria for “Yes” Response:</b></p></div> <ul> <li> The organization uses a repository to record all vulnerability information for all of the assets that support the critical service.</li> </ul> <div><p><b>Criteria for “Incomplete” Response:</b></p></div> <ul> <li> The organization uses a repository to record some vulnerability information.</li> <li> Or; the organization uses a repository to record all vulnerability information for some assets.</li> </ul>' WHERE [Mat_Question_Id] = 3301
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><p><b>Question Intent:</b></p></div> To determine if a repository for recording information about vulnerabilities and their resolution is used.  <ul> <li> A vulnerability repository should be used as the central source of vulnerability life-cycle information.</li> <li> A vulnerability repository supports analysis, disposition, trending, root cause analysis, and vulnerability management.</li> </ul>  <div><p><b>Information that should be recorded includes:</b></p></div> <ul> <li> a unique identifier</li> <li> description of the vulnerability</li> <li> date entered into the repository</li> <li> references to the source of the vulnerability</li> <li> the priority of the vulnerability (high, medium, low)</li> <li> categorization and disposition of the vulnerability</li> <li> individuals or teams assigned to analyze and remediate the vulnerability</li> <li> a log of actions taken to reduce or eliminate the vulnerability</li> </ul>  <div><p><b>Criteria for “Yes” Response:</b></p></div> <ul> <li> The organization uses a repository to record all vulnerability information for all of the assets that support the critical service.</li> </ul> <div><p><b>Criteria for “Incomplete” Response:</b></p></div> <ul> <li> The organization uses a repository to record some vulnerability information.</li> <li> Or; the organization uses a repository to record all vulnerability information for some assets.</li> </ul>' WHERE [Mat_Question_Id] = 3302
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><p><b>Question Intent:</b></p></div> To determine if a plan for performing vulnerability management activities exists.
<ul>
<li> The plan defines vulnerability management within the organization and prescribes how vulnerability management activities will be performed.</li>
<li> The plan may be a stand-alone document, embedded in a more comprehensive document, or be distributed across multiple documents.</li>
</ul>

<div><p><b>The plan typically includes:</b></p></div>
<ul>
<li> vulnerability management activities (source identification, vulnerability identification, prioritization, categorization, analysis, etc.)</li>
<li> standards and requirements</li>
<li> roles, assignments of responsibility, resources, and funding</li>
<li> identification of stakeholders</li>
<li> measurement and reporting requirements</li>
<li> training requirements</li>
<li> management oversight</li>
</ul>

<div><p><b>Criteria for “Yes” Response:</b></p></div>
<ul>
<li> There is a documented plan for performing vulnerability management.</li>
</ul>
<div><p><b>Criteria for “Incomplete” Response:</b></p></div>
<ul>
<li> A plan is in development and partially documented.</li>
</ul>' WHERE [Mat_Question_Id] = 3307
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><p><b>Question Intent:</b></p></div> To determine if a policy for performing vulnerability management activities exists.

<ul>
<li> A policy is a written communication from the organization''s senior management to employees.</li>
<li> It establishes the organizational expectations for planning and performing the vulnerability management process and communicates those expectations to the organization.</li>
</ul>

<div><p><b>The policy should address:</b></p></div>
<ul>
<li> responsibility, authority, ownership, and the requirement to perform vulnerability management activities</li>
<li> establishment of procedures, standards, and guidelines</li>
<li> requirements for periodically assessing the vulnerability management activities</li>
<li> measuring adherence to policy, exceptions granted, and policy violations</li>
<li> compliance with legal, regulatory, contractual, and government obligations</li>
</ul>

<div><p><b>Criteria for “Yes” Response:</b></p></div>
<ul>
<li> The organization has a documented policy for performing vulnerability management.</li>
</ul>
<div><p><b>Criteria for “Incomplete” Response:</b></p></div>
<ul>
<li> A policy is in development and partially documented.</li>
</ul>' WHERE [Mat_Question_Id] = 3308
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><p><b>Question Intent:</b></p></div> To determine if stakeholders for vulnerability management activities have been identified and made aware of their roles.

<div><p><b>Stakeholders of the vulnerability management process have the following responsibilities:</b></p></div>
<ul>
<li> overseeing the vulnerability management process</li>
<li> resolving issues with the vulnerability management process</li>
<li> establishing vulnerability prioritization guidelines</li>
<li> assessing collected vulnerability data</li>
<li> providing feedback to those responsible for providing vulnerability data</li>
<li> reviewing and appraising the effectiveness of vulnerability management activities</li>
</ul>

<div><p><b>Examples of stakeholders include:</b></p></div>
<ul>
<li> critical service owners</li>
<li> management</li>
<li> owners of external entity relationships</li>
<li> vulnerability management program staff</li>
<li> owners and custodians of assets that underpin the service</li>
<li> critical service staff</li>
<li> external entities responsible for some part of the service</li>
<li> information technology staff</li>
<li> staff responsible for physical security</li>
<li> human resources</li>
<li> internal and external auditors</li>
<li> acquisition and procurement staff</li>
<li> enterprise risk management staff</li>
<li> service continuity staff</li>
</ul>

<div><p><b>Criteria for “Yes” Response:</b></p></div>
<ul>
<li> All stakeholders for the vulnerability management activities have been identified and made aware of their roles.</li>
</ul>
<div><p><b>Criteria for “Incomplete” Response:</b></p></div>
<ul>
<li> Some stakeholders for the vulnerability management activities have been identified and made aware of their roles.</li>
<li> Or; stakeholders are identified but have not been made aware of their roles.</li>
</ul>' WHERE [Mat_Question_Id] = 3309
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><p><b>Question Intent:</b></p></div> To determine if standards and guidelines for performing vulnerability management activities have been implemented.

<ul>
<li> Standards establish expectations for performance.</li>
<li> Guidelines are issued by an organization to ensure the performance of vulnerability management activities meets standards and is predictable, measurable, and repeatable.</li>
</ul>

<div><p><b>Standards and guidelines typically address:</b></p></div>
<ul>
<li> prioritization and categorization guidelines</li>
<li> analysis and disposition</li>
<li> reporting</li>
<li> tool selection and use</li>
<li> collection of vulnerability data</li>
</ul>

<div><p><b>Criteria for “Yes” Response:</b></p></div>
<ul>
<li> The organization has implemented documented standards and guidelines for performing vulnerability management activities.</li>
</ul>
<div><p><b>Criteria for “Incomplete” Response:</b></p></div>
<ul>
<li> Some standards and guidelines have been implemented.</li>
</ul>' WHERE [Mat_Question_Id] = 3310
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><p><b>Question Intent:</b></p></div> To determine if management oversight exists. The intent of oversight is to ensure the direct day-to-day monitoring of the vulnerability management activities.

<ul>
<li> Management consists of the immediate level of managers that govern the day-to-day operation of the vulnerability management activities.</li>
<li> Oversight provides visibility into the vulnerability management activities so that issues can be identified and appropriate corrective actions can be taken when necessary.</li>
<li> Oversight activities could include regular meetings, written or oral status updates, auditing, or spot checks.</li>
</ul>

<div><p><b>Examples of corrective actions:</b></p></div>
<ul>
<li> taking actions to repair defective work products or services</li>
<li> ensuring that standards and guidelines are followed</li>
<li> adjusting resources (people, tools, etc.)</li>
<li> identifying improvements in the vulnerability management activities</li>
<li> escalating issues that require higher level management input for resolution</li>
</ul>

<div><p><b>Criteria for “Yes” Response:</b></p></div>
<ul>
<li> Management oversight of all the day-to-day vulnerability management activities is being performed.</li>
</ul>
<div><p><b>Criteria for “Incomplete” Response:</b></p></div>
<ul>
<li> Management oversight covers some aspects of the day-to-day vulnerability management activities.</li>
</ul>' WHERE [Mat_Question_Id] = 3311
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><p><b>Question Intent:</b></p></div> To determine if qualified staff have been assigned. The intent of this question is to evaluate the qualifications of the staff, not the completeness of the plan.

<ul>
<li> Qualified means that staff are appropriately skilled to perform vulnerability management activities.</li>
</ul>

<div><p><b>Examples of staff include personnel responsible for:</b></p></div>
<ul>
<li> collecting, analyzing, and prioritizing vulnerability management requirements</li>
<li> developing vulnerability management analysis and resolution plans and programs</li>
<li> establishing an appropriate infrastructure for vulnerability data</li>
<li> the security and protection of vulnerability data.</li>
<li> manage external entities that have contractual obligations for vulnerability management analysis and resolution</li>
</ul>
<div><p><b>Examples of skills needed include:</b></p></div>
<ul>
<li> knowledge of tools, techniques, and methods used to identify, analyze, remediate, monitor, and communicate vulnerabilities</li>
<li> knowledge to ensure confidentiality, integrity, and availability of vulnerability data</li>
<li> knowledge necessary to interpret vulnerability data and represent it to appropriate stakeholders</li>
</ul>

<div><p><b>Criteria for “Yes” Response:</b></p></div>
<ul>
<li> All staff assigned to perform the planned vulnerability management activities are appropriately skilled.</li>
</ul>
<div><p><b>Criteria for “Incomplete” Response:</b></p></div>
<ul>
<li> Some staff assigned have the skill necessary to perform their roles.</li>
</ul>' WHERE [Mat_Question_Id] = 3312
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><p><b>Question Intent:</b></p></div> To determine if adequate funding has been provided. The intent of the question is to evaluate the completeness of the funding, not the completeness of the plan.

<ul>
<li> Funding is an indication of higher level management support and sponsorship of vulnerability management activities.</li>
<li> Funding should be available to support the proper oversight, execution, and maintenance of these activities.</li>
</ul>

<div><p><b>Considerations for funding planned vulnerability management activities include:</b></p></div>
<ul>
<li> defining funding needs</li>
<li> establishing a budget</li>
<li> resolving funding gaps</li>
<li> funding the process activities including staffing, tools, training, etc.</li>
</ul>

<div><p><b>Criteria for “Yes” Response:</b></p></div>
<ul>
<li> Adequate funding has been provided to perform all planned vulnerability management activities.</li>
</ul>
<div><p><b>Criteria for “Incomplete” Response:</b></p></div>
<ul>
<li> The planned activities have only been partially funded.</li>
</ul>' WHERE [Mat_Question_Id] = 3313
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><p><b>Question Intent:</b></p></div> To determine if the organization identifies, analyzes, and mitigates risks related to the performance of the vulnerability management activities.

<ul>
<li> The intent is to determine risks that prevent the organization from performing vulnerability management activities (vulnerability management process), not the risks to the organization if the activities are not performed.</li>
</ul>

<div><p><b>Risks to consider in relation to the vulnerability management process include:</b></p></div>
<ul>
<li> poorly defined vulnerability management processes</li>
<li> inadequate staffing</li>
<li> inadequate funding</li>
<li> unqualified staff</li>
<li> lack of tools</li>
<li> lack of a documented plan, policy, standards, and guidelines</li>
<li> lack of stakeholder involvement</li>
<li> lack of management oversight</li>
</ul>

<div><p><b>Criteria for “Yes” Response:</b></p></div>
<ul>
<li> Risks to the performance of all planned vulnerability management activities are identified, analyzed, disposed of, monitored, and controlled.</li>
</ul>
<div><p><b>Criteria for “Incomplete” Response:</b></p></div>
<ul>
<li> Risks to the performance of some of the planned vulnerability management activities are identified, analyzed, disposed of, monitored, and controlled.</li>
<li> Or; risks to the performance of planned vulnerability management activities are identified, but are not analyzed, disposed of, monitored, or controlled.</li>
</ul>' WHERE [Mat_Question_Id] = 3314
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><p><b>Question Intent:</b></p></div> To ensure the vulnerability management activities (process) remain effective and produce intended results by periodic review and measurement.

<div><p><b>Periodic (as defined by the organization) reviews of the vulnerability management process are needed to ensure that:</b></p></div>
<ul>
<li> vulnerability management performance issues are identified and remediated</li>
<li> the quality of particular work products meets established guidelines</li>
<li> problems in the process plan or in the execution of the process are identified</li>
<li> risks related to vulnerability management performance are identified and addressed</li>
<li> actions requiring management involvement are elevated in a timely manner</li>
<li> new vulnerabilities are identified and prioritized</li>
<li> current sources of vulnerability data are in use</li>
<li> vulnerability mitigation activities are effective</li>
</ul>

<div><p><b>Example metrics of the vulnerability management process may include:</b></p></div>
<ul>
<li> number of reported vulnerabilities for which a vulnerability management strategy exists</li>
<li> number of vulnerabilities requiring a root-cause analysis</li>
<li> number of vulnerabilities referred to the risk management process</li>
<li> number of vulnerabilities where corrective action is still pending</li>
</ul>

<div><p><b>Criteria for “Yes” Response:</b></p></div>
<ul>
<li> All vulnerability management activities are periodically (as defined by the organization) reviewed and measured and the results evaluated.</li>
</ul>
<div><p><b>Criteria for “Incomplete” Response:</b></p></div>
<ul>
<li> The organization has not established a frequency for review of the vulnerability management activities.</li>
<li> Or; review and measurement address some of the vulnerability management activities.</li>
<li> Or; vulnerability management activities are reviewed but not measured.</li>
</ul>' WHERE [Mat_Question_Id] = 3315
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><p><b>Question Intent:</b></p></div> To periodically determine if vulnerability management activities are being performed as planned.

<ul>
<li> This review is often done by an independent entity (either internal or external to the organization).</li>
</ul>

<div><p><b>Periodic (as defined by the organization) reviews for adherence to the vulnerability management plan are needed to ensure that:</b></p></div>
<ul>
<li> activities are performed as planned and adhere to process descriptions, standards, and procedures</li>
<li> deviations from the plan are identified and evaluated</li>
<li> problems in the plan for performing vulnerability management activities are identified</li>
<li> non-compliance is addressed</li>
<li> needed process changes are identified when expected results or outputs are not met</li>
</ul>

<div><p><b>Criteria for “Yes” Response:</b></p></div>
<ul>
<li> All vulnerability management activities are periodically (as defined by the organization) reviewed to ensure that those activities are performed as planned.</li>
</ul>
<div><p><b>Criteria for “Incomplete” Response:</b></p></div>
<ul>
<li> The organization has not established a frequency for review.</li>
<li> Or; some vulnerability management activities are reviewed to ensure that those activities are performed as planned.</li>
</ul>' WHERE [Mat_Question_Id] = 3316
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><p><b>Question Intent:</b></p></div> To determine if the performance of vulnerability management is communicated to higher level managers to provide visibility and facilitate the resolution of issues.

<ul>
<li> Higher level managers include those in the organization above the immediate level of management responsible for the vulnerability management process.</li>
<li> Communications are expected to be performed periodically (as defined by the organization) and may be event-driven when escalation is needed.</li>
</ul>

<div><p><b>Communication with higher-level managers typically includes:</b></p></div>
<ul>
<li> status reviews of vulnerability management activities</li>
<li> issues identified in process and plan reviews</li>
<li> risks associated with vulnerability management activities</li>
<li> recommendations for improvement</li>
</ul>

<div><p><b>Criteria for “Yes” Response:</b></p></div>
<ul>
<li> Higher-level management is made aware of issues related to the performance of vulnerability management through scheduled communication.</li>
</ul>
<div><p><b>Criteria for “Incomplete” Response:</b></p></div>
<ul>
<li> The organization has not established a frequency for communication to higher-level management.</li>
<li> Or; communications address some issues.</li>
</ul>' WHERE [Mat_Question_Id] = 3317
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><p><b>Question Intent:</b></p></div> To determine if the organization has a standard process that defines vulnerability management activities.

<ul>
<li> A standard process should include guidelines for tailoring the process to meet the needs of an organizational unit.</li>
<li> A standard process provides a predictable level of consistency in vulnerability management activities across the organization.</li>
</ul>

<div><p><b>A standard definition may include:</b></p></div>
<ul>
<li> process description</li>
<li> process activities and practices to be performed</li>
<li> process flow including diagrams</li>
<li> inputs and expected outputs</li>
<li> performance measures for improvement</li>
<li> procedures for process improvement</li>
</ul>

<div><p><b>Criteria for “Yes” Response:</b></p></div>
<ul>
<li> The organization has adopted a standard definition of vulnerability management.</li>
</ul>
<div><p><b>Criteria for “Incomplete” Response:</b></p></div>
<ul>
<li> A standard definition of vulnerability management is in development and partially documented.</li>
</ul>' WHERE [Mat_Question_Id] = 3318
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><p><b>Question Intent:</b></p></div> To ensure that improvements to the vulnerability management process are documented and shared across the organization.

<ul>
<li> Documenting lessons learned during the execution and review of the vulnerability management process facilitates the proposal of improvements to the process.</li>
<li> Sharing lessons learned enables organization-wide process improvements and organization-wide learning.</li>
</ul>

<div><p><b>Examples of improvement work products may include:</b></p></div>
<ul>
<li> process metrics and measurements</li>
<li> reports on the effectiveness of controls in mitigating vulnerabilities</li>
<li> lessons learned from root-cause analysis</li>
<li> improvements based on risk identification and mitigation</li>
<li> changes in operating conditions, risk conditions, and the risk environment that impact vulnerability management</li>
</ul>

<div><p><b>Criteria for “Yes” Response:</b></p></div>
<ul>
<li> Improvements to vulnerability management processes are documented and shared across the organization.</li>
</ul>
<div><p><b>Criteria for “Incomplete” Response:</b></p></div>
<ul>
<li> Improvements to vulnerability management processes are inconsistently documented.</li>
<li> Or; not consistently shared across the organization.</li>
</ul>' WHERE [Mat_Question_Id] = 3319
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Ranking]=1111 WHERE [Mat_Question_Id] = 3333
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Ranking]=1111 WHERE [Mat_Question_Id] = 3336
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><p><b>Question Intent:</b></p></div> To determine if a plan for performing incident management activities exists.

<ul>
<li> The plan defines incident management within the organization and prescribes how incident management activities will be performed.</li>
<li> The plan may be a standalone document, embedded in a more comprehensive document, or distributed across multiple documents.</li>
</ul>

<div><p><b>The plan typically includes:</b></p></div>
<ul>
<li> incident management activities (event detection, incident declaration, incident analysis, etc.)</li>
<li> standards and requirements</li>
<li> roles, assignments of responsibility, resources, and funding</li>
<li> identification of stakeholders</li>
<li> measurement and reporting requirements</li>
<li> training requirements</li>
<li> management oversight</li>
</ul>

<div><p><b>Criteria for “Yes” Response:</b></p></div>
<ul>
<li> There is a documented plan for performing incident management.</li>
</ul>
<div><p><b>Criteria for “Incomplete” Response:</b></p></div>
<ul>
<li> A plan is in development and partially documented.</li>
</ul>' WHERE [Mat_Question_Id] = 3343
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><p><b>Question Intent:</b></p></div> To determine if a policy for performing incident management activities exists.

<ul>
<li> A policy is a written communication from the organization''s senior management to its employees.</li>
<li> It establishes the organizational expectations for planning and performing the incident management process and communicates those expectations to the organization.</li>
</ul>

<div><p><b>The policy should address:</b></p></div>
<ul>
<li> responsibility, authority, ownership, and the requirement to perform incident management activities</li>
<li> establishment of procedures, standards, and guidelines</li>
<li> requirements for periodically assessing incident management activities</li>
<li> post-incident review, problem resolution, and closure</li>
<li> measuring adherence to policy, exceptions granted, and policy violations</li>
<li> compliance with legal, regulatory, contractual, and government obligations</li>
</ul>

<div><p><b>Criteria for “Yes” Response:</b></p></div>
<ul>
<li> The organization has a documented policy for performing incident management.</li>
</ul>
<div><p><b>Criteria for “Incomplete” Response:</b></p></div>
<ul>
<li> A policy is in development and partially documented.</li>
</ul>' WHERE [Mat_Question_Id] = 3344
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><p><b>Question Intent:</b></p></div> To determine if stakeholders for incident management activities have been identified and made aware of their roles.

<div><p><b>Stakeholders of the incident management process have the following responsibilities:</b></p></div>
<ul>
<li> overseeing the incident management process</li>
<li> making critical decisions during the incident management process</li>
<li> resolving issues with the incident management process</li>
<li> detecting events and incidents</li>
<li> planning for incident handling, management, and response</li>
<li> collecting, documenting, and preserving event and incident evidence</li>
<li> analyzing events and incidents</li>
<li> declaring incidents</li>
</ul>

<div><p><b>Examples of stakeholders include:</b></p></div>
<ul>
<li> critical service owners and staff</li>
<li> management</li>
<li> incident manages</li>
<li> incident owners</li>
<li> staff who serve key roles in incident communication activities, such as public relations</li>
<li> owners and custodians of assets that underpin the service</li>
<li> external entities responsible for some part of the service</li>
<li> information technology staff</li>
<li> staff responsible for physical security</li>
<li> human resources</li>
<li> internal and external auditors</li>
<li> acquisition and procurement staff</li>
<li> service continuity staff</li>
</ul>

<div><p><b>Criteria for “Yes” Response:</b></p></div>
<ul>
<li> All stakeholders for the incident management activities have been identified and made aware of their roles.</li>
</ul>
<div><p><b>Criteria for “Incomplete” Response:</b></p></div>
<ul>
<li> Some stakeholders for the incident management activities have been identified and made aware of their roles.</li>
<li> Or; stakeholders are identified but have not been made aware of their roles.</li>
</ul>' WHERE [Mat_Question_Id] = 3345
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><p><b>Question Intent:</b></p></div> To determine if standards and guidelines for performing incident management activities have been implemented.

<ul>
<li> Standards establish expectations for performance.</li>
<li> Guidelines are issued by an organization to ensure the performance of incident management activities meets standards and is predictable, measurable, and repeatable.</li>
</ul>

<div><p><b>Standards and guidelines typically address:</b></p></div>
<ul>
<li> detecting, logging, reporting, and tracking events</li>
<li> collecting and preserving evidence</li>
<li> triaging events</li>
<li> analyzing events</li>
<li> declaring an incident from one or more events</li>
<li> responding to incidents, including escalation procedures</li>
<li> incident communication protocols</li>
<li> creating and maintaining the incident knowledge base</li>
</ul>

<div><p><b>Criteria for “Yes” Response:</b></p></div>
<ul>
<li> The organization has implemented documented standards and guidelines for performing incident management activities.</li>
</ul>
<div><p><b>Criteria for “Incomplete” Response:</b></p></div>
<ul>
<li> Some standards and guidelines have been implemented.</li>
</ul>' WHERE [Mat_Question_Id] = 3346
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><p><b>Question Intent:</b></p></div> To determine if management oversight exists. The intent of oversight is to ensure the direct day-to-day monitoring of the incident management activities.

<ul>
<li> Management consists of the immediate level of managers that govern the day-to-day operation of the incident management activities.</li>
<li> Oversight provides visibility into the incident management activities so that issues can be identified and appropriate corrective actions can be taken when necessary.</li>
<li> Oversight activities could include regular meetings, written or oral status updates, auditing, or spot checks.</li>
</ul>

<div><p><b>Examples of corrective actions:</b></p></div>
<ul>
<li> taking actions to repair defective work products or services</li>
<li> ensuring that standards and guidelines are followed</li>
<li> adjusting resources (people, tools, etc.)</li>
<li> identifying improvements in the incident management activities</li>
<li> escalating issues that require higher level management input for resolution</li>
</ul>

<div><p><b>Criteria for “Yes” Response:</b></p></div>
<ul>
<li> Management oversight of all the day-to-day incident management activities is being performed.</li>
</ul>
<div><p><b>Criteria for “Incomplete” Response:</b></p></div>
<ul>
<li> Management oversight covers some aspects of the day-to-day incident management activities.</li>
</ul>' WHERE [Mat_Question_Id] = 3347
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><p><b>Question Intent:</b></p></div> To determine if qualified staff have been assigned. The intent of this question is to evaluate the qualifications of the staff, not the completeness of the plan.

<ul>
<li> Qualified means that staff are appropriately skilled to perform incident management activities.</li>
</ul>

<div><p><b>Examples of staff include personnel responsible for:</b></p></div>
<ul>
<li> detecting, logging, analyzing, reporting, and tracking events</li>
<li> collecting and preserving evidence</li>
<li> declaring an incident from one or more events</li>
<li> managing incidents and making critical decisions</li>
<li> analyzing and responding to incidents, including escalation procedures</li>
<li> communicating incidents</li>
<li> performing post-incident reviews, resolving problems, and closing incidents</li>
<li> creating and maintaining the incident knowledge base</li>
<li> managing external entities that have contractual obligations for process activities</li>
</ul>
<div><p><b>Examples of skills needed include:</b></p></div>
<ul>
<li> event detection, reporting, and tracking, including service desk activities</li>
<li> documenting and logging event reports</li>
<li> collecting and preserving evidence</li>
<li> declaring incidents</li>
<li> incident analysis</li>
<li> escalating and communicating incidents</li>
<li> understanding and applying laws, rules, and regulations</li>
<li> performing root-cause analysis and post-incident review</li>
</ul>

<div><p><b>Criteria for “Yes” Response:</b></p></div>
<ul>
<li> All staff assigned to perform the planned incident management activities are appropriately skilled.</li>
</ul>
<div><p><b>Criteria for “Incomplete” Response:</b></p></div>
<ul>
<li> Some staff assigned have the skill necessary to perform their roles.</li>
</ul>' WHERE [Mat_Question_Id] = 3348
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><p><b>Question Intent:</b></p></div> To determine if adequate funding has been provided. The intent of the question is to evaluate the completeness of the funding, not the completeness of the plan.

<ul>
<li> Funding is an indication of higher level management support and sponsorship of incident management activities.</li>
<li> Funding should be available to support the proper oversight, execution, and maintenance of these activities.</li>
</ul>

<div><p><b>Considerations for funding planned incident management activities include:</b></p></div>
<ul>
<li> defining funding needs</li>
<li> establishing a budget</li>
<li> resolving funding gaps</li>
<li> funding the process activities including staffing, tools, training, etc.</li>
</ul>

<div><p><b>Criteria for “Yes” Response:</b></p></div>
<ul>
<li> Adequate funding has been provided to perform all planned incident management activities.</li>
</ul>
<div><p><b>Criteria for “Incomplete” Response:</b></p></div>
<ul>
<li> The planned activities have only been partially funded.</li>
</ul>' WHERE [Mat_Question_Id] = 3349
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><p><b>Question Intent:</b></p></div> To determine if the organization identifies, analyzes, and mitigates risks related to the performance of incident management activities.

<ul>
<li> The intent is to determine risks that prevent the organization from performing incident management activities (incident management process), not the risks to the organization if the activities are not performed.</li>
</ul>

<div><p><b>Risks to consider in relation to the incident management process include:</b></p></div>
<ul>
<li> poorly defined incident management processes</li>
<li> inadequate staffing</li>
<li> inadequate funding</li>
<li> unqualified staff</li>
<li> lack of tools</li>
<li> lack of a documented plan, policy, standards, and guidelines</li>
<li> lack of stakeholder involvement</li>
<li> lack of management oversight</li>
</ul>

<div><p><b>Criteria for “Yes” Response:</b></p></div>
<ul>
<li> Risks to the performance of all planned incident management activities are identified, analyzed, disposed of, monitored, and controlled.</li>
</ul>
<div><p><b>Criteria for “Incomplete” Response:</b></p></div>
<ul>
<li> Risks to the performance of some of the planned incident management activities are identified, analyzed, disposed of, monitored, and controlled.</li>
<li> Or; risks to the performance of planned incident management activities are identified, but are not analyzed, disposed of, monitored, or controlled.</li>
</ul>' WHERE [Mat_Question_Id] = 3350
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><p><b>Question Intent:</b></p></div> To periodically determine if incident management activities are being performed as planned.

<ul>
<li> This review is often done by an independent entity (either internal or external to the organization).</li>
</ul>

<div><p><b>Periodic (as defined by the organization) reviews for adherence to the incident management plan are needed to ensure that:</b></p></div>
<ul>
<li> activities are performed as planned and adhere to process descriptions, standards, and procedures</li>
<li> deviations from the plan are identified and evaluated</li>
<li> problems in the plan for performing incident management activities are identified</li>
<li> non-compliance is addressed</li>
<li> needed process changes are identified when expected results or outputs are not met</li>
</ul>

<div><p><b>Criteria for “Yes” Response:</b></p></div>
<ul>
<li> All incident management activities are periodically (as defined by the organization) reviewed to ensure that those activities are performed as planned.</li>
</ul>
<div><p><b>Criteria for “Incomplete” Response:</b></p></div>
<ul>
<li> The organization has not established a frequency for review.</li>
<li> Or; some incident management activities are reviewed to ensure that those activities are performed as planned.</li>
</ul>' WHERE [Mat_Question_Id] = 3352
UPDATE [dbo].[MATURITY_QUESTIONS] SET [Supplemental_Info]='<div><p><b>Question Intent:</b></p></div> To determine if service continuity plans are developed and documented for assets required for the delivery of the critical service.  <ul> <li> A service continuity plan is a proactive plan of action an organization will take if a service disruption occurs.</li> <li> Plans should be developed at the time of service development and implementation.</li> <li> Plans should also be adjusted on an ongoing basis as new risks are encountered and the operational environment changes.</li> <li> Service continuity plans may require one or more sub plans such as a recovery or restoration plan.</li> </ul>  <div><p><b>Typical work products include:</b></p></div> <ul> <li> service continuity plan templates</li> <li> service continuity plans (including a list of relevant stakeholders)</li> </ul>  <div><p><b>Criteria for “Yes” Response:</b></p></div> <ul> <li> The organization has developed and documented service continuity plans for all assets required for the delivery of the critical service.</li> </ul> <div><p><b>Criteria for “Incomplete” Response:</b></p></div> <ul> <li> Service continuity plans have been developed and documented for some assets.</li> <li> Or; service continuity plans are in development and partially documented.</li> </ul>' WHERE [Mat_Question_Id] = 3357
