INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3169, 1, '<span><b>CERT-RMM Reference</b></span><div><span><b>[AM:SG1.SP1]</b></span>&#160;Access requests should be sponsored by an appropriate person in the&#160;organization (i.e., a supervisor or manager) and should be directly submitted to and&#160;approved by the owner of the assets (or their agents) to which access is being requested.&#160;Access requests should include proper justification for the&#160; request and should be approved&#160;by the sponsor of the request.<span><br></span><span><br></span></div><div><span><b>Additional References:</b></span><ul><li>NIST SP 800-53 Rev. 4 AC-1</li><li>NIST CSF References: PR.AC-1, PR.AC-2, PR.AC-3, PR.AC-6, PR.AC-7</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3170, 1, '<span><b>CERT-RMM Reference</b></span><div><b><span>[AM:SG1.SP1]</span>&#160;</b>Access requests should be sponsored by an appropriate person in the&#160;organization (i.e., a supervisor or manager) and should be directly submitted to and&#160;approved by the owner of the assets (or their agents) to which access is being requested.&#160;Access requests should include proper justification for the&#160; request and should be approved&#160;by the sponsor of the request.<span><br></span><span><br></span></div><div><span><b>Additional References:</b></span><ul><li>NIST SP 800-53 Rev. 4 AC-1</li><li>NIST CSF References: PR.AC-1, PR.AC-2, PR.AC-3, PR.AC-6, PR.AC-7</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3171, 1, '<span><b>CERT-RMM Reference</b></span><div><b><span>[AM:SG1.SP1]</span>&#160;</b>Access requests should be sponsored by an appropriate person in the&#160;organization (i.e., a supervisor or manager) and should be directly submitted to and&#160;approved by the owner of the assets (or their agents) to which access is being requested.&#160;Access requests should include proper justification for the&#160; request and should be approved&#160;by the sponsor of the request.<span><br></span><span><br></span></div><div><span><b>Additional References:</b></span><ul><li>NIST SP 800-53 Rev. 4 AC-1</li><li>NIST CSF References: PR.AC-1, PR.AC-2, PR.AC-3, PR.AC-6, PR.AC-7</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3172, 1, '<span><b>CERT-RMM Reference</b></span><div><span><b>[AM:SG1.SP3]&#160;</b></span>The mismanagement of access privileges is a major source of potential risks&#160;and vulnerabilities to the organization. Because assets and the identity community that&#160;needs access to the assets are pervasive across the organization, and in some cases extend&#160;beyond the organization, the ability to ensure that only authorized identities have&#160;appropriate privileges is an ongoing challenge. The organization must establish&#160;responsibility for regular review of access privileges and a process for correcting&#160;inconsistencies.</div><div><br><span><b>Additional References:</b></span></div><div><ul><li>NIST SP 800-53 Rev. 4 AC-2</li><li>NIST CSF References: PR.AC-1</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3173, 1, '<span><b>CERT-RMM Reference</b></span><div><b>[AM:SG1.SP3]</b>&#160;The mismanagement of access privileges is a major source of potential risks&#160;and vulnerabilities to the organization. Because assets and the identity community that&#160;needs access to the assets are pervasive across the organization, and in some cases extend&#160;beyond the organization, the ability to ensure that only authorized identities have&#160;appropriate privileges is an ongoing challenge. The organization must establish&#160;responsibility for regular review of access privileges and a process for correcting&#160;inconsistencies.</div><div><br><span><b>Additional References:</b></span></div><div><ul><li>NIST SP 800-53 Rev. 4 AC-2</li><li>NIST CSF References: PR.AC-1</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3174, 1, '<b>CERT-RMM Reference</b><div><b>[AM:SG1.SP3]</b><span>&#160;</span>The mismanagement of access privileges is a major source of potential risks&#160;and vulnerabilities to the organization. Because assets and the identity community that&#160;needs access to the assets are pervasive across the organization, and in some cases extend&#160;beyond the organization, the ability to ensure that only authorized identities have&#160;appropriate privileges is an ongoing challenge. The organization must establish&#160;responsibility for regular review of access privileges and a process for correcting&#160;inconsistencies.</div><div><br><b>Additional References:</b></div><div><ul><li>NIST SP 800-53 Rev. 4 AC-2</li><li>NIST CSF References: PR.AC-1</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3175, 1, '<span><span><b>CERT-RMM Reference</b></span></span><div><span><b>[AM:SG1.SP4]&#160;</b></span>Asset owners should document any inconsistencies or misalignment in&#160;access privileges. Owners should identify privileges that are:<ul><li>excessive</li><li>out of alignment with the identity''s role or job responsibility</li><li>assigned but never approved by the asset owner</li><li>in violation of the asset''s resilience requirements</li></ul>Owners should also identify identities that may have been provisioned with access&#160;privileges but are no longer considered as valid identities. A disposition for each&#160;inconsistency or misalignment should be documented, as well as the actions that need to&#160;be taken to correct these issues.</div><div><br></div><div><span><b>Additional References:</b></span><ul><li>NIST SP 800-53 Rev. 4 AC-2</li><li>NIST CSF References: PR.AC-1</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3176, 1, '<span><b>CERT-RMM Reference</b></span><div><span><b>[AM:SG1.SP4]&#160;</b></span>Asset owners should document any inconsistencies or misalignment in&#160;access privileges. Owners should identify privileges that are:<ul><li>excessive</li><li>out of alignment with the identity''s role or job responsibility</li><li>assigned but never approved by the asset owner</li><li>in violation of the asset''s resilience requirements</li></ul>Owners should also identify identities that may have been provisioned with access&#160;privileges but are no longer considered as valid identities. A disposition for each&#160;inconsistency or misalignment should be documented, as well as the actions that need to&#160;be taken to correct these issues.</div><div><br></div><div><span><b>Additional References:</b></span><ul><li>NIST SP 800-53 Rev. 4 AC-2</li><li>NIST CSF References: PR.AC-1</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3177, 1, '<span><b>CERT-RMM Reference</b></span><div><b>[AM:SG1.SP4]</b>&#160;Asset owners should document any inconsistencies or misalignment in&#160;access privileges. Owners should identify privileges that are:<ul><li>excessive</li><li>out of alignment with the identity''s role or job responsibility</li><li>assigned but never approved by the asset owner</li><li>in violation of the asset''s resilience requirements</li></ul>Owners should also identify identities that may have been provisioned with access&#160;privileges but are no longer considered as valid identities. A disposition for each&#160;inconsistency or misalignment should be documented, as well as the actions that need to&#160;be taken to correct these issues.</div><div><b><br></b></div><div><span><b>Additional References:</b></span><ul><li>NIST SP 800-53 Rev. 4 AC-2</li><li>NIST CSF References: PR.AC-1</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3178, 1, '<span><b>CERT-RMM Reference</b></span><div><b><span>[AM:SG1.SP1]</span>&#160;</b>Access privileges are assigned and approved based on the role of the&#160;person, object, or entity that is requesting access. The access provided should be&#160;commensurate with and not exceed the requestors job responsibilities. Therefore, the&#160;asset owner is responsible for granting and revoking access privileges to an identity based&#160;on the identity''s role and the asset''s resilience requirements. To be successful, asset&#160;owners must be aware of identities that need access to their assets and must evaluate the&#160;need with respect to business and resilience requirements before granting approval.</div><div><span><br></span></div><div><b><span>Additional References:</span><br></b></div><div><ul><li>NIST SP 800-53 Rev. 4 AC-2, AC-3, AC-5, AC-6, AC-16</li><ul><li>The principle of least privilege is employed to ensure users and processes operate at&#160;privilege levels no higher than necessary. Access permissions can also be employed at the&#160;application and service level to provide increased information security.</li></ul><li>NIST CSF References: PR.AC-4</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3179, 1, '<span><span><b>CERT-RMM Reference</b></span></span><div><span><b>[AM:SG1.SP1]&#160;</b></span>Access privileges are assigned and approved based on the role of the&#160;person, object, or entity that is requesting access. The access provided should be&#160;commensurate with and not exceed the requestors job responsibilities. Therefore, the&#160;asset owner is responsible for granting and revoking access privileges to an identity based&#160;on the identity''s role and the asset''s resilience requirements. To be successful, asset&#160;owners must be aware of identities that need access to their assets and must evaluate the&#160;need with respect to business and resilience requirements before granting approval.</div><div><br></div><div><span><b>Additional References:</b><br></span></div><div><ul><li>NIST SP 800-53 Rev. 4 AC-2, AC-3, AC-5, AC-6, AC-16</li><ul><li>The principle of least privilege is employed to ensure users and processes operate at&#160;privilege levels no higher than necessary. Access permissions can also be employed at the&#160;application and service level to provide increased information security.</li></ul><li>NIST CSF References: PR.AC-4</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3180, 1, '<span><span><b>CERT-RMM Reference</b></span></span><div><span><b>[AM:SG1.SP1]&#160;</b></span>Access privileges are assigned and approved based on the role of the&#160;person, object, or entity that is requesting access. The access provided should be&#160;commensurate with and not exceed the requestors job responsibilities. Therefore, the&#160;asset owner is responsible for granting and revoking access privileges to an identity based&#160;on the identity''s role and the asset''s resilience requirements. To be successful, asset&#160;owners must be aware of identities that need access to their assets and must evaluate the&#160;need with respect to business and resilience requirements before granting approval.</div><div><br></div><div><span><b>Additional References:</b></span><br></div><div><ul><li>NIST SP 800-53 Rev. 4 AC-2, AC-3, AC-5, AC-6, AC-16</li><ul><li>The principle of least privilege is employed to ensure users and processes operate at&#160;privilege levels no higher than necessary. Access permissions can also be employed at the&#160;application and service level to provide increased information security.</li></ul><li>NIST CSF References: PR.AC-4</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3181, 1, '<span><span><b>CERT-RMM Reference</b></span></span><div><b><span>[AM:SG1.SP1]</span>&#160;</b>Access privileges are assigned and approved based on the role of the&#160;person, object, or entity that is requesting access. The access provided should be&#160;commensurate with and not exceed the requestors job responsibilities. Therefore, the&#160;asset owner is responsible for granting and revoking access privileges to an identity based&#160;on the identity''s role and the asset''s resilience requirements. To be successful, asset&#160;owners must be aware of identities that need access to their assets and must evaluate the&#160;need with respect to business and resilience requirements before granting approval.</div><div><span><br></span></div><div><span><b>Additional References:</b></span><br></div><div><ul><li>NIST SP 800-53 Rev. 4 AC-2, AC-3, AC-5, AC-6, AC-16</li><ul><li>Consider using separation of duties to address the potential for abuse of authorized&#160;privileges by dividing roles and privileges between users (e.g., ensuring security personnel&#160;administering access control functions do not also administer audit functions).</li></ul><li>NIST CSF References: PR.AC-4</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3182, 1, '<span><span><b>CERT-RMM Reference</b></span></span><div><span><b>[AM:SG1.SP1]</b></span>&#160;Access privileges are assigned and approved based on the role of the&#160;person, object, or entity that is requesting access. The access provided should be&#160;commensurate with and not exceed the requestors job responsibilities. Therefore, the&#160;asset owner is responsible for granting and revoking access privileges to an identity based&#160;on the identity''s role and the asset''s resilience requirements. To be successful, asset&#160;owners must be aware of identities that need access to their assets and must evaluate the&#160;need with respect to business and resilience requirements before granting approval.</div><div><span><b><br></b></span></div><div><span><b>Additional References:</b></span><br></div><div><ul><li>NIST SP 800-53 Rev. 4 AC-2, AC-3, AC-5, AC-6, AC-16</li><ul><li>Consider using separation of duties to address the potential for abuse of authorized&#160;privileges by dividing roles and privileges between users (e.g., ensuring security personnel&#160;administering access control functions do not also administer audit functions).</li></ul><li>NIST CSF References: PR.AC-4</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3183, 1, '<span><b>CERT-RMM Reference</b></span><div><b>[AM:SG1.SP1]&#160;</b>Access privileges are assigned and approved based on the role of the&#160;person, object, or entity that is requesting access. The access provided should be&#160;commensurate with and not exceed the requestors job responsibilities. Therefore, the&#160;asset owner is responsible for granting and revoking access privileges to an identity based&#160;on the identity''s role and the asset''s resilience requirements. To be successful, asset&#160;owners must be aware of identities that need access to their assets and must evaluate the&#160;need with respect to business and resilience requirements before granting approval.</div><div><span><br></span></div><div><b>Additional References:</b><br></div><div><ul><li>NIST SP 800-53 Rev. 4 AC-2, AC-3, AC-5, AC-6, AC-16</li><ul><li>Consider using separation of duties to address the potential for abuse of authorized&#160;privileges by dividing roles and privileges between users (e.g., ensuring security personnel&#160;administering access control functions do not also administer audit functions).</li></ul><li>NIST CSF References: PR.AC-4</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3185, 1, '<div><span><b>CERT-RMM Reference</b></span></div><div><b>[CTRL:SG1.SP1]</b>&#160;Define and document control objectives that result from management&#160;<span>directives and guidelines. Affinity analysis of directives and guidelines may be useful in&#160;</span><span>identifying categories of control objectives.</span></div><div><br></div><div>These are examples of control objectives:</div><div><ul><li>prevent unauthorized use of purchase orders</li><li>ensure adequate supplies of materials</li><li>establish an enterprise architecture for information technology</li><li>develop and communicate policies regarding standards of ethical behavior</li><li>identify and assess risks that may cause material misstatements of financial records</li><li>educate and train staff</li><li>manage external entity relationships</li><li>establish a compliance program</li></ul></div><div><span><b>Additional References:</b></span></div><div><ul><li>FIPS Publication 199 Standards for Security Categorization of Federal Information and Information Systems Page 2</li><li>NIST CSF References: ID.GV-3, PR.AC, PR.DS, PR.IP, PR.MA, PR.PT</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3186, 1, '<div><span><b>CERT-RMM Reference</b></span></div><div><b><span>[CTRL:SG1.SP1]</span>&#160;</b>Define and document control objectives that result from management&#160;<span>directives and guidelines. Affinity analysis of directives and guidelines may be useful in&#160;</span><span>identifying categories of control objectives.</span></div><div><br></div><div>These are examples of control objectives:</div><div><ul><li>prevent unauthorized use of purchase orders</li><li>ensure adequate supplies of materials</li><li>establish an enterprise architecture for information technology</li><li>develop and communicate policies regarding standards of ethical behavior</li><li>identify and assess risks that may cause material misstatements of financial records</li><li>educate and train staff</li><li>manage external entity relationships</li><li>establish a compliance program</li></ul></div><div><span><b>Additional References:</b></span></div><div><ul><li>FIPS Publication 199 Standards for Security Categorization of Federal Information and Information Systems Page 2</li><li>NIST CSF References: ID.GV-3, PR.AC, PR.DS, PR.IP, PR.MA, PR.PT</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3187, 1, '<div><span><b>CERT-RMM Reference</b></span></div><div><b><span>[CTRL:SG1.SP1]</span>&#160;</b>Define and document control objectives that result from management&#160;<span>directives and guidelines. Affinity analysis of directives and guidelines may be useful in&#160;</span><span>identifying categories of control objectives.</span></div><div><br></div><div>These are examples of control objectives:</div><div><ul><li>prevent unauthorized use of purchase orders</li><li>ensure adequate supplies of materials</li><li>establish an enterprise architecture for information technology</li><li>develop and communicate policies regarding standards of ethical behavior</li><li>identify and assess risks that may cause material misstatements of financial records</li><li>educate and train staff</li><li>manage external entity relationships</li><li>establish a compliance program</li></ul></div><div><span><b>Additional References:</b></span></div><div><ul><li>FIPS Publication 199 Standards for Security Categorization of Federal Information and Information Systems Page 2</li><li>NIST CSF References: ID.GV-3, PR.AC, PR.DS, PR.IP, PR.MA, PR.PT</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3189, 1, '<div><b>CERT-RMM Reference</b></div><div><b>[CTRL:SG2.SP1]</b> Establish enterprise-level controls to satisfy control objectives. These can&#160;<span>be a combination of controls that already exist, controls that need updated, and new&#160;</span><span>controls that need to be implemented.</span></div><div><br></div><div><b>Additional References:</b></div><div><ul><li>Special Publication 800-39 &#34;Managing Information Security Risk Organization, Mission, and Information System View&#34; Page 14-15</li><li>NIST CSF References: ID.GV-3, PR.AC, PR.DS, PR.IP, PR.MA, PR.PT</li></ul></div><div><br></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3190, 1, '<div><b>CERT-RMM Reference</b></div><div><b>[CTRL:SG2.SP1]</b> Establish service-level and asset-level controls to satisfy control objectives.&#160;<span>These can be a combination of controls that already exist, controls that need updated, and&#160;</span><span>new controls that need to be implemented.</span></div><div><br></div><div><b>Additional References:</b></div><div><ul><li>NIST SP 800-53 Rev. 4 SC-7: Consider implementing segregation to protect network integrity. Segregation is a form of boundary protection and provides the capability to isolate or segregate certain organizational information system assets.</li><li>NIST CSF References: PR.AC-5</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3191, 1, '<div><b>CERT-RMM Reference</b></div><div><b>[CTRL:SG2.SP1]</b> Establish service-level and asset-level controls to satisfy control objectives.&#160;<span>These can be a combination of controls that already exist, controls that need updated, and&#160;</span><span>new controls that need to be implemented.</span></div><div><b>[KIM:SG4.SP2] </b>Develop and implement access controls to satisfy confidentiality and&#160;<span>integrity requirements. Manage access to controls on an on-going basis to ensure&#160;</span><span>continued satisfaction of those requirements.</span></div><div><br></div><div><b>Additional References:</b></div><div><ul><li>NIST SP 800-53 Rev. 4 SC-28: Implement mechanisms (e.g. encryption and/or secure offline storage) to achieve confidentiality and integrity protection of data-at-rest.</li><li>NIST CSF References: PR.DS-1</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3193, 1, '<p class="p1"><b>CERT-RMM Reference</b></p><p class="p1"><b>[CTRL:SG2.SP1] </b>Establish service-level and asset-level controls to satisfy control objectives. These can be a combination of controls that already exist, controls that need updated, and new controls that need to be implemented.</p><p class="p1"><b>[KIM:SG4.SP1]</b>Consider applying cryptographic controls to protect against data leaks.&#160;<span>Cryptographic controls are applied to information assets to ensure confidentiality and prevent intentional or unintentional disclosure.</span></p><p class="p1"><b>[KIM:SG4.SP2]</b> Develop and implement access controls to satisfy confidentiality and integrity requirements. Manage access to controls on an on-going basis to ensure continued satisfaction of those requirements.</p><b>Additional References:</b><div><ul><li><span>NIST SP 800-53 Rev. 4 AC-4, AC-5, AC-6, PE-19, PS-3, PS-6, SC-7, SC-8, SC-13, SC-31, SI-4: Consider implementing mechanisms (e.g. encryption and/or access controls) to protect against data leaks. Information/data leakage is the intentional or unintentional release of information to an untrusted environment.</span></li><li>NIST CSF References: PR.DS-5</li></ul><p></p></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3194, 1, '<div><b>CERT-RMM Reference</b></div><div><b>[CTRL:SG2.SP1]</b> Establish service-level and asset-level controls to satisfy control objectives.&#160;<span>These can be a combination of controls that already exist, controls that need updated, and&#160;</span><span>new controls that need to be implemented.</span></div><div><b>[MON:SG1.SP3] </b>Establish monitoring requirements for the management and review of&#160;<span>audit logs. Identify the level and type of monitoring activities needed to meet&#160;</span><span>requirements. Requirements should consider:</span></div><div><ul><li>the sources of data</li><li>the granularity of data</li><li>the distribution frequency</li><li>the retention of data</li></ul></div><div><b>Additional References:</b></div><div><ul><li>NIST SP 800-53 Rev. 4 AU Family: To determine the set of auditable events, consider the auditing appropriate for each of the security controls to be implemented. Protect audit information and audit tools from unauthorized access, modification, and deletion. Retain audit records until they are no longer needed for administrative, legal, audit, or other purposes.</li><li>NIST CSF References: PR.PT-1</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3195, 1, '<div><b>CERT-RMM Reference</b></div><div><b>[CTRL:SG2.SP1]</b> Establish enterprise-level controls to satisfy control objectives. These can&#160;<span>be a combination of controls that already exist, controls that need updated, and new&#160;</span><span>controls that need to be implemented.</span></div><div><b>[TM:SG2.SP2] </b>Develop, implement, and manage an appropriate level of administrative,&#160;<span>technical, and physical security controls to protect and restrict the use of removable&#160;</span><span>media. Monitor the effectiveness of these controls on a regular basis to ensure they&#160;</span><span>continue to meet requirements.</span></div><div><br></div><div><b>Additional References:</b></div><div><ul><li>NIST SP 800-53 Rev. 4 MP-2, MP-4, MP-5, MP-7:&#160;</li><ul><li><span>Consider restricting user access to removable media to defined personnel or roles.</span></li><li>Consider also measures to restrict the use of certain types of removable media and measures to protect removable media during transport.</li></ul><li>NIST CSF References: PR.PT-2</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3196, 1, '<div><b>CERT-RMM Reference</b></div><div><b>[CTRL:SG2.SP1] </b>Establish enterprise-level controls to satisfy control objectives. These can&#160;<span>be a combination of controls that already exist, controls that need updated, and new&#160;</span><span>controls that need to be implemented.</span></div><div><b>[TM:SG2.SP2] </b>Develop, implement, and manage an appropriate level of administrative,&#160;<span>technical, and physical security controls to protect communication and control networks.&#160;</span><span>Monitor the effectiveness of these controls on a regular basis to ensure they continue to&#160;</span><span>meet requirements.</span></div><div><br></div><div><b>Additional References:</b></div><div><ul><li>NIST SP 800-53 Rev. 4 AC-4, AC-17, AC-18, CP-8, SC-7: Consider establishing and documenting usage restrictions, configuration/connection requirements, and implementation guidance for the protection of communication and control networks. Implement controls to protect communication and control networks. Consider establishing alternate telecommunication and data communication services.</li><li>NIST CSF References: PR.PT-4</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3197, 1, '<p><b>CERT-RMM Reference&#160;</b></p><p><b>[CTRL:SG2.SP1]</b> Establish enterprise-level controls to satisfy control objectives. These can be a combination of controls that already exist, controls that need updated, and new controls that need to be implemented.<b>[HRM:SG3.SP1] </b>Cybersecurity obligations should be clearly documented in job descriptions so that staff members know their roles and responsibilities. All job descriptions in the organization, particularly those with vital roles, should clearly state the staff member''s cybersecurity roles, responsibilities, and job tasks.</p><b>Additional References:</b><div><ul><li><span>NIST SP 800-53 Rev. 4 PS Family: Consider implementing cybersecurity in human resource practices such as:</span></li><ul><li>personnel screening and rescreening processes</li><li>implementing and managing access agreements (nondisclosure agreements, acceptable use agreements, access agreements, etc.)</li><li>third-party personnel security processes</li><li>personnel sanctions for noncompliance</li></ul><li><span>NIST CSF References: PR.IP-11</span></li></ul><p></p></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3198, 1, '<font size="3"><b>CERT-RMM Reference<br>[CTRL:SG2.SP1] </b>Establish enterprise-level controls to satisfy control objectives. These can be a combination of controls that already exist, controls that need updated, and new controls that need to be implemented.<br><b>[TM:SG2.SP2] </b>Develop, implement, and manage an appropriate level of administrative, physical, and technical security controls to protect access to systems and assets. Monitor the effectiveness of these controls on a regular basis to ensure they continue to meet requirements. Where appropriate access to all systems and assets should be controlled in accordance with the principle of least functionality.</font><div><font size="3"><br><b>Additional References:</b></font></div><div><font size="3"><ul><li><font size="3">NIST SP 800-53 Rev. 4 AC-3, CM-7: Consider controlling access to systems and assets employing the principle of least functionality when appropriate. Least functionality is the principle of configuring information systems to provide only essential capabilities. Prohibit or restrict the use of unnecessary functions, ports, protocols, services, etc. Where feasible, organizations should limit component functionality to a single function per device/system (e.g., email server or web server but not both).</font></li><li><font size="3">NIST CSF References: PR.PT-3</font></li></ul></font></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3202, 1, '<div><b>CERT-RMM Reference</b></div>&#10;<p>&#10;    <b>[CTRL:SG3.SP1]</b> Analyze existing controls against control objectives. Identify&#10;    gaps where enterprise control objectives for the resilience of services and assets and service control&#10;    objectives are not adequately satisfied by existing controls.&#10;</p>&#10;<div>&#10;    <b>Additional References:</b>&#10;</div>&#10;<ul>&#10;    <li>&#10;        Special Publication 800-30 &#34;Guide for Conducting Risk Assessments&#34;&#10;    </li>&#10;    <li>&#10;        NIST CSF References: PR.IP-7&#10;    </li>&#10;</ul>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3204, 1, '<div><b>CERT-RMM Reference</b></div>&#10;<p><b>[CTRL:SG3.SP1]</b> Identify updates to existing controls and proposed new controls to&#10;    address gaps. This includes identifying gaps where the control objective''s priority does not&#10;    warrant further investment in updated or new controls.&#10;</p>&#10;&#10;<div><b>Additional References:</b></div>&#10;<ul>&#10;    <li>&#10;        Special Publication 800-30 &#34;Guide for Conducting Risk Assessments&#34;&#10;    </li>&#10;    <li>&#10;        NIST CSF References: PR.IP-7&#10;    </li>&#10;</ul>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3205, 1, '<b>CERT-RMM Reference&#160;</b><div><b>[CTRL:SG4.SP1]&#160;&#160;</b><span>Perform control assessments. Performing periodic assessment of the internal control system is necessary to ensure that controls continue to meet control objectives, that control objectives continue to implement strategies for protecting and sustaining services (and their supporting assets), and that resilience requirements are satisfied. Various assessment techniques can be used ranging from informal, self assessments to more structured formal assessments against established standards.Affinity analysis, interviews, and surveys may provide useful insight. In addition, results from business impact analyses, risk assessments, and internal audits and external audits(refer to the Compliance process area) can contribute.&#160;</span></div><div><span><br></span></div><div><span><b>Additional References:</b></span></div><div><ul><li><span>Special Publication 800-39 &#34;Managing Information Security Risk Organization, Mission, and Information System View&#34; Page 46-48&#160;</span></li><li><span>NIST CSF References: PR.IP-7</span></li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3206, 1, '<span><b>CERT-RMM Reference&#160;</b></span><div><b>[CTRL:SG4.SP1]</b>&#160;&#160;Perform control assessments. Performing periodic assessment of the internal control system is necessary to ensure that controls continue to meet control objectives, that control objectives continue to implement strategies for protecting and sustaining services (and their supporting assets), and that resilience requirements are satisfied. Various assessment techniques can be used ranging from informal, self assessments to more structured formal assessments against established standards.Affinity analysis, interviews, and surveys may provide useful insight. In addition, results from business impact analyses, risk assessments, and internal audits and external audits(refer to the Compliance process area) can contribute.&#160;</div><div><br></div><div><span><b>Additional References:</b></span></div><div><ul><li>Special Publication 800-39 &#34;Managing Information Security Risk Organization, Mission, and Information System View&#34; Page 46-48&#160;</li><li>NIST CSF References: PR.IP-7</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3210, 1, '<b>CERT-RMM Reference</b><div><b>[CTRL:SG4.SP1] </b>Identify updates to existing controls and proposed new controls to address problem areas. Organizations can realize efficiencies of scale by requiring specific controls for a given type of asset. For example, standardizing desktop and laptop system configurations or deploying access control systems across a range of technology assets that support multiple high-value services can reduce the cost of controls. Straight forward changes can be addressed by service and asset owners and the line of business and organizational unit managers to whom they report. For more complex changes that require broader organizational planning and coordination, a remediation plan may be required.&#160;</div><div><br></div><div>Remediation plans should address:</div><div><ul><li>the actions the organization must take to ensure that controls satisfy control objectives effectively and efficiently</li><li>changes to the internal control system</li><li>assignment of responsibility and authority to perform the work</li><li>schedule and costs to perform the work</li><li>documentation of risk mitigation strategies and residual risks</li></ul></div><div>The actions called for in remediation plans must be tracked to closure. Plans are updated as required. Any changes to existing controls and the addition of any new controls may result in the need for a reassessment.<div><br></div><div><b>Additional References:</b></div><div><ul><li>Special Publication 800-39 &#34;Managing Information Security Risk Organization, Mission, and Information System View&#34; Page 48&#160;</li><li>NIST CSF References: PR.IP-7</li></ul></div></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3211, 1, '<b>CERT-RMM Reference</b><div>Consider establishing and maintaining a plan for controls management. The plan for the controls management process should be directly influenced by the management directives and guidelines and resilience requirements that serve as the basis for defining control objectives.&#160;<div><br></div><div>The plan for the controls management process should not be confused with remediation plans for changes to the internal control system that require broad organizational planning and coordination. The plan for the controls management process details how the organization will perform controls management, including the development of remediation plans.&#160;</div><div><br><div>Subpractice:<div><ul><li>define and document the plan for performing the process</li><li>define and document the process description</li><li>review the plan with relevant stakeholders and get their agreement</li><li>revise the plan as necessary</li></ul><span><b>Additional References:</b></span></div><div><ul><li><span>NIST CSF References: PR.AC, PR.DS, PR.IP, PR.MA, PR.PT</span></li></ul></div></div></div></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3212, 1, '<b>CERT-RMM Reference:</b><div>Consider developing a policy for controls management. The controls management policy should address:</div><div><ul><li>responsibility, authority, and ownership for performing process activities</li><li>procedures, standards, and guidelines for</li><ul><li>defining and selecting control objectives</li><li>prioritizing control objectives</li><li>evaluating and acquiring tools for monitoring the performance of controls</li><li>analyzing and assessing controls</li><li>identifying gaps in controls and approaches for addressing them</li><li>identifying redundant and conflicting controls</li><li>identifying risks associated with problems in the internal control system</li></ul><li><span>periodically assessing the internal control system</span><br></li><li><span>methods for measuring adherence to policy, exceptions granted, and policy violations</span></li></ul><span><b>Additional References:</b></span></div><div><ul><li><span>NIST CSF References: ID.GV-1, PR.IP</span></li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3213, 1, '<b>CERT-RMM Reference</b><div>Consider identifying and documenting stakeholders of the controls management process. Stakeholders of the controls management process include those that are responsible for control objectives and controls, oversee the controls management process, and are involved in any aspect of ensuring the effectiveness of the internal control system and managing risks resulting from unresolved problems. Stakeholders of the compliance process are also stakeholders of the controls management process for controls that directly support compliance process activities and the fulfillment of compliance obligations.</div><div><br></div><div><b>Additional References:</b></div><div><ul><li>NIST CSF References: ID.AM-6, ID.GV-2, PR.AT</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3214, 1, '<b>CERT-RMM Reference</b><div>Consider establishing standards and guidelines for controls management.</div><div><ul><li>affinity analysis methods for categorizing control objectives and analyzing controls</li><li>methods for prioritizing control objectives</li><li>techniques and tools for developing and maintaining traceability between control objectives and controls</li><li>methods for conducting surveys and interviews</li><li>methods and techniques for identifying and addressing gaps in controls as well as conflicting and redundant controls</li><li>methods, techniques, and tools for control analysis and assessment</li><li>methods, techniques, and tools for coordinating process activities across organizational units and lines of business</li><li>methods, techniques, and tools for collecting, analyzing, validating, and managing information about the internal control system</li><li>monitoring, auditing, and other assessment techniques to identify problem areas</li><li>methods and tools for managing changes to controls</li></ul><span><b>Additional References:</b></span></div><div><ul><li><span>NIST CSF References: PR.AC, PR.DS, PR.IP, PR.MA, PR.PT</span></li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3215, 1, '<b>CERT-RMM Reference</b><div>Consider conducting oversight of controls management activities. These are examples of controls management work products placed under control:</div><div><ul><li>management directives and guidelines</li><li>control objectives and their priorities</li><li>enterprise-level, service-level, and asset-level controls</li><li>traceability matrix of control objectives and controls, including responsible staff</li><li>analysis and assessment results, including control gaps</li><li>updates to existing controls</li><li>proposed new controls</li><li>redundant and conflicting controls</li><li>risks related to unsatisfied control objectives</li><li>risks related to redundant and conflicting controls</li><li>remediation plans</li><li>updates to service continuity plans</li><li>process plan</li><li>policies and procedures</li><li>contracts with external entities<br><br></li></ul><span><b>Additional References:</b></span></div><div><ul><li><span>NIST CSF References: PR.IP-8</span></li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3216, 1, '<b>CERT-RMM Reference</b><br>Consider ensuring that responsible staff are trained in the skills necessary to perform controls management. These are examples of skills required in the controls management<br>process:<br><ul><li>knowledge of the tools, techniques, and methods necessary to analyze, assess, and manage the internal control system, including those necessary to perform the process using the selected methods, techniques, and tools</li><li>knowledge unique to each control objective</li><li>knowledge necessary to successfully remediate control gaps, problem areas, redundancies, and conflicts</li><li>knowledge necessary to work effectively with asset and service owners and custodians</li><li>oral and written communication skills to prepare reports on the effectiveness of the internal control system and defend these reports if required</li><li>knowledge necessary to elicit and prioritize stakeholder requirements and needs and interpret them to develop effective control objectives and controls</li></ul><b>Additional References:</b><br><ul><li>NIST CSF References: PR.AT</li></ul>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3217, 1, '<b>CERT-RMM Reference</b><br>Consider ensuring that controls management activities are adequately funded.&#160;<span>Considerations for funding the process should extend beyond the initial development of </span><span>controls to the maintenance of the system of internal controls, which includes evaluation </span><span>of control effectiveness.</span><div><b><br></b></div><div><b>Additional References:</b><br>NIST CSF References: ID.GV-4</div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3218, 1, '<b>CERT-RMM Reference</b><div>Consider ensuring that risk arising from the failure of controls management is identified, assessed, and mitigated.</div><div><b><br></b></div><div><b>Additional References:</b></div><div><ul><li>NIST CSF References: ID.GV-4, ID.RA-6</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3219, 1, '<b>CERT-RMM Reference</b><br>Consider measuring the controls management process. These are examples of metrics for<br>the controls management process:<div><br><ul><li>number of controls and number of controls by category</li><li>percentage of control objectives that are fully satisfied by existing controls</li><li>percentage of controls that span multiple control objectives</li><li>percentage of controls that require updates; percentage of control objectives that are affected by updated controls</li><li><span>percentage of proposed new controls; percentage of control objectives that are&#160;</span>affected by proposed new controls</li><li>percentage of redundant controls; percentage of control objectives that are affected by redundant controls</li><li>percentage of conflicting controls; percentage of control objectives that are affected by conflicting controls</li><li>time and resources expended to conduct an analysis of controls (establish the baseline)</li><li>time and resources expended to conduct an assessment of controls (periodic)</li><li>number of problem areas resulting from the assessment of controls</li><li>number of problem areas escalated to higher-level managers for review</li><li>percentage of control objectives requiring remediation plans</li><li>percentage of controls that have been fully automated</li><li>timeliness of resolving control gaps (implementation of control updates and proposed new controls; resolution of redundant and conflicting control(s)</li><li>reduction in number of controls</li><li>number of process risks referred to the risk management process; number of risks where corrective action is still pending (by risk rank)</li><li>level of adherence to process policies; number of policy violations; number of policy exceptions requested and number approved</li><li>number of process activities that are on track per plan</li><li>rate of change of resource needs to support the process</li><li>rate of change of costs to support the process</li></ul></div><div><b>Additional References:</b><br><ul><li>NIST CSF References: PR.IP-7</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3220, 1, '<b>CERT-RMM Reference</b><br>Consider reviewing the controls management activities. Periodic reviews of the controls management process are needed to ensure that:<br><ul><li>control objectives are satisfied and continue to be satisfied across time and in the face of changing business and risk conditions</li><li>control problem areas have been identified and remediated</li><li>risks related to control problem areas have been identified, properly referred, and addressed</li><li>actions requiring management involvement are elevated in a timely manner</li><li>the performance of process activities is being monitored and regularly reported</li><li>key measures are within acceptable ranges as demonstrated in governance dashboards or scorecards and financial reports</li><li>actions requiring management involvement are elevated in a timely manner</li><li>actions resulting from internal and external audits are being closed in a timely manner</li></ul><b>Additional References:</b><br><ul><li>NIST CSF References: PR.IP-7</li></ul>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3221, 1, '<b>CERT-RMM Reference</b><br>Consider reviewing issues with performance of controls management. Reviews of the controls management process may result from periodic assessment or post-event audits that seek to identify problems that must be corrected. Elevating the results of these assessments and audits to managers provides an opportunity to correct controls management process deficiencies and to make managers aware of variations in the process that not only have localized impact but may also affect the organization''s resilience as a whole.<div><br><b>Additional References:</b><br>NIST CSF References: PR.IP-8</div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3222, 1, '<b>CERT-RMM Reference</b><br>Consider establishing an organization-wide approach to controls management, that<br>includes:<br><ul><li>selecting from the organization''s set of standard processes those processes that cover the controls management process and best meet the needs of the organizational unit or line of business</li><li>establishing the defined process by tailoring the selected processes according to the organization''s tailoring guidelines</li><li>ensuring that the organization''s process objectives are appropriately addressed in the defined process, and ensure that process governance extends to the tailored processes</li><li>documenting the defined process and the records of the tailoring</li><li>revising the description of the defined process as necessary</li></ul><b>Additional References:</b><br><ul><li>NIST CSF References: PR.IP</li></ul>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3223, 1, '<b>CERT-RMM Reference</b><br>Consider collecting controls management work products, measures, measurement results, and improvement information derived from planning and performing the process to support future use and improvement of the organization''s processes and process assets.<div><br><b>Additional References:</b><br><ul><li>NIST CSF References: PR.IP</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3225, 1, '<b><span>CERT-RMM Reference</span><br><span>[ADM:SG3.SP2]</span></b><span>&#160;Maintain a requirement change history with rationale for performing the&#160;</span><span>changes. Change management for resilience requirements is a continuous process and&#160;</span><span>therefore requires that the organization effectively assign responsibility and&#160;</span><span>accountability for it. The organization must independently monitor that the change&#160;</span><span>management process is operational and that asset-level resilience requirements have&#160;</span><span>been&#160; updated on a regular basis so that they remain in direct alignment with&#160;</span><span>organizational drivers.</span><div><b><br><span>Additional References:</span></b><br><ul><li>NIST SP 800-53 Rev. 4 CM-3</li><li>NIST CSF References: PR.IP-3</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3226, 1, '<b><span>CERT-RMM Reference</span><br><span>[ADM:SG3.SP2]</span></b><span><b>&#160;</b>Maintain a requirement change history with rationale for performing the&#160;</span><span>changes. Change management for resilience requirements is a continuous process and&#160;</span><span>therefore requires that the organization effectively assign responsibility and&#160;</span><span>accountability for it. The organization must independently monitor that the change&#160;</span><span>management process is operational and that asset-level resilience requirements have&#160;</span><span>been updated on a regular basis so that they remain in direct alignment with&#160;</span><span>organizational drivers.</span><div><br><b>Additional References:</b><br><ul><li>NIST SP 800-53 Rev. 4 CM-3</li><li>NIST CSF References: PR.IP-3</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3227, 1, '<b><span>CERT-RMM Reference</span><br><span>[ADM:SG3.SP2]</span></b><span>&#160;Maintain a requirement change history with rationale for performing the&#160;</span><span>changes. Change management for resilience requirements is a continuous process and&#160;</span><span>therefore requires that the organization effectively assign responsibility and&#160;</span><span>accountability for it. The organization must independently monitor that the change&#160;</span><span>management process is operational and that asset-level resilience requirements have&#160;</span><span>been updated on a regular basis so that they remain in direct alignment with&#160;</span><span>organizational drivers.</span><div><br><span><b>Additional References:</b></span><br><ul><li>NIST SP 800-53 Rev. 4 CM-3</li><li>NIST CSF References: PR.IP-3</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3229, 1, '<span><b>CERT-RMM Reference<br>[RRM:SG1.SP3]&#160;</b></span><span>Evaluate the impact of requirement changes on existing activities and&#160;</span><span>commitments for protecting and sustaining assets and services. The organization must&#160;</span><span>independently monitor that the change management process is operational and that&#160;</span><span>asset-level resilience requirements have been updated on a regular basis so that they&#160;</span><span>remain in direct alignment with organizational drivers.</span><div><br><span><b>Additional References:</b></span><br><ul><li>NIST SP 800-53 Rev. 4 CM-3</li><li>NIST CSF References: PR.IP-3</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3230, 1, '<span><b>CERT-RMM Reference<br>[RRM:SG1.SP3]&#160;</b></span>Evaluate the impact of requirement changes on existing activities and&#160;commitments for protecting and sustaining assets and services. The organization must&#160;independently monitor that the change management process is operational and that&#160;asset-level resilience requirements have been updated on a regular basis so that they&#160;remain in direct alignment with organizational drivers.<div><b><br><span>Additional References:</span></b><br><ul><li>NIST SP 800-53 Rev. 4 CM-3</li><li>NIST CSF References: PR.IP-3</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3231, 1, '<span><span><b>CERT-RMM Reference<br>[RRM:SG1.SP3]&#160;</b></span></span><span>Evaluate the impact of requirement changes on existing activities and&#160;commitments for protecting and sustaining assets and services. The organization must&#160;independently monitor that the change management process is operational and that&#160;asset-level resilience requirements have been updated on a regular basis so that they&#160;remain in direct alignment with organizational drivers.</span><div><span><b><br>Additional References:</b></span><br><ul><li>NIST SP 800-53 Rev. 4 CM-3</li><li>NIST CSF References: PR.IP-3</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3232, 1, '<b>CERT-RMM Reference<br>[TM:SG5.SP3]</b> Develop a strategy to meet the demand for capacity based on the resilience requirements for the technology asset and the services it supports. In this case, the strategy may need to consider the organization&#8217;s strategic objectives and how the accomplishment of these objectives affects capacity of current technology assets and future capacity needs.<div><br><b>Additional References:</b><br><ul><li>Special Publication 800-128 &#34;Guide for Security-Focused Configuration Management of Information Systems&#34;</li><li>NIST CSF References: PR.DS-4</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3235, 1, '<b>CERT-RMM Reference<br>[ADM:SG3.SP2]</b> Changes to high value systems and assets may require corresponding changes to cybersecurity requirements and the strategies the organization deploys to ensure that these assets are adequately protected and sustained. Maintain a requirement change history with rationale for performing the changes. Change management for resilience requirements is a continuous process and therefore requires that the organization effectively assign responsibility and accountability for it.<div><br><b>[RTSE:SG2.SP2] </b>Planning for the incorporation of resilience into the development life cycle ensures that resilience activities and controls are included as a required part of the production of systems and assets. Planning should describe the selection and incorporation of appropriate guidelines for addressing resilience in the life-cycle phases.</div><div><br></div><div><b>Additional References:</b><br><ul><li>NIST SP 800-53 Rev. 4 SA-3, SA-4, SA-8, SA-10, SA-11, SA-12, SA-15, SA-17, PL-8: A well-defined System Development Life Cycle provides the foundation for the successful development, implementation, operation, and disposal of organizational information systems. Consider incorporating information system security engineering principles to the specification, design, development, implementation, and modification of information systems.</li><li>NIST CSF References: PR.IP-2</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3239, 1, '<div><b>CERT-RMM Reference</b></div><div><b>[KIM:SG5.SP1]</b> Identify and document staff who are authorized to modify information&#160;<span>assets, relative to the asset&#8217;s integrity requirements. This information may be specifically&#160;</span><span>included as part of the information asset&#8217;s resilience requirements.</span></div><div><br></div><div><b>Additional References:</b></div><div><ul><li>NIST SP 800-53 Rev. 4 AC - 2</li><li>NIST CSF References: PR.AC-4, PR.IP-3, PR.IP-11</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3240, 1, '<font color="#000000"><b>CERT-RMM Reference</b></font><div><b>[KIM:SG5.SP3]</b><span> Establish requirements for the inclusion of data validation controls in services and related systems. The inclusion of data validation controls ensures that information assets retain their integrity when charged into the production cycles of processes and systems.</span></div><div><br><font color="#000000" size="3"><b>Additional References:</b></font><ul><li><span>NIST SP 800-53 Rev. 4 PL-1</span></li><li><font color="#000000" size="3">NIST CSF References: PR.DS-6</font></li></ul><p></p></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3243, 1, '<div><b><font size="3">CERT-RMM Reference</font></b></div><div><font size="3"><b>[TM:SG4.SP1]</b> Establish access management policies and procedures for requesting and&#160;</font><span>approving access privileges to technology assets. The organization should establish policies&#160;</span><span>and procedures for requesting, approving, and providing access to technology assets to&#160;</span><span>persons, objects, and entities. The access management policy should establish the&#160;</span><span>responsibilities of requestors, asset owners, and asset custodians (who typically are called&#160;</span><span>upon to implement access requests). The policy should address clear guidelines for access&#160;</span><span>requests that originate external to the organization (i.e., from contractors or business&#160;</span><span>partners). The policy should also cover the type and extent of access that will be provided&#160;</span><span>to objects such as systems and processes.</span></div><div><span><br></span></div><div><b>Additional References:&#160;</b></div><div><ul><li>NIST SP 800-53 Rev. 4 AC-1</li><li>NIST CSF References: PR.AC</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3244, 1, '<div><b>CERT-RMM Reference</b></div><div><b>[TM:SG5.SP2]</b> Document all preventive, corrective, and other types of maintenance.&#160;<span>Maintenance records should be retained for all technology assets and stored appropriately&#160;</span><span>with access only to authorized individuals. Risks related to software systems and their&#160;</span><span>maintenance may need additional analysis and resolution. These activities may result in&#160;</span><span>additions or revisions to existing service continuity plans. Implement maintenance&#160;</span><span>according to the organizations change management process and procedures.</span></div><div><b>[ADM:SG3.SP2]</b> Changes to high value systems and assets due to maintenance activities&#160;<span>may require corresponding changes to cybersecurity requirements and the strategies the&#160;</span><span>organization deploys to ensure that these assets are adequately protected and sustained.&#160;</span><span>For all maintenance activities, maintain a requirement change history with rationale for&#160;</span><span>performing the changes. Change management for resilience requirements is a continuous&#160;</span><span>process and therefore requires that the organization effectively assign responsibility and&#160;</span><span>accountability for it.</span></div><div><br></div><div><b>Additional References:</b></div><div><ul><li>NIST SP 800-53 Rev. 4 MA-2, MA-3, MA-5 :Consider implementing a maintenance and repair process that will approve and monitor all maintenance activities. Also, consider implementing a schedule to perform maintenance and repair activities and establish maintenance documentation standards and guidelines. Document all maintenance and repair activities on information system components for future review.</li><li>NIST CSF References: PR.MA-1</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3245, 1, '<div><b>CERT-RMM Reference</b></div><div><b>[TM:SG5.SP2] </b>Document all preventive, corrective, and other types of maintenance.&#160;<span>Maintenance records should be retained for all technology assets and stored appropriately&#160;</span><span>with access only to authorized individuals. Implement maintenance according to the&#160;</span><span>organizations change management process and procedures.&#160;</span></div><div><span><br></span></div><div><span>Identify the tools, techniques, and methods that the organization will use to perform&#160;</span><span>maintenance activities. Pre-approving tools, techniques, and methods ensures consistency&#160;</span><span>of maintenance activity outcomes. The identified tools, techniques, and methods should&#160;</span><span>cover the entire range of information system assets and may include both procedural and&#160;</span><span>automated methods.</span></div><div><b><br></b></div><div><b>[ADM:SG3.SP2] </b>Changes to high value systems and assets due to maintenance activities&#160;<span>may require corresponding changes to cybersecurity requirements and the strategies the&#160;</span><span>organization deploys to ensure that these assets are adequately protected and sustained.&#160;</span><span>For all maintenance activities, maintain a requirement change history with rationale for&#160;</span><span>performing the changes. Change management for resilience requirements is a continuous&#160;</span><span>process and therefore requires that the organization effectively assign responsibility and&#160;</span><span>accountability for it.</span></div><div><b><br></b></div><div><b>Additional References:</b></div><div><ul><li>NIST SP 800-53 Rev. 4 MA-2, MA-3, MA-5 Consider approving, controlling, and monitoring information system maintenance tools and methods.</li><li>NIST CSF References: PR.MA-1</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3246, 1, '<div><b>CERT-RMM Reference</b></div><div><b>[TM:SG5.SP2]</b> Document all preventive, corrective, and other types of remote&#160;<span>maintenance. Remote maintenance records should be retained for all technology assets&#160;</span><span>and stored appropriately with access only to authorized individuals. These activities may&#160;</span><span>result in additions or revisions to existing service continuity plans. Implement maintenance&#160;</span><span>according to the organizations change management process and procedures.</span></div><div><b><br></b></div><div><b>[ADM:SG3.SP2]</b> Changes to high value systems and assets due to remote maintenance&#160;<span>activities may require corresponding changes to cybersecurity requirements and the&#160;</span><span>strategies the organization deploys to ensure that these assets are adequately protected&#160;</span><span>and sustained. For all remote maintenance activities, maintain a requirement change&#160;</span><span>history with rationale for performing the changes. Change management for resilience&#160;</span><span>requirements is a continuous process and therefore requires that the organization&#160;</span><span>effectively assign responsibility and accountability for it.</span></div><div><b><br></b></div><div><b>Additional References:</b></div><div><ul><li>NIST SP 800-53 Rev. 4 MA-4: Consider implementing a remote maintenance and repair&#160;<span>process that will approve and monitor all remote maintenance activities. Also, consider&#160;</span><span>implementing a schedule to perform remote maintenance and repair activities and&#160;</span><span>establish remote maintenance documentation standards and guidelines. Document all&#160;</span><span>remote maintenance and repair activities on information system components for future&#160;</span><span>review.&#160;</span>Also, consider implementing strong authentication to resist replay attacks and terminating&#160;<span>sessions and network connections when remote maintenance and diagnostic activities are&#160;</span><span>completed.</span></li><li>NIST CSF References: PR.MA-2</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3248, 1, '<b>CERT-RMM Reference </b><br><b>[TM:SG4.SP3] </b><br><font color="#000000">Obtain agreement and approval for changes to baselines from relevant </font><font color="#000000">stakeholders.</font><div><font color="#000000"></font><font color="#000000"><br></font><b>Additional References:</b></div><div><ul><li>NIST SP 800-53 Rev. 4 CM-3</li><li>NIST CSF References: PR.IP-1, PR.IP-3</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3249, 1, '<div><b>CERT-RMM Reference</b></div><div><b>[TM:SG4.SP2] </b>Consider creating configuration baselines for network operational assets.&#160;<span>When integrity is suspect for any reason, the resilience of technology assets and associated&#160;</span><span>services may be affected. Establishing a technology asset baseline (commonly called a&#160;</span><span>configuration item) provides a foundation for managing the integrity of the asset as it&#160;</span><span>changes over its life cycle.</span></div><div><br></div><div><b>Additional References:</b></div><div><ul><li>NIST SP 800-53 Rev. 4 AC-4, CA-3, CM-2, SI-4: Consider establishing baseline configurations to include information about information system components, network topology, and the logical placement of those components within the system architecture and maintaining them under configuration control.</li><li>NIST CSF References: DE.AE-1</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3250, 1, '<div><b>CERT-RMM Reference</b></div><div><b>[TM:SG4.SP2] </b>Consider creating configuration baselines for network operational assets.&#160;<span>When integrity is suspect for any reason, the resilience of technology assets and associated&#160;</span><span>services may be affected. Establishing a technology asset baseline (commonly called a&#160;</span><span>configuration item) provides a foundation for managing the integrity of the asset as it&#160;</span><span>changes over its life cycle. Configuration management for technology assets is tightly&#160;</span><span>coupled with change control and management. Change control should be applied to&#160;</span><span>Configuration baselines. Track and control changes to configuration baselines, and perform&#160;</span><span>configuration baseline audits.</span></div><div><br></div><div><b>Additional References:</b></div><div><ul><li>NIST SP 800-53 Rev. 4 AC-4, CA-3, CM-2, SI-4: Baseline configurations for information systems and assets should be developed, documented, and maintained under configuration control. Formally review baseline configurations on a periodic basis. Maintaining baseline configurations requires creating new baselines as organizational information systems change over time.</li><li>NIST CSF References: DE.AE-1</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3251, 1, '<p class="p1"><b>CERT-RMM Reference</b><br><font color="#000000"><b>[TM:SG4.SP2]</b> Consider creating configuration baselines of expected data flows. When&#160;</font><span>integrity is suspect for any reason, the resilience of technology assets and associated&#160;</span><span>services may be affected. Establishing a technology asset baseline (commonly called a&#160;</span><span>configuration item) provides a foundation for managing the integrity of the asset as it&#160;</span><span>changes over its life cycle.</span><font color="#000000"><b><br></b></font></p><b>Additional References:</b><div><ul><li><font color="#000000">NIST SP 800-53 Rev. 4 AC-4, CA-3, CM-2, SI-4:&#160;</font><span>Consider establishing a configuration baseline of expected data flows. Information flow control regulates where information is allowed to travel within and between information systems. Consider developing interconnection interface characteristics, security requirements, and the parameters of the communication as part of the documented baseline.</span></li><li>NIST CSF References: DE.AE-1</li></ul><p></p><p></p></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3252, 1, '<font color="#000000" size="3"><b>CERT-RMM Reference</b></font><div><font color="#000000" size="3"><b>[TM:SG4.SP2] </b>Consider creating configuration baselines of expected data flows. When&#160;</font><font color="#000000" size="3">integrity is suspect for any reason, the resilience of technology assets and associated&#160;</font><font color="#000000" size="3">services may be affected. Establishing a technology asset baseline (commonly called a&#160;</font><font color="#000000" size="3">configuration item) provides a foundation for managing the integrity of the asset as it&#160;</font><font color="#000000" size="3">changes over its life cycle. Configuration management for technology assets is tightly&#160;</font><font color="#000000" size="3">coupled with change control and management. Change control should be applied to&#160;</font><font color="#000000" size="3">configuration baselines. Track and control changes to configuration baselines, and&#160;</font><font color="#000000" size="3">perform configuration baseline audits.</font><div><font color="#000000" size="3"><br></font></div><div><font color="#000000" size="3"><b>Additional References:</b></font></div><div><ul><li><font color="#000000" size="3">NIST SP 800-53 Rev. 4 AC-4, CA-3, CM-2, SI-4 Baseline configurations of expected data&#160;</font><font color="#000000" size="3">flows should be developed, documented, and maintained under configuration control.</font><font color="#000000" size="3">Formally review baseline configurations of dedicated connections on a periodic basis.</font><font color="#000000" size="3">Maintaining baseline configurations requires creating new baselines as organizational&#160;</font><font color="#000000" size="3">information systems change over time.</font></li><li>NIST CSF References: DE.AE-1</li></ul></div></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3253, 1, '<div><b>CERT-RMM Reference</b></div><div>Consider planning for configuration and change management. The plan for configuration&#160;<span>and change management should maintain a focus of ensuring adequate protection and&#160;</span><span>sustainment strategies as assets are deployed and are modified.</span></div><div><br></div><div><b>Additional References:</b></div><div><ul><li>NIST CSF References: PR.AC, PR.DS, PR.IP, PR.MA, PR.PT</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3254, 1, '<div><b>CERT-RMM Reference</b></div><div>Consider sponsoring policies and procedures, including the documentation of&#160;<span>configuration and changes. The configuration and change policy should address:</span></div><div><ul><li>configuration baselines, baseline review and change criteria, change request management, change testing, change risk assessment, and change deployment</li><li>methods for measuring adherence to policy, exceptions granted, and policy violations</li></ul></div><div><b>Additional References:</b></div><div><ul><li>NIST CSF References: ID.GV-1 , PR.IP</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3255, 1, '<font color="#000000"><span><b>CERT-RMM Reference</b></span></font><div><font color="#000000"><span>Consider identifying stakeholders, which are individuals who are involved in various tasks&#160;</span></font><font color="#000000"><span>in the configuration and change management process, such as:</span></font></div><div><ul><li><font color="#000000"><span>planning for the process</span></font></li><li><font color="#000000"><span>creating baseline configurations</span></font></li><li><font color="#000000"><span>evaluating and updating changes</span></font></li><li><font color="#000000"><span>managing changes to assets and to the asset inventory</span></font></li><li><font color="#000000"><span>reviewing and appraising the effectiveness of process activities</span></font></li><li><font color="#000000"><span>resolving issues in the process</span></font></li></ul></div><div><font color="#000000"><span><b>Additional References:</b></span></font></div><div><ul><li><font color="#000000"><span>NIST CSF References: ID.AM-6, ID.GV-2, PR.AT</span></font></li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3256, 1, '<div><b>CERT-RMM Reference</b></div><div>Consider sponsoring standards, and guidelines, including procedures, standards, and&#160;<span>guidelines for:</span></div><div><ul><li>establishing and managing baseline configurations</li><li>change control</li><li>methods for measuring adherence to policy, exceptions granted, and policy violations</li></ul></div><div><b>Additional References:</b></div><div><ul><li>NIST CSF References: PR.AC, PR.DS, PR.IP, PR.MA, PR.PT</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3257, 1, '<font color="#000000"><span><b>CERT-RMM Reference</b></span></font><div><font color="#000000"><span>Consider conducting periodic reviews of the configuration and change management&#160;</span></font><font color="#000000"><span>process are needed to ensure that:</span></font></div><div><ul><li><font color="#000000"><span>assets are placed under configuration management</span></font></li><li><font color="#000000"><span>baseline configurations meet the organization''s needs</span></font></li><li><font color="#000000"><span>baseline configurations are updated as needed</span></font></li><li><font color="#000000"><span>changes to assets do not introduce unacceptable risk</span></font></li><li><font color="#000000"><span>changes to assets are effectively communicated to all who need to know</span></font></li></ul><font color="#000000"><b>Additional References:</b></font></div><div><ul><li><font color="#000000">NIST CSF References: PR.IP-8</font></li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3259, 1, '<font color="#000000"><b>CERT-RMM Reference</b></font><div><font color="#000000">Consider ensuring that configuration and change management activities are adequately&#160;</font><font color="#000000">funded. Funding the configuration and change management process should include&#160;</font><font color="#000000">ensuring that baseline configurations are available to all stakeholders who require access&#160;</font><font color="#000000">and that baseline configurations are appropriately managed under the change control&#160;</font><font color="#000000">process. The change control process should be funded to ensure that all stakeholders are&#160;</font><font color="#000000">aware of changes, that changes are sufficiently tested, and that unacceptable risk is not&#160;</font><font color="#000000">introduced to the operating environment as a result of changes.</font></div><div><font color="#000000"><b><br></b></font></div><div><font color="#000000"><b>Additional References:</b></font></div><div><ul><li><font color="#000000">NIST CSF References: ID.GV-4</font></li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3260, 1, '<div><b>CERT-RMM Reference</b></div><div>Consider managing risk arising from insufficient configuration and change management&#160;<span>practices. Discrepancies result when assets are acquired, modified, or retired but not</span></div><div>reflected accurately in the change management repository, or when assets are deployed&#160;<span>without being placed under configuration management. Assets form the foundation for&#160;</span><span>operational resilience management, as they are the target of strategies required to&#160;</span><span>protect and sustain services. To the extent that the asset''s configuration is not under&#160;</span><span>configuration management, the organization&#8217;s overall ability to manage operational&#160;</span><span>resilience is impeded.</span></div><div><span><br></span></div><div><b>Additional References:</b></div><div><ul><li>NIST CSF References: ID.GV-4, ID.RA-6</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3261, 1, '<div><b>CERT-RMM Reference</b></div><div>Consider measuring the change management process against its process description,&#160;<span>standards, and procedures, and address non-compliance.</span></div><div><b><br></b></div><div><b>Additional References:</b></div><div><ul><li>NIST CSF References: PR.IP-7</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3262, 1, '<div><b>CERT-RMM Reference</b></div><div>Consider objectively evaluating adherence of the configuration and change management&#160;<span>process against its process description, standards, and procedures, and address noncompliance.</span></div><div><b><br></b></div><div><b>Additional References:</b></div><div><ul><li>NIST CSF References: PR.IP-7</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3263, 1, '<div><b>CERT-RMM Reference</b></div><div>Consider reviewing activities, status, and results of the process with higher level managers.&#160;<span>Reviews of the configuration and change management process may result from periodic&#160;</span><span>examination or post-event audits that seek to identify problems that must be corrected.&#160;</span><span>Elevating the results of these examinations to managers provides an opportunity to&#160;</span><span>correct process deficiencies and to make managers aware of variations in the risk&#160;</span><span>management process that not only have localized impact but may also affect the&#160;</span><span>organization&#8217;s resilience as a whole.</span></div><div><br></div><div><b>Additional References:</b></div><div><ul><li>NIST CSF References: PR.IP-8</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3264, 1, '<div><b>CERT-RMM Reference</b></div><div>Consider establishing an organization-wide approach to configuration and change&#160;<span>management, that includes:</span></div><div><ul><li>selecting from the organization&#8217;s set of standard processes those processes that cover&#160;<span>the configuration and change management process and best meet the needs of the&#160;</span><span>organizational unit or line of business</span></li><li>establishing the defined process by tailoring the selected processes according to the&#160;<span>organization&#8217;s tailoring guidelines</span></li><li>ensuring that the organization&#8217;s process objectives are appropriately addressed in the&#160;<span>defined process, and ensure that process governance extends to the tailored&#160;</span><span>processes</span></li><li>documenting the defined process and the records of the tailoring</li><li>revising the description of the defined process as necessary</li></ul></div><div><b>Additional References:</b></div><div><ul><li>NIST CSF References: PR.IP</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3265, 1, '<div><b>CERT-RMM Reference</b></div><div>Collect configuration and change management work products, measures, measurement&#160;<span>results, and improvement information derived from planning and performing the process&#160;</span><span>to support future use and improvement of the organization&#8217;s processes and process&#160;</span><span>assets.</span></div><div><b><br></b></div><div><b>Additional References:</b></div><div><ul><li>NIST CSF References: PR.IP</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3266, 1, '<div><b>CERT-RMM Reference</b></div><div><b>[VAR:SG1.SP2] </b>Develop and document an operational vulnerability analysis and&#160;<span>resolution strategy. The strategy for addressing vulnerability analysis and resolution&#160;</span><span>should be documented in a plan that can be communicated to relevant stakeholders and&#160;</span><span>implemented. The plan should address:</span></div><div><ul><li>the scope of vulnerability analysis and resolution activities</li><li>the essential activities that are required for vulnerability analysis and resolution</li><li>a plan for collecting the data necessary for vulnerability activities</li><li>tools, techniques, and methods that have been approved for identifying and analyzing&#160;<span>vulnerabilities across a range of assets</span></li><li>a schedule for performing vulnerability activities</li><li>the roles and responsibilities necessary to carry out the plan</li><li>the skills and training required to perform the vulnerability analysis and resolution&#160;<span>strategy and plan</span></li><li>the relative costs associated with the activities, particularly for the purchase and&#160;<span>licensing of tools, techniques, and methods</span></li><li>relevant stakeholders of the vulnerability activities and their roles</li><li>objectives for measuring when the plan and strategy are successful</li></ul></div><div><div><b>Additional References:</b></div><div><ul><li>Special Publication 800-137 &#34;Information Security Continuous Monitoring (ISCM) for Federal Information Systems and Organizations&#34; Page 6-9</li><li>NIST CSF References: PR.IP-12</li></ul></div></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3277, 1, '<div><b>CERT-RMM Reference</b></div><div><b>[VAR:SG1.SP2]</b> Identify the tools, techniques, and methods that the organization will use&#160;<span>to identify mobile code in technology assets. The organization should compile a list of&#160;</span><span>approved and recommended tools, techniques, and methods to be used for this activity.&#160;</span><span>Pre-approving tools, techniques, and methods ensures consistency and cost-effectiveness,&#160;</span><span>as well as validity of results. This list should cover the entire range of applicable assets and&#160;</span><span>include both procedural and automated methods.</span></div><div><br></div><div><b>Additional References:</b></div><div><ul><li>NIST SP 800-53 Rev. 4 SC-18, SI-4, SC-44: Consider employing unauthorized mobile code detection mechanisms. Mobile code is&#160;<span>software programs or parts of programs obtained from remote information systems,&#160;</span><span>transmitted across a network, and executed on a local information system without explicit&#160;</span><span>installation or execution by the recipient. Consider defining acceptable and unacceptable&#160;</span><span>mobile code technologies and establish usage restrictions. Authorize, monitor, and control&#160;</span><span>the use of mobile code.</span></li><li>NIST CSF References: DE.CM-5</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3278, 1, '<div><b>CERT-RMM Reference</b></div><div><b>[VAR:SG1.SP2]</b> Identify the tools, techniques, and methods that the organization will use&#160;<span>to monitor assets for unauthorized personnel, connections, devices and software. The&#160;</span><span>organization should compile a list of approved and recommended tools, techniques, and&#160;</span><span>methods to be used for these activities. Pre-approving tools, techniques, and methods&#160;</span><span>ensures consistency and cost-effectiveness, as well as validity of results. This list should&#160;</span><span>cover the entire range of assets and include both procedural and automated methods.</span></div><div><b><br></b></div><div><b>Additional References:</b></div><div><ul><li>NIST SP 800-53 Rev. 4 AU-12, CA-7, CM-3, CM-8, PE-3, PE-6, PE-20, SI-4: Consider enforcing and monitoring physical access controls to information systems in addition to the physical access controls for facilities (badging system, guard rounds, etc.). Monitor information systems to detect unauthorized local, network, and remote connections. Monitoring tools and techniques may include intrusion detection/prevention, log monitoring, SIEMs, etc.</li><li>NIST CSF References: DE.CM-7</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3279, 1, '<div><b>CERT-RMM Reference</b></div><div><b>[VAR:SG2.SP1]</b> Identify sources of relevant vulnerability information. The sources of&#160;<span>vulnerability information should fit the organization&#8217;s vulnerability identification and&#160;</span><span>analysis needs. The internal sources of vulnerability information supplied by other&#160;</span><span>operational resilience management processes should be included in the list.</span></div><div><br></div><div><b>Additional References:</b></div><div><ul><li>Special Publication 800-40 &#34;Guide to Enterprise Patch Management Technologies&#34;</li><li>NIST CSF References: RS.AN-5</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3291, 1, '<div><b>CERT-RMM Reference</b></div><div><b>[VAR:SG2.SP3] </b>Prioritize and categorize vulnerabilities for disposition. Based on the&#160;<span>organization&#8217;s prioritization guidelines and the results of vulnerability analysis,&#160;</span><span>vulnerabilities must be categorized by disposition.</span></div><div><b><br></b></div><div><b>Additional References</b>:</div><div><ul><li>Special Publication 800-40 &#34;Guide to Enterprise Patch Management&#160;<span>Technologies&#34;</span></li><li>NIST CSF References: RS.AN-5</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3303, 1, '<div><b>CERT-RMM Reference</b></div><div><b>[VAR:SG3.SP1]</b> Develop a vulnerability management strategy for all vulnerabilities that&#160;<span>require resolution. The strategy should address the actions that the organization will take&#160;</span><span>to reduce or eliminate exposure or to provide an operational workaround if preferable.</span></div><div><b><br></b></div><div><b>Additional References:&#160;</b></div><div><ul><li>Special Publication 800-40 &#34;Guide to Enterprise Patch Management&#160;<span>Technologies&#34;</span></li><li>NIST CSF References: RS.MI-3</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3306, 1, '<div><b>CERT-RMM Reference</b></div><div><b>[VAR:SG4.SP1] </b>Identify and analyze the root causes of vulnerabilities.</div><div><b><br></b></div><div><b>Additional References:</b></div><div><ul><li>Special Publication 800-39 &#34;Managing Information Security Risk Organization, Mission, and Information System View&#34; Page 39&#160;</li><li>NIST CSF References: PR.IP-12, RS.IM</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3307, 1, '<div><b>CERT-RMM Reference</b></div><div>Consider establishing and managing a plan for vulnerability management. The plan for the&#160;<span>vulnerability management process should not be confused with the organizational&#160;</span><span>vulnerability management strategy and plan for identifying and analyzing vulnerabilities.&#160;</span><span>The plan for the vulnerability management process details how the organization will&#160;</span><span>perform vulnerability analysis and resolution, including the development of strategies and&#160;</span><span>plans for vulnerability analysis and resolution.</span></div><div><b><br></b></div><div><b>Additional References:</b></div><div><ul><li>NIST CSF References: PR.IP-12</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3308, 1, '<div><b>CERT-RMM Reference</b></div><div><span>Consider developing a policy for vulnerability management. The vulnerability management&#160;</span><span>policy should address:</span></div><div><ul><li>responsibility, authority, and ownership for performing process activities</li><li>information categorization, labeling, and handling</li><li>protection against tampering or unauthorized access</li><li>encryption, secure storage, and secure transport and distribution of information</li><li>procedures, standards, and guidelines for</li><ul><li>identifying the assets that are the focus of vulnerability management activities</li><li>storage capacity of collection mechanisms and actions to take if capacity is exceeded by type of media</li><li>collection of vulnerability data</li><li>recording and storage of vulnerability data, including collection media (electronic logs, data files, databases, and information repositories)</li><li>distribution of vulnerability data, including media, methods, and channels</li><li>service level agreement terms and conditions for external entities involved in process activities</li></ul><li><span>methods for measuring adherence to policy, exceptions granted, and policy violations</span></li></ul></div><div><b>Additional References:</b></div><div><ul><li>NIST CSF References: ID.GV-1, PR.IP</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3309, 1, '<div><b>CERT-RMM Reference</b></div><div>Consider identifying stakeholders of the vulnerability management process. These are&#160;<span>examples of stakeholders of the vulnerability analysis and resolution process:</span></div><div><ul><li>higher-level managers responsible for establishing organizational risk criteria and&#160;<span>tolerances</span></li><li>staff responsible for the organization&#8217;s risk management plan</li><li>asset owners, custodians, and users</li><li>staff responsible for managing operational risks to assets</li><li>staff responsible for establishing, implementing, and maintaining an internal control&#160;<span>system for assets</span></li><li>staff responsible for developing, testing, implementing, and executing service&#160;<span>continuity plans</span></li><li>external entities responsible for managing high-value assets and providing essential&#160;<span>services</span></li><li>internet service providers</li><li>human resources (for people assets)</li><li>legal counsel</li><li>information technology staff, such as system administrators and CSIRTs</li><li>staff responsible for physical security (for facility assets)</li><li>internal and external auditors</li><li>owners of operational resilience management processes, including risk management,&#160;<span>incident management and control, and service continuity</span></li></ul><b>Additional References:</b><br></div><div><ul><li>NIST CSF References: ID.AM-6, ID.GV-2, PR.AT</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3310, 1, '<div><b>CERT-RMM Reference</b></div><div>Consider developing standards and guidelines for vulnerability management. Such&#160;<span>standards and guidelines should address:</span></div><div><ul><li>vulnerability data</li><li>process strategy and plans, including the scope of the plans and commitments to the plans</li><li>list of sources of vulnerability information</li><li>list of internal and external stakeholders and a plan for their involvement</li><li>vulnerability prioritization guidelines</li><li>prioritized process requirements, accepted requirements, and risks resulting from unsatisfied requirements</li><li>infrastructure requirements</li><li>vulnerability data collection and storage standards and parameters</li><li>vulnerability data identification, monitoring, collection, analysis, remediation, handling, and storage methods, procedures, techniques, and tools</li><li>vulnerability data distribution plans, procedures, processes, media, methods, and tools</li><li>collection media, including electronic logs, data files, databases, and repositories</li><li>vulnerability status reports, including resolution strategies</li><li>policies and procedures</li><li>contracts with external entities</li></ul></div><div><b>Additional References:</b></div><div><ul><li>NIST CSF References: PR.IP-12</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3311, 1, '<div><b>CERT-RMM Reference</b></div><div>Consider conducting reviews of the vulnerability management process, including:</div><div><ul><li>current sources of vulnerability data are in use</li><li>assets subject to the process are identified, documented, and included in the scope of process activities</li><li>assets that have been retired are removed from the scope of the process</li><li>vulnerability data is identified, collected, and stored in a timely manner</li><li>the vulnerability repository is established and maintained</li><li>access to the vulnerability repository is limited to authorized staff</li><li>vulnerability management status reports are provided to appropriate stakeholders in a timely manner</li><li>vulnerabilities are referred to the risk management process when necessary</li><li>actions requiring management involvement are elevated in a timely manner</li><li>the performance of process activities is being monitored and regularly reported</li><li>key measures are within acceptable ranges as demonstrated in governance dashboards or scorecards and financial reports</li><li>administrative, technical, and physical controls are operating as intended</li><li>controls are meeting the stated intent of the resilience requirements</li><li>actions resulting from internal and external audits are being closed in a timely manner</li></ul></div><div><b>Additional References:</b></div><div><ul><li><span>NIST CSF References: PR.IP-8</span></li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3312, 1, '<div><b>CERT-RMM Reference</b></div><div>Consider ensuring that responsible staff possess adequate skills to perform vulnerability&#160;<span>management activities. These are examples of skills required in the vulnerability&#160;</span><span>management process:</span></div><div><ul><li>knowledge of tools, techniques, and methods used to identify, analyze, remediate,&#160;<span>monitor, and communicate vulnerabilities for all asset types, including those necessary&#160;</span><span>to perform the process using the selected&#160;</span>methods, techniques, and tools</li><li>knowledge of tools, techniques, and methods necessary to ensure the confidentiality&#160;<span>integrity, and availability of vulnerability data</span></li><li>knowledge necessary to elicit and prioritize stakeholder requirements and needs and&#160;<span>interpret them to develop effective process requirements, plans, and programs</span></li><li>knowledge necessary to analyze and prioritize process requirements</li><li>knowledge necessary to interpret vulnerability data and represent it in ways that are&#160;<span>meaningful and appropriate for managers and stakeholders</span></li></ul></div><div><b>Additional References:</b></div><div><ul><li>NIST CSF References: PR.AT</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3313, 1, '<div><b>CERT-RMM Reference</b></div><div>Consider ensuring that vulnerability management activities are adequately funded.&#160;<span>Funding the process should extend beyond the initial development of vulnerability&#160;</span><span>management activities, tools, and processes to ensure that the operating environment is&#160;</span><span>continuously monitored for vulnerabilities.</span></div><div><b><br></b></div><div><b>Additional References:</b></div><div><ul><li>NIST CSF References: ID.GV-4</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3314, 1, '<div><b>CERT-RMM Reference</b></div><div>Consider managing risk from the failure of vulnerability management processes. Monitor&#160;<span>key components of vulnerability management, including:</span></div><div><ul><li>current sources of vulnerability data are in use</li><li>assets subject to the process are identified, documented, and included in the scope of&#160;<span>process activities</span></li><li>assets that have been retired are removed from the scope of the process</li><li>vulnerability data is identified, collected, and stored in a timely manner</li><li>the vulnerability repository is established and maintained</li><li>access to the vulnerability repository is limited to authorized staff</li><li>vulnerability management status reports are provided to appropriate stakeholders in a&#160;<span>timely manner</span></li><li>vulnerabilities are referred to the risk management process when necessary</li><li>actions requiring management involvement are elevated in a timely manner</li><li>the performance of process activities is being monitored and regularly reported</li><li>key measures are within acceptable ranges as demonstrated in governance&#160;<span>dashboards or scorecards and financial reports</span></li><li>administrative, technical, and physical controls are operating as intended</li><li>controls are meeting the stated intent of the resilience requirements</li><li>actions resulting from internal and external audits are being closed in a timely manner</li></ul></div><div><b>Additional References:</b></div><div><ul><li>NIST CSF References: ID.GV-4, ID.RA-6</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3315, 1, '<div><b>CERT-RMM Reference</b></div><div>Consider measuring the vulnerability management process. These are examples of metrics&#160;<span>for the vulnerability management process:</span></div><div><ul><li>number of high-value assets (by type) subject to process activities (This is determined by the resilience requirements associated with identified assets and assumes an up-to-date asset inventory.)</li><li>percentage of high-value assets that have been monitored for vulnerabilities within an agreed-upon time interval</li><li>percentage of high-value assets that have been audited or assessed for vulnerabilities within an agreed upon time interval</li><li>number of reported vulnerabilities by asset type or category for which some form of resolution or remediation is called for (course of action, reduction, elimination)</li><li>percentage of vulnerabilities that have been satisfactorily remediated (or conversely, percentage of open vulnerabilities) by time interval (days, weeks, months)</li><li>number of reported vulnerabilities for which a vulnerability management strategy exists</li><li>percentage of vulnerabilities with a vulnerability management strategy that is on track per plan</li><li>number and percentage of vulnerabilities requiring a root-cause analysis</li><li>number of vulnerabilities referred to the risk management process; number of vulnerabilities where corrective action is still pending (by risk rank)</li><li>number of vulnerabilities referred to the incident management and control process by time interval</li><li>number of vulnerabilities referred to the service continuity process by time interval</li><li>schedule for collecting, recording, and distributing vulnerability data, including elapsed time from high-value data collection to data distribution to key stakeholders</li><li>percentage of organizational units, lines of business, projects, and activities using</li><li>vulnerability data to assess the performance of operational resilience management processes</li><li>number of risks resulting from unsatisfied process requirements, designated as high, medium, or low or some other organizational risk ranking method</li><li>number of scope changes to process activities by time interval</li><li>number of process risks referred to the risk management process; number of risks where corrective action is still pending (by risk rank)</li><li>level of adherence to process policies; number of policy violations; number of policy exceptions requested and number approved</li><li>number of process activities that are on track per plan</li><li>rate of change of resource needs to support the process</li><li>rate of change of costs to support the process</li></ul></div><div><b>Additional References:</b></div><div><ul><li>CSF References: PR.IP-7</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3316, 1, '<div><b>CERT-RMM Reference</b></div><div>Consider objectively evaluating adherence of the vulnerability management process&#160;<span>against its process description, standards, and procedures, and address non-compliance.</span></div><div><span>These are examples of activities to be reviewed:</span><br></div><div><ul><li>the alignment of stakeholder requirements and needs with the process scope, strategy, plans, and management strategies for specific vulnerabilities</li><li>assignment of responsibility, accountability, and authority for process activities&#160;</li><li>determining the adequacy of process reports and reviews in informing decision makers regarding the performance of operational resilience management activities and the need to take corrective action, if any</li><li>verification of data confidentiality, integrity, and availability controls</li><li>use of process data for improving strategies for protecting and sustaining assets and services</li></ul></div><div><b>Additional References:</b></div><div><ul><li>NIST CSF References: PR.IP-7</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3317, 1, '<div><b>CERT-RMM Reference</b></div><div>Consider ensuring that the organization reviews the activities, status, and results of the&#160;<span>vulnerability management process with higher-level managers and resolves issues.</span></div><div><b><br></b></div><div><b>Additional References:</b></div><div><ul><li>NIST CSF References: PR.IP-8</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3318, 1, '<div><b>CERT-RMM Reference</b></div><div>Consider establishing an organization-wide approach to vulnerability management, that</div><div>includes:</div><div><ul><li>selecting from the organization&#8217;s set of standard processes those processes that cover the vulnerability management process and best meet the needs of the organizational unit or line of business</li><li>establishing the defined process by tailoring the selected processes according to the organization&#8217;s tailoring guidelines</li><li>ensuring that the organization&#8217;s process objectives are appropriately addressed in the defined process, and ensure that process governance extends to the tailored processes.</li><li>documenting the defined process and the records of the tailoring</li><li>revising the description of the defined process as necessary</li></ul></div><div><b>Additional References:</b></div><div><ul><li>NIST CSF References: PR.IP</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3319, 1, '<div><b>CERT-RMM Reference</b></div><div>Consider collecting vulnerability management work products, measures, measurement&#160;<span>results, and improvement information derived from planning and performing the process&#160;</span><span>to support future use and improvement of the organization&#8217;s processes and process&#160;</span><span>assets.</span></div><div><br></div><div><b>Additional References:</b></div><div><ul><li>NIST CSF References: PR.IP</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3325, 1, '<b>CERT-RMM Reference<br>[IMC:SG2.SP2]</b> Develop and implement an incident management knowledge base that allows for the entry of event reports (and the tracking of declared incidents) through all phases of their life cycle. Guidelines and standards for the consistent documentation of events should be developed and communicated to all who are involved in the reporting and logging processes.<div><br></div><div><b>Additional References:</b></div><div><ul><li>Special Publication 800-61 &#34;Computer Security Incident Handling guide&#34; Section 2</li><li>Handbook for Computer Security Incident Response Teams (CSIRTs)</li><li>NIST CSF References: DE.AE-3</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3326, 1, '<b>CERT-RMM Reference</b><div><b>[IMC:SG2.SP4]</b> Assign a category to events from the organization&#8217;s standard category definitions.</div><div><b><br></b></div><div><b>Additional References:</b></div><div><ul><li>Special Publication 800-61 &#34;Computer Security Incident Handling guide&#34; Section 3</li><li>Handbook for Computer Security Incident Response Teams (CSIRTs) Page 66</li><li>NIST CSF References: RS.AN-4</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3328, 1, '<b>CERT-RMM Reference</b><div><b>[IMC:SG2.SP4]</b> Prioritize events. Events may be prioritized based on event knowledge, the results of categorization and correlation analysis, incident declaration criteria and experience with past-declared incidents.</div><div><b><br></b></div><div><b>Additional References:</b></div><div><ul><li>Special Publication 800-61 &#34;Computer Security Incident Handling guide&#34; Section 3.2</li><li>Handbook for Computer Security Incident Response Teams (CSIRTs) Page 124-128</li><li>NIST CSF References: DE.AE-4</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3331, 1, '<b>CERT-RMM Reference<br>[IMC:SG2.SP3] </b>Identify relevant rules, laws, regulations, and policies for which incident evidence may be required. Because there may be compliance issues related to the collection and preservation of incident data, this practice must be considered in the context of the organization&#8217;s compliance program.<br><b><br></b><div><b>Additional References:</b><br><ul><li>Special Publication 800-61 &#34;Computer Security Incident Handling guide&#34; Section 2.4.4</li><li>Handbook for Computer Security Incident Response Teams (CSIRTs) Page 26</li><li>NIST CSF References: DE.DP-2, ID.GV-3</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3340, 1, '<div><b>CERT-RMM Reference</b></div><div><b>[IMC:SG5.SP1]</b> Identify root-cause analysis tools and techniques and ensure all staff who&#160;<span>participate in analysis are trained in their use. These tools and techniques may include&#160;</span><span>cause-and-effect diagrams, interrelationship diagrams, causal factor tree analysis, etc.</span></div><div><b><br></b></div><div><b>Additional References:</b></div><div><ul><li>NIST SP 800-53 Rev. 4 IR-8</li><li>NIST CSF References: DE.DP-5, PR.IP-7</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3341, 1, '<div><b>CERT-RMM Reference</b></div><div><b>[IMC:SG5.SP2]</b> Establish a problem management system to ensure that all operational&#160;<span>events that are not part of standard operation (incidents, problems, and errors) are&#160;</span><span>recorded, analyzed, and resolved in a timely manner.</span></div><div><br></div><div><b>Additional References:</b></div><div><ul><li>NIST SP 800-53 Rev. 4 IR-1</li><li>NIST CSF References: DE.DP-5, PR.IP-7</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3343, 1, '<div><b>CERT-RMM Reference</b></div><div>Consider establishing a plan for incident management. The plan for the incident&#160;<span>management and control process should reflect the organization&#8217;s stated philosophy of&#160;</span><span>incident management and the preferred means for handling incidents (i.e., through a&#160;</span><span>dedicated or permanent team, a virtual team, etc.).</span></div><div><br></div><div>Subpractice:</div><div>&#8226; Define and document the plan for performing the process.</div><div>&#8226; Define and document the process description.</div><div>&#8226; Review the plan with relevant stakeholders and get their commitment.</div><div>&#8226; Revise the plan as necessary.</div><div><br></div><div><b>Additional References:</b></div><div><ul><li><span>NIST CSF References: PR.IP-9</span></li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3344, 1, '<div><b>CERT-RMM Reference</b></div><div>Consider developing a policy for incident management. The incident management policy&#160;<span>should address:</span></div><div><ul><li>responsibility, authority, ownership, and the requirement to perform incident&#160;<span>management activities</span></li><li>establishment of procedures, standards, and guidelines for:</li><ul><li>event identification, detection, and reporting</li><li>analyzing events and incidents</li><li>collecting, documenting, and preserving evidence</li><li>recovering from incidents</li></ul><li><span>requirements for periodically assessing incident management activities</span><br></li><li><span>post-incident review, problem resolution, and closure</span></li><li>measuring adherence to policy, exceptions granted, and policy violations</li><li>compliance with legal, regulatory, contractual, and government obligations</li></ul></div><div><b><br></b></div><div><b>Additional References:</b></div><div><ul><li>NIST CSF References: ID.GV-1, PR.IP</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3345, 1, '<div><b>CERT-RMM Reference</b></div><div>Consider identifying stakeholders of the incident management process. Examples include:</div><div>&#8226; incident owners</div><div>&#8226; asset owners and custodians</div><div>&#8226; service owners</div><div>&#8226; organizational unit and line of business managers responsible for high-value assets&#160;<span>and the services they support</span></div><div>&#8226; staff who serve key roles in incident communications activities, such as public relations</div><div>&#8226; staff who provide input to and resolution of incidents as they are escalated</div><div>&#8226; staff responsible for developing, implementing, and managing an internal control&#160;<span>system for assets</span></div><div>&#8226; external entities involved in process activities and responsible for managing high-value&#160;<span>assets</span></div><div>&#8226; human resources</div><div>&#8226; information technology staff</div><div>&#8226; service desk staff</div><div>&#8226; staff responsible for physical security</div><div>&#8226; legal and law enforcement staff, including federal agencies</div><div>&#8226; internal and external auditors</div><div>&#8226; regulatory and governing agencies</div><div><b><br></b></div><div><b>Additional References:</b></div><div><ul><li>NIST CSF References: ID.AM-6, ID.GV-2, PR.AT</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3346, 1, '<div><b>CERT-RMM Reference</b></div><div>Consider developing standards and guidelines for incident management activities. Such&#160;<span>standards and guidelines should include information on:</span></div><div>&#8226; event reports, including sources of event detection and reporting</div><div>&#8226; incident management plans and the process plan</div><div>&#8226; incident response strategy and plan</div><div>&#8226; event and incident status reports</div><div>&#8226; incident communications plan</div><div>&#8226; list of incident stakeholders</div><div>&#8226; incident management policies, procedures, standards, and guidelines</div><div>&#8226; incident knowledge base</div><div>&#8226; event and incident evidence</div><div>&#8226; incident declaration criteria</div><div>&#8226; incident escalation procedures and criteria</div><div>&#8226; post-incident analysis reports</div><div>&#8226; list of incident management process improvements</div><div>&#8226; contracts with external entities</div><div><b><br></b></div><div><b>Additional References:</b></div><div><ul><li>NIST CSF References: PR.IP-9</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3347, 1, '<div><b>CERT-RMM Reference</b></div><div>Consider conducting periodic reviews of the incident management process. Periodic&#160;<span>reviews are needed to ensure that:</span></div><div>&#8226; the process is known and accessible</div><div>&#8226; events and incidents are identified, reported, and addressed on a timely basis</div><div>&#8226; events and incidents are logged and closed</div><div>&#8226; proper forensic procedures are used to collect and preserve evidence</div><div>&#8226; events are properly triaged and analyzed for root causes</div><div>&#8226; incidents are properly declared</div><div>&#8226; incidents are properly escalated to designated stakeholders</div><div>&#8226; incident response capabilities are commensurate with the priority of an incident</div><div>&#8226; incidents are communicated appropriately to stakeholders at a level commensurate&#160;<span>with their involvement</span></div><div>&#8226; event and incident status reports are provided to appropriate stakeholders in a timely&#160;<span>manner</span></div><div>&#8226; post-incident reviews are performed to improve the process</div><div>&#8226; actions requiring management involvement are elevated in a timely manner</div><div>&#8226; the performance of process activities is being monitored and regularly reported</div><div>&#8226; key measures are within acceptable ranges as demonstrated in governance dashboards&#160;<span>or scorecards and financial reports</span></div><div>&#8226; administrative, technical, and physical controls are operating as intended</div><div>&#8226; controls are meeting the stated intent of the resilience requirements</div><div>&#8226; actions resulting from internal and external audits are being closed in a timely manner</div><div><b><br></b></div><div><b>Additional References:</b></div><div><ul><li>NIST CSF References: PR.IP-8</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3348, 1, '<div><b>CERT-RMM Reference</b></div><div>Consider ensuring that responsible staff are trained in skills required in the incident&#160;<span>management process. Examples of these skills include:</span></div><div>&#8226; event detection, reporting, and tracking, including service desk activities</div><div>&#8226; documenting and logging event reports</div><div>&#8226; collecting and preserving evidence</div><div>&#8226; technical analysis of events and incidents, including triage</div><div>&#8226; declaring incidents</div><div>&#8226; escalating and communicating incidents</div><div>&#8226; understanding and applying laws, rules, and regulations</div><div>&#8226; performing incident response, including damage containment</div><div>&#8226; creating, managing, and deploying incident response teams</div><div>&#8226; developing and implementing administrative, technical, and physical controls</div><div>&#8226; performing root-cause analysis and post-incident review</div><div>&#8226; using tools, techniques, and methods necessary to handle incidents throughout their&#160;<span>life cycle, including those necessary to perform the process using the selected&#160;</span><span>methods, techniques, and tools</span></div><div>&#8226; knowledge unique to each type of asset or service that may be the target of an&#160;<span>incident</span></div><div>&#8226; working effectively and collaborating with asset owners and custodians</div><div>&#8226; eliciting and prioritizing stakeholder requirements and needs and interpreting them to&#160;<span>develop effective incident management plans and plans for handling specific types of&#160;</span><span>incidents</span></div><div><b>Additional References:</b></div><div><ul><li>NIST CSF References: PR.AT</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3349, 1, '<div><b>CERT-RMM Reference</b></div><div>Consider ensuring that incident management activities are adequately funded.&#160;<span>Considerations for funding the process should extend beyond the initial development of&#160;</span><span>incident management activities, tools, and processes to ensure that the organization&#160;</span><span>maintains a capability to manage incidents.</span></div><div><br></div><div><b>Additional References:</b></div><div><ul><li>NIST CSF References: ID.GV-4</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3350, 1, '<b>CERT-RMM Reference<br></b>Consider managing risk from the failure of the incident management process. Failures can&#160;<span>occur in:<br></span>&#8226; detecting events and incidents<br>&#8226; planning for incident handling, management, and response<br>&#8226; making commitments to process plans and activities<br>&#8226; collecting, documenting, and preserving event and incident evidence<br>&#8226; analyzing events and incidents<br>&#8226; declaring incidents<br>&#8226; responding to incidents, including participating on incident response teams<br>&#8226; communicating events and incidents and the status of incidents as they move through&#160;<span>the incident life cycle<br></span>&#8226; escalating incidents<br>&#8226; coordinating process activities<br>&#8226; reviewing and appraising the effectiveness of process activities<br>&#8226; performing post-incident review and improvement processes<br><b><br></b><div><b>Additional References:</b><ul><li>NIST CSF References: ID.GV-4, ID.RA-6</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3352, 1, '<b>CERT-RMM Reference</b><div>Consider objectively evaluating adherence of the incident management and control&#160;<span>process against its process description, standards, and procedures, and address noncompliance.</span></div><div><b><br></b></div><div><b>Additional References:</b><br><ul><li><span>NIST CSF References: PR.IP-7</span></li></ul><p></p></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3390, 1, '<b>CERT-RMM Reference<br>[RISK:SG1.SP1]</b> Determine operational risk categories. Risk categories provide a means for collecting and organizing risk for ease of analysis and mitigation. Typical operational risk categories align with the various sources of operational risk such as failed processes, actions of people, systems and technology, and external events but can be as granular as necessary for the organization to effectively manage risk. Operational risks may also align with the types of assets they are most likely to affect --risks to the availability of people, the confidentiality, integrity, and availability of information, etc.<div><br><b>Additional References:</b><br><ul><li>Special Publication 800-39 &#34;Managing Information Security Risk Organization, Mission, and Information System View&#34; Page 7-9</li><li>NIST CSF References: ID.RM, ID.SC-1</li></ul></div>')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3396, 1, 'CERT-RMM References<br>[RISK:SG2.SP1] Define risk thresholds for each risk category. Risk thresholds are a<br>management tool to determine when risk is in control or has exceeded acceptable<br>organizational limits. They must be set for each category of operational risk that the<br>organization establishes as a means for measuring and managing risk. For example, a risk<br>threshold for virus intrusions may be whenever more than 200 users are affected; this<br>would indicate that management needs to act to prevent operational disruption.<br>Additional References<br>Special Publication 800-39 &#34;Managing Information Security Risk Organization, Mission, and<br>Information System View&#34; Page 11<br>NIST CSF References: ID.RM-2, ID.RM-3, RC.CO-2')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3398, 1, 'CERT-RMM Reference<br>[RISK:SG4.SP1] Evaluate the identified risks using the defined risk parameters and risk<br>measurement criteria. Each risk is evaluated and assigned values in accordance with the<br>defined risk parameters and risk measurement criteria. (These include likelihood,<br>consequence, consequence severity, and thresholds.) The organization may weigh the<br>valuation of the risks by adjusting for the priority of impact areas (reputation, finance,<br>etc.) that they established as part of the risk measurement criteria. This will ensure that<br>impact areas of most importance to the organization will influence more strongly which<br>risks are prioritized higher for mitigation. The organization can further influence the<br>prioritization by applying a probability factor, if known.<br>Additional References<br>Special Publication 800-30 &#34;Guide for Conducting Risk Assessments&#34;<br>&#34;Introducing OCTAVE Allegro: Improving the Information Security Risk Assessment<br>Process&#34;<br>NIST CSF References: ID.RA-4')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3402, 1, 'CERT-RMM Reference<br>Consider developing a plan for risk management process. The plan for the risk<br>management process should be directly influenced by the strategic and operational<br>planning processes of the organization and reflect strategic objectives and initiatives<br>where appropriate. The plan for the risk management process should not be confused<br>with a risk management plan or plans for mitigating risk as the plan for the risk<br>management process details how the organization will perform risk management,<br>including the development of risk management and mitigation plans.<br>Additional References<br>NIST CSF References: ID.RM-1')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3403, 1, 'CERT-RMM Reference<br>Consider establishing a risk management policy that addresses:<br>&#8226; responsibility, authority, and ownership for performing process activities<br>&#8226; procedures, standards, and guidelines for<br>- identifying risk sources and categories of risk<br>- defining risk parameters (such as risk tolerance thresholds) and risk measurement<br>criteria<br>- assigning risk priorities based on risk valuation<br>- assigning risk dispositions<br>- developing risk mitigation plans<br>&#8226; periodically monitoring the status of all risks and adjusting as necessary<br>&#8226; methods for measuring adherence to policy, exceptions granted, and policy violations<br>Additional References<br>NIST CSF References: ID.GV-1, PR.IP')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3405, 1, 'CERT-RMM Reference<br>Consider developing standards and guidelines that address:<br>&#8226; identifying risk sources and categories of risk<br>&#8226; defining risk parameters (such as risk tolerance thresholds) and risk measurement<br>criteria<br>&#8226; assigning risk priorities based on risk valuation<br>&#8226; assigning risk dispositions<br>&#8226; developing risk mitigation plans<br>Additional References<br>NIST CSF References: ID.RM-1')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3406, 1, 'CERT-RMM Reference<br>Periodic reviews of the risk management process are needed to ensure that:<br>&#8226; actions requiring management involvement are elevated in a timely manner<br>&#8226; the performance of process activities is being monitored and regularly reported<br>&#8226; key measures are within acceptable ranges as demonstrated in governance<br>dashboards or scorecards and financial reports<br>&#8226; administrative, technical, and physical controls are elevated in a timely manner<br>&#8226; actions resulting from internal and external audits are being closed in a timely manner<br>&#8226; work products accurately reflect what is essential for managing operational risk to<br>ensure mission success, or are corrected or modified if necessary<br>Additional References<br>NIST CSF References: PR.IP-8')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3407, 1, 'CERT-RMM Reference<br>Consider assigning qualified staff to perform risk management processes. These are<br>examples of staff required to perform the risk management process:<br>&#8226; organizational unit managers, line of business managers, project managers, and asset<br>and service owners and custodians.<br>&#8226; the chief risk officer or equivalent<br>&#8226; a risk management steering council, group, or process group<br>&#8226; staff responsible for:<br>- identifying operational risk sources and categories<br>- identifying and assessing operational risks, including risks identified by the process<br>and other resilience management processes<br>- business impact analysis<br>- scenario planning and analysis<br>- assigning risk disposition to risk statements based on risk valuation and prioritization<br>- developing risk mitigation plans and implementing these plans, including accepting,<br>deferring, or transferring residual risk<br>- monitoring and tracking risks to closure<br>- managing external entities that have contractual obligations for risk management<br>activities<br>&#8226; higher-level managers responsible for defining risk parameters, including risk<br>tolerance thresholds, authorization for levels of risk acceptance, organizational impact<br>areas and priorities, and risk measurement criteria<br>&#8226; staff skilled in interview techniques and the use of questionnaires and surveys<br>&#8226; vital managers and subject matter experts<br>&#8226; external entities involved in process activities and in assessing risk on outsourced<br>functions<br>&#8226; internal and external auditors responsible for reporting to appropriate committees on<br>process effectiveness<br>Additional References<br>NIST CSF References: PR.AT')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3408, 1, 'CERT-RMM Reference<br>Consider ensuring that risk management activities are adequately funded. Funding<br>considerations should include ensuring that risk is adequately identified, assessed, and<br>mitigated on a continuous basis, and that risk management activities are not treated as<br>discrete occasional activities.<br>Additional References<br>NIST CSF References: ID.GV-4')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3409, 1, 'CERT-RMM Reference<br>Consider identifying risk to the organization that arises from failed risk management<br>processes. Deviations from the risk management plan may occur because operational<br>risks for assets and services vary widely, and thus the mitigation of these risks may require<br>process deviations. The organization must determine if the deviations are appropriate<br>given the risk parameters and whether the deviation will result in an impact on<br>operational resilience. In addition, deviations from the risk management plan may occur<br>when organizational units fail to follow the enterprise-sponsored process. These<br>deviations may affect the operational resilience of the organizational unit''s services but<br>may also have a cascading effect on enterprise operational resilience objectives.<br>Additional References<br>NIST CSF References: ID.GV-4, ID.RA-6')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3410, 1, 'CERT-RMM Reference<br>Consider measuring risk management activities to ensure their effectiveness. These are<br>examples of metrics for the risk management process:<br>&#8226; percentage of identified assets and services for which some form of risk assessment<br>has been performed and documented as required by policy<br>&#8226; percentage of identified assets and services for which the impact or cost of<br>compromise has been quantified<br>&#8226; percentage of identified risks that do not have a defined risk disposition<br>&#8226; percentage of identified risks that have a defined mitigation plan against which status<br>is reported in accordance with policy<br>&#8226; percentage of identified risks that have not been tracked to closure<br>&#8226; change in volume of risks that have been identified over a selected period<br>&#8226; percentage of previously identified risks that have converted to a risk disposition of<br>&#8220;mitigate&#8221;<br>&#8226; percentage of identified assets for which a mitigation plan has been implemented to<br>mitigate risks as necessary and to maintain these risks within acceptable risk<br>parameters and risk measurement criteria<br>&#8226; percentage of identified services for which a mitigation plan has been implemented to<br>mitigate risks as necessary and to maintain these risks within acceptable risk<br>parameters and risk measurement criteria<br>&#8226; percentage of security incidents that caused damage, compromise, or loss to<br>identified assets or services beyond established risk parameters and risk<br>measurement criteria<br>&#8226; percentage of realized risks that have exceeded established risk thresholds<br>&#8226; percentage of identified or realized risks that have been characterized as &#8220;high&#8221;<br>impact according to the organization''s risk evaluation criteria<br>&#8226; level of adherence to process policies; number of policy violations; number of policy<br>exceptions requested and number approved<br>&#8226; number of process activities that are on track per plan<br>&#8226; rate of change of resource needs to support the process<br>&#8226; rate of change of costs to support the process<br>Additional References<br>NIST CSF References: PR.IP-7')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3411, 1, 'CERT-RMM Reference<br>Consider objectively evaluating adherence of the risk management process against its<br>process description, standards, and procedures, and address non-compliance.<br>Additional References<br>NIST CSF References: PR.IP-7')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3412, 1, 'CERT-RMM Reference<br>Consider reviewing activities, status, and results of the process with higher-level<br>management.<br>Reviews of the risk management process may result from periodic examination or postevent<br>audits that seek to identify problems that must be corrected. Elevating the results<br>of these examinations to managers provides an opportunity to correct process<br>deficiencies and to make managers aware of variations in the risk management process<br>that not only have localized impact but may also affect the organization''s resilience as a<br>whole.<br>Additional References<br>NIST CSF References: PR.IP-8')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3413, 1, 'CERT-RMM Reference<br>Consider establishing an organization-wide approach to risk management, that includes:<br>&#8226; selecting from the organization''s set of standard processes those processes that cover<br>the risk management process and best meet the needs of the organizational unit or<br>line of business.<br>&#8226; establishing the defined process by tailoring the selected processes according to the<br>organization''s tailoring guidelines.<br>&#8226; ensuring that the organization''s process objectives are appropriately addressed in the<br>defined process, and ensure that process governance extends to the tailored<br>processes.<br>&#8226; documenting the defined process and the records of the tailoring.<br>&#8226; revising the description of the defined process as necessary.<br>Additional References<br>NIST CSF References: PR.IP')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3414, 1, 'CERT-RMM Reference<br>Collect risk management work products, measures, measurement results, and<br>improvement information derived from planning and performing the process to support<br>future use and improvement of the organization''s processes and process assets. These are<br>examples of improvement work products and information:<br>&#8226; metrics and measurements of the viability of the process<br>&#8226; changes and trends in operating conditions that affect risk sources and categories<br>&#8226; changes in risk conditions and the risk environment that affect risk parameters,<br>measurement criteria, or risk dispositions<br>&#8226; lessons learned in post-event review of continuity exercises, incidents, and disruptions<br>in continuity, particularly those that result in losses or compromises that exceed risk<br>parameters and measurement criteria<br>&#8226; process lessons learned that can be applied to improve operational resilience<br>management performance and internal controls<br>&#8226; issues with the risk identification, analysis, prioritization, overall assessment,<br>mitigation, and monitoring processes<br>&#8226; lessons learned from both successfully and unsuccessfully mitigating identified risks<br>&#8226; risk mitigation plan costs and benefits for future return on investment analysis<br>&#8226; resilience requirements that are not being satisfied or are being exceeded<br>Additional References<br>NIST CSF References: PR.IP')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3415, 1, 'CERT-RMM Reference<br>[EXD:SG1.SP1] Identify External Dependencies. It is important for the organization to<br>identify and characterize all such external dependencies so that they can be understood,<br>formalized, monitored, and managed as part of the organization''s comprehensive risk<br>management process.<br>Additional References<br>Special Publication 800-137 &#34;Information Security Continuous Monitoring (ISCM) for<br>Federal Information Systems and Organizations&#34; Page E-2<br>NIST CSF References: ID.BE-4, ID.SC-2')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3416, 1, 'CERT-RMM Reference<br>[EXD:SG1.SP1] Establish a process for creating and maintaining the list of external<br>dependencies and entities.<br>Additional References<br>Special Publication 800-137 &#34;Information Security Continuous Monitoring (ISCM) for<br>Federal Information Systems and Organizations&#34; Page 19<br>NIST CSF References: ID.BE-4, ID.SC-2')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3417, 1, 'CERT-RMM Reference<br>[EXD:SG1.SP2] Apply the prioritization criteria to the list of external dependencies to<br>produce a prioritized list. Depending on the prioritization scheme developed by the<br>organization, the result might be several lists, tiers, or sets of external dependencies. Be<br>sure that external dependencies that are required for the successful execution of security<br>activities, service continuity plans, and service restoration plans are prioritized<br>appropriately.<br>Additional References<br>Special Publication 800-39 &#34;Managing Information Security Risk Organization, Mission, and<br>Information System View&#34; Page 25-26<br>NIST CSF References: ID.BE-4, ID.SC-2')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3418, 1, 'CERT-RMM Reference<br>[EXD:SG2.SP1] Identify risks due to external dependencies. Identification of risks due to<br>external dependencies requires an understanding of the actions of the associated external<br>entity in the operation, support, or resilience of the organization''s services. External<br>entities will be responsible for varying dependencies in the support of the organization''s<br>operations.<br>Additional References<br>Special Publication 800-30 &#34;Guide for Conducting Risk Assessments&#34;<br>NIST CSF References: ID.BE-1, ID.RA-5, ID.SC-2')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3419, 1, 'CERT-RMM Reference<br>[EXD:SG3.SP2] For each external dependency, establish a list of resilience specifications<br>that apply to the responsible external entity. The process for determining and<br>documenting the resilience specifications that apply to an external dependency and entity<br>will vary based on the action of the entity in relation to the organization''s operations and<br>the priority of the external dependency. At a minimum, the resilience specifications should<br>include a clear and definitive statement of the external entity''s services, support,<br>products, assets, or staff on which the organization relies.<br>Additional References<br>Special Publication 800-39 &#34;Managing Information Security Risk Organization, Mission, and<br>Information System View&#34; Page 24-26<br>NIST CSF References: ID.BE-1, ID.BE-5, ID.SC-3')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3420, 1, 'CERT-RMM Reference<br>[EXD:SG3.SP2] Periodically review and update resilience specifications for external<br>dependencies and entities as conditions warrant.<br>Additional References<br>NIST CSF References: ID.BE-1, ID.BE-5, ID.SC-3')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3432, 1, 'CERT-RMM Reference<br>Consider developing standards and guidelines for external dependency management.<br>Include:<br>&#8226; list of external dependencies, with priorities<br>&#8226; criteria for prioritizing external dependencies<br>&#8226; affinity analyses results to inform dependency prioritization and risk identification<br>&#8226; information that defines external dependencies, stored as a maintainable information<br>repository or database<br>&#8226; risk statements with impact valuation<br>&#8226; list of external dependency risks with categorization and prioritization, risk disposition,<br>mitigation plans, and current status<br>&#8226; agreement templates, including enterprise specifications that apply to external<br>entities<br>&#8226; external dependencies and resilience specifications that apply to each external entity<br>&#8226; RFPs, including applicable SLAs<br>&#8226; criteria for selecting external entities<br>&#8226; proposal evaluation results and decision rationale<br>&#8226; agreements with external entities, including contracts, memoranda of agreement,<br>purchase orders, and licensing agreements<br>&#8226; performance-monitoring reports<br>&#8226; relationship management databases<br>&#8226; inspection reports on deliverables<br>&#8226; corrective-action reports<br>&#8226; process plan<br>&#8226; policies and procedures<br>Additional References<br>NIST CSF References: ID.SC')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3433, 1, 'CERT-RMM Reference<br>Consider conducting periodic reviews of the external dependency management process.<br>Ensure the organization:<br>&#8226; defines roles and responsibilities in the process plan<br>&#8226; includes process tasks and responsibility for these tasks in specific job descriptions<br>&#8226; develops policy requiring organizational unit managers, line of business managers,<br>project managers, and asset and service owners and custodians to participate in the<br>process for services and assets under their ownership or custodianship<br>&#8226; develops and implements agreements, including contracts, SLAs, memoranda of<br>agreement, purchase orders, and licensing agreements<br>&#8226; includes process tasks in staff performance management goals and objectives, with<br>requisite measurement of progress against these goals<br>Additional References<br>NIST CSF References: PR.IP-8')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3434, 1, 'CERT-RMM Reference<br>Consider ensuring that responsible staff are trained in skills required in external<br>dependency management. These are examples of skills required in the external<br>dependency management process:<br>&#8226; identifying and prioritizing external dependencies<br>&#8226; affinity analyses<br>&#8226; elicitation of resilience specifications to be reflected in RFPs and agreements with<br>external entities<br>&#8226; evaluating and selecting external entities<br>&#8226; negotiating agreements with external entities<br>&#8226; prioritizing external entities based on the priority of the external dependencies for<br>which the entity is responsible<br>&#8226; knowledge of tools, techniques, and methods that can be used to identify, analyze,<br>mitigate, and monitor operational risks resulting from external dependencies and from<br>relationships with external entities<br>&#8226; managing relationships with external entities<br>&#8226; monitoring the performance of external entities, including the inspection of<br>deliverables and knowing when corrective actions are called for<br>Additional References<br>NIST CSF References: PR.AT')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3435, 1, 'CERT-RMM Reference<br>Consider ensuring that external dependency management activities are adequately<br>funded. Funding the process should extend beyond the initial development of the<br>activities, but include maintenance and refresh.<br>Additional References<br>NIST CSF References: ID.GV-4')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3436, 1, 'CERT-RMM Reference<br>Consider managing risk arising from insufficient external dependency management<br>practices. Examples of practices that might be evaluated include:<br>&#8226; list of external dependencies, with priorities<br>&#8226; criteria for prioritizing external dependencies<br>&#8226; affinity analyses results to inform dependency prioritization and risk identification<br>information that defines external dependencies, stored as a maintainable information<br>repository or database<br>&#8226; risk statements with impact valuation<br>&#8226; list of external dependency risks with categorization and prioritization, risk disposition,<br>mitigation plans, and current status<br>&#8226; agreement templates, including enterprise specifications that apply to external<br>entities<br>&#8226; external dependencies and resilience specifications that apply to each external entity<br>&#8226; RFPs, including applicable SLAs<br>&#8226; criteria for selecting external entities<br>&#8226; proposal evaluation results and decision rationale<br>&#8226; agreements with external entities, including contracts, memoranda of agreement,<br>purchase orders, and licensing agreements<br>&#8226; performance-monitoring reports<br>&#8226; relationship management databases<br>&#8226; inspection reports on deliverables<br>&#8226; corrective-action reports<br>&#8226; process plan<br>&#8226; policies and procedures<br>Additional References<br>NIST CSF References: ID.GV-4, ID.RA-6')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3437, 1, 'CERT-RMM Reference<br>Consider measuring the external dependency management activities to ensure their<br>effectiveness and address non-compliance. Example metrics are:<br>&#8226; number and percentage of external entities in a variety of categories, such as:<br>- by external dependency<br>- by business process, by service, by asset or product<br>- by type of service or product provided<br>- by prioritized tier (based on prioritization criteria)<br>- by agreement type (formal contract with and without SLA, memorandum of<br>agreement, purchase order, licensing agreement, and other, including no type of<br>agreement)<br>- by number or type of agreement changes<br>- by status (RFP, source selection, awarded, contract initiated, performing as<br>expected, out of compliance, in dispute or litigation, terminated, renewed, etc.)<br>- by monetary value<br>- by geographic region<br>- by operational throughput that relies upon the external entity (for example, number<br>of customers, transaction volume)<br>- by number of entities external to itself upon which the external entity relies to meet<br>its agreements with the organization<br>- by CERT-RMM capability rating<br>&#8226; percentage of external dependencies without designated organizational owners<br>&#8226; percentage of external entities without designated organizational owners<br>&#8226; percentage of external entities whose financial status is at risk<br>&#8226; percentage of external entities that have undergone some form of assessment, risk<br>assessment, and audit as required by policy<br>&#8226; percentage of external entities that:<br>- play a key role in fulfilling service continuity plans during disruptive events<br>- have tested their service continuity plans, including their participation in the<br>organization''s service continuity plans per agreement<br>- failed to perform as expected during a disruptive event<br>&#8226; percentage of external entities whose deliverables have failed to pass inspection<br>&#8226; percentage of external entities with corrective actions that have not been remedied in<br>the designated time period<br>&#8226; number of external dependency risks referred to the risk management process;<br>number of risks where corrective action is still pending (by risk rank)<br>&#8226; level of adherence to process policies; number of policy violations; number of policy<br>exceptions requested and number approved<br>&#8226; number of process activities that are on track per plan<br>&#8226; rate of change of resource needs to support the process<br>&#8226; rate of change of costs to support the process<br>Additional References<br>NIST CSF References: PR.IP-7')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3438, 1, 'CERT-RMM Reference<br>Consider objectively evaluating adherence of the external dependency management<br>process against its process description, standards, and procedures, and address noncompliance.<br>Additional References<br>NIST CSF References: PR.IP-7')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3440, 1, 'CERT-RMM Reference<br>Consider establishing an organization-wide approach to external dependency<br>management that includes:<br>&#8226; selecting from the organization''s set of standard processes those processes that cover<br>the external dependency management process and best meet the needs of the<br>organizational unit or line of business.<br>&#8226; establishing the defined process by tailoring the selected processes according to the<br>organization''s tailoring guidelines.<br>&#8226; ensuring that the organization''s process objectives are appropriately addressed in the<br>defined process, and ensure that process governance extends to the tailored<br>processes.<br>&#8226; documenting the defined process and the records of the tailoring.<br>&#8226; revising the description of the defined process as necessary.<br>Additional References<br>NIST CSF References: PR.IP')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3441, 1, 'CERT-RMM Reference<br>Consider collecting external dependency management work products, measures,<br>measurement results, and improvement information derived from planning and<br>performing the process to support future use and improvement of the organization''s<br>processes and process assets.<br>Additional References<br>NIST CSF References: PR.IP')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3447, 1, 'CERT-RMM Reference<br>[OTA:SG4.SP1] Conduct the training. Experienced instructors should perform training.<br>When possible, training is conducted in settings that closely resemble actual performance<br>conditions and includes activities to simulate actual work situations. This approach<br>includes integration of tools, methods, and procedures for competency development.<br>Training is tied to work responsibilities so that on-the-job activities or other outside<br>experiences will reinforce the training within a reasonable time after the training.<br>Additional References<br>Special Publication 800-16 Revision 1 (DRAFT) &#34;A Role-Based Model for Federal<br>Information Technology/Cybersecurity Training (3rd Draft)&#34;<br>NIST CSF References: PR.AT-1')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3449, 1, 'CERT-RMM Reference<br>[OTA:SG1.SP3], [OTA:SG3.SP3] Revise the awareness materials and supporting artifacts as<br>necessary.<br>Revise the resilience training needs of the organization as necessary.<br>Additional References<br>Special Publication 800-16 Revision 1 (DRAFT) &#34;A Role-Based Model for Federal<br>Information Technology/Cybersecurity Training (3rd Draft)&#34;<br>NIST CSF References: PR.AT, PR.IP-7')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3451, 1, 'CERT-RMM Reference<br>[OTA:SG4.SP1] Conduct training for senior executives to ensure they are aware of their<br>specific roles and responsibilities. The organization must perform training to ensure staff<br>are appropriately skilled in their roles. Experienced instructors should perform training.<br>Training is tied to work responsibilities so that on-the-job activities or other outside<br>experiences will reinforce the training within a reasonable time after the training is<br>completed.<br>Additional References<br>Special Publication 800-16 Revision 1 (DRAFT) &#34;A Role-Based Model for Federal<br>Information Technology/Cybersecurity Training (3rd Draft)&#34;<br>NIST SP 800-53 Rev. 4 AT-3, PM-13<br>Consider providing role-based security training to senior executives with assigned security<br>roles and responsibilities. Comprehensive role-based training addresses management,<br>operational, and technical roles and responsibilities. Training should be provided before<br>access is authorized and periodically thereafter.<br>NIST CSF References: PR.AT-4')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3452, 1, 'CERT-RMM Reference<br>[OTA:SG4.SP1] Conduct training for physical and information security personnel. The<br>organization must perform training to ensure staff are appropriately skilled in their roles.<br>Experienced instructors should perform training. When possible, training is conducted in<br>settings that closely resemble actual performance conditions and includes activities to<br>simulate actual work situations. This approach includes integration of tools, methods, and<br>procedures for competency development. Training is tied to work responsibilities so that<br>on-the-job activities or other outside experiences will reinforce the training within a<br>reasonable time after the training is completed.<br>Additional References<br>Special Publication 800-16 Revision 1 (DRAFT) &#34;A Role-Based Model for Federal<br>Information Technology/Cybersecurity Training (3rd Draft)&#34;<br>NIST SP 800-53 Rev. 4 AT-3, PM-13<br>Consider providing role-based security training to physical and information security<br>personnel with assigned security roles and responsibilities. Comprehensive role-based<br>training addresses management, operational, and technical roles and responsibilities.<br>Role-based security training also applies to contractors providing services. Training should<br>be provided before access is authorized and periodically thereafter.<br>NIST CSF References: PR.AT-5')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3454, 1, 'CERT-RMM Reference<br>Consider developing policies and procedures for training and awareness. Include the<br>following:<br>&#8226; methods and tools for building and distributing awareness messages, including pens,<br>mugs, posters, signage, screen savers, newsletters, etc.<br>&#8226; instruments for analyzing training needs<br>&#8226; training workstations and other hardware needs<br>&#8226; instructional design tools<br>&#8226; packages for developing presentation materials<br>&#8226; tools, methods, and procedures that closely resemble actual performance conditions<br>and simulate actual work situations<br>&#8226; methods for delivering awareness and training materials, from user on-demand<br>training to classroom-based training<br>&#8226; tools for tracking awareness and training course attendance and successful and<br>unsuccessful completion by designated staff<br>&#8226; methods for evaluating the effectiveness of awareness activities, including surveys,<br>focus groups, interviews, etc.<br>&#8226; methods for evaluating the effectiveness of training activities, including testing,<br>assessment mechanisms, etc.<br>&#8226; tools used to capture and securely store training records and ensure such records are<br>accessed only by authorized staff<br>Additional References<br>NIST CSF References: ID.GV-1, PR.IP')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3456, 1, 'CERT-RMM Reference<br>Consider developing standards and guidelines for training and awareness. Include:<br>&#8226; awareness and training needs<br>&#8226; awareness and training plans and programs<br>&#8226; awareness and training records and waivers<br>&#8226; awareness and training materials and supporting work products<br>&#8226; instructor evaluation forms<br>&#8226; awareness and training effectiveness surveys<br>&#8226; survey and interview results<br>&#8226; awareness and training examinations and assessment results<br>&#8226; policies and procedures<br>&#8226; contracts with external entities<br>Additional References<br>NIST CSF References: PR.AT')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3457, 1, 'CERT-RMM Reference<br>Consider conducting periodic reviews of the training and awareness process as needed to<br>ensure control over:<br>&#8226; awareness and training needs<br>&#8226; awareness and training plans and programs<br>&#8226; awareness and training records and waivers<br>&#8226; awareness and training materials and supporting work products<br>&#8226; instructor evaluation forms<br>&#8226; awareness and training effectiveness surveys<br>&#8226; survey and interview results<br>&#8226; awareness and training examinations and assessment results<br>&#8226; policies and procedures<br>&#8226; contracts with external entities<br>Additional References<br>NIST CSF References: PR.IP-8')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3458, 1, 'CERT-RMM Reference<br>Consider ensuring that responsible staff are trained in skills required in training and<br>awareness. These are examples of skills required in the organizational training and<br>awareness process:<br>&#8226; curriculum and instructional design<br>&#8226; course delivery<br>&#8226; course and instructor evaluation<br>&#8226; measuring the effectiveness of awareness and training materials<br>&#8226; structuring and conducting participant surveys and interviews<br>&#8226; knowledge of the tools, techniques, and methods necessary to create, deliver, and<br>maintain training and awareness work products, including those necessary to perform<br>the process using the selected methods, techniques, and tools<br>&#8226; knowledge unique to each operational resilience management process area and assets<br>and services that are the focus of these processes<br>&#8226; knowledge necessary to elicit and prioritize stakeholder requirements and needs and<br>interpret them to develop effective process requirements, plans, and programs<br>Additional References<br>NIST CSF References: PR.AT')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3459, 1, 'CERT-RMM Reference<br>Consider ensuring that training and awareness activities are adequately funded. Funding<br>the process should extend beyond the initial development of the training and awareness<br>programs, but include maintenance and refresh.<br>Additional References<br>NIST CSF References: ID.GV-4')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3460, 1, 'CERT-RMM Reference<br>Consider managing risk arising from insufficient training and awareness practices.<br>Examples of practices that might be evaluated include:<br>&#8226; awareness and training needs<br>&#8226; awareness and training plans and programs<br>&#8226; awareness and training records and waivers<br>&#8226; awareness and training materials and supporting work products<br>&#8226; instructor evaluation forms<br>&#8226; awareness and training effectiveness surveys<br>&#8226; survey and interview results<br>&#8226; awareness and training examinations and assessment results<br>&#8226; policies and procedures<br>&#8226; contracts with external entities<br>Additional References<br>NIST CSF References: ID.GV-4, ID.RA-6')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3461, 1, 'CERT-RMM Reference<br>Consider measuring the training and awareness activities to ensure their effectiveness.<br>Example metrics for the training and awareness process:<br>&#8226; number of training courses and awareness sessions delivered (e.g., planned versus<br>actual)<br>&#8226; percentage of new users (internal and external) who have satisfactorily completed<br>awareness training before being granted network access<br>&#8226; percentage of users (internal and external) who have satisfactorily completed periodic<br>awareness refresher training as required by policy<br>&#8226; percentage of internal and external staff trained versus expected<br>&#8226; percentage of favorable training program quality survey ratings<br>&#8226; percentage of passing scores (by participants) on training and awareness examinations<br>Additional References<br>NIST CSF References: PR.IP-7')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3462, 1, 'CERT-RMM Reference<br>Consider objectively evaluating adherence of the training and awareness processes against<br>their process description, standards, and procedures, and address non-compliance.<br>Additional References<br>NIST CSF References: PR.IP-7')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3463, 1, 'CERT-RMM Reference<br>Consider ensuring that the organization reviews the activities, status, and results of the<br>training and awareness process with higher-level managers and resolves issues.<br>Additional References<br>NIST CSF References: PR.IP-8')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3464, 1, 'CERT-RMM Reference<br>Consider establishing an organization-wide approach to training and awareness, that<br>includes:<br>&#8226; selecting from the organization''s set of standard processes those processes that cover<br>the training and awareness process and best meet the needs of the organizational unit<br>or line of business.<br>&#8226; establishing the defined process by tailoring the selected processes according to the<br>organization''s tailoring guidelines.<br>&#8226; ensuring that the organization''s process objectives are appropriately addressed in the<br>defined process, and ensure that process governance extends to the tailored<br>processes.<br>&#8226; documenting the defined process and the records of the tailoring.<br>&#8226; revising the description of the defined process as necessary.<br>Additional References<br>NIST CSF References: PR.IP')
INSERT INTO [dbo].[MATURITY_REFERENCE_TEXT] ([Mat_Question_Id], [Sequence], [Reference_Text]) VALUES (3465, 1, 'CERT-RMM Reference<br>Consider collecting training and awareness work products, measures, measurement<br>results, and improvement information derived from planning and performing the process<br>to support future use and improvement of the organization''s processes and process<br>assets.<br>Additional References<br>NIST CSF References: PR.IP')
PRINT(N'Operation applied to 156 rows out of 156')

