INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025205, 'MDM-1', 'If the PEDs are furnished by the aircraft operator, is the hardware, operating system architecture and associated software applications installed on the PED designed so that usage, network connectivity restrictions, and administrative control can be maintained on the device?', '<div><b>NIST SP 1800-21: Mobile Device Security:&#10;Corporate-Owned Personally-Enabled (COPE)</b><br></div><div>Mobile devices are a staple within modern workplaces. As employees use COPE devices to perform&#10;tasks, organizations are challenged with ensuring that these devices process, modify, and store sensitive&#10;data securely. COPE devices bring unique threats to the enterprise and therefore should be managed in&#10;a manner distinct from desktop platforms.&#10;These challenges include securing them from different types of application- and network-based attacks&#10;on mobile devices that have an always-on connection to the internet. Mobile devices also introduce&#10;potential privacy implications for employees using the devices for personal activities.&#10;Managing the security and privacy of workplace mobile devices and minimizing the risk posed can be&#10;challenging because there are many mobile device security tools available. Proper implementation can&#10;be difficult because the method of implementation varies considerably from tool to tool. In addition,&#10;unfamiliarity with the threats to mobile devices can increase implementation challenges.&#160;<br></div><div><br></div>https://nvlpubs.nist.gov/nistpubs/SpecialPublications/NIST.SP.1800-21.pdf<br><div><b><br></b></div><div><b>NIST 800-53 AC-19: Access Control for Mobile Devices</b></div><div>A mobile device is a computing device that has a small form factor such that it can&#10;easily be carried by a single individual; is designed to operate without a physical connection;&#10;possesses local, non-removable or removable data storage; and includes a self-contained power&#10;source. Mobile device functionality may also include voice communication capabilities, on-board&#10;sensors that allow the device to capture information, and/or built-in features for synchronizing&#10;local data with remote locations. Examples include smart phones and tablets. Mobile devices are&#10;typically associated with a single individual. The processing, storage, and transmission capability&#10;of the mobile device may be comparable to or merely a subset of notebook/desktop systems,&#10;depending on the nature and intended purpose of the device. Protection and control of mobile&#10;devices is behavior or policy-based and requires users to take physical action to protect and&#10;control such devices when outside of controlled areas. Controlled areas are spaces for which&#10;organizations provide physical or procedural controls to meet the requirements established for&#10;protecting information and systems.<br></div><div>Due to the large variety of mobile devices with different characteristics and capabilities,&#10;organizational restrictions may vary for the different classes or types of such devices. Usage&#10;restrictions and specific implementation guidance for mobile devices include configuration&#10;management, device identification and authentication, implementation of mandatory protective&#10;software, scanning devices for malicious code, updating virus protection software, scanning for&#10;critical software updates and patches, conducting primary operating system (and possibly other&#10;resident software) integrity checks, and disabling unnecessary hardware.&#10;Usage restrictions and authorization to connect may vary among organizational systems. For&#10;example, the organization may authorize the connection of mobile devices to its network and&#10;impose a set of usage restrictions, while a system owner may withhold authorization for mobile&#10;device connection to specific applications or impose additional usage restrictions before allowing&#10;mobile device connections to a system. Adequate security for mobile devices goes beyond the&#10;requirements specified in NIST 800-53 AC-19. Many safeguards for mobile devices are reflected in other&#10;controls. AC-20 addresses mobile devices that are not organization-controlled.<br></div>', 'Mobile Device Management MDM', 'Mobile Device Management MDM ', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9546, 38, NULL, 23847)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025206, 'MDM-2', 'Does the aircraft operator have an enterprise mobility management (EMM) or mobile device management (MDM) solution for all PEDs (including company-provided devices and personally-owned BYOD devices) used for aircraft operations?', 'Mobile Device Management helps to ensure applications, operating systems, and devices within a company&#8217;s network are maintained at specified patch levels for operational and connectivity requirements.&#160; This will also provide centralized means for visibility and correlation for monitoring and awareness within the company&#8217;s existing cybersecurity framework.<div><br></div><div><b>Enterprise Mobility Management (EMM)</b></div><div><b><br></b></div><div><div>Organizations use EMM solutions to secure the mobile devices of users who are authorized to access organizational resources. Such solutions generally have two main components. The first is a backend service that mobile administrators use to manage the policies, configurations, and security actions applied to registered mobile devices. The second is an on-device agent, usually in the form of a mobile application, that integrates between the mobile OS and the solution&#8217;s backend service. iOS also supports a web-based EMM enrollment use case, which we do not discuss in this document.</div><div><br></div><div>At a minimum, an EMM solution can perform mobile device management (MDM) functions, which include the ability to provision configuration profiles to devices, enforce security policies on devices, and monitor compliance with those policies. The on-device MDM agent can typically notify the device user of any noncompliant settings and may be able to remediate some noncompliant settings automatically.The organization can use policy compliance data to inform its access control decisions so that it grants access only to a device that demonstrates the mandated level of compliance with the security policies in place.</div><div><br></div><div>EMM solutions commonly include any of the following capabilities: mobile application management, mobile content management, and implementations of or integrations with device- or mobile-OS-specific containerization solutions, such as Samsung Knox. These capabilities can be used in the following ways:</div><div><br></div><div><ul><li>Mobile application management can be used to manage the installation and usage of applications based on their trustworthiness and work relevance.</li><li><span>Mobile content management can control how managed applications access and use organizational data.</span></li><li><span>Containerization solutions can strengthen the separation between a user&#8217;s personal and professional usage of the device.</span></li><li><span>Also, EMM solutions often have integrations with a diverse set of additional tools and security technologies that enhance their capabilities.</span></li></ul></div><div><br></div><div>For further reading on this topic, NIST SP 800-124 Revision 2 (Draft), Guidelines for Managing the Security of Mobile Devices in the Enterprise provides additional information on mobile device management with EMM solutions. The National Information Assurance Partnership&#8217;s (NIAP&#8217;s) Protection&#160; Profile for Mobile Device Management Servers and Extended Package for Mobile Device Management Agents describes important capabilities and security requirements to look for in EMM systems.</div><div><br></div><div>EMMs can help BYOD deployments improve the security posture of the organization by providing a baseline of controls to limit attack vectors and help protect enterprise information that is on a personally owned device. EMMs can also provide an additional layer of separation between enterprise</div><div>data and personal data on a mobile device.</div><div><br></div><div><br></div></div>', 'Mobile Device Management MDM', 'Mobile Device Management MDM', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9547, 38, NULL, 23848)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025207, 'MDM-3', 'Does the aircraft operator use enterprise mobility management (EMM) or mobile device management (MDM) to maintain an inventory of all PEDs?', 'The inventory in a device management database can store a wealth of information about technology hardware, operating systems, software and services, settings, and provisioned accounts.  This inventory data helps IT gain a better understanding of the technologies that reside within their support environment, and leads to smarter decisions on how to secure and deploy new technologies.  Without knowing what is in a specific inventory, it can be difficult to determine whether the organization is at risk from a particular public vulnerability.  An inventory also enables automation of a number of otherwise expensive manual tasks.<div><b><br></b></div><div><b><span>Enterprise Mobility Management (EMM)</span><br></b></div><div><div>Organizations use enterprise mobility management (EMM) solutions to secure the mobile devices of users who are authorized to access organizational resources. Such solutions generally have two main components. The first is a backend service that mobile administrators use to manage the policies, configurations, and security actions applied to registered mobile devices. The second is an on-device agent, usually in the form of a mobile application, that integrates between the mobile OS and the solution&#8217;s backend service. iOS also supports a web-based EMM enrollment use case, which we do not discuss in this document.</div><div><br></div><div>At a minimum, an EMM solution can perform mobile device management (MDM) functions, which include the ability to provision configuration profiles to devices, enforce security policies on devices, and monitor compliance with those policies. The on-device MDM agent can typically notify the device user of any noncompliant settings and may be able to remediate some noncompliant settings automatically.The organization can use policy compliance data to inform its access control decisions so that it grants access only to a device that demonstrates the mandated level of compliance with the security policies in place.</div><div><br></div><div>EMM solutions commonly include any of the following capabilities: mobile application management, mobile content management, and implementations of or integrations with device- or mobile-OS-specific containerization solutions, such as Samsung Knox. These capabilities can be used in the following ways:</div><div><br></div><div><ul><li>Mobile application management can be used to manage the installation and usage of applications based on their trustworthiness and work relevance.</li><li>Mobile content management can control how managed applications access and use organizational data.</li><li>Containerization solutions can strengthen the separation between a user&#8217;s personal and professional usage of the device.</li><li>Also, EMM solutions often have integrations with a diverse set of additional tools and security technologies that enhance their capabilities.</li></ul></div><div><br></div><div>For further reading on this topic, NIST SP 800-124 Revision 2 (Draft), Guidelines for Managing the Security of Mobile Devices in the Enterprise provides additional information on mobile device management with EMM solutions. The National Information Assurance Partnership&#8217;s (NIAP&#8217;s) Protection&#160; Profile for Mobile Device Management Servers and Extended Package for Mobile Device Management Agents describes important capabilities and security requirements to look for in EMM systems.</div><div><br></div><div>EMMs can help BYOD deployments improve the security posture of the organization by providing a baseline of controls to limit attack vectors and help protect enterprise information that is on a personally owned device. EMMs can also provide an additional layer of separation between enterprise</div><div>data and personal data on a mobile device.</div></div>', 'Mobile Device Management MDM', 'Mobile Device Management MDM', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9548, 38, NULL, 23849)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025208, 'MDM-4', 'Does the aircraft operator have the ability to remotely wipe the PED (both company-provided and BYOD) in the event the PED is lost or stolen? ', 'In the event that a PED is reported lost/stolen, an MDM solution or (enterprise mobility management) EMM platform provides a practical means to remotely terminate wireless provisioned services and remotely wipe a device &#8211; thereby minimizing risks relevant to unauthorized usage and data/device tampering.<div><b><br></b><div><span><b>Enterprise Mobility Management (EMM)</b></span><br></div><div><div><span>Organizations use EMM solutions to secure the mobile devices of users who are authorized to access organizational resources. Such solutions generally have two main components. The first is a backend service that mobile administrators use to manage the policies, configurations, and security actions applied to registered mobile devices. The second is an on-device agent, usually in the form of a mobile application, that integrates between the mobile OS and the solution&#8217;s backend service. iOS also supports a web-based EMM enrollment use case, which we do not discuss in this document.</span></div><div><br></div><div>At a minimum, an EMM solution can perform mobile device management (MDM) functions, which include the ability to provision configuration profiles to devices, enforce security policies on devices, and monitor compliance with those policies. The on-device MDM agent can typically notify the device user of any noncompliant settings and may be able to remediate some noncompliant settings automatically.The organization can use policy compliance data to inform its access control decisions so that it grants access only to a device that demonstrates the mandated level of compliance with the security policies in place.</div><div><br></div><div>EMM solutions commonly include any of the following capabilities: mobile application management, mobile content management, and implementations of or integrations with device- or mobile-OS-specific containerization solutions, such as Samsung Knox. These capabilities can be used in the following ways:</div><div><br></div><div><ul><li>Mobile application management can be used to manage the installation and usage of applications based on their trustworthiness and work relevance.</li><li><span>Mobile content management can control how managed applications access and use organizational data.</span></li><li><span>Containerization solutions can strengthen the separation between a user&#8217;s personal and professional usage of the device.</span></li><li><span>Also, EMM solutions often have integrations with a diverse set of additional tools and security technologies that enhance their capabilities.</span></li></ul></div><div><br></div><div>For further reading on this topic, NIST SP 800-124 Revision 2 (Draft), Guidelines for Managing the Security of Mobile Devices in the Enterprise provides additional information on mobile device management with EMM solutions. The National Information Assurance Partnership&#8217;s (NIAP&#8217;s) Protection&#160; Profile for Mobile Device Management Servers and Extended Package for Mobile Device Management Agents describes important capabilities and security requirements to look for in EMM systems.</div><div><br></div><div>EMMs can help BYOD deployments improve the security posture of the organization by providing a baseline of controls to limit attack vectors and help protect enterprise information that is on a personally owned device. EMMs can also provide an additional layer of separation between enterprise</div><div>data and personal data on a mobile device.</div></div></div>', 'Mobile Device Management MDM', 'Mobile Device Management MDM', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9549, 38, NULL, 23850)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025209, 'MDM-5', 'Does the aircraft operator ensure that all PEDs have a reliable means for revising the EFB databases?', 'Operators must have a reliable means for revising the EFB databases. Database currency is determined by what required aeronautical information the EFB is replacing. Each method of data revision must ensure integrity of the data being loaded and not negatively impact the reliability of EFB operation. Procedures must exist to protect the EFB from corruption, especially when Internet and/or wireless means are used. Database revisions must not include software application or operating system changes. Application software and/or operating system program changes must be controlled and tested prior to use in-flight. Database and/or application software changes may not be performed during operations (taxi, takeoff, in-flight, and landing). NOTE: External drives for data loading are considered ancillary EFB equipment and not subject to specific requirements beyond those identified for data loading/database revision above.', 'Mobile Device Management MDM', 'Mobile Device Management MDM', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9550, 38, NULL, 23851)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025210, 'MDM-6', 'Does the operator utilize a reliable means for revising the EFB databases?', 'EFB database changes should be made via a secure container on the mobile device, using https or other encrypted channels.', 'Mobile Device Management MDM', 'Mobile Device Management MDM', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9551, 38, NULL, 23852)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025211, 'MDM-7', 'Does the aircraft operator specify a time frame in which patches must be tested and implemented?', '<div><b>NIST SP 800-53: SI-2</b></div>The need to remediate system flaws applies to all types of software and firmware.&#10;Organizations identify systems affected by software flaws, including potential vulnerabilities&#10;resulting from those flaws, and report this information to designated organizational personnel&#10;with information security and privacy responsibilities. Security-relevant updates include patches,&#10;service packs, and malicious code signatures. Organizations also address flaws discovered during&#10;assessments, continuous monitoring, incident response activities, and system error handling. By&#10;incorporating flaw remediation into configuration management processes, required remediation&#10;actions can be tracked and verified.&#10;Organization-defined time periods for updating security-relevant software and firmware may&#10;vary based on a variety of risk factors, including the security category of the system, the criticality&#10;of the update (i.e., severity of the vulnerability related to the discovered flaw), the organizational&#10;risk tolerance, the mission supported by the system, or the threat environment. Some types of&#10;flaw remediation may require more testing than other types. Organizations determine the type&#10;of testing needed for the specific type of flaw remediation activity under consideration and the&#10;types of changes that are to be configuration-managed. In some situations, organizations may&#10;determine that the testing of software or firmware updates is not necessary or practical, such as&#10;when implementing simple malicious code signature updates. In testing decisions, organizations&#10;consider whether security-relevant software or firmware updates are obtained from authorized&#10;sources with appropriate digital signatures.', 'Mobile Device Management MDM', 'Mobile Device Management MDM', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9552, 38, NULL, 23853)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025212, 'MDM-8', 'Does the aircraft operator enforce MDM containerization (or sandboxing) in order to isolate core applications and functionality within a PED?', 'Flight plans and operational data should be signed by FAA (or the local airspace authority) and verified for authenticity by applications on the PED.   Containerization (sandboxing) is essential to prevent malware, intruders, system resources or other applications from interacting with core applications and sensitive data elements required for aircraft operations.  Containerization allows for a centralized capability to isolate applications, disable certain functions of applications within the container (if necessary), and wipe information within the container without affecting user data, as well as remotely wipe devices in case of loss or theft.', 'Mobile Device Management MDM', 'Mobile Device Management MDM', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9553, 38, NULL, 23854)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025213, 'Inv-1', 'Does the aircraft operator maintain an inventory of PEDs authorized for use in aircraft operations?', 'It is insufficient to maintain a manual list (spreadsheet) of devices in the system.  In order to fully understand your attack surface and manage associated risks, a complete inventory is essential.  This becomes a more difficult problem for PEDs that are not always connected.   Providing processes and procedures that allow for natural and easy synchronization of a device with the enterprise MDM solution will enable much easier management, administration, and inventory tracking.', 'Inventory', 'Inventory', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9554, 10, NULL, 23855)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025214, 'Inv-2', 'Does the aircraft operator maintain an inventory of all PEDs where software applications used in operations are hosted and utilized?', 'Application inventory is essential to determining if unauthorized software is on the device.', 'Inventory', 'Inventory', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9555, 10, NULL, 23856)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025215, 'Inv-3', 'Does the aircraft operator maintain administrative control of the PEDs used by crewmembers?', 'Maintaining ownership of the devices allows much easier enforcement of usage policies on the device and administration', 'Inventory', 'Inventory', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9556, 10, NULL, 23857)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025217, 'App-2', 'Are custom applications developed only when necessary?', 'Best practice guidance recommends utilizing custom applications only where necessary.', 'Proprietary Application Development', 'Proprietary Application Development', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9558, 47, NULL, 23859)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025218, 'App-3', 'Does the aircraft operator deploy applications to the PED and/or portable EFB via an MDM solution and avoid manual processes when possible?', 'MDM based distribution of applications provides an additional layer of security.', 'Proprietary Application Development', 'Proprietary Application Development', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9559, 47, NULL, 23860)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025219, 'App-4', 'Does the aircraft operator authenticate applications?', 'Each application should be signed and the application signature should be verified when installed on a device.', 'Proprietary Application Development', 'Proprietary Application Development', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9560, 47, NULL, 23861)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025220, 'App-5', 'Does the aircraft operator require user authentication when applications connect to backend systems or server services over the network?', 'Each application should have some form of user authentication.  Generally it is best to integrate the application authentication with the operating system authentication mechanism.', 'Proprietary Application Development', 'Proprietary Application Development', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9561, 47, NULL, 23862)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025221, 'App-6', 'Are development processes controlled using a security assurance process such as threat modeling?', 'Referencing the Security Development Life Cycle or some other method of application attack modeling, is a recommended best practice for application development.', 'Proprietary Application Development', 'Proprietary Application Development', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9562, 47, NULL, 23863)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025222, 'App-7', 'Are custom software applications tested for compatibility with a patch before the patch is rolled out across company PEDs?', 'Rolling out untested applications or patches can create an emergency scenario that provides opportunity for a malicious actor to exploit otherwise protected resources or systems.', 'Proprietary Application Development', 'Proprietary Application Development', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9563, 47, NULL, 23864)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025223, 'Config-1', 'Does the aircraft operator ensure that all major components such as motherboards, processors, Random-Access Memory (RAM), video cards, hard drives, power supplies, and connections (modem, wireless, etc.) should be configuration controlled?', 'See 8900.1 CHG 331  Figure 4-76. Hardware Description Template for a description of the recommended fields and questionnaire.', 'Device Configuration', 'Device Configuration', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9564, 45, NULL, 23865)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025224, 'Config-2', 'Does the device allow the installation and/or use of non-allowlisted apps in any operational configuration?', 'Application allowlisting is a computer administration practice used to prevent unauthorized programs from running. The purpose is primarily to protect computers and networks from harmful applications, and, to a lesser extent, to prevent unnecessary demand for resources.<div><br></div><div><p><span>SM 4.3: Employ endpoint security protection</span>&#160;on EO-critical software platforms to protect the platforms and all software running on them. Capabilities include:</p><ul><li>protecting the software, data, and platform by identifying, reviewing, and minimizing the attack surface and exposure to known threats</li><li>permitting only verified software to execute (e.g., file integrity verification, signed executables, allowlisting)</li><li>proactively detecting threats and stopping them when possible</li><li>responding to and recovering from incidents</li><li>providing the necessary information for security operations, threat hunting, incident response, and other security needs</li><li><br></li></ul><div><font color="#1b1b1b"><span>https://www.nist.gov/itl/executive-order-improving-nations-cybersecurity/critical-software-0</span><br></font></div></div>', 'Device Configuration', 'Device Configuration', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9565, 45, NULL, 23866)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025225, 'Config-3', 'Are non-essential ports and services disabled on PEDs used in aircraft operations?', 'Short of performing an individual examination of a specific PED installation instance, it is difficult to determine exactly which ports and services are necessary and which are not.  However, there are common ports and services that should be disabled if not needed for the business operations of the device.  The following are services and communications paths to consider:  Communications services:   Bluetooth, Infrared, USB, Wireless networking, Wired networking, Cellular network connections, Near Field Communications.  Specific Application Level Services: Disallow Siri when the device is locked, Disable Wi-Fi assist during flight operations, Disable iCloud backup during flight operations, Determine if iCloud backup should be used or not, Force encrypted backups, Disable Handoff if not needed.  For a comprehensive list see the Apple iOS 9 Interim Security Configuration Guide (ISCG) Configuration Table.', 'Device Configuration', 'Device Configuration', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9566, 45, NULL, 23867)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025226, 'Config-4', 'Are CIS Benchmarks or DISA STIGs utilized to harden operating system architecture? ', '<div><b><u>CIS Benchmarks and DISA STIGs</u></b><br></div><div><b><font face="Arial" color="#000000">CIS Benchmarks</font></b><br></div><div><font face="Arial" color="#000000">Center for Internet Security (CIS) Benchmarks are best practices for the secure configuration of a target system. Available for more than 100 CIS Benchmarks across 25+ vendor product families, CIS Benchmarks are developed through a unique consensus-based process comprised of cybersecurity professionals and subject matter experts around the world. CIS Benchmarks are the only consensus-based, best-practice security configuration guides both developed and accepted by government, business, industry, and academia.<b><br></b></font><div><font face="Arial" color="#000000"><br></font></div><div><p><font face="Arial" color="#000000">Most CIS Benchmarks include multiple configuration profiles. A profile definition describes the configurations assigned to benchmark recommendations.</font></p><p><font face="Arial" color="#000000">The Level 1 profile is considered a base recommendation that can be implemented fairly promptly and is designed to not have an extensive performance impact. The intent of the Level 1 profile benchmark is to lower the attack surface of your organization while keeping machines usable and not hindering business functionality.</font></p><p><font face="Arial" color="#000000">The Level 2 profile is considered to be &#34;defense in depth&#34; and is intended for environments where security is paramount. The recommendations associated with the Level 2 profile can have an adverse effect on your organization if not implemented appropriately or without due care.</font></p><p><font face="Arial" color="#000000">The STIG profile replaces the previous Level 3. The STIG profile provides all recommendations that are STIG specific. Overlap of recommendations from other profiles, i.e. Level 1 and Level 2, are present in the STIG profile as applicable.</font></p><p><font face="Arial" color="#000000">Every recommendation within each CIS Benchmark is associated with at least one profile. Regardless of which level profile you plan to implement in your environment, we recommend applying CIS Benchmark guidance in a test environment first to determine potential impact.</font></p><p class="MsoNormal"><a href="https://learn.cisecurity.org/benchmarks"><font face="Arial" color="#3554b1">https://learn.cisecurity.org/benchmarks</font></a></p><p class="MsoNormal"><a href="https://downloads.cisecurity.org/" target="_blank">https://downloads.cisecurity.org</a><br></p><p class="MsoNormal"><a href="https://www.cisecurity.org/" target="_blank">https://www.cisecurity.org/</a><br></p><p class="MsoNormal"><b><font color="#000000"><u>DISA STIGs</u></font></b></p><p class="MsoNormal"><span><font size="3" color="#000000">The Defense Information Systems Agency&#8217;s (DISA) Security Technical Implementation Guides (STIGs) are a set of best practice rules for installing and supporting IT systems. Each STIG relates to a specific asset: (an OS, a system app, or network hardware)</font></span></p><p class="MsoNormal"><span><font color="#000000">and prescribes the configuration and maintenance steps and best practices necessary to ensure that asset is configured and managed securely.</font></span></p><p class="MsoNormal"><span><font color="#000000">https://public.cyber.mil/stigs/</font></span></p><p class="MsoNormal"><span><font color="#000000">Ensure that the most recent OS hardening guides are being referenced as the guides change frequently with every major OS update.</font></span></p></div></div>', 'Device Configuration', 'Device Configuration', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9567, 45, NULL, 23868)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025227, 'Config-5', 'If the aircraft operator uses Apple iOS devices, are special considerations given to iOS hardware and OS hardening guides?', 'Ensure that the most recent OS hardening guides are being references as the guides change frequently with every major OS update', 'Device Configuration', 'Device Configuration', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9568, 45, NULL, 23869)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025228, 'Config-6', 'If the aircraft operator uses Microsoft Surface devices, are special considerations given to Surface hardware and OS hardening guides?', 'Ensure that the most recent OS hardening guides are being references as the guides change frequently with every major OS update', 'Device Configuration', 'Device Configuration', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9569, 45, NULL, 23870)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025229, 'Config-7', 'If the aircraft operator uses Google Android devices, are special considerations given to Android hardware and OS hardening guides?', 'Ensure that the most recent OS hardening guides are being references as the guides change frequently with every major OS update', 'Device Configuration', 'Device Configuration', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9570, 45, NULL, 23871)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025230, 'Config-8', 'Is the aircraft operating system architecture and associated installed software applications updated automatically?', 'Automatic updates help to minimize risk exposure to software vulnerabilities by ensuring the latest security patches are applied, thereby minimizing the number of known vulnerabilities.  It is best if an organization has the means of testing software updates before they are widely disseminated.', 'Device Configuration', 'Device Configuration', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9571, 45, NULL, 23872)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025231, 'Hard-1', 'Does the aircraft operator ensure a process is in place to periodically perform malware and antivirus scans?', 'This question implies the company has designated IT personnel and has resources available to create and maintain baseline image hashes, subscribe to anti-virus definition services, establish policy, and distribute and enforce policy.', 'System Hardening', 'System Hardening', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9572, 45, NULL, 23873)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025232, 'Hard-2', 'Does the aircraft operator ensure a process is in place to periodically check file hashes to perform integrity checks?', '<div><ul><li><strong>Hash function</strong>&#160;&#8211; A hash function (also called a &#8220;hash&#8221;) is a fixed-length string of numbers and letters generated from a mathematical algorithm and an arbitrarily sized file such as an email, document, picture, or other type of data. This generated string is unique to the file being hashed and is a one-way function&#8212; a computed hash cannot be reversed to find other files that may generate the same hash value. Some of the more popular hashing algorithms in use today are Secure Hash Algorithm-1 (SHA-1), the Secure Hashing Algorithm-2 family (SHA-2 and SHA-256), and Message Digest 5 (MD5).</li><li><strong>Public key cryptography&#160;</strong>&#8211; Public key cryptography (also known as asymmetric encryption) is a cryptographic method that uses a key pair system. One key, called the public key, encrypts the data. The other key, called the private key, decrypts the data. Public key cryptography can be used several ways to ensure confidentiality, integrity, and authenticity. Public key cryptography can<ul><li>Ensure integrity by creating a digital signature of the message using the sender&#8217;s private key. This is done by hashing the message and encrypting the hash value with their private key. By doing this, any changes to the message will result in a different hash value.</li><li>Ensure confidentiality by encrypting the entire message with the recipient&#8217;s public key. This means that only the recipient, who is in possession of the corresponding private key, can read the message.</li><li>Verify the user&#8217;s identity using the public key and checking it against a certificate authority.</li></ul></li></ul></div><div><br></div><div>These days, pretty much everything has some kind of&#10;unique identifier; for example, stock items have SKUs, cars&#10;have VINs, employees have IDs, US citizens have SSNs, etc.&#10;One could say that hashing is an attempt to &#34;label&#34; some&#10;chunk of data with a fixed-length, unique identifier. A&#10;message digest, or hash, is a signature that identifies some&#10;amount of data, usually a file or message. Cryptographic&#10;hashing algorithms are one-directional mathematical&#10;formulae designed to generate a unique value for every&#10;possible input-in this case, the data. Common algorithms&#10;include MDS, SHA-1, SHA-256, and SHA-512, although&#10;there exist a number of more esoteric or use-case-specific&#10;methods.&#10;Obviously, one cannot represent an infinite number&#10;of inputs with a finite-sized signature; when two inputs&#10;result in the same output, this is called a hash collision.&#10;Algorithms that produce a shorter hash are more likely&#10;to cause collisions. Both the MDS and SHA-1 hashing&#10;algorithms have methods of producing collisions that&#10;threat actors can use to hide malicious content.&#160;<br></div><div><br></div><div>Hashing has a large number of applications in&#10;cybersecurity, centering around the ability to verify that&#10;data is legitimate. With a secure hashing algorithm, one&#10;could verify that a downloaded file matched what was&#10;expected. In fact, many projects provide hashes alongside&#10;their downloads. This provides some peace of mind that a&#10;file is authentic and has not been altered in transmission.&#10;In addition, some online services provide the ability to&#10;look up whether a file is known to be malicious based&#10;on file hash. Rather than uploading the entire file for the&#10;service to analyze, one can just provide the hash, since it&#10;uniquely identifies the data in the file.<br></div><div><br></div><div>Often, vendors will provide hashes with downloads of&#10;firmware or other critical files. This can provide an extra&#10;level of security Isafety when downloading files and help&#10;to prevent watering hole attacks. If your vendor does not&#10;provide hashes, it may be possible to contact them and&#10;ask before deploying a new package. Additional safety&#10;measures are never a bad thing, especially when it comes&#10;to downloading files, even from trusted sources.<br></div><div><br></div>Most often this task is performed be dedicated personnel in conjunction with an MDM system running policy checking and auditing.<div><a href="https://www.cisa.gov/tips/st04-018" target="_blank">&#160;https://www.cisa.gov/tips/st04-018</a><br></div>', 'System Hardening', 'System Hardening', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9573, 45, NULL, 23874)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025233, 'Hard-3', 'Does the aircraft operator ensure a process is in place to periodically verify company configuration policies and policy enforcement software?', 'Is the process and time period (if not continuous) for performing audits to ensure company policy and enforcement software are in place and performing correctly defined.', 'System Hardening', 'System Hardening', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9574, 45, NULL, 23875)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025234, 'Hard-4', 'Are crewmember PEDs scanned both before boarding and after deplaning to detect potential compromised software applications and/or operating system architecture?', 'In cybersecurity, the signal (verifiable indication of a compromise) to noise (legitimate activity) ratio is extremely low.  By scanning PED devices both before and after each flight and comparing the results is a strong indicator of either infected aircraft or in-flight tampering with devices.  As with other system hardening questions, this question implies processes and resources are in place to provide easy and seamless scanning of devices in a secure area.', 'System Hardening', 'System Hardening', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9575, 45, NULL, 23876)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025235, 'Hard-5', 'Are systems put through a hardening procedure that requires turning off unused services before being put into service?', 'This question implies there is a process in place to intercept new PEDs and apply hardening configuration before they are put into production use.  Interception of new equipment before it is put into use can be a difficult safeguard to implement.', 'System Hardening', 'System Hardening', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9576, 45, NULL, 23877)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025237, 'Hard-7', 'If commercial off-the-shelf- PEDs are used as portable EFBs,  has the aircraft operator successully completed rapid decompression testing?  ', 'This comes with typical hardening process for EFB''''s.  Hardened devices have been put through a verification process to ensure that the device can withstand sudden drops, shocks, or decompression and continue to fully operate.', 'System Hardening', 'System Hardening', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9578, 45, NULL, 23879)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025238, 'Hard-8', 'Does the aircraft operator have a formalized process for standardization of PED technologies (including relevant applications which interface with PEDs)?', 'Standardization of PEDs allows for much easier and more cost effective administration of PEDs.  Standardizing on one platform and set of applications reduces administration overhead and promotes tighter control on the selected platforms.  A general recommendation would be to ensure the software was developed using a modern programming quality standard such as the Microsoft Trustworthy Computing Security Development Lifecycle or secure coding guidelines provided by Apple for applications that run on IOS platforms.', 'System Hardening', 'System Hardening', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9579, 45, NULL, 23880)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025239, 'Access-1', 'Does access to the network require authentication prior to system connection?', 'When devices are added to the network the should be an authentication process in place to ensure that the devices is authorized for that connection.', 'Access Control', 'Access Control', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9580, 4, NULL, 23881)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025240, 'Access-2', 'Are all the methods of access to the system authorized, monitored, and managed?', 'There should not be any point in the system in which access to system resources is not controlled.', 'Access Control', 'Access Control', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9581, 4, NULL, 23882)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025241, 'Access-3', 'If your authentication encryption module fails can you still authenticate without creating a denial of service that impacts operational performance of the system?', 'An alternative procedure, backup authentication methods, or other means should be inplace to enable the safe utilization of the device is the authentication module fails.', 'Access Control', 'Access Control', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9582, 4, NULL, 23883)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025242, 'Access-4', 'Does the system terminate a network connection at the end of a session?', 'Each session should be terminated at the end of session to prevent a malicous actor from connecting to the open session without requiring additional authentication.', 'Access Control', 'Access Control', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9583, 4, NULL, 23884)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025243, 'Access-5', 'Do PEDs require an unlock authentication (e.g., pin, swipe password, fingerprint etc.) mechanism to enforce identity verification and authentication requirements for PEDs accessing aircraft interfaces and wireless communications paths?', 'At a minimum, PEDs should enforce either a strong passphrase, 8-digit PIN, or Touch ID/fingerprint verification for interfacing with or unlocking a device.  This verification is designed to prevent an unauthorized person(s) from accessing the PED while it is not on the airplane.  While on the airplane, the PED is likely in the cockpit, which is locked from within.  Requiring flight crews to unlock a device during flight operations could introduce unnecessary safety hazards and is therefore not recommended while the device is in the cockpit.', 'Access Control', 'Access Control', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9584, 4, NULL, 23885)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025244, 'AM-1', 'Does the aircraft operator have a policy requiring that default passwords are changed before a device or software application is put into use?', 'Where a device needs a username and/or password to log in, a default password is usually provided that allows the device to be accessed during its initial setup, or after resetting to factory defaults.  Manufacturers typically use a simple password, such as “admin” or “password” on all such equipment, with the expectation users will change the password during initial configuration.  The default username and password is usually found in the instruction manual (common for all devices) or on the device itself.  Default passwords are one of the major contributing factors to large-scale compromises of home routers. Leaving such a password on devices available to the public is a significant security risk.', 'Account Management', 'Account Management', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9585, 5, NULL, 23886)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025245, 'AM-2', 'Does the aircraft operator have a policy requiring periodic password changes for user accounts on PEDs?', 'Periodic password changes can work for and against you.  Password change policies need to be weighed against the probability a password has been compromised.  Difficult-to-guess passwords that apply to a very narrow scope (e.g., a single file, etc.) should not be changed frequently, if ever.  Frequent password change policies force people to write down their password; or worse, choose easy-to-guess passwords.   Passwords typed in multiple times a day are more vulnerable to shoulder surfing (observation by a nearby individual) or becoming victimized by malware interception (e.g., key loggers, etc.).  In addition, accounts may not always be disabled when an individual leaves the company.  Periodic forced password changes or expirations reduce risk exposure.', 'Account Management', 'Account Management', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9586, 5, NULL, 23887)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025246, 'Https-1', 'Does the aircraft operator give preference to file sources that distribute aviation related information (including firmware updates) via https protocol over file sources that use http?', 'Http is an inherently weak protocol for firmware update and distribution.  To further ensure that application updates are received as intended it is recommended that preference be given to https distribution when ever possible.', 'HTTPS', 'HTTPS', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9587, 9, NULL, 23888)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025247, 'Https-2', 'Is all information distributed to crewmembers crews via a web interface via an https link?', 'For all webbased applications and services that deliver information to crewmembers it is recommended that https be given preference over http.   All network based application services should be reviewed to ensure communication protection is inplace and appropriate for the confidentiality, integrity, and availability requirements of the communications link.', 'HTTPS', 'HTTPS', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9588, 9, NULL, 23889)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025248, 'Mal-1', 'Does the aircraft operator have a policy that periodically requires any PED that can connect to an aircraft system to include onboard wireless networks be scanned for vulnerabilities?', 'Mobile devices cannot be scanned from the network in the same manner as permanently connected network devices. The best known workaround is to have the device periodically synced and scanned, including performing anti-virus and malware scans, scanning for unauthorized configuration changes, and performing software and firmware updates.', 'Malware', 'Malware', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9589, 25, NULL, 23890)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025250, 'Mon-2', 'Does the aircraft operator have a policy requiring that firmware updates file hashes be verified before applying to production systems?', 'This policy ensures the firmware intended for the device is correct and untampered with before being applied to the device.  From an operational standpoint this prevents devices from being destroyed beyond recovery from an accidental misapplication of firmware.  In addition, this policy detects changes from a malicious attacker attempting to inject rogue firmware into the supply stream.', 'Monitoring', 'Monitoring', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9591, 25, NULL, 23892)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025251, 'Mon-3', 'Does the aircraft operator monitor the use of PEDs to ensure only authorized software applications are used during aircraft operations?', 'The ability to monitor the use of PED applications not only prevents the misuse of the device (e.g., playing games during aircraft operations, etc.) but also provides a means to determine if an attack is ongoing by detecting malicious software as well.  Due to the lack of logging and forensics frameworks for some PED devices, intrusion detection is not an easy to accomplish on mobile devices.  Application monitoring provides significant insight not easily achieved otherwise.   How does the operator ensure that only those software applications pertinent to the safe operation of the aircraft are used during flight operations?  Generally this is accomplished through profiles, application whitelisting, and MDM integration with mobile device management auditing software pushed onto the device.', 'Monitoring', 'Monitoring', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9592, 25, NULL, 23893)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025252, 'Mon-4', 'Does the aircraft operator enforce application whitelisting or audit applications to ensure the integrity of the PED?', 'Application whitelisting is once again achieved through an enterprise MDM.  This tends to be very difficult in BYOD (bring your own device) situations, but should be easier to achieve for company owned/managed devices in which the applications that should be allowed to run during flight operations can be reasonably identified. See supplemental text in 1.2 regarding electronic manuals.', 'Monitoring', 'Monitoring', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9593, 25, NULL, 23894)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025254, 'Physical-2', 'Do operational processes ensure a means for the secure storage of PEDs when not in use by crewmembers?', 'PEDs should have a designated secure storage location either on the aircraft, or in an area of an airport where the company has storage vaults/lockers (controlled by the company).  PEDs should be physically protected and stored to a level commensurate with the type of data and access necessary to ensure the integrity and confidentiality of aircraft and operational data elements.', 'Physical Access Protection', 'Physical Access Protection', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9595, 32, NULL, 23896)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025255, 'Physical-3', 'Does secure storage also provide charging service to ensure the operational availability of the device?', 'The secure storage location for PEDs (when not in use) should also provide a practical means for charging the devices.  Companies should consider the potential downstream impact if a PED wasn’t fully charged, and was not operational at the time of a flight (or became unusable during a flight).  If power loss or reduced charging capabilities during flight were to hamper the availability of the device, additional controls and processes should be identified for ensuring the safety and integrity of the aircraft’s operations (that are not reliant upon crew members utilizing a PED).   We understand the operational portable EFB requirements with respect to backup mitigation strategies (power, device failure etc.) as defined in current FAA policy and guidance.', 'Physical Access Protection', 'Physical Access Protection', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9596, 32, NULL, 23897)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025256, 'RM-1', 'Are company controlled removable media used for transferring information to the PED purchased from a reputable source?', 'USB drives have been found in which malware was on the device at the time of purchase.  Those responsible for acquisition of removable media should ensure the device is purchased from a reputable source.  Policies and procedures should prohibit the use of non-company purchased and verified USB-Media for connection to critical systems.', 'Removable Media', 'Removable Media', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9597, 66, NULL, 23898)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025257, 'RM-2', 'Where possible does the company use SD flash media instead of USB Drives, as there are fewer exploits using SD flash media?', 'USB drives are particularly vulnerable to driver-level exploits as there are many publicly available exploits available targeting USB drives.  SD Flash media does not have as many exploit kits or exploit packages, and could be considered more secure.', 'Removable Media', 'Removable Media', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9598, 66, NULL, 23899)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025259, 'RM-4', 'Are personally owned removable media should prohibited from use on PEDs?', 'USB devices are recognized as a well known path of intrusion.  All USB and removeable media should be controlled to prevent accidental or deliberate introduction of malware from personal systems or intentionally planted devices.', 'Removable Media', 'Removable Media', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9600, 66, NULL, 23901)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025260, 'Training-1', 'Does the operator develop PED and/or portable EFB training for crewmembers in accordance with FAA Advisory Circular (AC) 120-76, "Authorization for Use of Electronic Flight Bags"?', 'Training should be made available to the flight and grounds crews that use PEDs informing them of the cybersecurity concerns associated with each type of PED and system interface.  Personnel not properly trained or educated on cybersecurity risks are more likely to misuse a PED in a way that can enable a cyber-actor to cause an event.', 'Training', 'Training', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9601, 51, NULL, 23902)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025261, 'Training-2', 'Are crewmembers trained in cybersecurity awareness to include training on social engineering and phishing attacks?', '<div><b>NIST SP 800-53 AT-2(3)</b></div>Social engineering is an attempt to trick an individual into revealing information&#10;or taking an action that can be used to breach, compromise, or otherwise adversely impact a&#10;system. Social engineering includes phishing, pretexting, impersonation, baiting, quid pro&#10;quo, thread-jacking, social media exploitation, and tailgating. Social mining is an attempt to&#10;gather information about the organization that may be used to support future attacks.&#10;Literacy training includes information on how to communicate the concerns of employees&#10;and management regarding potential and actual instances of social engineering and data&#10;mining through organizational channels based on established policies and procedures.', 'Training', 'Training', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9602, 51, NULL, 23903)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025262, 'Training-3', 'Are crewmembers trained from a cybersecurity awareness perspective to question irregular software application performance/activity as possibly being compromised (e.g., abnormal numbers generated from a weight and balance application on a portable EFB)?', 'Personnel should be taught to consider that atypical behavior could possibly be attributed to a compromised system and to report potential compromises.', 'Training', 'Training', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9603, 51, NULL, 23904)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025263, 'Encryption-1', 'Does the aircraft operator have a policy that requires encryption of files on PEDs that connect to aircraft and aircraft system or onboard wireless network?', 'Encrypting files on PEDs protects the files from modification as well as from exposing otherwise sensitive information.', 'Encryption', 'Encryption', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9604, 13, NULL, 23905)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025264, 'Encryption-2', 'Is full disk encryption required for all PEDS?', 'In the event that a PED is reported lost/stolen, an MDM solution or platform provides a practical means to remotely terminate wireless provisioned services and remotely wipe a device – thereby minimizing risks relevant to unauthorized usage and data/devic', 'Encryption', 'Encryption', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9605, 13, NULL, 23906)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025265, 'Encryption-3', 'Does the aircraft operator have a policy that requires open networks with connectivity to aircraft be encrypted (i.e., wireless networks, or public or Internet traversing networks)?', 'Any data traffic coming or going to an aircraft PED that will be exposed to an open or public network is vulnerable to a number of attacks, such as interception, malicious data injection, or capture-and-replay.  It is important these connections are encrypted using either point-to-point encryption, tunneled via a VPN, SSL, or other means of ensuring the privacy, integrity, and availability of the link.   Does the system protect wireless access using authentication and encryption?   Are unauthorized remote connections to the system monitored, including scanning for unauthorized mobile or wireless access points on a defined frequency and is appropriate action taken if an unauthorized connection is discovered?', 'Encryption', 'Encryption', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9606, 13, NULL, 23907)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025266, 'Encryption-4', 'If using a commercial off-the-shelf PED, does it employ a cryptographically secure boot process which guarantees operating system integrity?', 'The most difficult malware to remove and detect (i.e., rootkits, bootkits, illegitimate drivers, etc.) all depend upon exploiting the boot process.  Cryptographically secure boot processes have legitimate file identifiers (hashes) stored in the firmware to confirm that security significant pieces of boot software are verified and malware is rejected when booting the device.', 'Encryption', 'Encryption', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9607, 13, NULL, 23908)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025267, 'Encryption-5', 'If using a commercial off-the-shelf PED, how do users ensure operating system architecture and app updates/upgrades are delivered in an auditable cryptographically secure process?', 'Operating System updates from the manufacturer are generally delivered through cryptographically secure processes.  However, taking OS updates directly from the manufacturer may not allow time for operations-critical applications to be tested before updates are rolled out.  Hence, if an update is rolled out via a company OS update server, the implementation needs to ensure packages are cryptographically signed and secured, and transmitted through trusted delivery channels.  Many applications implement their own update processes.  These process need to be examined to ensure they are also signed and distributed via secure channels and processes.', 'Encryption', 'Encryption', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9608, 13, NULL, 23909)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025268, 'Encryption-6', 'Do enterprise communications with PEDs used in aircraft operations handle all transmissions via secure VPN and CAC-card or two-factor biometric encryption?', 'When connecting back to enterprise systems through Internet or across open channels, all communications should be authenticated via two-factor authentication.  Remote access channels are a common attack entryway.  Because they are available to a broader group of potential attackers, these remote channel interfaces need to be more rigorously protected.', 'Encryption', 'Encryption', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9609, 13, NULL, 23910)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025269, 'Con-1', 'Does the aircraft operator allow crewmembers to connect mobile devices to unsecured Wi-Fi, or other untrusted networks?', 'Public and Open networks are littered with malware that may or may not be explicitly targeting aircraft EFBs.  However, as the potential for mobile device corruption via Wi-Fi and other public networks is inherently high and often OS specific, operators should explicitly discourage PED access at any untrusted or public network.', 'Communication Protection', 'Communication Protection', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9610, 9, NULL, 23911)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025270, 'Con-2', 'Does the aircraft operator ensure the wireless network utilized for interfacing with crewmember''s PEDs and retrieving critical data relevant to flight operations is not be bridged or co-utilized by personnel (i.e., customers) not associated with the certificate holder, aircraft operations, or governance?', 'Create a logical network-based separation for PEDs to utilize for interfacing with aircraft avionics and systems that are essential to the operation of the aircraft.  The wireless network utilized for this access (from a PED) should not be broadcast, advertised, and available (or accessible) by unauthorized personnel (including customers).     The wireless network should support robust encryption and authentication for PEDs.    Most importantly, the wireless network utilized for interfacing with aircraft avionics and retrieving critical data relevant to flight operations should not be bridged or co-utilized by personnel (i.e., customers) not associated with the company, aircraft operations, or governance.     At a minimum, EAP-TLS (mutual certificate authentication) should be utilized for PED authentication to the wireless network.    In addition, at the application layer (for Layer 7 technologies – which may provide an interface to the aircraft avionics), the communications between the avionics and the PED should be verified and validated.  Certificates could be utilized to perform this function (if supported by the application and avionics network interface).    An example of such a risk would be if a PED is lost/stolen, or if someone has gained unauthorized access to the PED, in such a case, the trusted PED could be utilized to connect to the network and interface with the avionics (just as an authorized user could).', 'Communication Protection', 'Communication Protection', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9611, 9, NULL, 23912)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025271, 'Policy-1', 'Does the aircraft operator provide a means for airline personnel to report PED incidents, defined processes and allocated resources to handle and follow up on the incident and policies for incident reporting requirements?', 'The company needs processes defined, support individuals able to respond to an identified incident, and policies in place to both enforce incident reporting and enable flight crews and other personnel to detect and correct an incident.', 'Policies & Procedures General', 'Policies & Procedures General', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9612, 37, NULL, 23913)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025272, 'Policy-2', 'Does the aircraft operator have detailed processes and procedures for enforcing service termination and remote wipe capabilities (for lost and stolen devices).', 'Formalized processes relevant to reporting (notification) and handling for lost/stolen PEDs are important for ensuring the integrity of data resident on devices that interface directly with aircraft avionics, store important data pertinent to operations, or are used for in-flight situational awareness.', 'Policies & Procedures General', 'Policies & Procedures General', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9613, 37, NULL, 23914)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025273, 'Policy-3', 'When a crewmember retires, transfers to another airline, quits, or is terminated, is a policy in place that all company proprietary data is wiped from the PED that was being used by the individual?', 'When flight crew personnel transfer to another airline in a BYOD situation, is there company proprietary information that will need to be removed from the device?  If so, that information should be kept in a container or sandbox maintained by the MDM system so it can be automatically wiped when employee terminates or transfers to a different airline.', 'Policies & Procedures General', 'Policies & Procedures General', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9614, 37, NULL, 23915)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025274, 'Policy-4', 'If PEDs are allowed to connect to the corporate network, do they meet the same connection policies as hardwired devices (e.g., anti-virus software, etc.)?', 'When PEDs are docked or wirelessly connected to the corporate network, they become an extension of the corporate network and should be held to the same security standards.', 'Policies & Procedures General', 'Policies & Procedures General', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9615, 37, NULL, 23916)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025275, 'Policy-5', 'Have PED IR ports been physically disabled or covered with metallic tape?', 'For mobile devices that travel through public areas, a simple piece of metallic tape prevents any kind of successful attack through the IR port.', 'Policies & Procedures General', 'Policies & Procedures General', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9616, 37, NULL, 23917)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025276, 'Policy-6', 'Are PEDs returning from temporary duty (TDY) checked or reimaged by trained network personnel before connection to the network?', 'In the case of loaner or hot-swappable PEDs, best practices are generally to either scan or entirely wipe and reimage the device to ensure the return to service state is known and any malware and/or proprietary information are removed.', 'Policies & Procedures General', 'Policies & Procedures General', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9617, 37, NULL, 23918)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025277, 'Policy-7', 'Is the anti-virus software updated each time the PED reconnects to the network?', 'Ideally, automated processes will detect the PED on the network, authenticate and authorize the device from the inventory and automatically initiate a virus scan.', 'Policies & Procedures General', 'Policies & Procedures General', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9618, 37, NULL, 23919)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025278, 'Policy-8', 'Can security patches be installed once the PED connects to the network?', 'Similar to the anti-virus process, automatic detection, authentication and authorization of a device when it connects to the network with an automated push of updates, helps ensure devices are maintained with the latest security patches.', 'Policies & Procedures General', 'Policies & Procedures General', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9619, 37, NULL, 23920)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025279, 'Policy-9', 'Is there a mechanism in place to ensure PED passwords meet official password policies?', 'This implies the need for an automated system to ensure password complexity and expiration polices are enforced on the device.  Because of the need to ensure policy enforcement on the device, there may need to be a policy in place requiring that PEDs be connected to the network for software and policy updates on a regular period basis (i.e., every 6 months) or the device is not permitted to connect to the network and access network data.', 'Policies & Procedures General', 'Policies & Procedures General', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9620, 37, NULL, 23921)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025280, 'Policy-10', 'Are PEDs and the information stored on those devices subject to random reviews and inspections?', 'Random inspections and a corresponding policy provide a precedent for and an expectation of inspections, and are an avenue for detecting devices that fail to install OS, application, and policy updates.', 'Policies & Procedures General', 'Policies & Procedures General', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9621, 37, NULL, 23922)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025281, 'DR-1', 'Since being granted operational approval by the FAA in accordance with OpSpec/MSpec/LOA A061 as applicable to use a PED as a portable EFB have you had to recover any of the PEDs?', '** Since being granted operational approval by the FAA  to use a PED as a portable EFB have you had to recover any of the PEDs?', 'Disaster Recovery', 'Disaster Recovery', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9625, 61, NULL, 23923)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025282, 'DR-2', 'Are records of PED failure and recovery incidents maintained to enable the company to determine common causes and recognizes anomalies?', 'A data collection system for common PED failures enables the company to identify common modes of failure and increase reliablity as well as identify potential compromise attempts.', 'Disaster Recovery', 'Disaster Recovery', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9626, 61, NULL, 23924)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025283, 'DR-3', 'If the PED becomes corrupted or inoperable, is there a mitigation procedure to recover the device?', 'Pilots and other users should be trained in how to factory reset the device if necessary, who to contact in the event of failure, and other mitigation processes.', 'Disaster Recovery', 'Disaster Recovery', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9627, 61, NULL, 23925)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025284, 'DR-4', 'If the PED becomes corrupted or inoperable in international space, are there mitigation procedures to recover the device?', 'Either at the international destinations or onboard each aircraft a backup device should be maintained with the ability to restore sufficent flight data to enable the operation of a device on the return flight.', 'Disaster Recovery', 'Disaster Recovery', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9628, 61, NULL, 23926)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025285, 'DR-5', 'Has a consequence analysis been performed for each onboard PED in the event of before flight or during flight failure of the device?', 'An analysis should be performed to consider the consequeces of device failure and potential recovery plans if needed.', 'Disaster Recovery', 'Disaster Recovery', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9629, 61, NULL, 23927)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025286, 'DR-6', 'If the PED fails are the consequences known and has recovery process been defined?', 'The recovery procedures should be known and crew members trained on those procedures.', 'Disaster Recovery', 'Disaster Recovery', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9630, 61, NULL, 23928)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025287, 'DR-7', 'Are PED backups created, maintained, and recovery tested?', 'The recovery procedures should be known and crew members trained on those procedures.', 'Disaster Recovery', 'Disaster Recovery', 10, NULL, 'SET.20210831.165809', NULL, NULL, 9631, 61, NULL, 23929)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025288, 'MDM-BYOD-1', 'Does the operator''s security architecture block unauthorized access to sensitive information by malicious or privacy-intrusive applications?', '<b>Test Activity: </b>Place mock sensitive enterprise contact list and calendar entries on devices, then attempt to install and use applications that access and back up those entries.<div><br><b>Desired Outcome: </b>The enterprise&#8217;s security architecture would either detect or prevent use of these<br>applications, or it would block the applications from accessing enterprise-controlled contact list and<br>calendar entries. The enterprise&#8217;s security architecture should identify presence of the applications and<br>the fact that they access contact and calendar entries. The security architecture should block these<br>applications from installing, block them from running, or detect their presence and cause another<br>appropriate response, such as blocking the mobile device from accessing enterprise resources until the<br>applications are removed.</div><div><br>Alternatively, built-in device mechanisms such as Apple&#8217;s managed applications functionality and<br>Google&#8217;s Android enterprise work profile functionality could be used to separate the contact and<br>calendar entries associated with enterprise email accounts so that they can only be accessed by<br>enterprise applications (applications that the enterprise mobility management (EMM) authorizes and<br>manages), not by applications manually installed by the user. The user should not be able to manually<br>provision their enterprise email account. Only the EMM should be able to provision the account,<br>enabling enterprise controls on the enterprise contact list and calendar data.</div><div><br></div><div><p class="MsoNormal"><br></p></div><div><br><div><br></div></div>', 'Mobile Device Management MDM', 'Bring Your Own Device (BYOD) ', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025289, 'MDM-BYOD-2', 'Does the operator’s security architecture block the user from browsing to known malicious websites? ', '<div><b>Test Activity:</b></div><div><ul><li>This threat event can be tested by establishing a web page with a form that impersonates an enterprise login prompt.</li><li>Then send the web page&#8217;s uniform resource locator (URL) via SMS or email and attempt to collect and use enterprise login credentials.</li></ul></div><div><b>Desired Outcome: </b>The enterprise&#8217;s security architecture should block the user from browsing to known malicious websites. Additionally, the enterprise should use multifactor authentication or phishing- resistant authentication methods such as those based on public key cryptography so that either there is no password for a malicious actor to capture or capturing the password is insufficient to obtain access to enterprise resources.</div><div><br></div><div><br></div>', 'Mobile Device Management MDM', 'Bring Your Own Device (BYOD) ', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025290, 'RKW-1', 'This is an access control requirement', NULL, 'Access Control', 'Access Control Decisions', NULL, NULL, 'SET.20210901.171358', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025291, 'MDM-BYOD-3', 'Does the operator use multi-factor authentication (MDA ) or phishing-resistant MFA methods so that either (1) there is no password for a malicious actor to capture or (2) capturing the password is insufficient to obtain access to enterprise resources?', '<div><b>Test Activity:</b></div><div><ul><li>This threat event can be tested by establishing a web page with a form that impersonates an enterprise login prompt.</li><li>Then send the web page&#8217;s uniform resource locator (URL) via SMS or email and attempt to collect and use enterprise login credentials.</li></ul></div><div><b>Desired Outcome: </b>The enterprise&#8217;s security architecture should block the user from browsing to known malicious websites. Additionally, the enterprise should use multifactor authentication or phishing- resistant authentication methods such as those based on public key cryptography so that either there is no password for a malicious actor to capture or capturing the password is insufficient to obtain access to enterprise resources.</div><div><br></div>', 'Mobile Device Management MDM', 'Access Control For Mobile Devices', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 79, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025292, 'MDM-BYOD-4', 'Does the operator detect and respond to the installation of unauthorized applications?', '<div>Testing to discover for unauthorized applications that are not present on the official Apple App Store or Google Play Store, that can be installed via URL links in SMS, email messages, or third-party websites.</div><div><b><br></b></div><div><b>Test Activity (Android):</b></div><div><ul><li>Send an email to the user with a message urging the user to click the link to install the application.</li><li>On the device, if not already enabled, attempt to enable the Unknown Sources toggle setting in the device security settings to allow installing applications from sources other than the Google Play Store.</li><li>On the device, read the received email, click the link, and attempt to install the application.</li><li>Observe whether the application could be successfully installed. If so, observe whether the enterprise detected and responded to installation of the unauthorized application.</li></ul></div><div><b>Test Activity (iOS):</b></div><div><ul><li><span>Send an email to the user with a message urging the user to click the link to install the application.</span></li><li>On the device, read the received email, click the link, and attempt to install the application</li></ul></div><div>The organization''s EMM and MTD should alert both the user and admin about the presence of a side-loaded application, for example, by sending an email notification to the user and administrator about the presence of side-loaded applications and required actions.</div><div><br></div>', 'Mobile Device Management MDM', 'Access Control For Mobile Devices', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 79, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025293, 'MDM-BYOD-5', 'Does the operator’s security architecture identify the presence of devices running an outdated version of iOS or Android and block them from accessing enterprise resources until system updates are installed?', '<div><b>Summary: </b>Confidentiality and integrity loss due to exploitation of known vulnerability in the operating system or firmware.</div><div><br></div><div><b>Test Activity: </b>Attempt to access enterprise resources from a mobile device with known vulnerabilities (e.g., running an older, unpatched version of iOS or Android).</div><div><br></div><div><b>Desired Outcome: </b>The enterprise&#8217;s security architecture should identify the presence of devices that are running an outdated version of iOS or Android susceptible to known vulnerabilities. It should be possible, when warranted by the risks, to block devices from accessing enterprise resources until system updates are installed.</div><div><br></div><div>The organization''s EMM/MTD should identify devices running an outdated version of iOS or Android, and inform a user when a device is out of compliance.</div><div><br></div><div><br></div>', 'Mobile Device Management MDM', 'Access Control For Mobile Devices', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 79, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025294, 'MDM-BYOD-6', 'Does the operator conduct application vetting (testing) on applications that collect or access location, camera, and microphone data to determine (1) the intent of the use of such data and (2) whether the application is malicious?', '<div>The threat: the collection of location, camera, or microphone data by an application that has no need to access this data.</div><div><br></div><div>Note: Not all applications that have access to location, camera, or microphone data are malicious. However, when applications are found collecting this information, additional vetting or testing may be required to determine the intent of its use and then to determine if the application is malicious.</div>', 'Mobile Device Management MDM', 'Access Control For Mobile Devices', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 79, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025295, 'MDM-BYOD-7', 'Does the operator''s security architecture detect applications that attempt to establish a hypertext transfer protocol or unencrypted connection?', '<div>Test if applications will attempt to establish a hypertext transfer protocol or unencrypted connection.</div><div><br></div><div><b>Desired Outcome:</b></div><div><ul><li>Android: Because all work applications are inside a work container, a container-wide virtual private network (VPN) policy can be applied to mitigate this threat event; all communications, both encrypted and unencrypted, will be sent through the VPN tunnel. This will prevent eavesdropping on any communication originating from a work application.</li><li>iOS: Apply a per-application VPN policy that will send all data transmitted by managed applications through the VPN tunnel. This will prevent eavesdropping on any unencrypted communication originating from work applications.</li><li>An organization''s MTD should identify if an application attempts to establish an unencrypted connection.</li></ul></div><div>An MTD report should indicate if an application did not use in-transit data encryption to prevent the<span>&#160;loss of confidentiality of sensitive information via eavesdropping on unencrypted device communications.&#160;</span></div>', 'Mobile Device Management MDM', 'Access Control For Mobile Devices', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 79, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025296, 'MDM-BYOD-8', 'Does the operator''s enterprise mobility management (EMM) enforce policies that require a device unlock code to be set, prevent the device unlock code from being removed, require a minimum complexity for the device unlock code, and factory reset the device after 10 failed unlock attempts?', '<p class="MsoBodyText">Threat: compromise of device integrity via observed, inferred, or brute-forced device unlock code.</p><p class="MsoBodyText"><br></p><p class="MsoBodyText">Test Activity:</p><p class="MsoBodyText"></p><ul><li><span>Attempt to completely remove the device unlock code. Observe whether the attempt succeeds.</span></li><li>Attempt to set the device unlock code to &#8220;1234,&#8221; a weak four-digit personal identification number (PIN). Observe whether the attempt succeeds.</li><li>Attempt to continually unlock the device, confirming that the device is factory reset after 10 failed attempts.</li></ul><p></p><p class="MsoBodyText">Policies set on the device by the EMM should require a device unlock code to be set, prevent the device unlock code from being removed, require a minimum complexity for the device unlock code, and factory resetting the device after 10 failed unlock attempts.</p><p class="MsoBodyText"><br></p><p class="MsoBodyText">Additionally, EMM should have the capability to identify and report devices with a disabled lock screen.</p>', 'Mobile Device Management MDM', 'Access Control For Mobile Devices', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 79, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025297, 'MDM-BYOD-9', 'Does the operator''s EMM or MDM system have the capability to identify and report devices with a disabled lock screen?', '<div>Threat: compromise of device integrity via observed, inferred, or brute-forced device unlock code.</div><div><br></div><div><b>Test Activity:</b></div><div>&#8226;<span>&#9;</span>Attempt to completely remove the device unlock code. Observe whether the attempt succeeds.</div><div>&#8226;<span>&#9;</span>Attempt to set the device unlock code to &#8220;1234,&#8221; a weak four-digit personal identification number (PIN). Observe whether the attempt succeeds.</div><div>&#8226;<span>&#9;</span>Attempt to continually unlock the device, confirming that the device is factory reset after 10 failed attempts.</div><div>Policies set on the device by the EMM should require a device unlock code to be set, prevent the device unlock code from being removed, require a minimum complexity for the device unlock code, and factory resetting the device after 10 failed unlock attempts.</div><div><br></div><div>Additionally, EMM should have the capability to identify and report devices with a disabled lock screen.</div>', 'Mobile Device Management MDM', 'Access Control For Mobile Devices', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 79, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025298, 'MDM-BYOD-10', 'Does the operator''s EMM or MDM discover and report credential weaknesses in cases of unauthorized access to backend services via authentication or credential storage vulnerabilities in internally developed applications?', '<div><b>Threat: </b>Unauthorized access to backend services via authentication or credential storage vulnerabilities in internally developed applications.</div><div><br></div><div><b>Test Activity:</b> Analyze application for credential weaknesses.</div><div><b><br></b></div><div><b>Desired Outcome: </b>Discover and report credential weaknesses.&#160;<span>An application&#8217;s use of hardcoded credentials could introduce vulnerabilities if unauthorized entities used the hardcoded credentials to access enterprise resources.</span></div><div><br></div>', 'Mobile Device Management MDM', 'Access Control For Mobile Devices', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 79, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025299, 'MDM-BYOD-11', 'Does the operator block unauthorized access of enterprise resources from unmanaged and potentially compromised devices?', '<p class="MsoBodyText">Threat: Unauthorized access of enterprise resources from an unmanaged and potentially compromised device.</p><p class="MsoBodyText"><br></p><p class="MsoBodyText">Test Activity: Attempt to directly access enterprise services, e.g., Exchange email server or corporate VPN, on a mobile device that is not enrolled in the EMM system.</p><p class="MsoBodyText"><br></p><p class="MsoBodyText">Desired Outcome: Enterprise services should not be accessible from devices that are not enrolled in the EMM system. Otherwise, the enterprise is not able to effectively manage devices to prevent threats.</p><p class="MsoBodyText"><br></p><p class="MsoBodyText">Devices that are not enrolled in an EMM system should be unable to access enterprise resources. These devices should be prevented from authenticating without proper client certificates&#8212;obtainable only through enrolling in the EMM.</p>', 'Mobile Device Management MDM', 'Access Control For Mobile Devices', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 79, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025300, 'MDM-BYOD-12', 'Is the operator''s EMM or MDM system capable of locating or wiping EMM/MDM-enrolled devices in response to a report that they have been lost or stolen?', '<div><b>Threat: </b>Loss of organizational data due to a lost or stolen device.</div><div><br></div><div><b>Test Activity: </b>Attempt to download enterprise data onto a mobile device that is not enrolled in the EMM system. Attempt to remove the screen lock passcode or demonstrate that the device does not have a screen lock passcode in place. Attempt to locate and selectively wipe the device through the EMM console (will fail if the device is not enrolled in the EMM).</div><div><br></div><div><b>Desired Outcome:</b> It should be possible to locate or wipe EMM enrolled devices in response to a report that they have been lost or stolen. Only EMM enrolled devices should be able to access enterprise resources. EMM-enrolled devices can be forced to have a screen lock with a passcode of appropriate strength, which helps resist exploitation (including loss of organizational data) if the device has been lost or stolen.</div><div><br></div><div><b>Enrolled Devices: </b>After 10 attempts to access the device, a device should be selectively wiped, removing all enterprise data. Additionally, the device should be remotely wiped after it was reported as lost to enterprise mobile device service management, ensuring no corporate data is left in the hands of attackers.</div><div><br></div><div><div><b>Unenrolled Devices:</b> Only enrolled devices should have access to enterprise services. When an unenrolled device attempts to access enterprise data, no connection to the enterprise services should be available. Because the device cannot access the enterprise, the device would not contain enterprise information.</div><div><br></div><div>In both outcomes, both enrolled and unenrolled, it would be at the user&#8217;s discretion if they wanted to wipe all personal data as well. Because this is a Bring Your Own Device (BYOD) scenario, only corporate data (managed applications on iOS, and the work container on Android) would be deleted from a device if the device were lost or stolen.</div></div>', 'Mobile Device Management MDM', 'Access Control For Mobile Devices', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 79, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025301, 'MDM-BYOD-13', 'Does the operator''s EMM or MDM system prohibit screenshots and other data-sharing actions while using managed applications?', '<div><b>Threat: </b>Loss of confidentiality of organizational data due to its unauthorized storage in non-organizationally managed services.</div><div><br></div><div><b>Test Activity:</b> Connect to the enterprise VPN. Open an enterprise website or application. Attempt to extract enterprise data by taking a screenshot, or copy/paste and send it via an unmanaged email account.</div><div><b><br></b></div><div><b>Desired Outcome:</b> The EMM will prohibit screenshots and other data-sharing actions while using managed applications.</div><div>Through EMM device policies, an administrator could prevent the following actions on BYODs:</div><div><br></div><div>Android</div><div><ul><li>clipboard sharing</li><li>screen capture</li><li>share list</li><li>backup to Google</li><li>Secure Digital card write</li><li>Universal Serial Bus storage</li><li>video recording</li><li>Bluetooth</li><li>background data sync</li><li>Android Beam</li><li>Sbeam</li></ul></div><div>iOS</div><div><ul><li>opening, writing, and saving from managed to unmanaged applications</li><li>AirDrop for managed applications</li><li>screen capture</li><li>AirPlay</li><li>iCloud backup</li><li>document, photo stream, and application sync</li><li>print</li><li>importing files</li></ul></div><div><br></div>', 'Mobile Device Management MDM', 'Access Control For Mobile Devices', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 79, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025302, 'MDM-BYOD-14', 'Does the operator''s EMM or MDM system prevent unauthorized access to work applications via a bypassed lock screen?', '<p class="MsoBodyText"><b>Threat: </b>Unauthorized access to work applications via bypassed lock screen (e.g., sharing the device&#8217;s PIN with family members).</p><p class="MsoBodyText"><br></p><p class="MsoBodyText"><b>Test Activity:</b> Assume the user is an unauthorized person attempting to access enterprise resources. Unlock the device and attempt to open a work application.</p><p class="MsoBodyText"><br></p><p class="MsoBodyText"><b>Desired Outcome: </b>The user will be prompted to log in to the VPN using their corporate username and password. Because the user does not know this password, they are unable to log in and access corporate resources. However, if the user attempts to access a work application within the idle log-out time, they will be granted access because no password will be requested.</p>', 'Mobile Device Management MDM', 'Access Control For Mobile Devices', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 79, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025303, 'MDM-BYOD-P-1', 'Does the EMM and/or MDM prevent the following: (1) the collection/inventory of applications on the device; (2) location information, including physical address, geographic coordinates and history, IP address, and SSID?', '<div><div><b>Issue: </b>Collection of application and location data is restricted.</div><div><br></div><div><b>Test Activity: </b>Disable location and application inventory collection in MDM system.</div><div><br></div><div><b>Desired Outcome: </b>The MDM system does not collect an inventory of applications on the device and does not collect location information, including physical address, geographic coordinates and history, internet protocol (IP) address, and secure set identifier (SSID).&#160;<span>When inspecting a device, location and application inventory information are not shown to the user, and application inventory information is not transmitted to EMM.</span></div></div>', 'Mobile Device Management MDM', 'Privacy Impact and Risk Assessment', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 54, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025304, 'MDM-BYOD-P-2', 'Is access to MDM monitoring data restricted to administrators, such that the system provides access controls to monitoring functions and logs, and data flow between the operator and third parties does not contain location information such as physical address, geographic coordinates and history, IP address, and SSID?', '<p class="MsoBodyText"><b>Issue: </b>Access to monitoring data from the device should be restricted to administrators. Application and location data should not be shared with third parties that support monitoring, data analytics, and other functions for operating the BYOD solution.</p><p class="MsoBodyText"><br></p><p class="MsoBodyText"><b>Test Activity: </b>Attempt to log in to the MDM admin portal without domain administrator permissions.</p><p class="MsoBodyText"><br></p><p class="MsoBodyText">&#160;<b>Desired Outcome: </b><span>System provides access controls to monitoring functions and logs. Data flow between the organization and third parties does not contain location information, including physical address, geographic coordinates and history, IP address, and SSID.</span><span>&#160;</span></p><p class="MsoBodyText"><br></p>', 'Mobile Device Management MDM', 'Privacy Impact and Risk Assessment', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 79, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025305, 'MDM-BYOD-P-3', 'Does the operator''s EMM or MDM system allow the selective wiping of the device, such that the user retains personal data/applications while the corporate applications and data are removed?', '<div><b>Issue:</b> The user should retain personal data and applications while access to corporate applications and data is removed.</div><div><b>Action:</b></div><div><ul><li>Block staff access to enterprise resources by removing the device from MDM control instead of wiping the device.&#160;</li><li>Enable only selectively wiping corporate resources on the device.&#160;</li><li>Restrict staff access to system capabilities that permit removing device access or performing wipes.</li></ul></div><div><b>Test Activity: </b>Selectively wipe a device using MDM.</div><div><br></div><div><b>Desired Outcome: </b>The user will no longer be able to access work applications and data on the device and retains all access to their personal applications and data.&#160;<span>Corporate data and applications are removed while personal data is untouched.</span></div><div><br></div>', 'Mobile Device Management MDM', 'Privacy Impact and Risk Assessment', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 79, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025306, 'BYOD-1', 'Testing whether I can add BYOD as my new subcategory', NULL, 'Boundary Protection', 'BYOD', NULL, NULL, 'SET.20210901.171358', NULL, NULL, NULL, 61, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025307, '5.2.8', 'Determination of pipeline critical facilities:

Operators may consider their ability to continue operations (e.g., product free flow or alternate or redundant prime-mover capacity) as an adequate facility backup as long as they demonstrate no impact to deliverability.', NULL, 'Criticality', 'Facility Criticality', NULL, NULL, 'TSA2018', NULL, NULL, NULL, 59, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025308, '5.2.9', 'Determination of pipeline critical facilities:

TSA, in consultation with pipeline operators, may designate specific pipeline facilities as critical in accordance with this guidance.', NULL, 'Criticality', 'Facility Criticality', NULL, NULL, 'TSA2018', NULL, NULL, NULL, 59, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025309, '5.2.10', 'Determination of pipeline critical facilities:

Operators may set more stringent criteria and designate facilities as critical in addition to those meeting the guidance below.', NULL, 'Criticality', 'Facility Criticality', NULL, NULL, 'TSA2018', NULL, NULL, NULL, 59, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025310, '5.2.11', 'A pipeline facility is defined as new and existing pipelines, rights of way, and any equipment, facility, or building used in the transportation of gas or hazardous liquids or in the treatment of gas or hazardous liquids during the course of transportation. Critical facilities may include, but are
not limited to:
• pipeline interconnections
• metering and/or regulating stations
• pump stations
• compressor stations
• operational control facilities
• main line valves
• tank farms, terminals', NULL, 'Criticality', 'Facility Criticality', NULL, NULL, 'TSA2018', NULL, NULL, NULL, 59, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025311, '5.2.12', 'If damage or destruction of a facility has the potential to meet at least one of the following criteria, the facility or facilities should be designated as critical:
Disrupt or significantly reduce required service or deliverability to installations identified as critical to national defense.', '                  <table cellspacing="0">&#10;                  <tbody><tr>&#10;                    <td bgcolor="#D9D9D9">&#10;                      <p class="s16">&#10;                        Criteria&#10;                      </p>&#10;                    </td>&#10;                    <td bgcolor="#D9D9D9">&#10;                      <p class="s16">&#10;                        Subsector&#10;                      </p>&#10;                    </td>&#10;                    <td bgcolor="#D9D9D9">&#10;                      <p class="s16">&#10;                        Guidance&#10;                      </p>&#10;                    </td>&#10;                  </tr>&#10;                  <tr>&#10;                    <td bgcolor="#FFE499">&#10;                      <p class="s17">&#10;                        1. Disrupt or significantly reduce required service or deliverability to installations identified as critical to national defense.&#10;                      </p>&#10;                    </td>&#10;                    <td rowspan="6">&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s18">&#10;                        TSA will notify pipeline operators who directly serve installations or defense industrial base (DIB) manufacturers deemed critical to national defense and who rely on the pipeline commodity to perform a critical mission at that location.&#10;                      </p>&#10;                    </td>&#10;                  </tr>&#10;                  <tr>&#10;                    <td bgcolor="#FFE499">&#10;                      &#10;                    </td>&#10;                    <td>&#10;                    &#10;                    </td>&#10;                  </tr>&#10;                  <tr>&#10;                    <td bgcolor="#FFE499">&#10;                     &#10;                    </td>&#10;                    <td>&#10;                     &#10;                    </td>&#10;                  </tr>&#10;                  <tr>&#10;                    <td bgcolor="#FFE499">&#10;                     &#10;                    </td>&#10;                    <td>&#10;                      &#10;                    </td>&#10;                  </tr>&#10;                  <tr>&#10;                    <td bgcolor="#FFE499">&#10;                      &#10;                    </td>&#10;                    <td>&#10;                     &#10;                    </td>&#10;                  </tr>&#10;                  <tr>&#10;                    <td rowspan="2" bgcolor="#FFE499">&#10;                      &#10;                    </td>&#10;                    <td>&#10;                      <p><br></p>&#10;                    </td>&#10;                  </tr>&#10;                  <tr>&#10;                    <td>&#10;                      <p class="s19">&#10;                        Natural Gas Distribution&#10;                      </p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s19">&#10;                        Natural gas distribution operators should designate as critical those facilities that must function to provide service to critical defense installations or DIB manufacturers with a firm contract.&#10;                      </p>&#10;                    </td>&#10;                  </tr>&#10;                  <tr>&#10;                    <td bgcolor="#FFE499">&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                      &#10;                    </td>&#10;                  </tr>&#10;                  <tr>&#10;                    <td bgcolor="#FFE499">&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                      &#10;                    </td>&#10;                  </tr>&#10;                  <tr>&#10;                    <td bgcolor="#FFE499">&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                      &#10;                    </td>&#10;                  </tr>&#10;                  <tr>&#10;                    <td bgcolor="#FFE499">&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s20">&#10;                        Natural Gas Transmission&#10;                      </p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s20">&#10;                        Natural gas transmission operators should designate as critical those facilities that must function to provide service to critical defense installations or DIB manufacturers with a firm contract.&#10;                      </p>&#10;                    </td>&#10;                  </tr>&#10;                  <tr>&#10;                    <td bgcolor="#FFE499">&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                      &#10;                    </td>&#10;                  </tr>&#10;                  <tr>&#10;                    <td bgcolor="#FFE499">&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                     &#10;                    </td>&#10;                  </tr>&#10;                  <tr>&#10;                    <td bgcolor="#FFE499">&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                     &#10;                    </td>&#10;                  </tr>&#10;                  <tr>&#10;                    <td bgcolor="#FFE499">&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                     &#10;                    </td>&#10;                  </tr>&#10;                  <tr>&#10;                    <td bgcolor="#FFE499">&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s21">&#10;                        Hazardous Liquid&#10;                      </p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s21">&#10;                        Hazardous liquid transmission operators should designate as critical those facilities that must function to provide service to critical defense installations or DIB manufacturers.&#10;                      </p>&#10;                    </td>&#10;                  </tr>&#10;                  <tr>&#10;                    <td bgcolor="#FFE499">&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s21">&#10;                        Transmission&#10;                      </p>&#10;                    </td>&#10;                    <td>&#10;                     &#10;                    </td>&#10;                  </tr>&#10;                  <tr>&#10;                    <td bgcolor="#FFE499">&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                      &#10;                    </td>&#10;                  </tr>&#10;                  <tr>&#10;                    <td bgcolor="#FFE499">&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                     &#10;                    </td>&#10;                  </tr>&#10;                  </tbody></table>&#10;', 'Criticality', 'Facility Criticality', NULL, NULL, 'TSA2018', NULL, NULL, NULL, 59, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025312, '5.2.13', 'If damage or destruction of a facility has the potential to meet at least one of the following criteria, the facility or facilities should be designated as critical:
Disrupt or significantly reduce required service or deliverability to key infrastructure (such as power plants or major airports) resulting in major
operational disruption.', '                        <table cellspacing="0">&#10;                  <tbody><tr>&#10;                    <td bgcolor="#D9D9D9">&#10;                      <p class="s16">&#10;                        Criteria&#10;                      </p>&#10;                    </td>&#10;                    <td bgcolor="#D9D9D9">&#10;                      <p class="s16">&#10;                        Subsector&#10;                      </p>&#10;                    </td>&#10;                    <td bgcolor="#D9D9D9">&#10;                      <p class="s16">&#10;                        Guidance&#10;                      </p>&#10;                    </td>&#10;                  </tr>&#10;                  <tr>&#10;                    <td bgcolor="#C5DFB3">&#10;                      <p class="s17">&#10;                        2. Disrupt or significantly reduce required service or&#10;                        deliverability to key infrastructure (such as power&#10;                        plants or major airports) resulting in major operational&#10;                        disruption.&#10;                      </p>&#10;                    </td>&#10;                    <td>&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s18">&#10;                        TSA will notify pipeline operators of key infrastructure they serve (e.g., &#8220;black start&#8221; electric power generation plants, Category X airports and service to the Strategic Petroleum Reserve).&#10;                      </p>&#10;                     &#10;                    </td>&#10;                  </tr>&#10;                   <tr>&#10;                    <td bgcolor="#C5DFB3">&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s20">&#10;                        Natural Gas Distribution&#10;                      </p>&#10;                    </td>&#10;                     &#10;                    <td>&#10;                      <p class="s22">&#10;                        Service to Natural Gas-Fired Power Generation Plants&#10;                      </p>&#10;                      &#10;                      <p class="s19">&#10;                        Natural gas distribution operators should designate as&#10;                        critical those facilities that must function to provide&#10;                        service to power generation facilities that:<br>&#10;                        </p><ul><li>Directly serve as Defense Critical Electric Infrastructure as identified by Department of Energy (DOE) and with firm contract<br></li>&#10;                            <li>Receive natural gas in excess of 30,000 MMcf annually per a firm contract as listed on Energy Information Administration (EIA) Form 923 (Power Plant Operations Report (Annual)) <br></li>&#10;                            <li>Serve as a &#8220;black start&#8221; electric generation plant with firm contract </li> </ul>&#10;                      <p></p>&#10;                    </td>&#10;                  </tr>&#10;                  <tr>&#10;                    <td bgcolor="#C5DFB3">&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                  </td></tr>&#10;                  <tr>&#10;                    <td bgcolor="#C5DFB3">&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s20">&#10;                        Natural Gas Transmission&#10;                      </p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s23">&#10;                        Service to Natural Gas-Fired Power Generation<span class="s20">&#10;                        </span>Plants&#10;                      </p>&#10;                      <p class="s20">&#10;                        Natural gas transmission operators should designate as&#10;                        critical those facilities that must function to provide&#10;                        service to power generation facilities that:&#10;                          </p><ul><li>&#8226;Directly serve as Defense Critical ElectricInfrastructure as identified by DOE and withfirm contract</li>&#10;                        <li>Receive natural gas in excess of 30,000 MMcfannually per a firm contract as listed on EIAForm 923 (Power Plant Operations Report(Annual))</li>&#10;                        <li>Serve as a &#8220;black start&#8221; electric generationplant with firm contract</li></ul>&#10;                      <p></p>&#10;                    </td>&#10;                  </tr>&#10;              &#10;                  <tr>&#10;                    <td rowspan="2" bgcolor="#C5DFB3">&#10;                    &#10;                    </td>&#10;                    <td>&#10;                    &#10;                    </td>&#10;                    <td>&#10;                  </td></tr>&#10;                  <tr>&#10;                    <td>&#10;                      <p class="s21">&#10;                        Hazardous Liquid Transmission&#10;                      </p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s24">&#10;                        Service to Category X Airports &#160;&#10;                      </p>&#10;                      <p class="s21">&#10;                        Hazardous liquid transmission operators should designate&#10;                        as critical those facilities that must function to&#10;                        provide service to TSA designated Category X airports.&#10;                      </p>&#10;                    </td>&#10;                  </tr>&#10;                  <tr>&#10;                    <td bgcolor="#C5DFB3">&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s24">&#10;                        Service to the Strategic Petroleum Reserve<span class="s21">&#10;                        </span>(SPR)&#10;                      </p>&#10;                      <p class="s21">&#10;                        Hazardous liquid transmission operators should designate&#10;                        as critical those facilities that must function to&#10;                        provide service to or within the SPR sites.&#10;                      </p>&#10;                    </td>&#10;                  </tr>&#10;      </tbody></table>&#10;', 'Criticality', 'Facility Criticality', NULL, NULL, 'TSA2018', NULL, NULL, NULL, 59, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025313, '5.2.14', 'If damage or destruction of a facility has the potential to meet at least one of the following criteria, the facility or facilities should be designated as critical:
Cause mass injuries, casualties or significant health or environmental effects.', '<table>&#10;        &#10;                  <tbody><tr>&#10;                    <td bgcolor="#D9D9D9">&#10;                      <p class="s16">&#10;                        Criteria&#10;                      </p>&#10;                    </td>&#10;                    <td bgcolor="#D9D9D9">&#10;                      <p class="s16">&#10;                        Subsector&#10;                      </p>&#10;                    </td>&#10;                    <td bgcolor="#D9D9D9">&#10;                      <p class="s16">&#10;                        Guidance&#10;                      </p>&#10;                    </td></tr><tr>&#10;                    <td bgcolor="#BCD5ED">&#10;                      <p class="s17">&#10;                        3. Cause mass injuries, casualties or significant health&#10;                        or environmental effects.<span class="s25"></span>&#10;                      </p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s19">&#10;                        Natural Gas Distribution&#10;                      </p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s22">&#10;                        Operator-Generated Methodology&#10;                      </p>&#10;                      <p class="s19">&#10;                        In addition to guidance below, natural gas distribution&#10;                        operators should use their own methodology to designate&#10;                        additional critical facilities which may cause mass&#10;                        casualty or significant health effects. Operators should&#10;                        consider variation in service territory and facility&#10;                        siting, differences in regional weather extremes and&#10;                        distinctions among risk profiles.&#10;                      </p>&#10;                    </td>&#10;                  </tr>&#10;                  <tr>&#10;                    <td bgcolor="#BCD5ED">&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s22">&#10;                        Facilities Operating Near Occupied Buildings or<span class="s19">&#10;                        </span>Areas&#10;                      </p>&#10;                      <p class="s19">&#10;                        Natural gas operators should evaluate their facilities&#10;                        through their Distribution Integrity Management Program&#10;                        (DIMP)<span class="s26">3</span> or comparable risk&#10;                        methodology and designate as critical those facilities&#10;                        that:&#10;                      </p>&#10;                    </td>&#10;                  </tr>&#10;                  <tr>&#10;                    <td bgcolor="#BCD5ED">&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s19">&#10;                        (regardless of operating pressure) and do not have&#10;                        service regulators installed or redundant overpressure&#10;                        protection systems&#10;                      </p>&#10;                    </td>&#10;                  </tr>&#10;               &#10;                  <tr>&#10;                    <td bgcolor="#BCD5ED">&#10;                     &#10;                    </td>&#10;                    <td>&#10;                      &#10;                    </td>&#10;                    <td>&#10;                      <p class="s22">&#10;                        High Risk (Tiered) Facilities under DHS CFATS<span class="s19">&#10;                          Natural gas distribution operators should review and&#10;                          consider as critical all facilities designated as high&#10;                          risk under the DHS Chemical Facility Anti-Terrorism&#10;                          Standards (CFATS) program.</span>&#10;                      </p>&#10;                    </td>&#10;                  </tr>&#10;                  <tr>&#10;                    <td bgcolor="#BCD5ED">&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s20">&#10;                        Natural Gas Transmission&#10;                      </p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s23">&#10;                        Facilities Operating in HCAs&#10;                      </p>&#10;                      <p class="s20">&#10;                        Natural gas transmission operators should designate as&#10;                        critical all facilities operating in High Consequence&#10;                        Areas (HCAs) as defined in Dept. of Transportation (DOT)&#10;                        49 Code of Federal Regulations.<span class="s28">5</span>&#10;                        HCAs could include designated human health-safety,&#10;                        structure or human occupancy impact zones from a release&#10;                        of natural gas.&#10;                      </p>&#10;                    </td>&#10;                  </tr>&#10;                  <tr>&#10;                    <td bgcolor="#BCD5ED">&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s23">&#10;                        High Risk (Tiered) Facilities under DHS CFATS<span class="s20">&#10;                          Natural gas transmission operators should review and&#10;                          consider as critical all facilities designated as high&#10;                          risk under the DHS Chemical Facility Anti-Terrorism&#10;                          Standards (CFATS) program.</span>&#10;                      </p>&#10;                    </td>&#10;                  </tr>&#10;                  <tr>&#10;                    <td bgcolor="#BCD5ED">&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s21">&#10;                        Hazardous Liquid Transmission&#10;                      </p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s24">&#10;                        Facilities Operating in HCAs&#10;                      </p>&#10;                      <p class="s21">&#10;                        Hazardous liquid transmission operators should designate&#10;                        as critical all facilities operating in High Consequence&#10;                        Areas (HCAs) as defined in Dept. of Transportation (DOT)&#10;                        49 Code of Federal Regulations.<span class="s29">6</span>&#10;                        HCAs can include commercially navigable waterways, high&#10;                        population areas, other populated areas, or unusually&#10;                        sensitive areas.&#10;                      </p>&#10;                    </td>&#10;                  </tr>&#10;                  <tr>&#10;                    <td bgcolor="#BCD5ED">&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s24">&#10;                        High Risk (Tiered) Facilities under DHS CFATS<span class="s21">&#10;                          Hazardous liquid transmission operators should review&#10;                          and consider as critical all facilities designated as&#10;                          high risk under the DHS Chemical Facility&#10;                          Anti-Terrorism Standards (CFATS) program.</span>&#10;                      </p>&#10;                    </td>&#10;                  </tr>&#10;  </tbody></table>&#10;&#10;', 'Criticality', 'Facility Criticality', NULL, NULL, 'TSA2018', NULL, NULL, NULL, 59, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025314, '5.2.15', 'If damage or destruction of a facility has the potential to meet at least one of the following criteria, the facility or facilities should be designated as critical:
Disrupt or significantly reduce required service or deliverability resulting in a state or local government''s inability to provide essential public services and emergency response for an extended period of time.', '  &#10;&#10;&#10;                <table cellspacing="0">&#10;                     <tbody><tr>&#10;                    <td bgcolor="#D9D9D9">&#10;                      <p class="s16">&#10;                        Criteria&#10;                      </p>&#10;                    </td>&#10;                    <td bgcolor="#D9D9D9">&#10;                      <p class="s16">&#10;                        Subsector&#10;                      </p>&#10;                    </td>&#10;                    <td bgcolor="#D9D9D9">&#10;                      <p class="s16">&#10;                        Guidance&#10;                      </p>&#10;                    </td>&#10;                  </tr>&#10;          <tr>&#10;                    <td bgcolor="#DFC8EE">&#10;                      <p class="s17">&#10;                        4. Disrupt or significantly reduce required service or&#10;                        deliverability resulting in a state or local&#10;                        government''s inability to provide essential public&#10;                        services and emergency response for an extended period of time.&#10;                      </p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s19">&#10;                        Natural Gas Distribution&#10;                      </p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s19">&#10;                        Natural gas distribution operators should designate as&#10;                        critical those facilities that directly support&#10;                        essential public services and emergency response and&#10;                        which rely on natural gas to perform their critical&#10;                        mission.&#10;                      </p>&#10;                      <p class="s19">&#10;                        Consideration should be given to:&#10;                      </p>&#10;                      <p class="s19">&#10;                        function as a state&#8217;s primary government facility,&#10;                        including executive, legislative and judicial complexes&#10;                      </p>&#10;                    </td>&#10;                  </tr>&#10;                &#10;&#10;                  <tr>&#10;                    <td rowspan="3" bgcolor="#DFC8EE">&#10;                      &#10;                    </td>&#10;                    <td>&#10;                      &#10;                    </td>&#10;                    <td>&#10;                      <p class="s19">&#10;                        Operators should coordinate with the appropriate state&#10;                        office (e.g., State Office of Emergency Management) to&#10;                        identify essential public service and emergency response&#10;                        facilities. In the case that state offices are&#10;                        nonresponsive to operator requests, TSA will work with&#10;                        DHS to facilitate this coordination.&#10;                      </p>&#10;                      <p class="s19">&#10;                        For this criterion, an extended period of time is&#10;                        defined as the inability to provide essential public&#10;                        services and emergency response for seven or more&#10;                        consecutive days due to a disruption of natural gas&#10;                        distribution service.&#10;                      </p>&#10;                    </td>&#10;                  </tr>&#10;                  <tr>&#10;                    <td>&#10;                      <p class="s20">&#10;                        Natural Gas Transmission&#10;                      </p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s20">&#10;                        Not applicable&#10;                      </p>&#10;                    </td>&#10;                  </tr>&#10;                  <tr>&#10;                    <td>&#10;                      <p class="s21">&#10;                        Hazardous Liquid Transmission&#10;                      </p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s21">&#10;                        Hazardous liquid transmission operators should designate&#10;                        as critical those facilities that directly support&#10;                        essential public services and emergency response and&#10;                        which rely on hazardous liquids to perform their&#10;                        critical mission.&#10;                      </p>&#10;                      <p class="s21">&#10;                        Consideration should be given to:&#10;                      </p>&#10;                      <p class="s21">&#10;                        function as a state&#8217;s primary government facility,&#10;                        including executive, legislative and judicial complexes&#10;                      </p>&#10;                      <p class="s21">&#10;                        Operators should coordinate with the appropriate state&#10;                        office (e.g., State Office of Emergency Management) to&#10;                        identify essential public service and emergency response&#10;                        facilities. In the case that state offices are&#10;                        nonresponsive to operator requests, TSA will work with&#10;                        DHS to facilitate this coordination. For this criterion,&#10;                        an extended period of time is defined as the inability&#10;                        to provide essential public services and emergency&#10;                        response for seven or more consecutive days due to a&#10;                        disruption of hazardous liquid transmission service.&#10;                      </p>&#10;                    </td>&#10;                  </tr>&#10;                </tbody></table>&#10;', 'Criticality', 'Facility Criticality', NULL, NULL, 'TSA2018', NULL, NULL, NULL, 59, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025315, '5.2.16', 'If damage or destruction of a facility has the potential to meet at least one of the following criteria, the facility or facilities should be designated as critical:
Disrupt or significantly reduce the intended usage of major rivers, lakes, or waterways (for example, public drinking water for large populations or
disruption of major commerce or public transportation routes).', '                <table cellspacing="0">&#10;                  <tbody><tr>&#10;                    <td bgcolor="#D9D9D9">&#10;                      <p class="s16">&#10;                        Criteria&#10;                      </p>&#10;                    </td>&#10;                    <td bgcolor="#D9D9D9">&#10;                      <p class="s16">&#10;                        Subsector&#10;                      </p>&#10;                    </td>&#10;                    <td bgcolor="#D9D9D9">&#10;                      <p class="s16">&#10;                        Guidance&#10;                      </p>&#10;                    </td>&#10;                  </tr>&#10;                  <tr>&#10;                    <td rowspan="3" bgcolor="#FFB3B3">&#10;                      <p class="s17">&#10;                        5. Disrupt or significantly reduce the intended usage of&#10;                        major rivers, lakes, or waterways (for example, public&#10;                        drinking water for large populations or disruption of&#10;                        major commerce or public transportation routes).&#10;                      </p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s19">&#10;                        Natural Gas Distribution&#10;                      </p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s19">&#10;                        Not applicable&#10;                      </p>&#10;                    </td>&#10;                  </tr>&#10;                  <tr>&#10;                    <td>&#10;                      <p class="s20">&#10;                        Natural Gas Transmission&#10;                      </p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s20">&#10;                        Not applicable&#10;                      </p>&#10;                    </td>&#10;                  </tr>&#10;                  <tr>&#10;                    <td>&#10;                      <p class="s21">&#10;                        Hazardous Liquid Transmission&#10;                      </p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s21">&#10;                        Hazardous liquid transmission operators should designate&#10;                        as critical all pipeline facilities that could&#10;                        significantly impact public drinking water sources if&#10;                        state or local advisories are issued.&#10;                      </p>&#10;                      <p class="s21">&#10;                        Hazardous liquid transmission operators should designate&#10;                        as critical all pipeline facilities subject to Oil&#10;                        Pipeline Response Plans<span class="s29">9</span>&#10;                        impacting a PHMSA-defined Major River-High Volume Area&#10;                        or Other Navigable Waters.<span class="s29">10</span>&#10;                      </p>&#10;                      <p class="s21">&#10;                        Hazardous liquid transmission operators are encouraged&#10;                        to consult with environmental/risk specialists with&#10;                        expertise in this area.&#10;                      </p>&#10;                    </td>&#10;                  </tr>&#10;</tbody></table>', 'Criticality', 'Facility Criticality', NULL, NULL, 'TSA2018', NULL, NULL, NULL, 59, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025316, '5.2.17', 'If damage or destruction of a facility has the potential to meet at least one of the following criteria, the facility or facilities should be designated as critical:
Disrupt or significantly reduce required service or deliverability to a significant number of customers or individuals for an extended period of time.', '<table>&#10;                  <tbody><tr>&#10;                       </tr><tr>&#10;                    <td bgcolor="#D9D9D9">&#10;                      <p class="s16">&#10;                        Criteria&#10;                      </p>&#10;                    </td>&#10;                    <td bgcolor="#D9D9D9">&#10;                      <p class="s16">&#10;                        Subsector&#10;                      </p>&#10;                    </td>&#10;                    <td bgcolor="#D9D9D9">&#10;                      <p class="s16">&#10;                        Guidance&#10;                      </p>&#10;                    </td>&#10;                  </tr>&#10;                    <tr><td rowspan="3" bgcolor="#6CD9FF">&#10;                        &#10;                      <p class="s17">&#10;                        6. Disrupt or significantly reduce required service or&#10;                        deliverability to a significant number of customers or&#10;                        individuals for an extended period of time.&#10;                      </p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s19">&#10;                        Natural Gas Distribution&#10;                      </p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s19">&#10;                        Natural gas distribution operators should designate as&#10;                        critical all facilities that if disrupted for more than&#10;                        seven consecutive days would experience reduced service&#10;                        or deliverability to 100,000 or more meters.&#10;                      </p>&#10;                    </td>&#10;                  </tr>&#10;                  <tr>&#10;                    <td>&#10;                      <p class="s20">&#10;                        Natural Gas Transmission&#10;                      </p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s20">&#10;                        Not applicable&#10;                      </p>&#10;                    </td>&#10;                  </tr>&#10;                  <tr>&#10;                    <td>&#10;                      <p class="s21">&#10;                        Hazardous Liquid Transmission&#10;                      </p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s21">&#10;                        Not applicable&#10;                      </p>&#10;                    </td>&#10;                  </tr>&#10;</tbody></table>', 'Criticality', 'Facility Criticality', NULL, NULL, 'TSA2018', NULL, NULL, NULL, 59, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025317, '5.2.18', 'If damage or destruction of a facility has the potential to meet at least one of the following criteria, the facility or facilities should be designated as critical:
Significantly disrupt pipeline system operations for an extended period of time.', '<table>&#10;             <tbody><tr>&#10;                    <td bgcolor="#D9D9D9">&#10;                      <p class="s16">&#10;                        Criteria&#10;                      </p>&#10;                    </td>&#10;                    <td bgcolor="#D9D9D9">&#10;                      <p class="s16">&#10;                        Subsector&#10;                      </p>&#10;                    </td>&#10;                    <td bgcolor="#D9D9D9">&#10;                      <p class="s16">&#10;                        Guidance&#10;                      </p>&#10;                    </td>&#10;                  </tr>      &#10;    <tr>&#10;&#10;&#10;                    <td bgcolor="#FFFFCC">&#10;                      <p class="s17">&#10;                        7. Significantly disrupt pipeline system operations for&#10;                        an extended period of time.&#10;                      </p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s19">&#10;                        Natural Gas Distribution&#10;                      </p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s19">&#10;                        Natural gas distribution operators should designate as&#10;                        critical all pipeline facilities where the loss or&#10;                        disruption of facility operations lasting more than&#10;                        seven days would significantly impact overall&#10;                        deliverability and system safety.&#10;                      </p>&#10;                      <p class="s19">&#10;                        Factors to consider in determining criticality of a&#10;                        facility include:&#10;                      </p>&#10;                      <p class="s19">&#10;                        Natural gas distribution operators should identify as&#10;                        critical operational control rooms without a hot site&#10;                        backup (i.e., a backup control room that is continuously&#10;                        running and where all hardware and software are run&#10;                        concurrently with the primary site).&#10;                      </p>&#10;                    </td>&#10;                  </tr>&#10;               &#10;                  &#10;                &#10;                  <tr>&#10;                    <td bgcolor="#FFFFCC">&#10;                      &#10;                    </td>&#10;                    <td>&#10;                      <p class="s20">&#10;                        Natural Gas Transmission&#10;                      </p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s20">&#10;                        Natural gas transmission operators should designate as&#10;                        critical all pipeline facilities where the loss or&#10;                        disruption of facility operations lasting more than 14&#10;                        days would significantly impact overall deliverability&#10;                        and system safety.&#10;                      </p>&#10;                      <p class="s20">&#10;                        Factors to consider in determining criticality of a&#10;                        facility include:&#10;                      </p>&#10;                    </td>&#10;                  </tr>&#10;                  <tr>&#10;                    <td bgcolor="#FFFFCC">&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s20">&#10;                        Natural gas transmission operators should identify as&#10;                        critical operational control rooms without a hot site&#10;                        backup (i.e., a backup control room that is continuously&#10;                        running and where all hardware and software are run&#10;                        concurrently with the primary site).&#10;                      </p>&#10;                    </td>&#10;                  </tr>&#10;                  <tr>&#10;                    <td bgcolor="#FFFFCC">&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s21">&#10;                        Hazardous Liquid Transmission&#10;                      </p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s21">&#10;                        Hazardous liquid transmission operators should designate&#10;                        as critical all pipeline facilities where the loss or&#10;                        disruption of facility operations lasting more than&#10;                        seven days would significantly impact overall&#10;                        deliverability and system safety.&#10;                      </p>&#10;                    </td>&#10;                  </tr>&#10;                  <tr>&#10;                    <td bgcolor="#FFFFCC">&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s21">&#10;                        Factors to consider in determining criticality of a&#10;                        facility include:&#10;                      </p>&#10;                    </td>&#10;                  </tr>&#10;                  <tr>&#10;                    <td bgcolor="#FFFFCC">&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                      <p><br></p>&#10;                    </td>&#10;                    <td>&#10;                      <p class="s21">&#10;                        Hazardous liquid transmission operators should identify&#10;                        as critical operational control rooms without a hot site&#10;                        backup (i.e., a backup control room that continuously&#10;                        running and where all hardware and software are run&#10;                        concurrently with the primary site).&#10;                      </p>&#10;                    </td>&#10;                  </tr>&#10;                </tbody></table>', 'Critcality', 'Facility Criticality', NULL, NULL, 'TSA2018', NULL, NULL, NULL, 59, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025318, 'Hard-6', 'Does the commercial off-the-shelf PED have an ingress protection (IP) rating to ensure moisture/dust migration into cooling vents, fan ports and/or power/data connections and screen or battery boards and components?', NULL, 'Mobile Device Management MDM', 'System Hardening', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025321, 'PED-SM-1.3', 'Does the operator follow privileged access management principles for network-based administration of EO-critical software and EO-critical software platforms?', '<div>Examples of possible implementations include using hardened platforms dedicated to administration and verified before each use, requiring unique identification of each administrator, and proxying and logging all administrative sessions to EO-critical software platforms.</div><div><br></div><div><p class="p2">Examples of system account types include individual, shared, group, system, guest,&#10;anonymous, emergency, developer, temporary, and service. Identification of authorized system&#10;users and the specification of access privileges reflect the requirements in other controls in the&#10;security plan. Users requiring administrative privileges on system accounts receive additional&#10;scrutiny by organizational personnel responsible for approving such accounts and privileged&#10;access, including system owner, mission or business owner, senior agency information security&#10;officer, or senior agency official for privacy. Types of accounts that organizations may wish to&#10;prohibit due to increased risk include shared, group, emergency, anonymous, temporary, and&#10;guest accounts.<b><br></b></p><p class="p2"><b><br></b></p><p class="p2"><b>Definition of EO-Critical Software</b></p><p class="p1"><span>EO-critical software is defined as any software that has, or has direct software dependencies upon, one or more components with at least one of these attributes:</span></p><ul class="ul1"><li class="li2"><span class="s1"></span>is designed to run with elevated privilege or manage privileges;</li><li class="li2"><span class="s1"></span>has direct or privileged access to networking or computing resources;</li><li class="li2"><span class="s1"></span>is designed to control access to data or operational technology;</li><li class="li2"><span class="s1"></span>performs a function critical to trust; or,</li><li class="li2"><span class="s1"></span>operates outside of normal trust boundaries with privileged access.</li><li class="li2"><span class="s1"></span>The definition applies to software of all forms (e.g., standalone software, software integral to specific devices or hardware components, cloud-based software) purchased for, or deployed in, production systems and used for operational purposes. Other use cases, such as software solely used for research or testing that is not deployed in production systems, are outside of the scope of this definition.&#160;</li></ul><p class="p1"><span>https://www.nist.gov/itl/executive-order-improving-nations-cybersecurity/security-measures-eo-critical-software-use-2</span><br></p><p class="p2"><br></p></div>', 'Software', 'Account Management', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025322, 'PED-SM-1.2', 'Does the operator use multi-factor authentication that is verifier impersonation-resistant for all users and administrators of EO-critical software and EO-critical software platforms?', '<div><div>Organizations can satisfy the identification and authentication requirements by&#10;complying with the requirements in [HSPD 12]. Organizational users include employees or&#10;individuals who organizations consider to have an equivalent status to employees (e.g.,&#10;contractors and guest researchers). Unique identification and authentication of users applies to&#10;all accesses other than those that are explicitly identified in AC-14 and that occur through the&#10;authorized use of group authenticators without individual authentication. Since processes&#10;execute on behalf of groups and roles, organizations may require unique identification of&#10;individuals in group accounts or for detailed accountability of individual activity.&#160;</div><div><br></div><div>Organizations employ passwords, physical authenticators, or biometrics to authenticate user&#10;identities or, in the case of multi-factor authentication, some combination thereof. Access to&#10;organizational systems is defined as either local access or network access. Local access is any&#10;access to organizational systems by users or processes acting on behalf of users, where access is&#10;obtained through direct connections without the use of networks. Network access is access to&#10;organizational systems by users (or processes acting on behalf of users) where access is obtained&#10;through network connections (i.e., nonlocal accesses). Remote access is a type of network access&#10;that involves communication through external networks. Internal networks include local area&#10;networks and wide area networks.&#160;</div><div><br></div><div>The use of encrypted virtual private networks for network connections between organization controlled endpoints and non-organization-controlled endpoints may be treated as internal&#10;networks with respect to protecting the confidentiality and integrity of information traversing&#10;the network. Identification and authentication requirements for non-organizational users are&#10;described in NIST 800-53 IA-8.<span><b><br></b></span></div><div><span><b><br></b></span></div><div><span><b>Definition of EO-Critical Software</b></span></div><div>EO-critical software is defined as any software that has, or has direct software dependencies upon, one or more components with at least one of these attributes:</div><div><ul><li>is designed to run with elevated privilege or manage privileges;</li><li>has direct or privileged access to networking or computing resources;</li><li>is designed to control access to data or operational technology;</li><li>performs a function critical to trust; or,</li><li>operates outside of normal trust boundaries with privileged access.</li></ul></div><div>The definition applies to software of all forms (e.g., standalone software, software integral to specific devices or hardware components, cloud-based software) purchased for, or deployed in, production systems and used for operational purposes. Other use cases, such as software solely used for research or testing that is not deployed in production systems, are outside of the scope of this definition.&#160;</div><div><br></div></div><div>https://www.nist.gov/itl/executive-order-improving-nations-cybersecurity/security-measures-eo-critical-software-use-2</div><div><br></div>', 'Software', 'Authentication Management', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 65, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025323, 'PED-SM-1.1', 'Does the operator uniquely identify and authenticate each service attempting to access EO-critical software or EO-critical software platforms?', '<div><div>Services that may require identification and authentication include web applications&#10;using digital certificates or services or applications that query a database. Identification and&#10;authentication methods for system services and applications include information or code signing,&#10;provenance graphs, and electronic signatures that indicate the sources of services. Decisions&#10;regarding the validity of identification and authentication claims can be made by services&#10;separate from the services acting on those decisions. This can occur in distributed system&#10;architectures. In such situations, the identification and authentication decisions (instead of actual&#10;identifiers and authentication data) are provided to the services that need to act on those&#10;decisions.<span><b><br></b></span></div><div><br></div><div><b>Definition of EO-Critical Software</b><br></div><div><span>EO-critical software is defined as any software that has, or has direct software dependencies upon, one or more components with at least one of these attributes:</span></div><div><ul><li>is designed to run with elevated privilege or manage privileges;</li><li>has direct or privileged access to networking or computing resources;</li><li>is designed to control access to data or operational technology;</li><li>performs a function critical to trust; or,</li><li>operates outside of normal trust boundaries with privileged access.</li></ul></div><div>The definition applies to software of all forms (e.g., standalone software, software integral to specific devices or hardware components, cloud-based software) purchased for, or deployed in, production systems and used for operational purposes. Other use cases, such as software solely used for research or testing that is not deployed in production systems, are outside of the scope of this definition.&#160;</div></div><div><br></div><div>https://www.nist.gov/itl/executive-order-improving-nations-cybersecurity/security-measures-eo-critical-software-use-2</div><div><div><br></div><div><p class="MsoNormal"><br></p></div></div>', 'Software', 'Service Identification And Authentication', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 65, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025324, 'PED-SM-1.4', 'Does the operator employ boundary protection techniques as appropriate to minimize direct access to EO-critical software, EO-critical software platforms, and associated data?', '&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;<p class="MsoNormal">Examples of such techniques include network segmentation,&#10;isolation, software-defined perimeters, and proxies.</p><p class="MsoNormal"><span>Managed interfaces include gateways, routers, firewalls, guards, network-based&#10;malicious code analysis, virtualization systems, or encrypted tunnels implemented within a&#10;security architecture. Subnetworks that are physically or logically separated from internal&#10;networks are referred to as demilitarized zones or DMZs. Restricting or prohibiting interfaces&#10;within organizational systems includes restricting external web traffic to designated web servers&#10;within managed interfaces, prohibiting external traffic that appears to be spoofing internal&#10;addresses, and prohibiting internal traffic that appears to be spoofing external addresses. [SP&#10;800-189] provides additional information on source address validation techniques to prevent&#10;ingress and egress of traffic with spoofed addresses. Commercial telecommunications services&#10;are provided by network components and consolidated management systems shared by&#10;customers. These services may also include third party-provided access lines and other service&#10;elements. Such services may represent sources of increased risk despite contract security&#10;provisions. Boundary protection may be implemented as a common control for all or part of an&#10;organizational network such that the boundary to be protected is greater than a system-specific&#10;boundary (i.e., an authorization boundary).</span></p><div><div><br></div><div><b>Definition of EO-Critical Software</b></div><div>EO-critical software is defined as any software that has, or has direct software dependencies upon, one or more components with at least one of these attributes:</div><div><br></div><div><ul><li>is designed to run with elevated privilege or manage privileges;</li><li>has direct or privileged access to networking or computing resources;</li><li>is designed to control access to data or operational technology;</li><li>performs a function critical to trust; or,</li><li>operates outside of normal trust boundaries with privileged access.</li></ul></div><div>The definition applies to software of all forms (e.g., standalone software, software integral to specific devices or hardware components, cloud-based software) purchased for, or deployed in, production systems and used for operational purposes. Other use cases, such as software solely used for research or testing that is not deployed in production systems, are outside of the scope of this definition.&#160;</div><div><br></div></div><div>https://www.nist.gov/itl/executive-order-improving-nations-cybersecurity/security-measures-eo-critical-software-use-2</div><div><br></div>&#10;&#10;', 'Software', 'System and Communications Protection', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 65, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025325, 'PED-SM-2.1', 'Does the operator establish and maintain a data inventory for EO-critical software and EO-critical software platforms?', '<div><div>System components are discrete, identifiable information technology assets that&#10;include hardware, software, and firmware. Organizations may choose to implement centralized&#10;system component inventories that include components from all organizational systems. In such&#10;situations, organizations ensure that the inventories include system-specific information required&#10;for component accountability. The information necessary for effective accountability of system&#10;components includes the system name, software owners, software version numbers, hardware&#10;inventory specifications, software license information, and for networked components, the&#10;machine names and network addresses across all implemented protocols (e.g., IPv4, IPv6).&#10;Inventory specifications include date of receipt, cost, model, serial number, manufacturer,&#10;supplier information, component type, and physical location.&#160;</div><div><br></div><div>Preventing duplicate accounting of system components addresses the lack of accountability that&#10;occurs when component ownership and system association is not known, especially in large or&#10;complex connected systems. Effective prevention of duplicate accounting of system components&#10;necessitates use of a unique identifier for each component. For software inventory, centrally&#10;managed software that is accessed via other systems is addressed as a component of the system&#10;on which it is installed and managed. Software installed on multiple organizational systems and&#10;managed at the system level is addressed for each individual system and may appear more than&#10;once in a centralized component inventory, necessitating a system association for each software&#10;instance in the centralized inventory to avoid duplicate accounting of components. Scanning&#10;systems implementing multiple network protocols (e.g., IPv4 and IPv6) can result in duplicate&#10;components being identified in different address spaces. The implementation of CM-8(7) can&#10;help to eliminate duplicate accounting of components.<b><br></b></div><div><b><br></b></div><div><b>Definition of EO-Critical Software<br></b></div><div><span>EO-critical software is defined as any software that has, or has direct software dependencies upon, one or more components with at least one of these attributes:</span></div><div><ul><li>is designed to run with elevated privilege or manage privileges;</li><li>has direct or privileged access to networking or computing resources;</li><li>is designed to control access to data or operational technology;</li><li>performs a function critical to trust; or,</li><li>operates outside of normal trust boundaries with privileged access.</li></ul></div><div>The definition applies to software of all forms (e.g., standalone software, software integral to specific devices or hardware components, cloud-based software) purchased for, or deployed in, production systems and used for operational purposes. Other use cases, such as software solely used for research or testing that is not deployed in production systems, are outside of the scope of this definition.&#160;</div><div><br></div></div><div>https://www.nist.gov/itl/executive-order-improving-nations-cybersecurity/security-measures-eo-critical-software-use-2</div><div><br></div>', 'Software', 'Asset Management', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 49, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025326, 'PED-SM-2.3', 'Consistent with NIST’s cryptographic standards, does the org protect data at rest by encrypting the sensitive data used by EO-critical software and EO-critical software platforms?', '<p class="MsoNormal">Information at rest refers to the state of information when it is not in process or in&#10;transit and is located on system components. Such components include internal or external hard&#10;disk drives, storage area network devices, or databases. However, the focus of protecting&#10;information at rest is not on the type of storage device or frequency of access but rather on the&#10;state of the information. Information at rest addresses the confidentiality and integrity of&#160;<span>information and covers user information and system information. System-related information&#10;that requires protection includes configurations or rule sets for firewalls, intrusion detection and&#10;prevention systems, filtering routers, and authentication information. Organizations may employ&#10;different mechanisms to achieve confidentiality and integrity protections, including the use of&#10;cryptographic mechanisms and file share scanning. Integrity protection can be achieved, for&#10;example, by implementing write-once-read-many (WORM) technologies. When adequate&#10;protection of information at rest cannot otherwise be achieved, organizations may employ other&#10;controls, including frequent scanning to identify malicious code at rest and secure offline storage&#10;in lieu of online storage.</span><span><b><br></b></span></p><p class="MsoNormal"><span><b><br></b></span></p><p class="MsoNormal"><span><b>Definition of EO-Critical Software</b></span></p><p class="MsoNormal"><font color="#000000" face="Calibri, sans-serif">EO-critical software is defined as any software that has, or has direct software dependencies upon, one or more components with at least one of these attributes:</font></p><p class="MsoNormal"></p><ul><li><font color="#000000" face="Calibri, sans-serif">is designed to run with elevated privilege or manage privileges;</font></li><li><font color="#000000" face="Calibri, sans-serif">has direct or privileged access to networking or computing resources;</font></li><li><font color="#000000" face="Calibri, sans-serif">is designed to control access to data or operational technology;</font></li><li><font color="#000000" face="Calibri, sans-serif">performs a function critical to trust; or,</font></li><li><font color="#000000" face="Calibri, sans-serif">operates outside of normal trust boundaries with privileged access.</font></li><li><font color="#000000" face="Calibri, sans-serif">The definition applies to software of all forms (e.g., standalone software, software integral to specific devices or hardware components, cloud-based software) purchased for, or deployed in, production systems and used for operational purposes. Other use cases, such as software solely used for research or testing that is not deployed in production systems, are outside of the scope of this definition.&#160;</font></li></ul><p class="MsoNormal"><font color="#000000" face="Calibri, sans-serif">https://www.nist.gov/itl/executive-order-improving-nations-cybersecurity/security-measures-eo-critical-software-use-2</font></p>', 'Software', 'System and Communications Protection', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025327, 'PED-SM-2.4', 'Consistent with NIST’s cryptographic standards, does the operator protect data in transit by (1) using mutual authentication whenever feasible, and (2) encrypting sensitive data communications for EO-critical software and EO-critical software platforms?', '<div>Information flow control regulates where information can travel within a system and&#10;between systems (in contrast to who is allowed to access the information) and without regard to&#10;subsequent accesses to that information. Flow control restrictions include blocking external&#10;traffic that claims to be from within the organization, keeping export-controlled information&#10;from being transmitted in the clear to the Internet, restricting web requests that are not from&#10;the internal web proxy server, and limiting information transfers between organizations based&#10;on data structures and content. Transferring information between organizations may require an&#10;agreement specifying how the information flow is enforced (see CA-3). Transferring information&#10;between systems in different security or privacy domains with different security or privacy&#10;policies introduces the risk that such transfers violate one or more domain security or privacy&#10;policies. In such situations, information owners/stewards provide guidance at designated policy&#10;enforcement points between connected systems.&#160;</div><div><br></div><div>Organizations consider mandating specific&#10;architectural solutions to enforce specific security and privacy policies. Enforcement includes&#10;prohibiting information transfers between connected systems (i.e., allowing access only),&#10;verifying write permissions before accepting information from another security or privacy&#10;domain or connected system, employing hardware mechanisms to enforce one-way information&#160;<span>flows, and implementing trustworthy regrading mechanisms to reassign security or privacy&#10;attributes and labels.&#10;Organizations commonly employ information flow control policies and enforcement mechanisms&#10;to control the flow of information between designated sources and destinations within systems&#10;and between connected systems. Flow control is based on the characteristics of the information&#10;and/or the information path. Enforcement occurs, for example, in boundary protection devices&#10;that employ rule sets or establish configuration settings that restrict system services, provide a&#10;packet-filtering capability based on header information, or provide a message-filtering capability&#10;based on message content. Organizations also consider the trustworthiness of filtering and/or&#10;inspection mechanisms (i.e., hardware, firmware, and software components) that are critical to&#10;information flow enforcement. Control enhancements 3 through 32 primarily address cross-domain solution needs that focus on more advanced filtering techniques, in-depth analysis, and&#10;stronger flow enforcement mechanisms implemented in cross-domain products, such as high assurance guards. Such capabilities are generally not available in commercial off-the-shelf&#10;products. Information flow enforcement also applies to control plane traffic (e.g., routing and&#10;DNS).</span><span>&#160;</span></div><div><span><br></span></div><div><b>Definition of EO-Critical Software</b></div><div>EO-critical software is defined as any software that has, or has direct software dependencies upon, one or more components with at least one of these attributes:</div><div><ul><li>is designed to run with elevated privilege or manage privileges;</li><li>has direct or privileged access to networking or computing resources;</li><li>is designed to control access to data or operational technology;</li><li>performs a function critical to trust; or,</li><li>operates outside of normal trust boundaries with privileged access.</li></ul></div><div>The definition applies to software of all forms (e.g., standalone software, software integral to specific devices or hardware components, cloud-based software) purchased for, or deployed in, production systems and used for operational purposes. Other use cases, such as software solely used for research or testing that is not deployed in production systems, are outside of the scope of this definition.&#160;</div><div><br></div><div><span>https://www.nist.gov/itl/executive-order-improving-nations-cybersecurity/security-measures-eo-critical-software-use-2</span><br></div>', 'Software', 'System and Communications Protection and Information Integrity', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025328, 'PED-SM-2.5', 'Does the operator back up data, exercise backup restoration, and be prepared to recover data used by EO-critical software and EO-critical software platforms at any time from backups?', '<div><span>System-level information includes system state information, operating system&#10;software, middleware, application software, and licenses. User-level information includes&#10;information other than system-level information. Mechanisms employed to protect the integrity&#10;of system backups include digital signatures and cryptographic hashes. Protection of system&#10;backup information while in transit is addressed by NIST 800-53 MP-5 and NIST 800-53 SC-8. System backups reflect the&#10;requirements in contingency plans as well as other organizational requirements for backing up&#10;information. Organizations may be subject to laws, executive orders, directives, regulations, or&#10;policies with requirements regarding specific categories of information (e.g., personal health&#10;information). Organizational personnel consult with the senior agency official for privacy and&#10;legal counsel regarding such requirements.</span><br></div><div><span><br></span></div><div><b>Definition of EO-Critical Software</b></div><div>EO-critical software is defined as any software that has, or has direct software dependencies upon, one or more components with at least one of these attributes:</div><div><ul><li>is designed to run with elevated privilege or manage privileges;</li><li>has direct or privileged access to networking or computing resources;</li><li>is designed to control access to data or operational technology;</li><li>performs a function critical to trust; or,</li><li>operates outside of normal trust boundaries with privileged access.</li></ul></div><div>The definition applies to software of all forms (e.g., standalone software, software integral to specific devices or hardware components, cloud-based software) purchased for, or deployed in, production systems and used for operational purposes. Other use cases, such as software solely used for research or testing that is not deployed in production systems, are outside of the scope of this definition.&#160;</div><div><br></div><div>https://www.nist.gov/itl/executive-order-improving-nations-cybersecurity/security-measures-eo-critical-software-use-2</div>', 'Software', 'System Backup', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 64, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025329, 'PED-SM-3.1', 'Does the operator establish and maintain a software inventory for all platforms running EO-critical software and all software (both EO-critical and non-EO-critical) deployed to each platform?', 'System components are discrete, identifiable information technology assets that&#10;include hardware, software, and firmware. Organizations may choose to implement centralized&#10;system component inventories that include components from all organizational systems. In such&#10;situations, organizations ensure that the inventories include system-specific information required&#10;for component accountability. The information necessary for effective accountability of system&#10;components includes the system name, software owners, software version numbers, hardware&#10;inventory specifications, software license information, and for networked components, the&#10;machine names and network addresses across all implemented protocols (e.g., IPv4, IPv6).&#10;Inventory specifications include date of receipt, cost, model, serial number, manufacturer,&#10;supplier information, component type, and physical location.&#160;<div><br></div><div>Preventing duplicate accounting of system components addresses the lack of accountability that&#10;occurs when component ownership and system association is not known, especially in large or&#10;complex connected systems. Effective prevention of duplicate accounting of system components&#10;necessitates use of a unique identifier for each component. For software inventory, centrally&#10;managed software that is accessed via other systems is addressed as a component of the system&#10;on which it is installed and managed. Software installed on multiple organizational systems and&#10;managed at the system level is addressed for each individual system and may appear more than&#10;once in a centralized component inventory, necessitating a system association for each software&#10;instance in the centralized inventory to avoid duplicate accounting of components. Scanning&#10;systems implementing multiple network protocols (e.g., IPv4 and IPv6) can result in duplicate&#10;components being identified in different address spaces.<br><div><p class="p1"><br></p><p class="p2"><b>Definition of EO-Critical Software</b></p><p class="p2">EO-critical software is defined as any software that has, or has direct software dependencies upon, one or more components with at least one of these attributes:</p><ul class="ul1"><li class="li2"><span class="s1"></span>is designed to run with elevated privilege or manage privileges;</li><li class="li2"><span class="s1"></span>has direct or privileged access to networking or computing resources;</li><li class="li2"><span class="s1"></span>is designed to control access to data or operational technology;</li><li class="li2"><span class="s1"></span>performs a function critical to trust; or,</li><li class="li2"><span class="s1"></span>operates outside of normal trust boundaries with privileged access.</li><li class="li2"><span class="s1"></span>The definition applies to software of all forms (e.g., standalone software, software integral to specific devices or hardware components, cloud-based software) purchased for, or deployed in, production systems and used for operational purposes. Other use cases, such as software solely used for research or testing that is not deployed in production systems, are outside of the scope of this definition.&#160;</li></ul><p class="p2">https://www.nist.gov/itl/executive-order-improving-nations-cybersecurity/security-measures-eo-critical-software-use-2</p></div></div>', 'Software', 'Inventory Software', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 10, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025330, 'PED-SM-3.2', 'Does the operator use patch management practices to maintain EO-critical software platforms and all software deployed to those platforms to include (1) rapidly identify, document, and mitigate known vulnerabilities (e.g., patching, updating, upgrading software to supported version) to continuously reduce the exposure time and (2) monitor the platforms and software to ensure the mitigations are not removed outside of change control processes?', '<div>Continuous monitoring at the system level facilitates ongoing awareness of the&#10;system security and privacy posture to support organizational risk management decisions. The&#10;terms &#8220;continuous&#8221; and &#8220;ongoing&#8221; imply that organizations assess and monitor their controls&#10;and risks at a frequency sufficient to support risk-based decisions. Different types of controls may&#10;require different monitoring frequencies. The results of continuous monitoring generate risk&#10;response actions by organizations. When monitoring the effectiveness of multiple controls that&#10;have been grouped into capabilities, a root-cause analysis may be needed to determine the&#10;specific control that has failed. Continuous monitoring programs allow organizations to maintain&#10;the authorizations of systems and common controls in highly dynamic environments of operation&#10;with changing mission and business needs, threats, vulnerabilities, and technologies. Having&#10;access to security and privacy information on a continuing basis through reports and dashboards&#10;gives organizational officials the ability to make effective and timely risk management decisions,&#10;including ongoing authorization decisions.&#160;</div><div><br></div><div>Automation supports more frequent updates to hardware, software, and firmware inventories,&#10;authorization packages, and other system information. Effectiveness is further enhanced when&#10;continuous monitoring outputs are formatted to provide information that is specific, measurable,&#10;actionable, relevant, and timely. Continuous monitoring activities are scaled in accordance with&#10;the security categories of systems.<b><br></b></div><div><b><br></b></div><div><b>Definition of EO-Critical Software</b><br></div><div><p class="p2">EO-critical software is defined as any software that has, or has direct software dependencies upon, one or more components with at least one of these attributes:</p><ul class="ul1"><li class="li2"><span class="s1"></span>is designed to run with elevated privilege or manage privileges;</li><li class="li2"><span class="s1"></span>has direct or privileged access to networking or computing resources;</li><li class="li2"><span class="s1"></span>is designed to control access to data or operational technology;</li><li class="li2"><span class="s1"></span>performs a function critical to trust; or,</li><li class="li2"><span class="s1"></span>operates outside of normal trust boundaries with privileged access.</li><li class="li2"><span class="s1"></span>The definition applies to software of all forms (e.g., standalone software, software integral to specific devices or hardware components, cloud-based software) purchased for, or deployed in, production systems and used for operational purposes. Other use cases, such as software solely used for research or testing that is not deployed in production systems, are outside of the scope of this definition.&#160;</li></ul><p class="p2">https://www.nist.gov/itl/executive-order-improving-nations-cybersecurity/security-measures-eo-critical-software-use-2</p></div>', 'Software', 'Patch Management', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 49, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025331, 'PED-SM-3.3', 'Does the operator use configuration management practices to maintain EO-critical software platforms and all software deployed to those platforms?', '<div><p class="MsoNormal">Practices include:</p><p class="MsoNormal"></p><ul><li><span>identify the proper hardened security configuration for each EO-critical software platform and all software deployed to that platform (hardened security configurations enforce the principles of least privilege, separation of duties, and least functionality)</span></li><li>implement the configurations for the platforms and software</li><li>control and monitor the platforms and software to ensure the configuration is not changed outside of change control processes</li></ul></div><div><p class="p2"><b>Definition of EO-Critical Software</b></p><p class="p2">EO-critical software is defined as any software that has, or has direct software dependencies upon, one or more components with at least one of these attributes:</p><ul class="ul1"><li class="li2"><span class="s1"></span>is designed to run with elevated privilege or manage privileges;</li><li class="li2"><span class="s1"></span>has direct or privileged access to networking or computing resources;</li><li class="li2"><span class="s1"></span>is designed to control access to data or operational technology;</li><li class="li2"><span class="s1"></span>performs a function critical to trust; or,</li><li class="li2"><span class="s1"></span>operates outside of normal trust boundaries with privileged access.</li><li class="li2"><span class="s1"></span>The definition applies to software of all forms (e.g., standalone software, software integral to specific devices or hardware components, cloud-based software) purchased for, or deployed in, production systems and used for operational purposes. Other use cases, such as software solely used for research or testing that is not deployed in production systems, are outside of the scope of this definition.&#160;</li></ul><p class="p2">https://www.nist.gov/itl/executive-order-improving-nations-cybersecurity/security-measures-eo-critical-software-use-2</p></div>', 'Software', 'Baseline Configuration', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 10, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025332, 'PED-SM-4.1', 'Does the operator configure logging to record the necessary information about security events involving EO-critical software platforms and all software running on those platforms?', '<p class="MsoNormal">An event is an observable occurrence in a system. The types of events that require&#10;logging are those events that are significant and relevant to the security of systems and the&#10;privacy of individuals. Event logging also supports specific monitoring and auditing needs. Event&#10;types include password changes, failed logons or failed accesses related to systems, security or&#10;privacy attribute changes, administrative privilege usage, PIV credential usage, data action&#10;changes, query parameters, or external credential usage. In determining the set of event types&#10;that require logging, organizations consider the monitoring and auditing appropriate for each of&#10;the controls to be implemented. For completeness, event logging includes all protocols that are&#10;operational and supported by the system.&#160;</p><p class="MsoNormal">To balance monitoring and auditing requirements with other system needs, event logging&#10;requires identifying the subset of event types that are logged at a given point in time. For&#10;example, organizations may determine that systems need the capability to log every file access&#10;successful and unsuccessful, but not activate that capability except for specific circumstances due&#10;to the potential burden on system performance. The types of events that organizations desire to&#10;be logged may change. Reviewing and updating the set of logged events is necessary to help&#10;ensure that the events remain relevant and continue to support the needs of the organization.&#10;Organizations consider how the types of logging events can reveal information about individuals&#10;that may give rise to privacy risk and how best to mitigate such risks. For example, there is the&#10;potential to reveal personally identifiable information in the audit trail, especially if the logging&#10;event is based on patterns or time of usage<b><br></b></p><p class="MsoNormal"><b><br></b></p><p class="MsoNormal"><b>Definition of EO-Critical Software</b><br></p><p class="MsoNormal"><font color="#000000">EO-critical software is defined as any software that has, or has direct software dependencies upon, one or more components with at least one of these attributes:</font></p><p class="MsoNormal"></p><ul><li><font color="#000000">is designed to run with elevated privilege or manage privileges;</font></li><li><font color="#000000">has direct or privileged access to networking or computing resources;</font></li><li><font color="#000000">is designed to control access to data or operational technology;</font></li><li><font color="#000000">performs a function critical to trust; or,</font></li><li><font color="#000000">operates outside of normal trust boundaries with privileged access.</font></li></ul><p></p><p class="MsoNormal"><font color="#000000">The definition applies to software of all forms (e.g., standalone software, software integral to specific devices or hardware components, cloud-based software) purchased for, or deployed in, production systems and used for operational purposes. Other use cases, such as software solely used for research or testing that is not deployed in production systems, are outside of the scope of this definition.&#160;</font></p><p class="MsoNormal"><br></p><p class="MsoNormal"><font color="#000000">https://www.nist.gov/itl/executive-order-improving-nations-cybersecurity/security-measures-eo-critical-software-use-2</font></p>', 'Software', 'Security Event Logging', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 6, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025333, 'PED-SM-4.2', 'Does the operator continuously monitor the security of EO-critical software platforms and all software running on those platforms?', '&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;<p class="MsoNormal">Capabilities include:</p><p class="MsoNormal"></p><ul><li>protecting the software, data, and platform by&#10;identifying, reviewing, and minimizing the attack surface and exposure to known&#10;threats</li><li>permitting only verified software to execute&#10;(e.g., file integrity verification, signed executables, allowlisting)</li><li>proactively detecting threats and stopping them&#10;when possible</li><li>responding to and recovering from incidents</li><li>providing the necessary information for security&#10;operations, threat hunting, incident response, and other security needs</li></ul><div><b>Malicious Code: NIST 800-53 SI-3</b></div><div>System entry and exit points include firewalls, remote access servers, workstations,&#10;electronic mail servers, web servers, proxy servers, notebook computers, and mobile devices.&#10;Malicious code includes viruses, worms, Trojan horses, and spyware. Malicious code can also be&#10;encoded in various formats contained within compressed or hidden files or hidden in files using&#10;techniques such as steganography. Malicious code can be inserted into systems in a variety of&#10;ways, including by electronic mail, the world-wide web, and portable storage devices. Malicious&#10;code insertions occur through the exploitation of system vulnerabilities. A variety of technologies&#10;and methods exist to limit or eliminate the effects of malicious code.<br></div><div><b>System Monitoring: NIST 800-53 SI-4</b></div><div>System monitoring includes external and internal monitoring. External monitoring&#10;includes the observation of events occurring at external interfaces to the system. Internal&#10;monitoring includes the observation of events occurring within the system. Organizations&#10;monitor systems by observing audit activities in real time or by observing other system aspects&#10;such as access patterns, characteristics of access, and other actions. The monitoring objectives&#10;guide and inform the determination of the events. System monitoring capabilities are achieved&#10;through a variety of tools and techniques, including intrusion detection and prevention systems,&#10;malicious code protection software, scanning tools, audit record monitoring software, and&#10;network monitoring software.<br></div><div><b>Software Integrity: NIST 800-53 SI-7</b></div><div>Unauthorized changes to software, firmware, and information can occur due to&#10;errors or malicious activity. Software includes operating systems (with key internal components,&#10;such as kernels or drivers), middleware, and applications. Firmware interfaces include Unified&#10;Extensible Firmware Interface (UEFI) and Basic Input/Output System (BIOS). Information includes&#10;personally identifiable information and metadata that contains security and privacy attributes&#10;associated with information. Integrity-checking mechanisms&#8212;including parity checks, cyclical&#10;redundancy checks, cryptographic hashes, and associated tools&#8212;can automatically monitor the&#10;integrity of systems and hosted applications.<br></div><div><br></div><div><p class="p2"><b>Definition of EO-Critical Software</b></p><p class="p2">EO-critical software is defined as any software that has, or has direct software dependencies upon, one or more components with at least one of these attributes:</p><ul class="ul1"><li class="li2"><span class="s1"></span>is designed to run with elevated privilege or manage privileges;</li><li class="li2"><span class="s1"></span>has direct or privileged access to networking or computing resources;</li><li class="li2"><span class="s1"></span>is designed to control access to data or operational technology;</li><li class="li2"><span class="s1"></span>performs a function critical to trust; or,</li><li class="li2"><span class="s1"></span>operates outside of normal trust boundaries with privileged access.</li><li class="li2"><span class="s1"></span>The definition applies to software of all forms (e.g., standalone software, software integral to specific devices or hardware components, cloud-based software) purchased for, or deployed in, production systems and used for operational purposes. Other use cases, such as software solely used for research or testing that is not deployed in production systems, are outside of the scope of this definition.&#160;</li></ul><p class="p2">https://www.nist.gov/itl/executive-order-improving-nations-cybersecurity/security-measures-eo-critical-software-use-2</p></div><p></p>&#10;&#10;<p class="MsoListParagraphCxSpFirst"></p>&#10;&#10;<p class="MsoListParagraphCxSpMiddle"></p>&#10;&#10;<p class="MsoListParagraphCxSpMiddle"></p>&#10;&#10;<p class="MsoListParagraphCxSpMiddle"></p>&#10;&#10;<p class="MsoListParagraphCxSpLast"></p>&#10;&#10;', 'Software', 'Continuous Monitoring', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 25, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025334, 'PED-SM-4.4', 'To protect the platforms and their software using networks, does the operator employ network security protection that monitors the network traffic to and from EO-critical software platforms?', '&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;<p class="MsoNormal">Capabilities include: </p>&#10;&#10;<p class="MsoListParagraphCxSpFirst"></p><ul><li>proactively detecting threats at all layers of&#10;the stack, including the application layer, and stopping them when possible</li><li>providing the necessary information for security&#10;operations, threat hunting, incident response, and other security needs.</li></ul><div><div><b>Definition of EO-Critical Software</b></div><div>EO-critical software is defined as any software that has, or has direct software dependencies upon, one or more components with at least one of these attributes:</div><div><ul><li>is designed to run with elevated privilege or manage privileges;</li><li>has direct or privileged access to networking or computing resources;</li><li>is designed to control access to data or operational technology;</li><li>performs a function critical to trust; or,</li><li>operates outside of normal trust boundaries with privileged access.</li></ul></div><div>The definition applies to software of all forms (e.g., standalone software, software integral to specific devices or hardware components, cloud-based software) purchased for, or deployed in, production systems and used for operational purposes. Other use cases, such as software solely used for research or testing that is not deployed in production systems, are outside of the scope of this definition.&#160;</div><div><br></div><div>https://www.nist.gov/itl/executive-order-improving-nations-cybersecurity/security-measures-eo-critical-software-use-2</div></div>&#10;&#10;', 'Software', 'Boundary Protection', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025335, 'PED-SM-4.3', 'Does the org employ endpoint security protection on EO-critical software platforms to protect the platforms and all software running on them?', '&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;<p class="MsoNormal">Capabilities include:</p>&#10;&#10;<p class="MsoListParagraphCxSpFirst"></p><ul><li>protecting the software, data, and platform by&#10;identifying, reviewing, and minimizing the attack surface and exposure to known&#10;threats</li><li>permitting only verified software to execute&#10;(e.g., file integrity verification, signed executables, allowlisting)</li><li>proactively detecting threats and stopping them&#10;when possible</li><li>responding to and recovering from incidents</li><li>providing the necessary information for security&#10;operations, threat hunting, incident response, and other security needs</li></ul><p></p><p class="MsoListParagraphCxSpFirst"></p><div><p class="p2"><b>Definition of EO-Critical Software</b></p><p class="p2">EO-critical software is defined as any software that has, or has direct software dependencies upon, one or more components with at least one of these attributes:</p><ul class="ul1"><li class="li2"><span class="s1"></span>is designed to run with elevated privilege or manage privileges;</li><li class="li2"><span class="s1"></span>has direct or privileged access to networking or computing resources;</li><li class="li2"><span class="s1"></span>is designed to control access to data or operational technology;</li><li class="li2"><span class="s1"></span>performs a function critical to trust; or,</li><li class="li2"><span class="s1"></span>operates outside of normal trust boundaries with privileged access.</li><li class="li2"><span class="s1"></span>The definition applies to software of all forms (e.g., standalone software, software integral to specific devices or hardware components, cloud-based software) purchased for, or deployed in, production systems and used for operational purposes. Other use cases, such as software solely used for research or testing that is not deployed in production systems, are outside of the scope of this definition.&#160;</li></ul><p class="p2">https://www.nist.gov/itl/executive-order-improving-nations-cybersecurity/security-measures-eo-critical-software-use-2</p></div>&#10;&#10;<p class="MsoListParagraphCxSpMiddle"></p>&#10;&#10;<p class="MsoListParagraphCxSpMiddle"></p>&#10;&#10;<p class="MsoListParagraphCxSpMiddle"></p>&#10;&#10;<p class="MsoListParagraphCxSpLast"></p>&#10;&#10;', 'Software', 'Malicious Code Protection', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 25, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025336, 'PED-SM-5.1', 'Does the operator train all users of EO-critical software, based on their roles and responsibilities, on how to securely use the software and the EO-critical software platforms?', 'Organizations determine the content of training based on the assigned roles and&#10;responsibilities of individuals as well as the security and privacy requirements of organizations&#10;and the systems to which personnel have authorized access, including technical training&#10;specifically tailored for assigned duties. Roles that may require role-based training include senior&#10;leaders or management officials (e.g., head of agency/chief executive officer, chief information&#10;officer, senior accountable official for risk management, senior agency information security&#10;officer, senior agency official for privacy), system owners; authorizing officials; system security&#10;officers; privacy officers; acquisition and procurement officials; enterprise architects; systems&#10;engineers; software developers; systems security engineers; privacy engineers; system, network,&#10;and database administrators; auditors; personnel conducting configuration management&#10;activities; personnel performing verification and validation activities; personnel with access to&#10;system-level software; control assessors; personnel with contingency planning and incident&#10;response duties; personnel with privacy management responsibilities; and personnel with access&#10;to personally identifiable information.&#160;<div><br></div><div>Comprehensive role-based training addresses management, operational, and technical roles and&#10;responsibilities covering physical, personnel, and technical controls. Role-based training also&#10;includes policies, procedures, tools, methods, and artifacts for the security and privacy roles&#10;defined. Organizations provide the training necessary for individuals to fulfill their responsibilities&#10;related to operations and supply chain risk management within the context of organizational&#10;security and privacy programs. Role-based training also applies to contractors who provide&#10;services to federal agencies. Types of training include web-based and computer-based training,&#10;classroom-style training, and hands-on training (including micro-training). Updating role-based&#160;<span>training on a regular basis helps to ensure that the content remains relevant and effective.&#10;Events that may precipitate an update to role-based training content include, but are not limited&#10;to, assessment or audit findings, security incidents or breaches, or changes in applicable laws,&#10;executive orders, directives, regulations, policies, standards, and guidelines.</span></div><div><span><b><br></b></span></div><div><p class="p2"><span><b>Definition of EO-Critical Software</b></span></p><p class="p2">EO-critical software is defined as any software that has, or has direct software dependencies upon, one or more components with at least one of these attributes:</p><ul class="ul1"><li class="li2"><span class="s1"></span>is designed to run with elevated privilege or manage privileges;</li><li class="li2"><span class="s1"></span>has direct or privileged access to networking or computing resources;</li><li class="li2"><span class="s1"></span>is designed to control access to data or operational technology;</li><li class="li2"><span class="s1"></span>performs a function critical to trust; or,</li><li class="li2"><span class="s1"></span>operates outside of normal trust boundaries with privileged access.</li></ul><span>The definition applies to software of all forms (e.g., standalone software, software integral to specific devices or hardware components, cloud-based software) purchased for, or deployed in, production systems and used for operational purposes. Other use cases, such as software solely used for research or testing that is not deployed in production systems, are outside of the scope of this definition.&#160;</span></div><div><br><p class="p2">https://www.nist.gov/itl/executive-order-improving-nations-cybersecurity/security-measures-eo-critical-software-use-2</p></div>', 'Software', 'Role-Based Training', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 63, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025337, 'PED-SM-2.2', 'To enforce the principle of least privilege to the extent possible, does the operator use fine-grained access control for data and resources used by EO-critical software and EO-critical software platforms?', '<p class="p2">Organizations employ least privilege for specific duties and systems. The principle of&#10;least privilege is also applied to system processes, ensuring that the processes have access to&#10;systems and operate at privilege levels no higher than necessary to accomplish organizational&#10;missions or business functions. Organizations consider the creation of additional processes, roles,&#10;and accounts as necessary to achieve least privilege. Organizations apply least privilege to the&#10;development, implementation, and operation of organizational systems.<span><br></span></p><p class="p2"><span><b>Definition of EO-Critical Software</b></span></p><p class="p2">EO-critical software is defined as any software that has, or has direct software dependencies upon, one or more components with at least one of these attributes:</p><ul class="ul1"><li class="li2"><span class="s1"></span>is designed to run with elevated privilege or manage privileges;</li><li class="li2"><span class="s1"></span>has direct or privileged access to networking or computing resources;</li><li class="li2"><span class="s1"></span>is designed to control access to data or operational technology;</li><li class="li2"><span class="s1"></span>performs a function critical to trust; or,</li><li class="li2"><span class="s1"></span>operates outside of normal trust boundaries with privileged access.</li><li class="li2"><span class="s1"></span>The definition applies to software of all forms (e.g., standalone software, software integral to specific devices or hardware components, cloud-based software) purchased for, or deployed in, production systems and used for operational purposes. Other use cases, such as software solely used for research or testing that is not deployed in production systems, are outside of the scope of this definition.&#160;</li></ul><p class="p2">https://www.nist.gov/itl/executive-order-improving-nations-cybersecurity/security-measures-eo-critical-software-use-2</p>', 'Software', 'Least Privilege', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025338, 'PED-SM-4.5', 'Does the operator train all security operations personnel and incident response team members, based on their roles and responsibilities, on how to handle incidents involving EO-critical software or EO-critical software platforms?', 'Incident response training is associated with the assigned roles and responsibilities&#10;of organizational personnel to ensure that the appropriate content and level of detail are&#10;included in such training. For example, users may only need to know who to call or how to&#10;recognize an incident; system administrators may require additional training on how to handle&#10;incidents; and incident responders may receive more specific training on forensics, data&#10;collection techniques, reporting, system recovery, and system restoration. Incident response&#10;training includes user training in identifying and reporting suspicious activities from external and&#10;internal sources. Incident response training for users may be provided as part of NIST 800-53 AT-2 or AT-3.&#10;Events that may precipitate an update to incident response training content include, but are not&#10;limited to, incident response plan testing or response to an actual incident (lessons learned),&#10;assessment or audit findings, or changes in applicable laws, executive orders, directives,&#10;regulations, policies, standards, and guidelines.<div><br><div><p class="p1"><b>Definition of EO-Critical Software</b></p><p class="p1">EO-critical software is defined as any software that has, or has direct software dependencies upon, one or more components with at least one of these attributes:</p><ul class="ul1"><li class="li1"><span class="s1"></span>is designed to run with elevated privilege or manage privileges;</li><li class="li1"><span class="s1"></span>has direct or privileged access to networking or computing resources;</li><li class="li1"><span class="s1"></span>is designed to control access to data or operational technology;</li><li class="li1"><span class="s1"></span>performs a function critical to trust; or,</li><li class="li1"><span class="s1"></span>operates outside of normal trust boundaries with privileged access.</li><li class="li1"><span class="s1"></span>The definition applies to software of all forms (e.g., standalone software, software integral to specific devices or hardware components, cloud-based software) purchased for, or deployed in, production systems and used for operational purposes. Other use cases, such as software solely used for research or testing that is not deployed in production systems, are outside of the scope of this definition.&#160;</li></ul><p class="p2"><br></p><p class="p1">https://www.nist.gov/itl/executive-order-improving-nations-cybersecurity/security-measures-eo-critical-software-use-2</p></div></div>', 'Software', 'Incident Response Training', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 17, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025339, 'PED-SM-5.2', 'Train all administrators of EO-critical software and EO-critical software platforms, based on their roles and responsibilities, on how to securely administer the software and/or platforms.', '<div><span>Organizations determine the content of training based on the assigned roles and&#10;responsibilities of individuals as well as the security and privacy requirements of organizations&#10;and the systems to which personnel have authorized access, including technical training&#10;specifically tailored for assigned duties. Roles that may require role-based training include senior&#10;leaders or management officials (e.g., head of agency/chief executive officer, chief information&#10;officer, senior accountable official for risk management, senior agency information security&#10;officer, senior agency official for privacy), system owners; authorizing officials; system security&#10;officers; privacy officers; acquisition and procurement officials; enterprise architects; systems&#10;engineers; software developers; systems security engineers; privacy engineers; system, network,&#10;and database administrators; auditors; personnel conducting configuration management&#10;activities; personnel performing verification and validation activities; personnel with access to&#10;system-level software; control assessors; personnel with contingency planning and incident&#10;response duties; personnel with privacy management responsibilities; and personnel with access&#10;to personally identifiable information.&#160;</span><br></div><div><span><br></span></div><div><span>Comprehensive role-based training addresses management, operational, and technical roles and&#10;responsibilities covering physical, personnel, and technical controls. Role-based training also&#10;includes policies, procedures, tools, methods, and artifacts for the security and privacy roles&#10;defined. Organizations provide the training necessary for individuals to fulfill their responsibilities&#10;related to operations and supply chain risk management within the context of organizational&#10;security and privacy programs. Role-based training also applies to contractors who provide&#10;services to federal agencies. Types of training include web-based and computer-based training,&#10;classroom-style training, and hands-on training (including micro-training). Updating role-based&#160;</span>training on a regular basis helps to ensure that the content remains relevant and effective.&#10;Events that may precipitate an update to role-based training content include, but are not limited&#10;to, assessment or audit findings, security incidents or breaches, or changes in applicable laws,&#10;executive orders, directives, regulations, policies, standards, and guidelines.</div><div><br><div><p class="p1"><b>Definition of EO-Critical Software</b></p><p class="p1">EO-critical software is defined as any software that has, or has direct software dependencies upon, one or more components with at least one of these attributes:</p><ul class="ul1"><li class="li1"><span class="s1"></span>is designed to run with elevated privilege or manage privileges;</li><li class="li1"><span class="s1"></span>has direct or privileged access to networking or computing resources;</li><li class="li1"><span class="s1"></span>is designed to control access to data or operational technology;</li><li class="li1"><span class="s1"></span>performs a function critical to trust; or,</li><li class="li1"><span class="s1"></span>operates outside of normal trust boundaries with privileged access.</li><li class="li1"><span class="s1"></span>The definition applies to software of all forms (e.g., standalone software, software integral to specific devices or hardware components, cloud-based software) purchased for, or deployed in, production systems and used for operational purposes. Other use cases, such as software solely used for research or testing that is not deployed in production systems, are outside of the scope of this definition.&#160;</li></ul><p class="p1">https://www.nist.gov/itl/executive-order-improving-nations-cybersecurity/security-measures-eo-critical-software-use-2</p></div></div>', 'Software', 'Role-Based Security Training', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 63, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025340, 'PED-SM-5.3', 'Does the operator conduct frequent awareness activities to reinforce the training for all users and administrators of EO-critical software and platforms, and to measure the training’s effectiveness for continuous improvement purposes?', 'Organizations determine the content of training based on the assigned roles and&#10;responsibilities of individuals as well as the security and privacy requirements of organizations&#10;and the systems to which personnel have authorized access, including technical training&#10;specifically tailored for assigned duties. Roles that may require role-based training include senior&#10;leaders or management officials (e.g., head of agency/chief executive officer, chief information&#10;officer, senior accountable official for risk management, senior agency information security&#10;officer, senior agency official for privacy), system owners; authorizing officials; system security&#10;officers; privacy officers; acquisition and procurement officials; enterprise architects; systems&#10;engineers; software developers; systems security engineers; privacy engineers; system, network,&#10;and database administrators; auditors; personnel conducting configuration management&#10;activities; personnel performing verification and validation activities; personnel with access to&#10;system-level software; control assessors; personnel with contingency planning and incident&#10;response duties; personnel with privacy management responsibilities; and personnel with access&#10;to personally identifiable information.&#160;<div><br><div><span>Comprehensive role-based training addresses management, operational, and technical roles and&#10;responsibilities covering physical, personnel, and technical controls. Role-based training also&#10;includes policies, procedures, tools, methods, and artifacts for the security and privacy roles&#10;defined. Organizations provide the training necessary for individuals to fulfill their responsibilities&#10;related to operations and supply chain risk management within the context of organizational&#10;security and privacy programs. Role-based training also applies to contractors who provide&#10;services to federal agencies. Types of training include web-based and computer-based training,&#10;classroom-style training, and hands-on training (including micro-training). Updating role-based&#160;</span><span>training on a regular basis helps to ensure that the content remains relevant and effective.&#10;Events that may precipitate an update to role-based training content include, but are not limited&#10;to, assessment or audit findings, security incidents or breaches, or changes in applicable laws,&#10;executive orders, directives, regulations, policies, standards, and guidelines.</span><br></div><div><span><br></span></div><div><p class="p1"><b>Definition of EO-Critical Software</b></p><p class="p1">EO-critical software is defined as any software that has, or has direct software dependencies upon, one or more components with at least one of these attributes:</p><ul class="ul1"><li class="li1"><span class="s1"></span>is designed to run with elevated privilege or manage privileges;</li><li class="li1"><span class="s1"></span>has direct or privileged access to networking or computing resources;</li><li class="li1"><span class="s1"></span>is designed to control access to data or operational technology;</li><li class="li1"><span class="s1"></span>performs a function critical to trust; or,</li><li class="li1"><span class="s1"></span>operates outside of normal trust boundaries with privileged access.</li><li class="li1"><span class="s1"></span>The definition applies to software of all forms (e.g., standalone software, software integral to specific devices or hardware components, cloud-based software) purchased for, or deployed in, production systems and used for operational purposes. Other use cases, such as software solely used for research or testing that is not deployed in production systems, are outside of the scope of this definition.&#160;</li></ul><p class="p1">https://www.nist.gov/itl/executive-order-improving-nations-cybersecurity/security-measures-eo-critical-software-use-2</p></div></div>', 'Software', 'Role-Based Security Training', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 63, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025341, 'PED-CA-8', 'Does the operator conduct regular penetration testing on systems, components, and software applications (hosted on operating architectures whether third party or in-house)?', '<p class="MsoNormal"><span>Penetration testing is a specialized type of assessment conducted on systems or individual system components to identify vulnerabilities that could be exploited by adversaries. Penetration testing goes beyond automated vulnerability scanning and is conducted by agents and teams with demonstrable skills and experience that include technical expertise in network, operating system, and/or application level security. Penetration testing can be used to validate vulnerabilities or determine the degree of penetration resistance of systems to adversaries within specified constraints. Such constraints include time, resources, and skills. Penetration testing attempts to duplicate the actions of adversaries and provides a more in-depth analysis of security- and privacy-related weaknesses or deficiencies. Penetration testing is especially important when organizations are transitioning from older technologies to newer technologies (e.g., transitioning from IPv4 to IPv6 network protocols).</span></p><p class="MsoNormal"><span>Organizations can use the results of vulnerability analyses to support penetration testing activities. Penetration testing can be conducted internally or externally on the hardware, software, or firmware components of a system and can exercise both physical and technical controls. A standard method for penetration testing includes a pretest analysis based on full knowledge of the system, pretest identification of potential vulnerabilities based on the pretest analysis, and testing designed to determine the exploitability of vulnerabilities. All parties agree to the rules of engagement before commencing penetration testing scenarios. Organizations correlate the rules of engagement for the penetration tests with the tools, techniques, and procedures that are anticipated to be employed by adversaries. Penetration testing may result in the exposure of information that is protected by laws or regulations, to individuals conducting the testing. Rules of engagement, contracts, or other appropriate mechanisms can be used to communicate expectations for how to protect this information. Risk assessments guide the decisions on the level of independence required for the personnel conducting penetration testing.</span></p><p class="MsoNormal"><span>&#160;</span></p><p class="MsoNormal"><span>Related Controls: CA-8, RA-5, RA-10, SA-11, SR-5, SR-6.</span></p>', 'Assessment, Authorization, and Monitoring', 'Penetration Testing', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 20, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025342, 'PED-CA-2', 'Does the operator employ an independent penetration testing agent or team to perform penetration testing on the system, system components, and software applications (hosted on operating architectures whether third party or in-house?', '<p class="MsoNormal"><span>Independent penetration testing agents or teams are individuals or groups who conduct impartial penetration testing of organizational systems. Impartiality implies that penetration testing agents or teams are free from perceived or actual conflicts of interest with respect to the development, operation, or management of the systems that are the targets of the penetration testing. RELATED: CA-2</span></p><p class="MsoNormal"><span>&#160;</span></p>', 'Assessment, Authorization, and Monitoring', 'Penetration Testing', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 20, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025343, 'PED-CA-8.2', 'Does the operator employ red-team exercises to simulate attempts by adversaries to compromise organizational systems in accordance with applicable rules of engagement?', '&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;<p class="MsoNormal"><span>Red&#10;team exercises extend the objectives of penetration testing by examining the&#10;security and privacy posture of organizations and the capability to implement&#10;effective cyber defenses. Red team exercises simulate attempts by adversaries&#10;to compromise mission and business functions and provide a comprehensive&#10;assessment of the security and privacy posture of systems and organizations.&#10;Such attempts may include technology-based attacks and social engineering-based&#10;attacks. Technology-based attacks include interactions with hardware, software,&#10;or firmware components and/or mission and business processes. Social&#10;engineering-based attacks include interactions via email, telephone, shoulder&#10;surfing, or personal conversations. Red team exercises are most effective when&#10;conducted by penetration testing agents and teams with knowledge of and&#10;experience with current adversarial tactics, techniques, procedures, and tools.&#10;While penetration testing may be primarily laboratory-based testing,&#10;organizations can use red team exercises to provide more comprehensive&#10;assessments that reflect real-world conditions. The results from red team&#10;exercises can be used by organizations to improve security and privacy&#10;awareness and training and to assess control effectiveness. Related Controls:&#10;CA-8.2</span></p>&#10;&#10;<p class="MsoNormal"><span>&#160;</span></p>&#10;&#10;', 'Assessment, Authorization, and Monitoring', 'Penetration Tests and Red Team Exercises', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 20, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025344, 'PED-PE-3', 'Does the operator employ a penetration testing process that includes announced and/or unannounced attempts to bypass or circumvent controls associated with a PED used by a crewmember?', '<p class="MsoNormal"><span>When PEDs and personal mobile devices (BYOD) are left unattended and/or unlocked, they are vulnerable to physical access by unauthorized parties. Crewmembers should not leave PEDs or personal mobile devices physically unattended without the appropriate mitigation strategies in place.</span></p><p class="MsoNormal"><span>&#160;</span></p><p class="MsoNormal"><span>Aircraft operators should conduct penetration testing on hardware, operating systems, physical access points, and hosted applications.</span></p><p class="MsoNormal"><span>&#160;</span></p><p class="MsoNormal"><span>Related Controls: CA-2, PE-3.&#160;</span></p>', 'Assessment, Authorization, and Monitoring', 'Physical Access Protection', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 32, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025345, 'PED-RA-10', 'Does the operator establish and maintain a cyber threat hunting capability to: 

•	Search for indicators of compromise in operational systems; and 
•	Detect, track, and disrupt threats that evade existing controls; and 
•	Employ the threat hunting capability regularly?', '<p class="MsoNormal"><span>Threat hunting is an active means of cyber defense in contrast to traditional protection measures, such as firewalls, intrusion detection and prevention systems, quarantining malicious code in sandboxes, and Security Information and Event Management technologies and systems. Cyber threat hunting involves proactively searching organizational systems, networks, and infrastructure for advanced threats. The objective is to track and disrupt cyber adversaries as early as possible in the attack sequence and to measurably improve the speed and accuracy of organizational responses. Indications of compromise include unusual network traffic, unusual file changes, and the presence of malicious code. Threat hunting teams leverage existing threat intelligence and may create new threat intelligence, which is shared with peer organizations, Information Sharing and Analysis Organizations (ISAO), Information Sharing and Analysis Centers (ISAC), and relevant government departments and agencies.</span></p><p class="MsoNormal"><span>&#160;</span></p><p class="MsoNormal"><span>Related Controls: CA-2, CA-7, CA-8, RA-3, RA-5, RA-6, SI-4.</span></p><p class="MsoNormal"><span>&#160;</span></p>', 'Risk Assessment', 'Threat Hunting', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 12, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025346, 'PED-172-1', 'Does the operator implement applicable enhanced security requirements of NIST 800-172 to protect CUI, for example, to safeguard electronic crewmember manuals that contain Sensitive Security Information (SSI)?', '<p class="MsoNormal"><b>NIST SP 800-172 &#34;</b><span><b>ENHANCED SECURITY REQUIREMENTS FOR PROTECTING CUI&#34;</b></span></p><p class="MsoNormal"><span><b><br></b></span></p><p class="MsoNormal"><b>Protection strategies outlined in NIST 800-172:</b></p><p class="MsoNormal"></p><ul><li><span>Penetration-resistant architecture &#8211; The architecture must use technology and procedures to limit the opportunities for an adversary to compromise the system. More than half of the 35 controls in 800-72 impact the architecture&#8217;s creation and security.</span></li><li>Damage limiting operations &#8211; Focused on detecting compromises and limiting the effect of both detected and undetected system compromises.</li><li>Cyber resiliency and survivability &#8211; The ability to anticipate, withstand, and recover from an attack.</li></ul><p></p><p class="MsoNormal">The adversarial effects listed in the controls support each of these strategies.</p><p class="MsoNormal"><br></p><p class="MsoNormal"><b>Five high-level desired effects on adversaries and attackers:</b><br></p><p class="MsoNormal"></p><ol><li>Redirect &#8211; Deter, divert, deceive which includes technologies such as sandboxing, detonation chambers, honeypots, and other practices like tainting that use deliberately misleading systems&#8217; information to lure attackers away from the real CUI.</li><li><span>Preclude &#8211; Expunge, preempt, negate. The goal is to ensure that the threat does not have the attacker&#8217;s desired outcomes.</span></li><li>Impede &#8211; Contain, degrade, delay, exert. Actions that make it more difficult for threat events to cause negative consequences.</li><li>Limit &#8211; Shorten or reduce the degree of damage from a threat event.</li><li>Expose &#8211; Detect, scrutinize, reveal. This not only includes threat hunting but also participating in threat intelligence data feeds.</li></ol><p></p><p class="MsoNormal">Each of these adversarial effects breaks down into 15 specific impacts on risk and expected results. These effects are described in detail in NIST 800-160.</p><p class="MsoNormal"><span><br></span></p><p class="MsoNormal"><span><b>Four Fundamental Assumptions</b></span></p><p class="MsoNormal"><span>The enhanced security requirements described in NIST 800-172 have been developed based on four fundamental assumptions:</span></p><p class="MsoNormal"></p><ul><li>Statutory and regulatory requirements for the protection of CUI are consistent, whether such information resides in federal or nonfederal systems and organizations.</li><li>Safeguards implemented to protect CUI are consistent in federal and nonfederal systems and organizations.</li><li>The impact value for CUI is no less than [FIPS 199] moderate.&#160;&#160;</li><li>Additional protections are necessary to protect CUI associated with critical programs or high value assets.</li></ul><p></p><p class="MsoNormal">The assumptions reinforce the concept that CUI has the same value and potential adverse impact if compromised, whether such information is located in a federal or a nonfederal organization. Additional assumptions that also impact the development of the enhanced security requirements and the expectation of federal agencies in working with nonfederal organizations include:</p><p class="MsoNormal"></p><ul><li><span>Nonfederal organizations have specific safeguarding measures in place to protect their information, which may also be sufficient to satisfy the enhanced security requirements.</span></li><li>Nonfederal organizations can implement a variety of security solutions directly or using external service providers (e.g., managed services) to satisfy the enhanced security requirements.</li><li>Nonfederal organizations may not have the necessary organizational structure or resources to satisfy a particular enhanced security requirement and may implement alternative but equally effective security measures to satisfy the intent of the requirement.</li><li>Federal agencies define, in appropriate contracts or other agreements, the organization defined parameters for applicable enhanced security requirements.</li></ul><p></p><p class="MsoNormal">The enhanced security requirements are applied, as necessary, to protect CUI associated with a critical program or a high value asset. Federal agencies may limit application as long as the needed protection is achieved, such as by applying the enhanced security requirements to the components of nonfederal systems that process, store, or transmit CUI associated with a critical program or high value asset; provide protection for such components; or provide a direct attack path to such components (e.g., due to established trust relationships between system components).</p><p class="MsoNormal">There is no expectation that all of the enhanced security requirements will be selected by every federal agency. The decision to select enhanced security requirements will be based on the specific mission and business protection needs of the agency, group of agencies, or the federal government (i.e., federal entity) and will be guided and informed by ongoing assessments of risk. The selection of enhanced security requirements for a nonfederal system processing, storing, or transmitting CUI associated with a critical program or a high value asset will be conveyed to the nonfederal organization by the federal entity in a contract, grant, or other agreement. The application of the enhanced security requirements to subcontractors will also be addressed by the federal entity in consultation with the nonfederal organization.</p><div><br></div><span></span>', 'Information Protection', 'Protecting Controlled Unclassified Information', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 18, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025347, 'PED-RA-1', 'When conducting a risk assessment, does the operator adequately prepare by identifying the following:
•	Purpose,
•	Scope,
•	Assumptions and Constraints,
•	Information Sources, 
•	Risk model, 
•	and analytic approach?', '<div><b>Risk Assessment Prepare Tasks&#160;</b></div><div><b><br></b></div><div><b>1. RA TASK 1-1 Identify Purpose&#160;</b></div><div>When conducting a risk assessment, does the operator identify the purpose of the risk assessment in terms of the information that the assessment is intended to produce and the decisions the assessment is intended to support?</div><div><br></div><div><b>2. RA TASK 1-2 Identify Scope&#160; </b>&#160;</div><div>When conducting a risk assessment, does the operator identify the scope of the risk assessment in terms of organizational applicability, time frame supported, and architectural/technology considerations?</div><div><b><br></b></div><div><b>3. RA TASK 1-3 Identify Assumptions and Constraints&#160; &#160;</b></div><div>When conducting a risk assessment, does the operator identify the specific assumptions and constraints under which the risk assessment is conducted?</div><div><br></div><div><b>4. RA TASK 1-4 Identify Information Sources&#160; &#160;</b></div><div>When conducting a risk assessment, does the operator identify the sources of descriptive, threat, vulnerability, and impact information to be used in the risk assessment?</div><div><br></div><div><b>5. RA TASK 1-5 Identify Risk Model and Analytic Approach&#160; &#160;</b></div><div>When conducting a risk assessment, does the operator identify the risk model and analytic approach to be used in the risk assessment?</div><div><br></div><div><b>Preparing for the Risk Assessment</b></div><div><br></div><div>The first step in the risk assessment process is to prepare for the assessment. The objective of this step is to establish a context for the risk assessment. This context is established and informed by the results from the risk framing step of the risk management process.&#160;</div><div><br></div><div>Risk framing identifies, for example, organizational information regarding policies and requirements for conducting risk assessments, specific assessment methodologies to be employed, procedures for selecting risk factors to be considered, scope of the assessments, rigor of analyses, degree of formality, and requirements that facilitate consistent and repeatable risk determinations across the organization.</div><div><br></div><div>Organizations use the risk management strategy to the extent practicable to obtain information to</div><div>prepare for the risk assessment. Preparing for a risk assessment includes the following tasks:</div><div><br><ul><li>Identify the purpose of the assessment;</li><li>Identify the scope of the assessment;</li><li>Identify the assumptions and constraints associated with the assessment;</li><li>Identify the sources of information to be used as inputs to the assessment; and</li><li>Identify the risk model and analytic approaches (i.e., assessment and analysis approaches) to be employed during the assessment.</li></ul></div>', 'Risk Assessment', 'Risk Assessment', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 70, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025348, 'PED-RA-2800', 'When conducting a risk assessment, does the operator identify the following:
•	Threat sources
•	Threat events 
•	Vulnerabilities and predisposing conditions?', '<p class="MsoNormal"><b><span><u>Conducting the Risk Assessment&#160;</u></span></b></p><p class="MsoNormal"><b><span>1. RA TASK 2-1 Identify Threat Sources</span></b></p><p class="MsoNormal"><span>Section 3.2, Appendix D</span></p><p class="MsoNormal"><span>Identify and characterize threat sources of concern, including capability, intent, and targeting characteristics for adversarial threats and range of effects for non-adversarial threats.</span></p><p class="MsoNormal"><b><span>2. RA TASK 2-2 Identify Threat Events</span></b></p><p class="MsoNormal"><span>Section 3.2, Appendix E</span></p><p class="MsoNormal"><span>Identify potential threat events, relevance of the events, and the threat sources that could initiate the events.</span></p><p class="MsoNormal"><b><span>3. RA TASK 2-3 Identify Vulnerabilities and Predisposing Conditions</span></b></p><p class="MsoNormal"><span>Section 3.2, Appendix F</span></p><p class="MsoNormal"><span>Identify vulnerabilities and predisposing conditions that affect the likelihood that threat events of concern result in adverse impacts.</span></p><p class="MsoNormal"><b><span>4. RA TASK 2-4 Determine Likelihood</span></b></p><p class="MsoNormal"><span>Section 3.2, Appendix G</span></p><p class="MsoNormal"><span>Determine the likelihood that threat events of concern result in adverse impacts, considering: (i) the characteristics of the threat sources that could initiate the events; (ii) the vulnerabilities/predisposing conditions identified; and (iii) the organizational susceptibility reflecting the safeguards/countermeasures planned or implemented to impede such events.</span></p><p class="MsoNormal"><b><span>5. RA TASK 2-5 Determine Impact</span></b></p><p class="MsoNormal"><span>Section 3.2, Appendix H</span></p><p class="MsoNormal"><span>Determine the adverse impacts from threat events of concern, considering: (i) the characteristics of the threat sources that could initiate the events; (ii) the vulnerabilities/predisposing conditions identified; and (iii) the organizational susceptibility reflecting the safeguards/countermeasures planned or implemented to impede such events.</span></p><p class="MsoNormal"><b><span>6. RA TASK 2-6 Determine Risk</span></b></p><p class="MsoNormal"><span>Section 3.2, Appendix I</span></p><p class="MsoNormal"><span>Determine the risk to the organization from threat events of concern considering: (i) the impact that would result from the events; and (ii) the likelihood of the events occurring.</span></p><p class="MsoNormal"><b><span><u>Supplemental Guidance:</u></span></b></p><p class="MsoNormal"><span>The second step in the risk assessment process is to conduct the assessment. The objective of this step is to produce a list of information security risks that can be prioritized by risk level and used to inform risk response decisions.</span></p><p class="MsoNormal"><span>To accomplish this objective, organizations analyze threats and vulnerabilities, impacts and likelihood, and the uncertainty associated with the risk assessment process. This step also includes the gathering of essential information as a part of each task and is conducted in accordance with the assessment context established in the Prepare step of the risk assessment process.</span></p><p class="MsoNormal"><span>The expectation for risk assessments is to adequately cover the entire threat space in accordance with the specific definitions, guidance, and direction established during the Prepare step. However, in practice, adequate coverage within available resources may dictate generalizing threat sources, threat events, and vulnerabilities to ensure full coverage and assessing specific, detailed sources, events, and vulnerabilities only as necessary to accomplish risk assessment objectives.</span></p><p class="MsoNormal"><span><b>Conducting risk assessments includes the following specific tasks:</b></span></p><p class="MsoListParagraph"></p><ul><li><span>Identify threat sources that are relevant to organizations;</span></li><li>Identify threat events that could be produced by those sources;</li><li>Identify vulnerabilities within organizations that could be exploited by threat sources through specific threat events and the predisposing conditions that could affect successful exploitation;</li><li>Determine the likelihood that the identified threat sources would initiate specific threat events and the likelihood that the threat events would be successful;</li><li>Determine the adverse impacts to organizational operations and assets, individuals, other organizations, and the Nation resulting from the exploitation of vulnerabilities by threat sources (through specific threat events); and</li><li>Determine information security risks as a combination of likelihood of threat exploitation of vulnerabilities and the impact of such exploitation, including any uncertainties associated with the risk determinations.</li></ul><p></p>', 'Risk Assessment', 'Risk Assessment', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 70, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025349, 'PED-RA-3', 'When conducting a risk assessment, does the operator determine the likelihood, impact, and risk associated with a threat event?', '<p class="MsoNormal"><span><u><b>Conducting the Risk Assessment&#160;</b></u></span></p><p class="MsoNormal"><span><b>1. RA TASK 2-1 Identify Threat Sources</b></span></p><p class="MsoNormal">Section 3.2, Appendix D</p><p class="MsoNormal">Identify and characterize threat sources of concern, including capability, intent, and targeting characteristics for adversarial threats and range of effects for non-adversarial threats.</p><p class="MsoNormal"><span><b>2. RA TASK 2-2 Identify Threat Events</b></span></p><p class="MsoNormal">Section 3.2, Appendix E</p><p class="MsoNormal">Identify potential threat events, relevance of the events, and the threat sources that could initiate the events.</p><p class="MsoNormal"><span><b>3. RA TASK 2-3 Identify Vulnerabilities and Predisposing Conditions</b></span></p><p class="MsoNormal">Section 3.2, Appendix F</p><p class="MsoNormal">Identify vulnerabilities and predisposing conditions that affect the likelihood that threat events of concern result in adverse impacts.</p><p class="MsoNormal"><span><b>4. RA TASK 2-4 Determine Likelihood</b></span></p><p class="MsoNormal">Section 3.2, Appendix G</p><p class="MsoNormal">Determine the likelihood that threat events of concern result in adverse impacts, considering: (i) the characteristics of the threat sources that could initiate the events; (ii) the vulnerabilities/predisposing conditions identified; and (iii) the organizational susceptibility reflecting the safeguards/countermeasures planned or implemented to impede such events.</p><p class="MsoNormal"><span><b>5. RA TASK 2-5 Determine Impact</b></span></p><p class="MsoNormal">Section 3.2, Appendix H</p><p class="MsoNormal">Determine the adverse impacts from threat events of concern, considering: (i) the characteristics of the threat sources that could initiate the events; (ii) the vulnerabilities/predisposing conditions identified; and (iii) the organizational susceptibility reflecting the safeguards/countermeasures planned or implemented to impede such events.</p><p class="MsoNormal"><span><b>6. RA TASK 2-6 Determine Risk</b></span></p><p class="MsoNormal">Section 3.2, Appendix I</p><p class="MsoNormal">Determine the risk to the organization from threat events of concern considering: (i) the impact that would result from the events; and (ii) the likelihood of the events occurring.</p><p class="MsoNormal"><span><u><b>Supplemental Guidance:</b></u></span></p><p class="MsoNormal">The second step in the risk assessment process is to conduct the assessment. The objective of this step is to produce a list of information security risks that can be prioritized by risk level and used to inform risk response decisions.</p><p class="MsoNormal">To accomplish this objective, organizations analyze threats and vulnerabilities, impacts and likelihood, and the uncertainty associated with the risk assessment process. This step also includes the gathering of essential information as a part of each task and is conducted in accordance with the assessment context established in the Prepare step of the risk assessment process.</p><p class="MsoNormal">The expectation for risk assessments is to adequately cover the entire threat space in accordance with the specific definitions, guidance, and direction established during the Prepare step. However, in practice, adequate coverage within available resources may dictate generalizing threat sources, threat events, and vulnerabilities to ensure full coverage and assessing specific, detailed sources, events, and vulnerabilities only as necessary to accomplish risk assessment objectives.</p><p class="MsoNormal"><span><b>Conducting risk assessments includes the following specific tasks:</b></span></p><p class="MsoListParagraph"></p><ul><li>Identify threat sources that are relevant to organizations;</li><li>Identify threat events that could be produced by those sources;</li><li>Identify vulnerabilities within organizations that could be exploited by threat sources through specific threat events and the predisposing conditions that could affect successful exploitation;</li><li>Determine the likelihood that the identified threat sources would initiate specific threat events and the likelihood that the threat events would be successful;</li><li>Determine the adverse impacts to organizational operations and assets, individuals, other organizations, and the Nation resulting from the exploitation of vulnerabilities by threat sources (through specific threat events); and</li><li>Determine information security risks as a combination of likelihood of threat exploitation of vulnerabilities and the impact of such exploitation, including any uncertainties associated with the risk determinations.</li></ul>', 'Risk Assessment', 'Risk Assessment', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 70, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025350, 'PED-RA-4', 'Does the operator communicate risk assessment results to organizational decision makers to support risk responses?', '<p class="MsoNormal"><span>The third step in the risk assessment process is to communicate the assessment results and share risk-related information.</span></p><p class="MsoNormal"><span>The objective of this step is to ensure that decision makers across the organization have the appropriate risk-related information needed to inform and guide risk decisions. Communicating and sharing information consists of the following specific tasks:</span></p><p class="MsoListParagraph"></p><ul><li><span>Communicate the risk assessment results; and</span></li><li>Share the risk assessment results and supporting evidence in accordance with organizational policies and guidance, including information developed in the execution of the risk assessment to support other risk management activities.</li><li>Organizations must determine the appropriate method (e.g., executive briefing, risk assessment report, or dashboard) to communicate risk assessment results.</li><li>Communicate risk assessment results to designated organizational stakeholders.</li></ul><p></p>', 'Risk Assessment', 'Risk Assessment', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 70, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025351, 'PED-RA-5', 'Does the operator share risk-related information produced during the risk assessment with appropriate organizational personnel?', '<p class="MsoNormal"><span>The third step in the risk assessment process is to communicate the assessment results and share risk-related information.</span></p><p class="MsoNormal"><span>The objective of this step is to ensure that decision makers across the organization have the appropriate risk-related information needed to inform and guide risk decisions. Communicating and sharing information consists of the following specific tasks:</span></p><p class="MsoNormal"></p><ul><li><span>Communicate the risk assessment results; and</span></li><li>Share the risk assessment results and supporting evidence in accordance with organizational policies and guidance, including information developed in the execution of the risk assessment to support other risk management activities.</li><li>Organizations must determine the appropriate method (e.g., executive briefing, risk assessment report, or dashboard) to communicate risk assessment results.</li><li>Communicate risk assessment results to designated organizational stakeholders.</li></ul><p></p>', 'Risk Assessment', 'Risk Assessment', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 70, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025352, 'PED-RA-6', 'Does the operator conduct ongoing monitoring of the risk factors that contribute to changes in risk to organizational operations, assets, and individuals?', '&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;&#10;<p class="p1">The fourth step in the risk assessment process is to maintain the assessment. The objective of this&#160;<span>step is to keep current, the specific knowledge of the risk organizations incur. The results of risk&#160;</span><span>assessments inform risk management decisions and guide risk responses. To support the ongoing&#160;</span><span>review of risk management decisions (e.g., acquisition decisions, authorization decisions for&#160;</span><span>information systems and common controls, connection decisions), organizations maintain risk&#160;</span><span>assessments to incorporate any changes detected through risk monitoring. Risk monitoring&#160;</span><span>provides organizations with the means to, on an ongoing basis: (i) determine the effectiveness of&#160;</span><span>risk responses; (ii) identify risk-impacting changes to organizational information systems and the&#160;</span><span>environments in which those systems operate; and (iii) verify compliance. Maintaining risk assessments includes the following specific tasks:</span></p><p class="p1"></p><ul><li>Monitor risk factors identified in risk assessments on an ongoing basis and understanding&#160;<span>subsequent changes to those factors; and</span></li><li>Update the components of risk assessments reflecting the monitoring activities carried out by organizations.</li></ul><p></p><p class="p1"><b>Key Activities</b></p><p class="p1"></p><ul><li><span>Identify key risk factors that have been identified for ongoing monitoring.</span></li><li>Identify the frequency of risk factor monitoring activities and the circumstances under which the risk assessment needs to be updated.</li><li>Reconfirm the purpose, scope, and assumptions of the risk assessment.</li><li>Conduct the appropriate risk assessment tasks, as needed.</li><li>Communicate the subsequent risk assessment results to specified organizational personnel.</li></ul><p></p><p class="p1"></p><p class="p1"><br></p><p class="MsoNormal"><span>&#160;</span></p>&#10;&#10;', 'Risk Assessment', 'Risk Assessment', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 70, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025353, 'PED-RA-7', 'Does the operator update the existing risk assessment using the results from ongoing monitoring of risk factors?', '<p class="p1">The fourth step in the risk assessment process is to maintain the assessment. The objective of this&#160;step is to keep current, the specific knowledge of the risk organizations incur. The results of risk&#160;assessments inform risk management decisions and guide risk responses. To support the ongoing&#160;review of risk management decisions (e.g., acquisition decisions, authorization decisions for&#160;information systems and common controls, connection decisions), organizations maintain risk&#160;assessments to incorporate any changes detected through risk monitoring. Risk monitoring&#160;provides organizations with the means to, on an ongoing basis: (i) determine the effectiveness of&#160;risk responses; (ii) identify risk-impacting changes to organizational information systems and the&#160;environments in which those systems operate; and (iii) verify compliance. Maintaining risk assessments includes the following specific tasks:</p><p class="p1"></p><ul><li>Monitor risk factors identified in risk assessments on an ongoing basis and understanding&#160;subsequent changes to those factors; and</li><li>Update the components of risk assessments reflecting the monitoring activities carried out by organizations.</li></ul><p></p><p class="p1"><span>Key Activities</span></p><p class="p1"></p><ul><li>Identify key risk factors that have been identified for ongoing monitoring.</li><li>Identify the frequency of risk factor monitoring activities and the circumstances under which the risk assessment needs to be updated.</li><li>Reconfirm the purpose, scope, and assumptions of the risk assessment.</li><li>Conduct the appropriate risk assessment tasks, as needed.</li><li>Communicate the subsequent risk assessment results to specified organizational personnel.</li></ul><p></p><p class="p1"></p><p class="p1"><br></p>', 'Risk Assessment', 'Risk Assessment', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 70, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025354, 'PED-CSF-1', 'Does the operator utilize the core principles of the NIST Cybersecurity Framework to understand, manage, and express cybersecurity risk to internal and external stakeholders?', '<div>The Framework provides a common language for understanding, managing, and expressing cybersecurity risk to internal and external stakeholders. It can be used to help identify and prioritize actions for reducing cybersecurity risk, and it is a tool for aligning policy, business, and technological approaches to managing that risk. It can be used to manage cybersecurity risk across entire organizations, or it can be focused on the delivery of critical services within an organization. Different types of entities &#8211; including sector coordinating structures, associations, and organizations &#8211; can use the Framework for different purposes, including the creation of common Profiles.</div><div><br></div><div>The Framework Core provides a set of activities to achieve specific cybersecurity outcomes, and references examples of guidance to achieve those outcomes. The Core is not a checklist of actions to perform. It presents key cybersecurity outcomes identified by stakeholders as helpful in managing cybersecurity risk. The Core comprises four elements: Functions, Categories, Subcategories, and Informative References.</div><div><br></div><div><b>The Framework Core elements work together as follows:&#160;</b></div><div><br></div><div><ul><li><b>Functions</b> organize basic cybersecurity activities at their highest level. These Functions are Identify, Protect, Detect, Respond, and Recover. They aid an organization in expressing its management of cybersecurity risk by organizing information, enabling risk management decisions, addressing threats, and improving by learning from previous activities. The Functions also align with existing methodologies for incident management and help show the impact of investments in cybersecurity. For example, investments in planning and exercises support timely response and recovery actions, resulting in reduced impact to the delivery of services.</li><li><b>Categories</b> are the subdivisions of a Function into groups of cybersecurity outcomes closely tied to programmatic needs and particular activities. Examples of Categories include &#8220;Asset Management,&#8221; &#8220;Identity Management and Access Control,&#8221; and &#8220;Detection Processes.&#8221;</li><li><b>Subcategories </b>further divide a Category into specific outcomes of technical and/or management activities. They provide a set of results that, while not exhaustive, help support achievement of the outcomes in each Category. Examples of Subcategories include &#8220;External information systems are catalogued,&#8221; &#8220;Data-at-rest is protected,&#8221; and &#8220;Notifications from detection systems are investigated.&#8221;</li><li><b>Informative References</b> are specific sections of standards, guidelines, and practices common among critical infrastructure sectors that illustrate a method to achieve the outcomes associated with each Subcategory. The Informative References presented in the Framework Core are illustrative and not exhaustive. They are based upon cross-sector guidance most frequently referenced during the Framework development process.</li></ul></div><div><b>The Five Framework Core Functions</b></div><div>The five Framework Core Functions are defined below. These Functions are not intended to form a serial path or lead to a static desired end state. Rather, the Functions should be performed concurrently and continuously to form an operational culture that addresses the dynamic cybersecurity risk. See Appendix A for the complete Framework Core listing.&#160;</div><div><br></div><div><ul><li><b>Identify </b>&#8211; Develop an organizational understanding to manage cybersecurity risk to systems, people, assets, data, and capabilities. The activities in the Identify Function are foundational for effective use of the Framework. Understanding the business context, the resources that support critical functions, and the related cybersecurity risks enables an organization to focus and prioritize its efforts, consistent with its risk management strategy and business needs. Examples of outcome Categories within this Function include: Asset Management; Business Environment; Governance; Risk Assessment; and Risk Management Strategy.&#160;</li><li><b>Protect </b>&#8211; Develop and implement appropriate safeguards to ensure delivery of critical services. The Protect Function supports the ability to limit or contain the impact of a potential cybersecurity event. Examples of outcome Categories within this Function include: Identity Management and Access Control; Awareness and Training; Data Security; Information Protection Processes and Procedures; Maintenance; and Protective Technology.&#160;</li><li><b>Detect </b>&#8211; Develop and implement appropriate activities to identify the occurrence of a cybersecurity event. The Detect Function enables timely discovery of cybersecurity events. Examples of outcome Categories within this Function include: Anomalies and Events; Security Continuous Monitoring; and Detection Processes.</li><li><b>Respond </b>&#8211; Develop and implement appropriate activities to take action regarding a detected cybersecurity incident. The Respond Function supports the ability to contain the impact of a potential cybersecurity incident. Examples of outcome Categories within this Function include: Response Planning; Communications; Analysis; Mitigation; and Improvements.&#160;</li><li><b>Recover</b> &#8211; Develop and implement appropriate activities to maintain plans for resilience and to restore any capabilities or services that were impaired due to a cybersecurity incident.&#160;</li></ul></div><div>The Recover Function supports timely recovery to normal operations to reduce the impact from a cybersecurity incident. Examples of outcome Categories within this Function include: Recovery Planning; Improvements; and Communications.</div><div><br></div>', 'Risk Management and Assessment', 'Risk Management Strategy', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 41, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (1025355, 'MDM-BYOD-P-4', 'PLACEHOLDER QUESTION: Do you have a MDM and/or EMM that facilitates VPN functionality to allow for selective VPN activation for each app?', NULL, 'BYOD', 'Privacy Impact Assessment', NULL, NULL, 'SET.20210831.165809', NULL, NULL, NULL, 79, NULL, NULL)
